import type { VoiceLine } from "./voices";

const V2_P0: VoiceLine[] = [
  { id: "a4-21a85113dec", who: "amy", text: "봤지? 봤지?!", tag: "[ecstatic] [shouting] 봤지? 봤지?!" },
  { id: "a4-675409a8ea", who: "amy", text: "방금 태어났잖아.", tag: "[chuckles] [confident] 방금 태어났잖아!" },
  { id: "a4-d35495c33f", who: "amy", text: "첫 장은 브이. 두 번째는 곰. 마지막은… 그때 정해.", tag: "[bright] 첫 장은 브이! [chuckles] 두 번째는 곰. 마지막은… [thoughtful] 그때 정해." },
  { id: "a4-d70911e432", who: "amy", text: "마지막 장. 이번엔 제대로 웃어. 너 사진 찍을 때 얼굴 굳는 거 알지?", tag: "[softly] [tender] 마지막 장. [bright] 이번엔 제대로 웃어. [chuckles] 너 사진 찍을 때 얼굴 굳는 거 알지?" },
  { id: "a4-e36786aee2cu", who: "amy", text: "야, 너 왜 나를 봐? 카메라 보라고 했잖아.", tag: "(직접 생성) [flustered] 야, 너 왜 나를 봐??! 카메라 보라고 했잖아...!" },
  { id: "a4-24b881b164c", who: "amy", text: "나는… 곰 보다가 시선이 미끄러진 거야.", tag: "[flustered, stammering] 나는... 곰 보다가, 시선이 미끄러진 거야." },
  { id: "a4-1d1582094bc", who: "amy", text: "이건 곰 보다가 시선이 미끄러진 거야. 곰이 네 쪽에 있었어.", tag: "[flustered] 이건... 곰 보다가 시선이 미끄러진 거야! 곰이, 네 쪽에 있었어!" },
  { id: "a4-5fc96ff225", who: "amy", text: "조용히 해. 사진 한 장 줄게. 입막음용이야.", tag: "[sulky] 조용히 해... [sighs] 사진 한 장 줄게. 입막음용이야!" },
  { id: "a4-4fd5ad7fa9", who: "amy", text: "나 어릴 때 이런 거 뽑으면 아빠한테 자랑했다? 아빠가 엄청 크게 박수 쳐 줬거든.", tag: "[bright] [chuckles] 나 어릴 때 이런 거 뽑으면 아빠한테 자랑했다? [happy] 아빠가 엄청 크게 박수 쳐 줬거든!" },
  { id: "a4-1a77dbd96b", who: "amy", text: "요즘은 자랑할 데가 없어서 그냥 뽑기만 해.", tag: "[sighs] 요즘은 자랑할 데가 없어서 그냥 뽑기만 해..." },
  { id: "a4-3d8c8da74d", who: "amy", text: "옆집 개가 짖을 만큼.", tag: "[confident] 옆집 개가 짖을 만큼... [chuckles]" },
  { id: "a4-e80b98f14b", who: "amy", text: "…너 이럴 때 말 없는 거, 이상하게 편하다.", tag: "[thoughtful] ...너 이럴 때 말 없는 거, [chuckles] 이상하게 편하다." },
  { id: "a4-1e0a4c2fbb", who: "amy", text: "감사 표시야. 앞으로 내가 질 때마다 딜러곰 머리를 한 대씩 칠 거야.", tag: "[confident] 감사 표시야. [chuckles] 앞으로 내가 질 때마다 딜러곰 머리를 한 대씩 칠 거야!" },
  { id: "a2-7c308a8209u", who: "amy", text: "딜러, 마침 잘 왔다. 나 지금 포커페이스 특훈 중이야.", tag: "(직접 생성) [smug] 딜러, 마침 잘 왔다! 나 지금, 포커페이스 특훈 중이야." },
  { id: "a4-f1ea8b3bb9", who: "amy", text: "거울은 표정이 안 바뀌어서 상대가 안 돼. 네가 해.", tag: "[sighs] 거울은 표정이 안 바뀌어서 상대가 안 돼. [short pause] 네가 해!" },
  { id: "a4-1ce06b8625", who: "amy", text: "규칙은 간단해. 서로 눈 보고, 먼저 웃거나 눈 피하는 사람이 진 거. 진 사람이 바나나우유.", tag: "[confident] 규칙은 간단해. [short pause] 서로 눈 보고, 먼저 웃거나 눈 피하는 사람이 진 거... [chuckles] 진 사람이 바나나우유!" },
  { id: "a4-f7f9f7c8e8", who: "amy", text: "딸기는 이긴 날만 마셔. 오늘은 바나나 날.", tag: "[confident] 딸기는 이긴 날만 마셔... [short pause] 오늘은 바나나 날!" },
  { id: "a4-35a004de4f", who: "amy", text: "…너 눈, 생각보다 예쁘다.", tag: "[softly] [flustered] ...너 눈, 생각보다... 예쁘다." },
  { id: "a4-8f60c1249dc", who: "amy", text: "아, 방금 건 작전이야! 웃기려는 작전! 안 웃었으니까 무효!", tag: "[panicked] [shouting] 아, 방금 건 작전이야! 웃기려는 작전! 안 웃었으니까, 무효!" },
  { id: "a4-28e581fe6d", who: "amy", text: "…바나나우유 사 올게.", tag: "[sighs] ...바나나우유 사 올게." },
  { id: "a4-9f043ed381", who: "amy", text: "근데 진짜 궁금한 거. 나 테이블에서 티 나?", tag: "[thoughtful] 근데 진짜 궁금한 거... [short pause] 나 테이블에서 티 나?" },
  { id: "a4-e7c9d3ab45", who: "amy", text: "저번에 네가 그랬잖아. 시끄러울 땐 블러프, 조용할 땐 진짜. 그거 고치는 중이야.", tag: "[thoughtful] 저번에 네가 그랬잖아... [short pause] 시끄러울 땐 블러프, 조용할 땐 진짜. [sighs] 그거 고치는 중이야." },
  { id: "a4-080ef9b8d5", who: "amy", text: "포커페이스는 눈부터래. 영상에서 봤어.", tag: "[confident] 포커페이스는 눈부터래... [chuckles] 영상에서 봤어!" },
  { id: "a4-5b510c89a1", who: "amy", text: "……그건 정민이 통계잖아. 믿지 마.", tag: "[sighs] ...그건 정민이 통계잖아, [sulky] 믿지 마." },
  { id: "a4-abffdfd638", who: "amy", text: "딜러, 블라인드 테스트 하자. 신상 세 개 중에 '불닭 신상' 맞히기.", tag: "[confident] [excited] 딜러, 블라인드 테스트 하자. [short pause] 신상 세 개 중에 '불닭 신상' 맞히기." },
  { id: "a4-e87aa6a093", who: "amy", text: "맞히면 내가 퇴근길 야식 쏜다. 틀리면 네가 쏴.", tag: "[confident] 맞히면 내가 퇴근길 야식 쏜다... [chuckles] 틀리면 네가 쏴!" },
  { id: "a4-4942cf9608", who: "amy", text: "그러니까 네가 틀려야 돼.", tag: "[confident] 그러니까... 네가 틀려야 돼!" },
  { id: "a4-5cc6618e97", who: "amy", text: "눈 가렸으니까 내가 먹여 줘야지. 규칙이야. 방금 만든 거.", tag: "[bright] 눈 가렸으니까 내가 먹여 줘야지. 규칙이야. 방금 만든 거." },
  { id: "a4-183ca22ec5", who: "amy", text: "땡! 2번은 그냥 김치라면이야. 네가 맵찔이인 거야.", tag: "[laughing] 땡! 이 번은 그냥 김치라면이야. [chuckles] 네가 맵찔이인 거야!" },
  { id: "a4-6ab12c5a6f", who: "amy", text: "떡볶이. 제일 매운 거. 맵찔이 훈련이야.", tag: "[confident] 떡볶이! 제일 매운 거... [chuckles] 맵찔이 훈련이야." },
  { id: "a4-0bffbe5fc4", who: "amy", text: "……정답.", tag: "[surprised] ……정답." },
  { id: "a4-e84c0c7f53", who: "amy", text: "너 진짜 뭐야? 혀까지 카드 읽듯이 읽어?", tag: "[surprised] 너 진짜 뭐야? [short pause] 혀까지 카드 읽듯이 읽어?" },
  { id: "a4-9f45e31e3a", who: "amy", text: "아 몰라, 야식은 내가 쏠게. 대신 편의점 도시락으로.", tag: "[sighs] 아 몰라... 야식은 내가 쏠게. [chuckles] 대신 편의점 도시락으로!" },
  { id: "a2-63ade381c3", who: "amy", text: "저거 봤어? 여기 직원 할인 30퍼래.", tag: "저거 봤어? 여기 직원 할인 삼십 퍼래." },
  { id: "a4-0c57b7df50", who: "amy", text: "딜러! 나 왔어. 오늘은 만 원만 할 거야. 진짜로.", tag: "[excited] 딜러! 나 왔어! [chuckles] 오늘은 만 원만 할 거야. 진짜로." },
  { id: "a4-ea7f667c53", who: "amy", text: "첫 번째. 그러니까 진짜야. 아껴 쓴 거야.", tag: "[confident] 첫 번째! [short pause] 그러니까 진짜야. 아껴 쓴 거야." },
  { id: "a4-0fe76c051c", who: "amy", text: "방금 그거, 딜러가 손님 쫓아낸 거야?", tag: "[surprised] 방금 그거... 딜러가 손님 쫓아낸 거야?" },
  { id: "a4-42cdd09ac4", who: "amy", text: "규정 진짜 많네, 이 가게. …오늘은 좀 좋다, 그 규정.", tag: "[bright] 규정 진짜 많네, 이 가게. [short pause] [softly] ...오늘은 좀 좋다, 그 규정." },
  { id: "a4-592b3ee46c", who: "amy", text: "미끄러진 카드가 그렇게 예쁘게 꽂혀? 다음에 그거 가르쳐 줘.", tag: "[impressed] 미끄러진 카드가 그렇게 예쁘게 꽂혀? [playful] 다음에 그거 가르쳐 줘!" },
  { id: "a2-051b68fe13", who: "amy", text: "이건 팁. 오늘은 두 개.", tag: "이건 팁.\n오늘은 두 개." },
  { id: "a2-922df1c4b9", who: "amy", text: "오늘은 이긴 날이야. 블러프 잡았잖아. …네 덕도 좀 있고.", tag: "오늘은 이긴 날이야. 블러프 잡았잖아. …네 덕도 좀 있고." },
  { id: "a4-39fe46a0bdc", who: "amy", text: "…근데 고마워.", tag: "[whispers] [shy] ...근데, 고마워." },
  { id: "a4-7ee441dadb", who: "amy", text: "이 말은 두 번 안 해. 비싸거든.", tag: "[confident] 이 말은 두 번 안 해. [chuckles] 비싸거든." },
  { id: "a4-c98f9647dd", who: "amy", text: "아까 그 아저씨 같은 사람, 처음 아니야. '외국인이야?' '한국말 잘하네?' 다음 말도 늘 비슷해.", tag: "[quietly] 아까 그 아저씨 같은 사람, 처음 아니야. [short pause] '외국인이야?' '한국말 잘하네?' [sighs] 다음 말도 늘 비슷해." },
  { id: "a4-c9da860e6e", who: "amy", text: "웃으면서 넘기는 거 잘하거든, 나. 근데 오늘은 손이 안 움직였어.", tag: "[sad] 웃으면서 넘기는 거 잘하거든, 나. [short pause] 근데 오늘은... 손이 안 움직였어." },
  { id: "a4-a32cddd4a6", who: "amy", text: "…너는? 너는 왜 딜러 해? 셔플도 이상하게 잘하고, 앉는 게 더 어울리는 사람 같은데.", tag: "[curious] ...너는? [short pause] 너는 왜 딜러 해? 셔플도 이상하게 잘하고, 앉는 게 더 어울리는 사람 같은데." },
  { id: "a4-08264301a9", who: "amy", text: "안 맞았다는 게 졌다는 거야, 무서웠다는 거야?", tag: "[carefully] 안 맞았다는 게... 졌다는 거야, 무서웠다는 거야?" },
  { id: "a2-2a000f0f25u", who: "amy", text: "…솔직하네. 그럼 나도 하나만 솔직하게.", tag: "(직접 생성) [softly] ...솔직하네. 그럼 나도, 하나만 솔직하게." },
  { id: "a4-33bed54a0f", who: "amy", text: "거짓말은 아닌데 다는 아니네. 대답이 너무 짧아.", tag: "[playful] 거짓말은 아닌데 다는 아니네. [chuckles] 대답이 너무 짧아." },
  { id: "a4-ae4e10936b", who: "amy", text: "좋아. 그럼 공평하게 나도 하나만 말할게.", tag: "[thoughtful] 좋아. [short pause] 그럼 공평하게 나도 하나만 말할게." },
  { id: "a4-2ef4a38859", who: "amy", text: "나 사실 포커 엄청 좋아하는 거 아니야. 테이블이 좋은 거야. 거기선 아무도 어디서 왔냐고 안 물어.", tag: "[quietly] 나 사실 포커 엄청 좋아하는 거 아니야. [short pause] 테이블이 좋은 거야. 거기선 아무도 어디서 왔냐고 안 물어." },
  { id: "a4-b8e6688345", who: "amy", text: "…오늘은 테이블에서도 물어봤지만.", tag: "[sad] ...오늘은 테이블에서도 물어봤지만." },
  { id: "a4-70f4f84c5a", who: "amy", text: "편의점에서 말했지. 테이블에선 아무도 어디서 왔냐고 안 물어본다고.", tag: "[quietly] 편의점에서 말했지. [short pause] 테이블에선 아무도 어디서 왔냐고 안 물어본다고." },
  { id: "a4-f7b5b8792b", who: "amy", text: "근데 오늘은 테이블에서도 물어봤어. 그래서 손이 안 움직였나 봐.", tag: "[sad] 근데 오늘은 테이블에서도 물어봤어... [short pause] 그래서 손이 안 움직였나 봐." },
  { id: "a4-5793b6de5a", who: "amy", text: "나머지는 다음에. 너도 아직 다 말한 거 아니잖아. 하나씩 꺼내자.", tag: "[warmly] 나머지는 다음에. [chuckles] 너도 아직 다 말한 거 아니잖아. 하나씩 꺼내자." },
  { id: "a4-ed1fe35336", who: "amy", text: "마셔. 탄산은 반까지만 맛있어.", tag: "[casual] 마셔. [short pause] 탄산은 반까지만 맛있어." },
  { id: "a2-1fa737591e", who: "amy", text: "딜러 몫. 오늘 일당 추가.", tag: "[confident] 딜러 몫.\n오늘 일당 추가." },
  { id: "a4-0033b22149", who: "amy", text: "저기요, 카운터. 칩 오만 원어치만요. 다음에 줄게요.", tag: "[casual] 저기요, 카운터! 칩 오만 원어치만요. [short pause] 다음에 줄게요." },
  { id: "a4-ec5e39e2ce", who: "amy", text: "봤지? 만 원만 했어. 나 이런 사람이야. 자제력 만렙.", tag: "[proud] 봤지? 만 원만 했어! [chuckles] 나 이런 사람이야. 자제력 만렙." },
  { id: "a4-37bb00504b", who: "amy", text: "오, 칭찬. 적어 둬야지. 오늘 날짜, 딜러 칭찬 1회.", tag: "[delighted] 오, 칭찬! [chuckles] 적어 둬야지. 오늘 날짜, 딜러 칭찬 일 회." },
  { id: "a4-bfab41c4a0", who: "amy", text: "어, 딜러. 또 만났네. 이건 다이어트야. 반만 먹는 다이어트.", tag: "[bright] 어, 딜러! 또 만났네. [chuckles] 이건 다이어트야. 반만 먹는 다이어트." },
  { id: "a4-4cc0bd9f94", who: "amy", text: "……외상 조금 했어. 진짜 조금.", tag: "[hesitant] ......외상 조금 했어. [short pause] 진짜 조금." },
  { id: "a4-f0ca66fdae", who: "amy", text: "……이번 주 생활비가 좀 모자라서. 오늘은 외상 좀 해 볼까 해.", tag: "[hesitant] ......이번 주 생활비가 좀 모자라서. [short pause] 오늘은 외상 좀 해 볼까 해." },
  { id: "a2-1a925a1967", who: "amy", text: "근데 오늘 느낌 와. 아침에 신호등이 전부 초록이었거든. 이런 날은 무조건이야.", tag: "[bright] 근데 오늘 느낌 와. 아침에 신호등이 전부 초록이었거든. 이런 날은 무조건이야." },
  { id: "a4-8503418826", who: "amy", text: "알아. 아는데.", tag: "[quietly] 알아. [short pause] 아는데." },
  { id: "a4-898fa74444", who: "amy", text: "집에 있으면 계속 생각나. 월세, 생활비, 아빠. 테이블에 앉아 있으면 아무 생각이 안 나.", tag: "[sad] 집에 있으면 계속 생각나. [short pause] 월세, 생활비, 아빠. [sighs] 테이블에 앉아 있으면 아무 생각이 안 나." },
  { id: "a4-189e8fab54", who: "amy", text: "…이거 뭐야?", tag: "[surprised] ...이거 뭐야?" },
  { id: "a4-084dd6fcc0", who: "amy", text: "참치마요. 내가 제일 좋아하는 거. 어떻게 알았어?", tag: "[delighted] 참치마요! 내가 제일 좋아하는 거. [short pause] 어떻게 알았어?" },
  { id: "a4-4ed92a05d1", who: "amy", text: "…센스는 있네. 운도 좋고.", tag: "[playful] ...센스는 있네. [chuckles] 운도 좋고." },
  { id: "a4-d9b7e01f4dc", who: "amy", text: "……그런 걸 왜 기억해?", tag: "[flustered] ......그런 걸, 왜 기억해?" },
  { id: "a4-ae4232a4c6", who: "amy", text: "오늘 이기면 이거 열 개로 갚는다. 이자 포함.", tag: "[confident] 오늘 이기면 이거 열 개로 갚는다! [chuckles] 이자 포함." },
  { id: "a4-743a81b60a", who: "amy", text: "이따 봐. 오늘은 진짜 따는 거 보여 줄게.", tag: "[confident] 이따 봐! [short pause] 오늘은 진짜 따는 거 보여 줄게." },
  { id: "a4-d2c5b4c2c0", who: "amy", text: "딜러! 신호등이 그랬어. 오늘은 따는 날이야.", tag: "[excited] 딜러! 신호등이 그랬어! [short pause] 오늘은 따는 날이야!" },
  { id: "a4-a648594ecd", who: "amy", text: "저번 판 2라운드. 오늘도 한 판 해.", tag: "[confident] 저번 판 투 라운드! [short pause] 오늘도 한 판 해." },
  { id: "a4-ac60bc84ab", who: "amy", text: "사장님한테 혼났구나? 얼굴에 다 써 있어.", tag: "[teasing] 사장님한테 혼났구나? [chuckles] 얼굴에 다 써 있어." },
  { id: "a4-3ab6f6eba5", who: "amy", text: "포커페이스는 어디다 두고 다니는 거야, 딜러?", tag: "[teasing] 포커페이스는 어디다 두고 다니는 거야, 딜러?" },
  { id: "a4-f16cbd675cc", who: "amy", text: "레이즈! 또 레이즈! 오늘 나 미쳤나 봐!", tag: "[excited] [shouting] 레이즈! 또 레이즈! 오늘 나, 미쳤나 봐!" },
  { id: "a4-0f07bfe45fc", who: "amy", text: "플러시! 플러시야! 봤어? 내가 이겼어!!", tag: "[ecstatic] [shouting] 플러시! 플러시야! 봤어?! 내가 이겼어!!" },
  { id: "a4-dd2aee1711", who: "amy", text: "언니, 고마워요! 언니가 끝까지 밀어 줘서 팟이 이만큼 커졌어요!", tag: "[excited] 언니, 고마워요! [short pause] 언니가 끝까지 밀어 줘서 팟이 이만큼 커졌어요!" },
  { id: "a4-afafc90877", who: "amy", text: "사장님! 보셨어요? 플러시였어요!", tag: "[excited] 사장님! 보셨어요? [short pause] 플러시였어요!" },
  { id: "a4-20d2bbf49c", who: "amy", text: "오늘 첫 큰 판이잖아. 축하는 원래 같이 하는 거야.", tag: "[bright] 오늘 첫 큰 판이잖아! [short pause] 축하는 원래 같이 하는 거야." },
  { id: "a4-8de554e062", who: "amy", text: "오늘 이긴 거 축하해 줄 사람, 너밖에 생각 안 났는데.", tag: "[softly] [sad] 오늘 이긴 거 축하해 줄 사람... 너밖에 생각 안 났는데." },
  { id: "a4-6f70f3337c", who: "amy", text: "매워. 맵기 네가 고른다며. 왜 제일 매운 걸로 해?", tag: "[sulky] 매워! [short pause] 맵기 네가 고른다며. 왜 제일 매운 걸로 해?" },
  { id: "a4-1c5eb58bd6", who: "amy", text: "그게 무슨 논리야?", tag: "[laughing] 그게 무슨 논리야?" },
  { id: "a4-76ba52b981", who: "amy", text: "딜러 논리 진짜 별로다.", tag: "[chuckles] 딜러 논리 진짜 별로다." },
  { id: "a4-99e95ee54e", who: "amy", text: "나 포커 아빠한테 배웠어. 미국 살 때, 일요일마다 부엌 식탁에서 과자 걸고.", tag: "[softly] 나 포커 아빠한테 배웠어. [short pause] 미국 살 때, 일요일마다 부엌 식탁에서 과자 걸고." },
  { id: "a4-66e6bf4545", who: "amy", text: "곰 생일이야, 오늘. 생일엔 사진 찍는 거야.", tag: "[excited] 곰 생일이야, 오늘! [chuckles] 생일엔 사진 찍는 거야." },
  { id: "a4-a8006c78df", who: "amy", text: "진짜? 박수 크게 쳐야 돼. 아빠만큼.", tag: "[delighted] 진짜? [chuckles] 박수 크게 쳐야 돼, 아빠만큼!" },
  { id: "a4-7007e652c9", who: "amy", text: "얘 이름은 딜러곰이야. 딜러 덕에 뽑았으니까.", tag: "[proud] 얘 이름은 딜러곰이야. [chuckles] 딜러 덕에 뽑았으니까." },
  { id: "a4-7fd3c4cd23", who: "amy", text: "아 반칙이야! 말 거는 건 규칙에 없었어!", tag: "[laughing] 아, 반칙이야! [excited] 말 거는 건 규칙에 없었어!" },
  { id: "a2-3f9a081778u", who: "amy", text: "그 정도면 거의 패를 보여 주고 치는 거네.", tag: "(직접 생성) [taken aback] 그 정도면 거의 패를 보여 주고 치는 거네." },
  { id: "a4-226c923f9e", who: "amy", text: "좋아. 다음에 조용해도 블러프일 거야. 너만 헷갈리게.", tag: "[sly] 좋아. [short pause] 다음에 조용해도 블러프일 거야. [chuckles] 너만 헷갈리게." },
  { id: "a2-dc736c980bu", who: "amy", text: "……아.", tag: "(직접 생성) [realizing, deflated] ……아." },
  { id: "a2-e199738d2du", who: "amy", text: "나 할까 봐. 삼각김밥 주간이 매주 오는 건 좀 그렇잖아.", tag: "(직접 생성) [thoughtful, half-joking] 나, 할까 봐. 삼각김밥 주간이, 매주 오는 건 좀 그렇잖아." },
  { id: "a2-71f6b4b2c9u", who: "amy", text: "거봐, 뻥이었지! 다 보인다니까~", tag: "(직접 생성) [triumphant, taunting] 거봐, 뻥이었지!? 다 보인다니까~" },
  { id: "a4-31170c5500", who: "amy", text: "외상? 사장님이 얼마든지 해 준대. 근데 안 했어.", tag: "[proud] 외상? 사장님이 얼마든지 해 준대. [short pause] 근데 안 했어!" },
  { id: "a4-8b8043c6cd", who: "amy", text: "그러니까 오늘만. 신호등 믿어 볼래.", tag: "[forced brightness] 그러니까 오늘만! [short pause] 신호등 믿어 볼래." },
  { id: "a4-1f311d4150", who: "amy", text: "딜러! 오늘 떡볶이 내가 쏜다. 이긴 사람이 쏘는 거야.", tag: "[excited] 딜러! 오늘 떡볶이 내가 쏜다! [chuckles] 이긴 사람이 쏘는 거야." },
  { id: "a4-6e3a8c583b", who: "amy", text: "다음에 꼭이라고 했다? 녹음했어. 마음속으로.", tag: "[sulky] 다음에 꼭이라고 했다? [short pause] 녹음했어. 마음속으로." },
  { id: "a4-3202104f46", who: "amy", text: "아빠가 맨날 일부러 져 줬는데, 그게 너무 티 나서 화냈었어.", tag: "[bright] 아빠가 맨날 일부러 져 줬는데, [chuckles] 그게 너무 티 나서 화냈었어." },
  { id: "a4-5f2d7c8a52", who: "amy", text: "…아빠는 지금 없어. 5년 전에 한국 들어와서, 어느 날 연락이 끊겼어.", tag: "[sad] ...아빠는 지금 없어. [short pause] 오 년 전에 한국 들어와서, 어느 날 연락이 끊겼어." },
  { id: "a4-d62b725dc1", who: "amy", text: "마지막으로 간 데가 성수동 어디 포커 치는 데였대. 그거밖에 몰라.", tag: "[quietly] [sad] 마지막으로 간 데가 성수동 어디 포커 치는 데였대. [short pause] 그거밖에 몰라." },
  { id: "a4-c0555074e9", who: "amy", text: "…아까 사장님이 아빠 닮았다고 했잖아. 그냥 하는 말이겠지? 금발이면 다 비슷해 보이니까.", tag: "[sad] ...아까 사장님이 아빠 닮았다고 했잖아. [short pause] 그냥 하는 말이겠지? 금발이면 다 비슷해 보이니까." },
  { id: "a4-504ecca73e", who: "amy", text: "그래도 나는 아빠랑 달라. 나는 이기니까. 오늘처럼.", tag: "[bright] 그래도 나는 아빠랑 달라. [short pause] 나는 이기니까! 오늘처럼." },
  { id: "a4-76ff3ce883", who: "amy", text: "…너 진짜 이상한 딜러야. 손님 돈 따 가는 가게에서 손님 돈 걱정이나 하고.", tag: "[chuckles] ...너 진짜 이상한 딜러야. [short pause] 손님 돈 따 가는 가게에서 손님 돈 걱정이나 하고." },
  { id: "a4-750951abea", who: "amy", text: "알았어. 생각은 해 볼게. 생각만.", tag: "[playful] 알았어. [short pause] 생각은 해 볼게. 생각만." },
  { id: "a4-3d7cc5614e", who: "amy", text: "…뭐?", tag: "[surprised] ...뭐?" },
  { id: "a4-29406450ce", who: "amy", text: "5년 동안 경찰도 못 찾았는데 딜러가 어떻게 찾아?", tag: "[sad] 오 년 동안 경찰도 못 찾았는데... 딜러가 어떻게 찾아?" },
  { id: "a4-9646d05679", who: "amy", text: "……그게 무슨 상관이야?", tag: "[sad] ......그게 무슨 상관이야?" },
  { id: "a4-5153e55a74", who: "amy", text: "아빠 얼굴, 요즘 잘 생각이 안 나. 근데 카드 섞는 소리는 기억나. 일요일 아침 부엌에서.", tag: "[sad] 아빠 얼굴, 요즘 잘 생각이 안 나. [short pause] 근데 카드 섞는 소리는 기억나... 일요일 아침 부엌에서." },
  { id: "a4-ce49a4e6e3", who: "amy", text: "그래서 펍에 오면 좀 괜찮아. 다들 카드 섞으니까.", tag: "[softly] 그래서 펍에 오면 좀 괜찮아. [short pause] 다들 카드 섞으니까." },
  { id: "a4-ce90c39da9c", who: "amy", text: "고마워. …5년 동안, 그 말 해 준 사람 없었어.", tag: "[whispers] [holding back tears] 고마워. ...오 년 동안, 그 말 해 준 사람... 없었어." },
  { id: "a4-aa9b046004", who: "amy", text: "오늘 딴 거, 반은 외상 갚고 반은 월세 할 거야. 테이블엔 안 올릴 거야.", tag: "[confident] 오늘 딴 거, 반은 외상 갚고 반은 월세 할 거야. [short pause] 테이블엔 안 올릴 거야." },
  { id: "a4-125b47bc1d", who: "amy", text: "나 잘하지? 대답 안 해도 돼. 알아, 잘하는 거.", tag: "[proud] 나 잘하지? [chuckles] 대답 안 해도 돼. 알아, 잘하는 거." },
  { id: "a4-05b2950738", who: "amy", text: "딜러! 나 왔어. 다음 주말까지 못 기다리겠어서.", tag: "[excited] 딜러! 나 왔어! [short pause] 다음 주말까지 못 기다리겠어서." },
  { id: "a4-1528ac5d98", who: "amy", text: "메시지 봤어. 오지 말라며. 근데 그렇게 말하면 더 오고 싶잖아.", tag: "[playful] 메시지 봤어. 오지 말라며. [chuckles] 근데 그렇게 말하면 더 오고 싶잖아." },
  { id: "a4-8f5ac9e5b9", who: "amy", text: "그러니까 나중에 들을게. 오늘은 따고 나서.", tag: "[confident] 그러니까 나중에 들을게. [short pause] 오늘은 따고 나서." },
  { id: "a4-ccb43f00ae", who: "amy", text: "사장님이 오늘 특별히 아래층 한 판 해도 된대. 어제 같은 날은 아래가 더 재밌대.", tag: "[excited] 사장님이 오늘 특별히 아래층 한 판 해도 된대! [short pause] 어제 같은 날은 아래가 더 재밌대." },
  { id: "a4-eaa2b70c15", who: "amy", text: "왜? 질투해? 딜러가 손님한테?", tag: "[teasing] 왜? 질투해? [chuckles] 딜러가 손님한테?" },
  { id: "a4-887e728c54", who: "amy", text: "어제 이겼잖아. 너도 봤잖아.", tag: "[sulky] 어제 이겼잖아. [short pause] 너도 봤잖아." },
  { id: "a2-3a6fce9373", who: "amy", text: "딱 한 판만 하고 올게. 이번 주 '진짜로' 두 번째 쓴다. 진짜로.", tag: "[bright] 딱 한 판만 하고 올게. 이번 주 '진짜로' 두 번째 쓴다, 진짜로." },
  { id: "a4-d1f22d5c2a", who: "amy", text: "알아. 그래서 가는 거야.", tag: "[quietly] 알아. [short pause] 그래서 가는 거야." },
  { id: "a4-57bb113b43", who: "amy", text: "…우리 아빠가 마지막으로 앉은 데가, 아마 거기거든.", tag: "[quietly] [sad] ...우리 아빠가 마지막으로 앉은 데가, 아마 거기거든." },
  { id: "a4-9683e3f65b", who: "amy", text: "이기고 올게. 아빠가 진 판. 그러면 뭔가 끝날 것 같아.", tag: "[determined] 이기고 올게. [short pause] 아빠가 진 판. 그러면... 뭔가 끝날 것 같아." },
  { id: "a4-0d015153e9", who: "amy", text: "어제 딴 거 다. 그리고 이번 달 월세도. 외상도 조금.", tag: "[sad] 어제 딴 거 다. [short pause] 그리고 이번 달 월세도... 외상도 조금." },
  { id: "a4-5f46be4e9b", who: "amy", text: "괜찮아! 다음 주에 다시 하면 돼. 사장님이 운이 한 번 왔으니까 또 온대.", tag: "[forced brightness] 괜찮아! 다음 주에 다시 하면 돼. [short pause] 사장님이 운이 한 번 왔으니까 또 온대." },
  { id: "a4-9530ac36aa", who: "amy", text: "…아래층 언니, 엄청 잘 치더라. 연서 언니. 표정이 하나도 안 변해.", tag: "[quietly] [sad] ...아래층 언니, 엄청 잘 치더라. [short pause] 연서 언니. 표정이 하나도 안 변해." },
  { id: "a4-2608a52dbd", who: "amy", text: "…아직 안 갔냐고? 비 그치면 가려고.", tag: "[quietly] ...아직 안 갔냐고? [short pause] 비 그치면 가려고." },
  { id: "a4-5569354de8", who: "amy", text: "그럼 좀 더 있지 뭐.", tag: "[softly] 그럼 좀 더 있지 뭐." },
  { id: "a4-0029e1de79", who: "amy", text: "아래층 언니다. 언니가 이겼어요. 축하해요. 진짜로.", tag: "[sad] 아래층 언니다. [short pause] 언니가 이겼어요. 축하해요... 진짜로." },
  { id: "a4-691b5163e5", who: "amy", text: "필요 없어요. 오늘은 언니한테 아무것도 안 받을래요.", tag: "[cold] 필요 없어요. [short pause] 오늘은 언니한테 아무것도 안 받을래요." },
  { id: "a4-a4c990490b", who: "amy", text: "딜러, 저 언니 기다리는 거면 가. 나 혼자 있어도 돼.", tag: "[quietly] 딜러, 저 언니 기다리는 거면 가. [short pause] 나 혼자 있어도 돼." },
  { id: "a4-b64b0a808b", who: "amy", text: "…오늘 '진짜로'는 이미 다 썼으니까, 이건 그냥 하는 말이야.", tag: "[sad] ...오늘 '진짜로'는 이미 다 썼으니까, [short pause] 이건 그냥 하는 말이야." },
  { id: "a4-1291149640", who: "amy", text: "…뭐야? 젖잖아, 너.", tag: "[surprised] ...뭐야? [short pause] 젖잖아, 너." },
  { id: "a4-11d86db176", who: "amy", text: "재킷에서 칩 냄새 나.", tag: "[flustered] 재킷에서 칩 냄새 나." },
  { id: "a4-52a50b5316", who: "amy", text: "싫지 않아. 이상하게 안심돼.", tag: "[flustered] 싫지 않아. [short pause] 이상하게 안심돼." },
  { id: "a4-2f6284c0aa", who: "amy", text: "…근데 진 날이 이긴 날보다 더 기억날 것 같아. 이상하지?", tag: "[sad] ...근데 진 날이 이긴 날보다 더 기억날 것 같아. [short pause] 이상하지?" },
  { id: "a4-6d71be31bb", who: "amy", text: "같이? 너 딜러잖아. 왜 손님 월세를 계산해?", tag: "[surprised] 같이? [short pause] 너 딜러잖아. 왜 손님 월세를 계산해?" },
  { id: "a4-937eda5ca1", who: "amy", text: "…그건 인정.", tag: "[chuckles] ...그건 인정." },
  { id: "a4-32bf39f548", who: "amy", text: "보지 마. 걔한테 오늘 진 거 아직 말 안 했단 말이야.", tag: "[flustered] 보지 마! [short pause] 걔한테 오늘 진 거 아직 말 안 했단 말이야." },
  { id: "a4-310213d63e", who: "amy", text: "오늘은 안 때려. 오늘은… 안아 줄 거야.", tag: "[sad] [softly] 오늘은 안 때려. [short pause] 오늘은... 안아 줄 거야." },
  { id: "a4-e45709c48c", who: "amy", text: "재킷은 내일 빨아서 돌려줄게. 이자는 없어.", tag: "[casual] 재킷은 내일 빨아서 돌려줄게. [short pause] 이자는 없어." },
  { id: "a4-e75dc9fc8b", who: "amy", text: "…그리고 그 사장님. 어제는 아빠 닮았다고 하더니, 오늘은 '아버님은 잘 계시냐'고 물어.", tag: "[sad] ...그리고 그 사장님. [short pause] 어제는 아빠 닮았다고 하더니, 오늘은 '아버님은 잘 계시냐'고 물어." },
  { id: "a4-ad66e6c029", who: "amy", text: "아빠를 진짜 아는 걸까? 아는데 왜 웃으면서 묻지?", tag: "[sad] 아빠를 진짜 아는 걸까? [short pause] 아는데... 왜 웃으면서 묻지?" },
  { id: "a4-08e7d842ec", who: "amy", text: "…너 왜 이렇게 따뜻해?", tag: "[softly] [flustered] ...너 왜 이렇게 따뜻해?" },
  { id: "a4-9f8d239b93c", who: "amy", text: "3초만. 3초만 이러고 있을게. 세지 마.", tag: "[whispers] [shy] 삼 초만. 삼 초만, 이러고 있을게... 세지 마." },
  { id: "a4-67cebb41d1", who: "amy", text: "…어? 잠깐만요, 사장님. 제가 하자고 한 거예요. 딜러는—", tag: "[surprised] ...어? [short pause] 잠깐만요, 사장님! 제가 하자고 한 거예요. 딜러는—" },
  { id: "a4-6deba4aa0e", who: "amy", text: "늦었어. …아, 아니다. 내가 일찍 온 거구나.", tag: "[sulky] 늦었어. [short pause] ...아, 아니다. 내가 일찍 온 거구나." },
  { id: "a4-237bef9160", who: "amy", text: "자, 이거부터 받아.", tag: "[casual] 자, 이거부터 받아." },
  { id: "a4-91156c8843", who: "amy", text: "두 번 빨았어. 칩 냄새가 안 빠져서.", tag: "[casual] 두 번 빨았어. [short pause] 칩 냄새가 안 빠져서." },
  { id: "a4-ca7da9e53e", who: "amy", text: "그래서 딸기로 덮었어. 이제 이거 입으면 너한테서 내 냄새 나.", tag: "[confident] 그래서 딸기로 덮었어. [short pause] 이제 이거 입으면 너한테서 내 냄새 나." },
  { id: "a4-768bcdbce9", who: "amy", text: "…섬유유연제 냄새. 내가 쓰는 거. 그 뜻이야.", tag: "[flustered] ...섬유유연제 냄새. [short pause] 내가 쓰는 거. 그 뜻이야." },
  { id: "a4-86884243d4", who: "amy", text: "알아들은 얼굴이 아닌데? 웃지 마.", tag: "[sulky] 알아들은 얼굴이 아닌데? [short pause] 웃지 마." },
  { id: "a4-4d8264d370", who: "amy", text: "적어 놓고 보니까 좀 무섭다. 나 원래 숫자 안 적거든.", tag: "[nervous] [chuckles] 적어 놓고 보니까 좀 무섭다. [short pause] 나 원래 숫자 안 적거든." },
  { id: "a4-cedb682d18", who: "amy", text: "…그래서 안 적었었나 봐.", tag: "[sad] ...그래서 안 적었었나 봐." },
  { id: "a4-8257e82550", who: "amy", text: "…싫어.", tag: "[sulky] ...싫어." },
  { id: "a4-86a52f54df", who: "amy", text: "돈 빌리면 그날부터 이상해져. 아빠가 그랬어. 친구한테 빌리고, 다음 주에 따서 준다고.", tag: "[sad] 돈 빌리면 그날부터 이상해져. [short pause] 아빠가 그랬어. 친구한테 빌리고, 다음 주에 따서 준다고." },
  { id: "a4-dac6d37381", who: "amy", text: "나는 아빠랑 달라. 내 월세는 내가 낼 거야.", tag: "[determined] 나는 아빠랑 달라. [short pause] 내 월세는 내가 낼 거야." },
  { id: "a4-e88d4daf26", who: "amy", text: "사장님한테? 같이?", tag: "[surprised] 사장님한테? 같이?" },
  { id: "a4-d5ae594d83", who: "amy", text: "싫어, 창피해. 그리고 사장님은 갚으라고도 안 해. 천천히 하래.", tag: "[sulky] 싫어, 창피해. [short pause] 그리고 사장님은 갚으라고도 안 해. 천천히 하래." },
  { id: "a4-f48b7c6fe3", who: "amy", text: "…딜러 명언 2호. 오늘 풍년이네.", tag: "[thoughtful] ...딜러 명언 이 호. [chuckles] 오늘 풍년이네." },
  { id: "a4-f9e6cc594d", who: "amy", text: "알았어. 날짜는 내가 정할게. 사장님 말고, 내가.", tag: "[determined] 알았어. [short pause] 날짜는 내가 정할게. 사장님 말고, 내가." },
  { id: "a4-26ddee8bc3", who: "amy", text: "…나 1+1도 헷갈리는 애야. 뽑아 줄까?", tag: "[sulky] ...나 원 플러스 원도 헷갈리는 애야. [short pause] 뽑아 줄까?" },
  { id: "a4-810bc42730", who: "amy", text: "어느 쪽 반인데?", tag: "[sulky] 어느 쪽 반인데?" },
  { id: "a4-79ee1a669a", who: "amy", text: "…성실도 할 거야. 두고 봐.", tag: "[determined] ...성실도 할 거야. [short pause] 두고 봐." },
  { id: "a4-235589e52d", who: "amy", text: "그때 그 종이네. 직원 할인 30퍼.", tag: "[quietly] 그때 그 종이네. [short pause] 직원 할인 삼십 퍼." },
  { id: "a2-4cd1ebea42u", who: "amy", text: "나 할까 봐, 했었지. 반은 농담이었는데.", tag: "(직접 생성) [sheepish] 나, 할까 봐... 했었지. 반은, 농담이었는데." },
  { id: "a4-b508708bd0", who: "amy", text: "…지금부터 진담. 두고 봐.", tag: "[determined] ...지금부터 진담. [short pause] 두고 봐." },
  { id: "a4-901b68423c", who: "amy", text: "내일 오전 면접. …아, 떨려. 올인할 땐 하나도 안 떨리는데.", tag: "[nervous] 내일 오전 면접. [short pause] ...아, 떨려. 올인할 땐 하나도 안 떨리는데." },
  { id: "a4-47b281e6e0", who: "amy", text: "그 잔소리는 면접 붙고 들을게.", tag: "[sulky] 그 잔소리는 면접 붙고 들을게." },
  { id: "a4-f2f34e7582", who: "amy", text: "근데 딜러. 너도 있지? 빚.", tag: "[curious] 근데 딜러. [short pause] 너도 있지? 빚." },
  { id: "a4-0746929fc9", who: "amy", text: "아까 내 숫자 볼 때, 남의 숫자 보는 얼굴이 아니었어. 거울에서 자주 보는 얼굴이야.", tag: "[confident] 아까 내 숫자 볼 때, 남의 숫자 보는 얼굴이 아니었어. [short pause] 거울에서 자주 보는 얼굴이야." },
  { id: "a4-8499406f09", who: "amy", text: "그럼 우리 둘 다 이번 주는 지옥이네.", tag: "[chuckles] 그럼 우리 둘 다 이번 주는 지옥이네." },
  { id: "a4-780910c261", who: "amy", text: "…지옥 동기. 이거 좀 든든하다.", tag: "[flustered] ...지옥 동기. [short pause] 이거 좀 든든하다." },
  { id: "a4-01095c04dc", who: "amy", text: "동기 첫 회식. 남은 반은 딜러 몫이야. 원래 그래.", tag: "[playful] 동기 첫 회식. [chuckles] 남은 반은 딜러 몫이야. 원래 그래." },
  { id: "a4-be9ea4cbac", who: "amy", text: "지옥은 원래 검소해.", tag: "[confident] 지옥은 원래 검소해." },
  { id: "a4-367a004d05", who: "amy", text: "봐, 명찰. 사흘 수습이지만 이름은 진짜야.", tag: "[proud] 봐, 명찰! [short pause] 사흘 수습이지만 이름은 진짜야." },
  { id: "a2-cb1bf7608d", who: "amy", text: "손님, 1+1은 둘 다 찍히고 하나 값이 빠지는 거예요. 아세요?", tag: "[confident] 손님, 원 플러스 원은 둘 다 찍히고 하나 값이 빠지는 거예요. 아세요?" },
  { id: "a4-86e3da4580", who: "amy", text: "어떤 친절한 아저씨가 알려 줬나? 아니, 계산대가 알려 줬나?", tag: "[teasing] 어떤 친절한 아저씨가 알려 줬나? [chuckles] 아니, 계산대가 알려 줬나?" },
  { id: "a4-7c36dccadd", who: "amy", text: "손님, 포인트 적립하시겠어요?", tag: "[bright] 손님, 포인트 적립하시겠어요?" },
  { id: "a4-fecae8bfe3", who: "amy", text: "해 줘. 수습은 실적이 있어야 돼. 번호 불러.", tag: "[sulky] 해 줘. [short pause] 수습은 실적이 있어야 돼. 번호 불러." },
  { id: "a4-007d8f0654", who: "amy", text: "……알지. 방금 건 연습이야.", tag: "[flustered] ......알지. [short pause] 방금 건 연습이야." },
  { id: "a4-363db15d8e", who: "amy", text: "이건 직원 할인으로 내가 산 거. 내 돈이니까 내 마음이야.", tag: "[confident] 이건 직원 할인으로 내가 산 거. [short pause] 내 돈이니까 내 마음이야." },
  { id: "a4-81bd6e87d6", who: "amy", text: "투자야. 단골 확보 중이야.", tag: "[playful] 투자야. [chuckles] 단골 확보 중이야." },
  { id: "a4-0342d2566c", who: "amy", text: "봤어? 계획표. 적으니까 진짜 덜 무섭다. 네 말이 맞았어.", tag: "[proud] 봤어? 계획표. [short pause] 적으니까 진짜 덜 무섭다. 네 말이 맞았어." },
  { id: "a4-099eb7575f", who: "amy", text: "…근데 칩을 안 만지니까 손이 좀 심심해.", tag: "[sighs] ...근데 칩을 안 만지니까 손이 좀 심심해." },
  { id: "a4-ac5ee5795c", who: "amy", text: "진짜? 딜러 셔플 과외? 수업료 비싸?", tag: "[excited] 진짜? [short pause] 딜러 셔플 과외? 수업료 비싸?" },
  { id: "a4-4cdac0cdd7", who: "amy", text: "싸다. 수상할 정도로.", tag: "[playful] 싸다. [chuckles] 수상할 정도로." },
  { id: "a4-9d86a20cf4", who: "amy", text: "좋아, 예약. 취소 불가야.", tag: "[bright] 좋아, 예약! [short pause] 취소 불가야." },
  { id: "a2-313f7fe5cc", who: "amy", text: "…뭐야? 오늘 왜 이렇게 다정해? 무섭게.", tag: "[flustered] …뭐야?\n오늘 왜 이렇게 다정해? 무섭게." },
  { id: "a4-84e22afe54", who: "amy", text: "그럼 수습 사흘 내내 봐줘.", tag: "[playful] 그럼 수습 사흘 내내 봐줘." },
  { id: "a4-3f28466983", who: "amy", text: "가. 출근해. 딜러 손님은 줄 서야 돼.", tag: "[sulky] 가. 출근해! [short pause] 딜러 손님은, 줄 서야 돼." },
  { id: "a4-7cd17bb868", who: "amy", text: "…늦게 끝나네. 위문품 미지근해졌어.", tag: "[sulky] ...늦게 끝나네. [short pause] 위문품, 미지근해졌어." },
  { id: "a4-6fbc9a2166", who: "amy", text: "오, 딜러의 단골 예약? 그럼 꼭 해야겠다.", tag: "[delighted] 오, 딜러의 단골 예약?! [chuckles] 그럼 꼭 해야겠다." },
  { id: "a2-4226ee0489u", who: "amy", text: "오늘 이겼는데 왜 그런 말을 해?", tag: "(직접 생성) [sulky] 오늘 이겼는데, 왜… 그런 말을 해?" },
  { id: "a2-a1d945bf1fu", who: "amy", text: "그러니까 오늘 가야지. 운 식기 전에.", tag: "(직접 생성) [confident, upbeat] 그러니까 오늘 가야지! 운, 식기 전에." },
  { id: "a4-cac824f804", who: "amy", text: "앞치마는 가게에 두고 왔잖아.", tag: "[softly] 앞치마는 가게에 두고 왔잖아." },
  { id: "a4-6512266df7", who: "amy", text: "자. 계산해 준다며. 계산은 딜러 전문이라며.", tag: "[shy] 자. [short pause] 계산해 준다며. 계산은 딜러 전문이라며." },
  { id: "a4-820f668ba3", who: "amy", text: "오. 딜러 명언 1호다.", tag: "[impressed] 오. [chuckles] 딜러 명언 일 호다." },
  { id: "a2-226e05934du", who: "amy", text: "어서 오세요! …아, 딜러네. 어서 오지 마세요.", tag: "(직접 생성) [bright, cheerful] 어서 오세요! [deadpan] …아, 딜러네. 어서 오지 마세요." },
  { id: "a4-135841d9f7", who: "amy", text: "…뭐야? 왜 그렇게 쉽게 믿어? 의심 좀 해.", tag: "[sad] ...뭐야? [short pause] 왜 그렇게 쉽게 믿어? 의심 좀 해." },
  { id: "a4-4a690f2376", who: "amy", text: "다들 의심하는데. 엄마도, 집주인 아줌마도. '또 그 돈 포커에 넣었지' 하고.", tag: "[sad] 다들 의심하는데. [short pause] 엄마도, 집주인 아줌마도. '또 그 돈 포커에 넣었지' 하고." },
  { id: "a4-6176adadd4", who: "amy", text: "……그런 걸 봐? 진짜 딜러 맞네.", tag: "[surprised] ......그런 걸 봐? [short pause] 진짜, 딜러 맞네." },
  { id: "a4-c446a98f2c", who: "amy", text: "…너까지 그러면, 나 진짜 갈 데 없어.", tag: "[sad] ...너까지 그러면, [short pause] 나 진짜 갈 데 없어." },
  { id: "a4-a8cd75216c", who: "amy", text: "알면 됐어. …아니, 안 됐어. 이따 뭐 하나 사.", tag: "[sulky] 알면 됐어. [short pause] ...아니, 안 됐어. 이따 뭐 하나 사." },
  { id: "a4-ca2b652912", who: "amy", text: "오늘 편의점에 아저씨 하나가 왔어. '외국인 알바는 처음 보네~'", tag: "[sulky] 오늘 편의점에, 아저씨 하나가 왔어. [short pause] '외국인 알바는 처음 보네~'" },
  { id: "a4-1f2bb75b76", who: "amy", text: "'한국말 잘하네~' 하면서, 계산은 안 하고 계속 말 걸어.", tag: "[sulky] '한국말 잘하네~' 하면서, [short pause] 계산은 안 하고 계속 말 걸어." },
  { id: "a4-9141dbb7db", who: "amy", text: "지난주 그 양복 아저씨랑 똑같은 말이야. 이번엔 계산대라 도망도 못 가.", tag: "[quietly] 지난주 그 양복 아저씨랑, 똑같은 말이야. [short pause] 이번엔 계산대라, 도망도 못 가." },
  { id: "a4-4d08fad8aa", who: "amy", text: "웃으면서 '다음 손님!' 했어. 잘했지? 나 웃는 거 잘하잖아.", tag: "[forced brightness] 웃으면서 '다음 손님!' 했어. 잘했지? [short pause] 나, 웃는 거 잘하잖아." },
  { id: "a4-db0524dbde", who: "amy", text: "…너 진짜 이상해. 위로하는 말을 하나도 안 하네.", tag: "[sulky] ...너 진짜 이상해. [short pause] 위로하는 말을, 하나도 안 하네." },
  { id: "a4-eaf87d966c", who: "amy", text: "근데 그게 나아. '괜찮아, 신경 쓰지 마' 들으면 더 신경 쓰이거든.", tag: "[softly] 근데, 그게 나아. [short pause] '괜찮아, 신경 쓰지 마' 들으면, 더 신경 쓰이거든." },
  { id: "a4-29e827040e", who: "amy", text: "화풀이할래. 노래방. …계산은 네가.", tag: "[confident] 화풀이할래. 노래방! [short pause] ...계산은 네가." },
  { id: "a4-8cb95c0d14", who: "amy", text: "앉아 준 건 고마운데, 그거랑 이거랑은 별개야.", tag: "[playful] 앉아 준 건 고마운데, [chuckles] 그거랑 이거랑은 별개야." },
  { id: "a4-517ca9d607c", who: "amy", text: "방이 좁은 거야. 내가 붙은 게 아니라. 이 방 설계한 사람 나와.", tag: "[flustered] [shouting] 방이 좁은 거야! 내가 붙은 게 아니라! 이 방 설계한 사람, 나와!" },
  { id: "a4-fd9cf2aa46", who: "amy", text: "…이거, 아빠가 일요일 아침마다 부르던 노래야. 부엌에서 팬케이크 뒤집으면서.", tag: "[softly] ...이거, 아빠가 일요일 아침마다 부르던 노래야. [short pause] 부엌에서, 팬케이크 뒤집으면서." },
  { id: "a4-626a2eeea1c", who: "amy", text: "아니, 거기서 올라가야지! 아 진짜, 줘 봐!", tag: "[shouting] 아니, 거기서 올라가야지! 아 진짜, 줘 봐!" },
  { id: "a4-71c87b93f7", who: "amy", text: "…0점이래. 한 소절은 불렀는데.", tag: "[sad] ...영 점이래. [short pause] 한 소절은 불렀는데." },
  { id: "a4-19db68ed78", who: "amy", text: "고마워. 안 끊어 줘서. 다들 이럴 때 다음 곡 눌러 버리거든.", tag: "[flustered] 고마워. [short pause] 안 끊어 줘서. 다들 이럴 때, 다음 곡 눌러 버리거든." },
  { id: "a4-8424ffffc8c", who: "amy", text: "…오늘만 어깨 빌려줘. 유료야. 떡볶이로 갚을게.", tag: "[whispers] [shy] ...오늘만, 어깨 빌려줘. 유료야. 떡볶이로 갚을게." },
  { id: "a4-f34227881fc", who: "amy", text: "이자 없음. 지옥 동기 할인.", tag: "[whispers] [amused] 이자 없음. 지옥 동기, 할인." },
  { id: "a4-30b0bf8d48c", who: "amy", text: "딜러. 그 노래 끝까지 들어 준 사람, 처음이야.", tag: "[whispers] [moved] 딜러. ...그 노래 끝까지 들어 준 사람, 처음이야." },
  { id: "a4-fc0f8d3af8c", who: "amy", text: "딜러. 아빠 노래, 나 혼자 부르는 노래인 줄 알았어. 음정은 최악이었지만.", tag: "[whispers] [soft] 딜러. 아빠 노래, 나 혼자 부르는 노래인 줄 알았어. ...음정은, 최악이었지만." },
  { id: "a4-1389fefb61", who: "amy", text: "…다음에 또 와. 그때는 98점 받을 거야. 너도.", tag: "[softly] [flustered] ...다음에 또 와. [short pause] 그때는 구십팔 점 받을 거야. 너도." },
  { id: "a4-74d51048ff", who: "amy", text: "어서 오세… 콜록.", tag: "[hoarse] 어서 오세... [coughs]" },
  { id: "a4-d1a896a50dc", who: "amy", text: "…따뜻해.", tag: "[whispers] [hoarse] ...따뜻해." },
  { id: "a4-bf93d82398u", who: "amy", text: "…야! 반칙!", tag: "(직접 생성) [voice cracking] ...야!! 반칙!" },
  { id: "a4-48fbdf9060c", who: "amy", text: "목 다 나으면 너 진짜 혼난다.", tag: "[whispers] [hoarse, sulky] 목 다 나으면, 너 진짜 혼난다." },
  { id: "a4-d820614d33c", who: "amy", text: "…펍 가서 읽어. 지금 읽으면 죽음.", tag: "[whispers] [hoarse, shy] ...펍 가서 읽어. 지금 읽으면, 죽음." },
  { id: "a4-55361a0d3a", who: "amy", text: "봐. 21만 이체 완료. 반이야, 반. 나머지는 다음 주까지 기다려 준대.", tag: "[proud] 봐! [short pause] 이십일 만, 이체 완료. 반이야, 반! 나머지는 다음 주까지 기다려 준대." },
  { id: "a4-7cacb2b9a0", who: "amy", text: "점장님이 사정 듣고 이번 주 치는 주급으로 당겨 줬어. 수습인데.", tag: "[bright] 점장님이 사정 듣고, 이번 주 치는 주급으로 당겨 줬어. [short pause] 수습인데." },
  { id: "a4-c92e7fc053", who: "amy", text: "집주인 아줌마가 '웬일이니' 했어. 나도 웬일인지 모르겠어.", tag: "[chuckles] 집주인 아줌마가 '웬일이니' 했어. [short pause] 나도 웬일인지 모르겠어." },
  { id: "a4-773594c4de", who: "amy", text: "박수. 크게.", tag: "[proud] 박수. [short pause] 크게!" },
  { id: "a4-8d7279b065", who: "amy", text: "어젯밤 답장 안 한 건 이걸로 퉁쳐 줄게. 박수. 크게.", tag: "[sulky] 어젯밤 답장 안 한 건, 이걸로 퉁쳐 줄게. [short pause] 박수. 크게!" },
  { id: "a4-6112b21ecf", who: "amy", text: "…뭘 봐? 그건 곰 생일 기념이야.", tag: "[flustered] ...뭘 봐? [short pause] 그건, 곰 생일 기념이야." },
  { id: "a4-20d94152b9", who: "amy", text: "곰 옆에 서 있었으니까. 운 좋은 줄 알아.", tag: "[sulky] 곰 옆에 서 있었으니까. [short pause] 운 좋은 줄 알아." },
  { id: "a4-c705d33075", who: "amy", text: "아빠야. 마지막으로 보내 준 사진. 5년 전에.", tag: "[softly] 아빠야. [short pause] 마지막으로 보내 준 사진. 오 년 전에." },
  { id: "a4-5bc44c79e8", who: "amy", text: "…말 안 했지? 아빠, 5년 전에 한국 들어오고 나서 연락이 끊겼어.", tag: "[sad] ...말 안 했지? [short pause] 아빠, 오 년 전에 한국 들어오고 나서, 연락이 끊겼어." },
  { id: "a4-6af3f03bc4", who: "amy", text: "경찰이 알아낸 건 하나. 마지막으로 간 데가 성수동 어느 포커장이래.", tag: "[sad] 경찰이 알아낸 건 하나. [short pause] 마지막으로 간 데가, 성수동 어느 포커장이래." },
  { id: "a4-42aaeda6a3", who: "amy", text: "뒤에 적혀 있어. 'Lucky chip! — Seoul'. 이 칩 들고 엄청 자랑했어.", tag: "[bright] 뒤에 적혀 있어. 'Lucky chip! — Seoul'. [chuckles] 이 칩 들고, 엄청 자랑했어." },
  { id: "a4-2cd99ab1fe", who: "amy", text: "……똑같아.", tag: "[stunned] ......똑같아." },
  { id: "a4-cb9e646707u", who: "amy", text: "이 칩. 아빠 사진이랑 똑같아. 테두리 무늬까지 하나도 안 달라.", tag: "(직접 생성) [stunned, quiet] 이 칩... 아빠 사진이랑, 똑같아. 테두리 무늬까지, 하나도 안 달라." },
  { id: "a4-bbd5ee5210", who: "amy", text: "성수동 포커장. …우리 가게도 성수동이야.", tag: "[sad] 성수동 포커장. [short pause] ...우리 가게도, 성수동이야." },
  { id: "a4-0a7145eb98", who: "amy", text: "아빠가 마지막으로 간 데, 성수동 포커 치는 데라고 했잖아.", tag: "[sad] 아빠가 마지막으로 간 데, [short pause] 성수동 포커 치는 데라고 했잖아." },
  { id: "a4-f91a2cdbf1", who: "amy", text: "…설마.", tag: "[sad] ...설마." },
  { id: "a4-4b79332331", who: "amy", text: "……응. 약속할게.", tag: "[quietly] ......응. [short pause] 약속할게." },
  { id: "a4-a1f84791fd", who: "amy", text: "……워커. 우리 아빠 성이야.", tag: "[stunned] ......워커. [short pause] 우리 아빠 성이야." },
  { id: "a4-5b36c108b1", who: "amy", text: "……아래층.", tag: "[sad] ......아래층." },
  { id: "a4-8b394258ac", who: "amy", text: "거기구나. 아빠가 진 데. 사장님이 '아버님 닮았다'고 한 거, 그냥 하는 말이 아니었어.", tag: "[sad] 거기구나. 아빠가 진 데. [short pause] 사장님이 '아버님 닮았다'고 한 거, 그냥 하는 말이 아니었어." },
  { id: "a4-4e7f2266af", who: "amy", text: "고마워. 숨기지 않아 줘서. 다들 나한테는 숨겨. 엄마도.", tag: "[softly] 고마워. [short pause] 숨기지 않아 줘서. 다들 나한테는 숨겨. 엄마도." },
  { id: "a4-16b8e031b6", who: "amy", text: "근데 딜러. 나 이제 그냥은 못 있을 것 같아.", tag: "[determined] 근데, 딜러. [short pause] 나 이제, 그냥은 못 있을 것 같아." },
  { id: "a4-c2d9f72d1a", who: "amy", text: "봤지? 첫 번째. 매주 할 거야.", tag: "[proud] 봤지? 첫 번째! [short pause] 매주 할 거야." },
  { id: "a4-3f01888c7c", who: "amy", text: "…네? 어떻게 아세요?", tag: "[surprised] ...네? [short pause] 어떻게 아세요?" },
  { id: "a4-578765ce0f", who: "amy", text: "저… 이모님. 워커라는 사람, 기억하세요?", tag: "[nervous] 저... 이모님. [short pause] 워커라는 사람, 기억하세요?" },
  { id: "a4-394c57e5f3", who: "amy", text: "……아빠가 그런 말을 했어요?", tag: "[sad] ......아빠가, 그런 말을 했어요?" },
  { id: "a4-0d3896890dc", who: "amy", text: "…하나도 안 매워요.", tag: "[crying] ...하나도, 안 매워요..." },
  { id: "a4-30b0870ea2", who: "amy", text: "옆에 있어 줘서… 고마워. 너 없었으면 못 먹었어.", tag: "[softly] [flustered] 옆에 있어 줘서... 고마워. [short pause] 너 없었으면, 못 먹었어." },
  { id: "a4-25b0048fe5", who: "amy", text: "알바 갔다 올게. 울어서 눈 부은 거, 손님한테는 비밀이야.", tag: "[bright] 알바 갔다 올게. [chuckles] 울어서 눈 부은 거, 손님한테는 비밀이야." },
  { id: "a4-43cd6d7ee6", who: "amy", text: "아직 안 갔지? 다행이다.", tag: "[relieved] 아직 안 갔지? [short pause] 다행이다." },
  { id: "a4-13c0f80b9f", who: "amy", text: "집에 갔다가 다시 나왔어. 혼자 있으니까 아빠 생각만 나서.", tag: "[quietly] 집에 갔다가 다시 나왔어. [short pause] 혼자 있으니까, 아빠 생각만 나서." },
  { id: "a4-c5ce717059", who: "amy", text: "나랑 내기해. 칩 말고 이걸로.", tag: "[playful] 나랑 내기해. [short pause] 칩 말고, 이걸로." },
  { id: "a4-d9c11a8282", who: "amy", text: "이건 사탕이야. 돈 아니야. 그리고 마감 후야. 손님도 사장님도 없어. 그러니까 괜찮아.", tag: "[confident] 이건 사탕이야. 돈 아니야. [short pause] 그리고 마감 후야. 손님도 사장님도 없어. 그러니까, 괜찮아." },
  { id: "a4-0ff620399c", who: "amy", text: "조건. 내가 지면… 내일 해 뜰 때까지 존댓말 해 줄게.", tag: "[confident] 조건. [short pause] 내가 지면... 내일 해 뜰 때까지, 존댓말 해 줄게." },
  { id: "a4-62dee47791", who: "amy", text: "그리고 내가 이기면…", tag: "[hesitant] 그리고, 내가 이기면..." },
  { id: "a4-3c8cbdd5c3c", who: "amy", text: "…머리 쓰다듬어 줘.", tag: "[whispers] [shy] ...머리, 쓰다듬어 줘." },
  { id: "a4-b3ec8bc0e6c", who: "amy", text: "아니, 방금 거 취소! …아니, 취소 안 해! 이긴 사람 기분 좋게 해 주는 게 원래 조건이야!", tag: "[panicked] [shouting] 아니, 방금 거 취소! ...아니, 취소 안 해! 이긴 사람 기분 좋게 해 주는 게, 원래 조건이야!" },
  { id: "a4-82ebe14fbcc", who: "amy", text: "이, 이건 무효야! 내기를 안 했는데 왜 상부터 줘! 순서가 틀렸잖아!", tag: "[flustered] [shouting] 이, 이건 무효야! 내기를 안 했는데, 왜 상부터 줘?! 순서가 틀렸잖아!" },
  { id: "a4-1a0ae0c20f", who: "amy", text: "다음엔 진짜 내기해서 따낼 거야. 공짜는 싫어.", tag: "[sulky] 다음엔, 진짜 내기해서 따낼 거야. [short pause] 공짜는 싫어." },
  { id: "a4-cb3bc3d8b6", who: "amy", text: "근데 오늘은… 공짜도 좀 괜찮았어.", tag: "[softly] [shyly] 근데 오늘은... 공짜도 좀 괜찮았어." },
  { id: "a4-7214f3c09d", who: "amy", text: "졌다. 진짜로 졌다.", tag: "[sulky] 졌다. [short pause] 진짜로 졌다." },
  { id: "a4-9e43a6b098", who: "amy", text: "……알겠어요. 내일 해 뜰 때까지 존댓말이에요. 딜러님.", tag: "[flustered] ......알겠어요. [short pause] 내일 해 뜰 때까지, 존댓말이에요. 딜러님." },
  { id: "a4-b6d547016ccu", who: "amy", text: "으아악! 딜러님이 뭐야, 딜러님이! 혀가 꼬여!", tag: "(직접 생성) [mortified, whiny] 으아악! 딜러님이 뭐야, 딜러님이! 혀가, 꼬여!" },
  { id: "a4-68e6addb03", who: "amy", text: "네에. 해 뜰 때까지요. 시계 보고 있을 거예요.", tag: "[sulky] 네에. [short pause] 해 뜰 때까지요. 시계 보고 있을 거예요." },
  { id: "a4-74bcfd9fecu", who: "amy", text: "근데요. 존댓말로 하니까 이상한 말도 할 수 있을 것 같네요.", tag: "(직접 생성) [softly] 근데요. [short pause] 존댄말로 하니까, 이상한 말도 할 수 있을 것 같네요." },
  { id: "a4-2c2df19dacc", who: "amy", text: "…오늘, 딜러님 있어서 버텼어요. 반말이면 못 할 말이에요, 이거.", tag: "[whispers] [shy] ...오늘, 딜러님 있어서 버텼어요. 반말이면 못 할 말이에요, 이거." },
  { id: "a4-1f9214228cu", who: "amy", text: "…아. 조건 있었지.", tag: "(직접 생성) [flustered] ...아. [short pause] [shyly] 조건, 있었지." },
  { id: "a4-e21f3343c1", who: "amy", text: "빨리 해. 한 번. 딱 한 번만이야. 대충 해도 돼.", tag: "[flustered] 빨리 해. 한 번! [short pause] 딱 한 번만이야. 대충 해도 돼." },
  { id: "a4-b5e5a3846bc", who: "amy", text: "한 번만이랬잖아. 반칙이야.", tag: "[whispers] [sulky] 한 번만이랬잖아... 반칙이야." },
  { id: "a4-e7408cc88cc", who: "amy", text: "근데 이번만 봐줄게. 이긴 사람이 기분 좋으니까.", tag: "[whispers] [soft] 근데, 이번만 봐줄게. 이긴 사람이, 기분 좋으니까." },
  { id: "a4-448b45b167", who: "amy", text: "앉으러 온 거 아니야. 구경하러 왔어. 손님 말고 구경꾼으로.", tag: "[casual] 앉으러 온 거 아니야. [short pause] 구경하러 왔어. 손님 말고, 구경꾼으로." },
  { id: "a4-7cc58857a1", who: "amy", text: "딜러 일하는 거 구경하는 구경꾼. 입장료는 콜라값이야.", tag: "[playful] 딜러 일하는 거 구경하는 구경꾼. [chuckles] 입장료는 콜라값이야." },
  { id: "a4-6855e0ec8e", who: "amy", text: "그럼 혼잣말할게. …딜러 오늘 셔츠 다렸네. 혼잣말이야.", tag: "[playful] 그럼 혼잣말할게. [short pause] ...딜러, 오늘 셔츠 다렸네. 혼잣말이야." },
  { id: "a4-40f2ceb696", who: "amy", text: "태양은 귀 막아.", tag: "[sulky] 태양은, 귀 막아." },
  { id: "a4-b87f8345cb", who: "amy", text: "…아빠를, 아세요?", tag: "[surprised] ...아빠를, 아세요?" },
  { id: "a4-5fee3dc50f", who: "amy", text: "…언니가 뭔데요?", tag: "[sulky] ...언니가 뭔데요?" },
  { id: "a4-caa71ab955", who: "amy", text: "있거든요. 편의점 우산. 직원 할인으로 산 거.", tag: "[sulky] 있거든요. [short pause] 편의점 우산. 직원 할인으로 산 거." },
  { id: "a4-be506c267e", who: "amy", text: "…아빠 자리가 그대로래. 5년 동안.", tag: "[sad] ...아빠 자리가, 그대로래. [short pause] 오 년 동안." },
  { id: "a4-ec2c3e1666", who: "amy", text: "나 거기 앉으면, 아빠가 어떤 기분이었는지 알 것 같아.", tag: "[quietly] 나, 거기 앉으면, [short pause] 아빠가 어떤 기분이었는지 알 것 같아." },
  { id: "a4-4bb266b667", who: "amy", text: "딜러는 알아? 그 기분?", tag: "[sad] 딜러는 알아? [short pause] 그 기분?" },
  { id: "a4-5fc48b8041", who: "amy", text: "……그래서 앉지 않는구나. 너.", tag: "[sad] ......그래서, 앉지 않는구나. 너." },
  { id: "a4-dd725c99d4", who: "amy", text: "손가락 걸어. 말로 하는 약속은 잘 까먹어서.", tag: "[softly] 손가락 걸어. [short pause] 말로 하는 약속은, 잘 까먹어서." },
  { id: "a4-5bf72a9c9a", who: "amy", text: "기억해. 말로 했지.", tag: "[quietly] 기억해. [short pause] 말로 했지." },
  { id: "a4-5894f40c34", who: "amy", text: "…이번엔 손가락으로 하자. 말은 자꾸 미끄러져.", tag: "[softly] ...이번엔, 손가락으로 하자. [short pause] 말은 자꾸 미끄러져." },
  { id: "a4-14b9487aec", who: "amy", text: "딜러는 아래층 싫어하잖아. 앉지도 않고.", tag: "[surprised] 딜러는, 아래층 싫어하잖아. [short pause] 앉지도 않고." },
  { id: "a4-c3b09e87e3", who: "amy", text: "…그런 말 하면, 진짜 그날 부른다?", tag: "[flustered] ...그런 말 하면, [short pause] 진짜 그날 부른다?" },
  { id: "a4-caec32b9dac", who: "amy", text: "약속이야. 손가락 걸어.", tag: "[whispers] [shy] 약속이야. ...손가락 걸어." },
  { id: "a4-ffffe162b0", who: "amy", text: "태양은 눈도 막아.", tag: "[sulky] 태양은, 눈도 막아." },
  { id: "a4-7b64580dab", who: "amy", text: "딜러. 나 요즘 좀 이상해.", tag: "[quietly] 딜러. [short pause] 나, 요즘 좀 이상해." },
  { id: "a4-afe73db569", who: "amy", text: "이긴 날도, 진 날도. 월세 낸 날도, 아빠 사진 본 날도.", tag: "[softly] 이긴 날도, 진 날도. [short pause] 월세 낸 날도, 아빠 사진 본 날도." },
  { id: "a4-be13b97853", who: "amy", text: "…제일 먼저 너한테 말하고 싶어. 매번.", tag: "[softly] [flustered] ...제일 먼저, 너한테 말하고 싶어. [short pause] 매번." },
  { id: "a4-a29fdfb80fc", who: "amy", text: "너는? …너는 안 이상해?", tag: "[whispers] [nervous] 너는? ...너는, 안 이상해?" },
  { id: "a3-b1ffded65b", who: "amy", text: "딜러 바뀌었네? 새 사람이다!", tag: "[excited] 딜러 바뀌었네? 새 사람이다!! [chuckles]" },
  { id: "a2-f7ab3334c5u", who: "amy", text: "잘됐다. 전 딜러는 손이 불길했거든. 오늘은 무조건 내가 이겨.", tag: "(직접 생성) [confident] 잘됐다. 전 딜러 손이 불길했거든. 오늘은 무조건 내가 이겨." },
  { id: "a3-095e24b60f", who: "amy", text: "나는 진짜야. 봐, 오늘 양말도 승리의 하늘색.", tag: "[confident] 나는 진짜야. [chuckles] 봐, 오늘 양말도 승리의 하늘색!" },
  { id: "a3-12173be96ev", who: "amy", text: "시끄러워, 태양. 오늘은 네 칩 전부 내 거야.", tag: "[sulky, playful] 시끄러워, 태양. [confident] 오늘은 네 칩 전부, 내 거야." },
  { id: "a3-d63cfa2146", who: "amy", text: "열네 번 지면 열다섯 번째는 이길 확률이 올라가는 거야. 수학 몰라?", tag: "[confident] 열네 번 지면... 열다섯 번째는 이길 확률이 올라가는 거야! [chuckles] 수학 몰라?" },
  { id: "a3-3c72eef664c", who: "amy", text: "올인! 이번엔 진짜야!", tag: "[excited] [shouting] 올인! 이번엔, 진짜야!" },
  { id: "a3-c8e6e67144", who: "amy", text: "용감한 거 맞거든? 7·2로 이기면 전설이 되는 거라고.", tag: "[sulky] 용감한 거 맞거든? [short pause] 칠 이로 이기면 전설이 되는 거라고...!" },
  { id: "a3-f25e955e26v", who: "amy", text: "…딜러, 첫날부터 말 세게 하네?", tag: "[surprised, a little impressed] ...딜러, 첫날부터 말 세게 하네?" },
  { id: "a3-afb67c4b5f", who: "amy", text: "좋아. 마음에 들었어. 복수 명단 1번으로 올려 줄게.", tag: "[confident] 좋아. [chuckles] 마음에 들었어. [short pause] 복수 명단 1번으로 올려 줄게!" },
  { id: "a3-942880c4c9", who: "amy", text: "'아마'는 빼. 그거 붙이면 위로가 아니라 확률 발표야.", tag: "[sulky] [annoyed] '아마'는 빼. [short pause] 그거 붙이면 위로가 아니라 확률 발표야." },
  { id: "a2-c0df6e5a17u", who: "amy", text: "봐, 또 붙였어!", tag: "(직접 생성) [exasperated] 봐, 또 붙였어!" },
  { id: "a3-ac5d1f5bbf", who: "amy", text: "…와. 진짜 아무 말도 안 하네.", tag: "[sighs] …와. [annoyed] 진짜 아무 말도 안 하네!" },
  { id: "a3-0fb263a66c", who: "amy", text: "위로도 안 하고, 놀리지도 않고. 차라리 놀리는 게 덜 아파.", tag: "[sulky] 위로도 안 하고... 놀리지도 않고. [sighs] 차라리 놀리는 게 덜 아파." },
  { id: "a3-8bca2647e6", who: "amy", text: "근데 딜러, 이름 뭐야?", tag: "[curious] 근데 딜러, 이름 뭐야? [short pause]" },
  { id: "a2-a76bf71c36", who: "amy", text: "이건 팁. 딜러 손 빠르더라. 그건 인정.", tag: "[warmly] 이건 팁.\n딜러 손 빠르더라. 그건 인정." },
  { id: "a3-20006957f4", who: "amy", text: "이긴 날 주면 당연한 거잖아. 진 날 줘야 기억에 남지.", tag: "[confident] 이긴 날 주면 당연한 거잖아. [chuckles] 진 날 줘야 기억에 남지." },
  { id: "a3-c28d67f0f6", who: "amy", text: "딜러! 나 왔어. 어제 복수한다고 했지? 기억하지?", tag: "[confident] 딜러! 나 왔어. [short pause] 어제 복수한다고 했지? 기억하지?" },
  { id: "a2-7272263267u", who: "amy", text: "아, 낮에 삼각김밥 반 준 건 그거고. 복수는 복수야.", tag: "(직접 생성) [matter-of-fact] 아, 낮에 삼각김밥 반 준 건 그거고. 복수는 복수야." },
  { id: "a3-7fd2e6c9f8", who: "amy", text: "오늘은 카드 운이 아니라 실력으로 이길 거야. 어젯밤에 영상 세 개 봤거든.", tag: "[confident] 오늘은 카드 운이 아니라 실력으로 이길 거야! [chuckles] 어젯밤에 영상 세 개 봤거든." },
  { id: "a3-a63247a861", who: "amy", text: "…딜러. 카드 이상하게 주는 거 아니지?", tag: "[sulky] [sighs] ...딜러. 카드 이상하게 주는 거 아니지?" },
  { id: "a3-412392e989", who: "amy", text: "그럼 섞을 때 나한테 좋은 마음을 좀 담아 봐.", tag: "[confident] 그럼 섞을 때... 나한테 좋은 마음을 좀 담아 봐! [chuckles]" },
  { id: "a3-ef37a86f28", who: "amy", text: "규정 진짜 많네, 이 가게.", tag: "[sighs] [sulky] 규정 진짜 많네, 이 가게!" },
  { id: "a3-dfd1e693d3", who: "amy", text: "좋아. 그럼 딜러 너랑 붙을래. 손님 다 빠지면, 우리 둘이 딱 한 판.", tag: "[confident] 좋아. 그럼 딜러 너랑 붙을래. [short pause] 손님 다 빠지면, 우리 둘이 딱 한 판!" },
  { id: "a3-03e2d7371e", who: "amy", text: "진 사람이 딸기우유 사기. 콜?", tag: "[excited] 진 사람이 딸기우유 사기! 콜?" },
  { id: "a3-004a74c63a", who: "amy", text: "사장님 없잖아. 그리고 딸기우유 하나에 규정까지 꺼내는 거, 너무 쫄보 같은데?", tag: "[confident] 사장님 없잖아... [chuckles] 그리고 딸기우유 하나에 규정까지 꺼내는 거, 너무 쫄보 같은데?!" },
  { id: "a3-7c32bb3090", who: "amy", text: "에이, 재미없어.", tag: "[sulky] [sighs] 에이, 재미없어..." },
  { id: "a3-2fcdb8d310", who: "amy", text: "손님이 진짜로 하자고 해도 안 돼?", tag: "[thoughtful] 손님이 진짜로 하자고 해도 안 돼...?" },
  { id: "a3-1029967f06", who: "amy", text: "…그거 무슨 뜻이야? 멋있는 척이야?", tag: "[sulky] ...그거 무슨 뜻이야? [annoyed] 멋있는 척이야?!" },
  { id: "a3-e762177493c", who: "amy", text: "또 규정!", tag: "[annoyed] [shouting] 또, 규정...!" },
  { id: "a3-c24bcc3aa4", who: "amy", text: "근데 좀 웃기다. 딸기우유 하나 걸었는데 딜러가 세상 진지해.", tag: "[laughs] 근데 좀 웃기다... [chuckles] 딸기우유 하나 걸었는데 딜러가 세상 진지해!" },
  { id: "a3-ca28c6734b", who: "amy", text: "좋아. 오늘은 봐줄게. 대신 언젠가 꼭 앉혀서 이긴다. 그게 내 이번 달 목표야.", tag: "[confident] 좋아. [chuckles] 오늘은 봐줄게. [short pause] 대신 언젠가 꼭 앉혀서 이긴다! 그게 내 이번 달 목표야." },
  { id: "a3-4429d5ab13c", who: "amy", text: "오, 앉았다! 앉았어! 태양, 봤어?", tag: "[excited] [shouting] 오, 앉았다! 앉았어! 태양, 봤어?!" },
  { id: "a3-6842994380", who: "amy", text: "딜러, 손 떨려? 지금이라도 도망가면 딸기우유 반값으로 해 줄게.", tag: "[confident] 딜러, 손 떨려? [chuckles] 지금이라도 도망가면 딸기우유 반값으로 해 줄게!" },
  { id: "a3-f612011da2", who: "amy", text: "접은 사람이 진 거야. 딸기우유는 네가 사.", tag: "[sulky] 접은 사람이 진 거야... [sighs] 딸기우유는 네가 사!" },
  { id: "a3-14d6fad50ev", who: "amy", text: "잠깐. 탑 페어 탑 키커로 왜 접어? 내가 셋인 거 어떻게 알았어?", tag: "[surprised] 잠깐. [puzzled, frustrated] 탑 페어 탑 키커로 왜 접어? 내가 셋인 거, 어떻게 알았어?" },
  { id: "a3-52229ea2e3", who: "amy", text: "그거 아무한테도 말하지 마. 딜러랑 나만 아는 거야.", tag: "[whisper] [flustered] 그거 아무한테도 말하지 마... [short pause] 딜러랑 나만 아는 거야." },
  { id: "a3-31dfc0705e", who: "amy", text: "대신 공평하게 너도 하나 알려 줘. 네 버릇.", tag: "[confident] 대신 공평하게 너도 하나 알려 줘... 네 버릇? [chuckles]" },
  { id: "a3-da51461077", who: "amy", text: "방금 눈썹 움직였어. 하나 찾았다.", tag: "[confident] 방금 눈썹 움직였어... [chuckles] 하나 찾았다!" },
  { id: "a3-fd4822f9e3c", who: "amy", text: "태양! 딜러 이겼어! 사진 찍어, 사진!", tag: "[excited] [shouting] 태양! 딜러 이겼어! 사진 찍어, 사진!" },
  { id: "a3-cd608b45ce", who: "amy", text: "진짜 사 왔네. 농담 반이었는데.", tag: "[surprised] 진짜 사 왔네... [chuckles] 농담 반이었는데!" },
  { id: "a3-224de50018", who: "amy", text: "빨대는 네가 꽂아 줘. 이긴 사람 특권이야.", tag: "[confident] [chuckles] 빨대는 네가 꽂아 줘. 이긴 사람 특권이야!" },
  { id: "a3-1b389d4fe8", who: "amy", text: "아 맞다. 딜러, 폰 줘 봐.", tag: "[thoughtful] 아 맞다. 딜러, 폰 줘 봐." },
  { id: "a3-08d4aa9b44v", who: "amy", text: "복수할 상대가 도망가면 안 되잖아. 번호 찍어 줘.", tag: "[confident, playful] 복수할 상대가 도망가면 안 되잖아. 번호 찍어 줘." },
  { id: "a3-8400b27a75", who: "amy", text: "에이미는 너무 평범하잖아. 이게 더 기억나.", tag: "[confident] 에이미는 너무 평범하잖아. [thoughtful] 이게 더 기억나!" },
  { id: "a3-b3f2b0e224", who: "amy", text: "그리고 그 존댓말 이제 그만해. 나 스물둘. 너는?", tag: "[thoughtful] 그리고 그 존댓말 이제 그만해. [chuckles] 나 스물둘. 너는?" },
  { id: "a3-35a44f3a4f", who: "amy", text: "아저씨네.", tag: "[confident] 아저씨네... [chuckles]" },
  { id: "a3-055dc47213", who: "amy", text: "오, 바로 하네? 그거 좋다.", tag: "[bright] 오, 바로 하네? [chuckles] 그거 좋다!" },
  { id: "a3-2d53a6998a", who: "amy", text: "그리고 그 존댓말 이제 그만해. 편의점에서 나이도 깠잖아, 아저씨.", tag: "[chuckles] 그리고 그 존댓말 이제 그만해. [short pause] 편의점에서 나이도 깠잖아, 아저씨!" },
  { id: "a3-7bc44a47a5", who: "amy", text: "마감했잖아. 그 말도 퇴근했어.", tag: "[confident] 마감했잖아... [chuckles] 그 말도 퇴근했어!" },
  { id: "a3-aac3ddcac6", who: "amy", text: "나 간다, 딜러 아저씨. 내일은 칩 많이 들고 올게.", tag: "[confident] 나 간다, 딜러 아저씨! [chuckles] 내일은 칩 많이 들고 올게..." },
  { id: "a3-cdd9644788", who: "amy", text: "딜러! 나 오늘은 관전만 할 거야. 관전은 공짜잖아.", tag: "[bright] 딜러! [chuckles] 나 오늘은 관전만 할 거야. [thoughtful] 관전은 공짜잖아!" },
  { id: "a3-15aac5ff3e", who: "amy", text: "그건… 전략적 후퇴. 오늘은 적을 관찰하는 날이야.", tag: "[chuckles] [confident] 그건… 전략적 후퇴. [thoughtful] 오늘은 적을 관찰하는 날이야!" },
  { id: "a3-663e15e5d0", who: "amy", text: "근데 너, 답장은 안 하면서 '세 배'는 읽었네?", tag: "[sulky] [clears throat] 근데 너, 답장은 안 하면서 '세 배'는 읽었네?!" },
  { id: "a3-0787d81b08", who: "amy", text: "그게 더 나빠. 관찰 일지에 적어 둘 거야.", tag: "[sulky] 그게 더 나빠... [thoughtful] 관찰 일지에 적어 둘 거야!" },
  { id: "a3-a8f771b3a1", who: "amy", text: "저기 안경 아저씨. 지금 블러프지? 딸기우유 걸고.", tag: "[confident] 저기 안경 아저씨. [chuckles] 지금 블러프지? [excited] 딸기우유 걸고!" },
  { id: "a3-04ef94e703", who: "amy", text: "그럼 내가 혼자 걸게. 블러프에 하나.", tag: "[confident] 그럼 내가 혼자 걸게. [short pause] 블러프에 하나." },
  { id: "a3-d479548af7v", who: "amy", text: "…방금 건 연습 문제였어.", tag: "[sulky, embarrassed] ...방금 건, 연습 문제였어." },
  { id: "a3-1c72706884", who: "amy", text: "…와. 방금 그거 뭐야? 칩이 알아서 걸어갔어.", tag: "[surprised] ...와! 방금 그거 뭐야? [short pause] 칩이 알아서 걸어갔어!" },
  { id: "a3-b82e06fe5c", who: "amy", text: "딜러, 손에 자석 붙였지? 검사할 거야.", tag: "[confident] 딜러, 손에 자석 붙였지? [annoyed] 검사할 거야!" },
  { id: "a3-6ebab96841", who: "amy", text: "1+1인데 왜 둘 다 찍혀요? …아, 몰라. 낼게요. 잠깐만요, 백 원짜리 하나 더 있어요.", tag: "[sulky] 원 플러스 원인데 왜 둘 다 찍혀요? [short pause] …아, 몰라. [sighs] 낼게요. 잠깐만요, 백 원짜리 하나 더 있어요." },
  { id: "a2-4b491c60f7", who: "amy", text: "오, 천사다. 고마—", tag: "[warmly] 오, 천사다. 고마—" },
  { id: "a3-7371415abd", who: "amy", text: "…설마 지금 동전 센 거 다 봤어?", tag: "[surprised] ...설마 지금 동전 센 거 다 봤어?" },
  { id: "a2-b9b5cf3192u", who: "amy", text: "그건 잊어. 딜러는 손님 비밀 지키는 거잖아.", tag: "(직접 생성) [flustered] 그건 잊어. 딜러는 손님 비밀 지키는 거잖아." },
  { id: "a2-6f5fb5a18d", who: "amy", text: "와, 그런 건 칼같이 지키네.", tag: "[annoyed, sulky] 와, 그런 건 칼같이 지키네." },
  { id: "a3-e9ea1f8d66", who: "amy", text: "근데 몇 살이야? 말투가 딱 회사원인데.", tag: "[thoughtful] 근데 몇 살이야? [chuckles] 말투가 딱 회사원인데." },
  { id: "a3-b76a86f771", who: "amy", text: "아저씨네. 나 스물둘. 그러니까 나는 계속 반말.", tag: "[smug] 아저씨네. [short pause] 나 스물둘. [chuckles] 그러니까 나는 계속 반말." },
  { id: "a2-6c7b306760u", who: "amy", text: "아까부터 '요' 꼬박꼬박 붙이던데? 그대로 해.", tag: "(직접 생성) [casual, bossy] 아까부터 '요' 꼬박꼬박 붙이던데? 그대로 해." },
  { id: "a3-a14b2648fb", who: "amy", text: "어, 딜러 아저씨? 여기서 뭐 해? 따라왔어?", tag: "[surprised] 어, 딜러 아저씨? [short pause] 여기서 뭐 해? 따라왔어?" },
  { id: "a3-90f5586a4c", who: "amy", text: "…설마 동전 센 거 다 봤어?", tag: "[surprised] ...설마 동전 센 거 다 봤어? [chuckles nervously]" },
  { id: "a3-0c5944c439", who: "amy", text: "그건 잊어. 손님 비밀이야.", tag: "[sighs] [sulky] 그건 잊어... [whisper] 손님 비밀이야." },
  { id: "a3-99aa16e06f", who: "amy", text: "하나 먹어. 1+1은 원래 둘이 먹으라고 있는 거야.", tag: "[happy] 하나 먹어. [chuckles] 원 플러스 원은 원래 둘이 먹으라고 있는 거야!" },
  { id: "a3-e6e6c9123f", who: "amy", text: "그러니까 더 맛있게 먹어. 내 전 재산의 절반이야.", tag: "[confident] 그러니까 더 맛있게 먹어... [chuckles] 내 전 재산의 절반이야!" },
  { id: "a3-137e279900", who: "amy", text: "봤어? 이건 내가 너보다 잘해.", tag: "[confident] 봤어? [chuckles] 이건 내가 너보다 잘해!" },
  { id: "a3-90174149db", who: "amy", text: "포커도 잘해. 결과가 못 따라올 뿐이야.", tag: "[sulky] 포커도 잘해... [sighs] 결과가 못 따라올 뿐이야!" },
  { id: "a3-c9ff9ccd0b", who: "amy", text: "엄마가 한국 사람이거든. 아빠는 미국 사람이고.", tag: "[bright] 엄마가 한국 사람이거든. [thoughtful] 아빠는 미국 사람이고." },
  { id: "a3-ee0df628b8", who: "amy", text: "미국에선 동양 애, 한국에선 외국인. 어딜 가도 '어디서 왔어요?'부터 나와.", tag: "[sighs] 미국에선 동양 애, 한국에선 외국인... [annoyed] 어딜 가도 '어디서 왔어요?'부터 나와." },
  { id: "a3-94f49880f1", who: "amy", text: "근데 포커 테이블은 아무도 안 물어봐. 칩만 봐. 그게 좋아.", tag: "[bright] 근데 포커 테이블은 아무도 안 물어봐... 칩만 봐. [chuckles] 그게 좋아!" },
  { id: "a2-5f8fd4f688", who: "amy", text: "그리고 이기려고. 그게 더 커.", tag: "[playful] 그리고 이기려고. 그게 더 커." },
  { id: "a3-3ea8a86cb8", who: "amy", text: "…방금 뭐 삼켰지? 괜찮아. 엄마가 한국 사람이거든. 그런 말은 하도 들어서 이젠 좀 웃겨.", tag: "[thoughtful] ...방금 뭐 삼켰지? [chuckles] 괜찮아. [softly] 엄마가 한국 사람이거든. 그런 말은 하도 들어서 이젠 좀 웃겨." },
  { id: "a3-2654600ebe", who: "amy", text: "목요일엔 좀 안 웃겼지만.", tag: "[sad] 목요일엔... 좀 안 웃겼지만." },
  { id: "a3-fe155f1e57", who: "amy", text: "응. 그 아저씨 때문에 안 가면 내가 지는 거잖아.", tag: "[confident] 응... [clears throat] 그 아저씨 때문에 안 가면 내가 지는 거잖아!" },
  { id: "a3-02507cbf13", who: "amy", text: "집주인 아줌마. 날짜 아직 멀었는데 미리미리 하시는 분이야.", tag: "[thoughtful] 집주인 아줌마... [sighs] 날짜 아직 멀었는데 미리미리 하시는 분이야." },
  { id: "a3-bf017bdd54", who: "amy", text: "괜찮아. 이번 주는 삼각김밥 주간이고, 다음 주엔 이기면 돼.", tag: "[bright] 괜찮아. [chuckles] 이번 주는 삼각김밥 주간이고, 다음 주엔 이기면 돼!" },
  { id: "a3-a917217959", who: "amy", text: "딜러가 손님한테 펍을 쉬라고 해도 돼? 사장님이 들으면 울겠다.", tag: "[chuckles] 딜러가 손님한테 펍을 쉬라고 해도 돼? [thoughtful] 사장님이 들으면 울겠다... [laughing]" },
  { id: "a3-a5e0c85762", who: "amy", text: "밥은 콜. 얻어먹는 건 내가 원래 잘해.", tag: "[bright] 밥은 콜! [chuckles] 얻어먹는 건 내가 원래 잘해." },
  { id: "a3-53f966d24d", who: "amy", text: "…와. 엄청 진지하네.", tag: "[surprised] …와. [soft chuckle] 엄청 진지하네." },
  { id: "a3-9db474a827", who: "amy", text: "근데 이상하다. 다들 그냥 '또 졌냐' 하고 웃거든. 이럴 땐 뭐라고 받아야 돼?", tag: "[thoughtful] 근데 이상하다... 다들 그냥 '또 졌냐' 하고 웃거든. [sighs] 이럴 땐 뭐라고 받아야 돼?" },
  { id: "a3-76addc652a", who: "amy", text: "…뭐야, 그거? 딜러 말투로 하니까 이상하게 설득된다.", tag: "[chuckles] ...뭐야, 그거? [thoughtful] 딜러 말투로 하니까 이상하게 설득된다!" },
  { id: "a3-ac479445b2", who: "amy", text: "그치? 역시 딜러는 뭘 좀 알아.", tag: "[chuckles] [forced brightness] 그치? 역시 딜러는 뭘 좀 알아!" },
  { id: "a3-9b17c7d8eev", who: "amy", text: "딜러가 칠칠맞으면 손님이 불안해.", tag: "[teasing, confident] 딜러가 칠칠맞으면, 손님이 불안해." },
  { id: "a3-0e17129117", who: "amy", text: "고마우면 다음 판에 좋은 카드 줘.", tag: "[chuckles] 고마우면 다음 판에 좋은 카드 줘! [confident]" },
  { id: "a3-015c0c8e8b", who: "amy", text: "알아, 안다고. 규정!", tag: "[annoyed] [quickly, cutting him off] 알아, 안다고... 규정!" },
  { id: "a3-0f9a2d0af9", who: "amy", text: "고마우면 오늘 밤 나한테 져 줘.", tag: "[confident] [chuckles] 고마우면 오늘 밤 나한테 져 줘..." },
  { id: "a3-c8b859bed9", who: "amy", text: "그럼 치게 만들어 줄게.", tag: "[confident] 그럼... 치게 만들어 줄게!" },
  { id: "a3-459d15ae19", who: "amy", text: "왔다, 지원군!", tag: "[excited] 왔다, 지원군!" },
  { id: "a3-3e5748aace", who: "amy", text: "이 곰 봐. 세 번째 시도까지 왔어. 집게가 일부러 힘 빼는 거야, 완전 사기.", tag: "[sulky] 이 곰 봐... 세 번째 시도까지 왔어! [sighs] 집게가 일부러 힘 빼는 거야, 완전 사기!" },
  { id: "a3-1be2996adf", who: "amy", text: "그럼 확률 전문가가 해 봐. 못 뽑으면 너도 사기꾼.", tag: "[confident] 그럼 확률 전문가가 해 봐. [chuckles] 못 뽑으면 너도 사기꾼!" },
  { id: "a3-4d9f5aa6cd", who: "amy", text: "…뭐야? 한 번에? 너 이거 연습했지?", tag: "[surprised] ...뭐야? 한 번에? [chuckles] 너 이거 연습했지?" },
  { id: "a3-34ede5d7cb", who: "amy", text: "거짓말. 손이 너무 익숙했어. 수상해.", tag: "[confident] 거짓말... [short pause] 손이 너무 익숙했어. 수상해!" },
  { id: "a3-4d4dff53ee", who: "amy", text: "반은 네 손이었지만, 레버는 내가 잡았으니까 내 거야.", tag: "[confident] 반은 네 손이었지만, 레버는 내가 잡았으니까... 내 거야! [chuckles]" },
];
const V2_P1: VoiceLine[] = [
  { id: "a4-0dd2e33856", who: "amy", text: "일주일 내내? 그럼 나보다 먼저잖아. 반칙이야.", tag: "[nervous] [flustered] 일주일 내내? [short pause] 그럼 나보다 먼저잖아. 반칙이야." },
  { id: "a4-d4dc472d73c", who: "amy", text: "…이건 져도 돼. 이건 괜찮아.", tag: "[whispers] [soft] ...이건, 져도 돼. 이건, 괜찮아." },
  { id: "a4-91a1e31106", who: "amy", text: "그날부터? 뛰어가 놓고? 그럼 나흘 동안 혼자 이상했던 거야? 바보야?", tag: "[nervous] [flustered] 그날부터? 뛰어가 놓고? [short pause] 그럼 나흘 동안, 혼자 이상했던 거야? 바보야?" },
  { id: "a4-e37c59a63cc", who: "amy", text: "…인정하니까 봐줄게. 이건 져 줘도 돼.", tag: "[whispers] [soft] ...인정하니까 봐줄게. 이건, 져 줘도 돼." },
  { id: "a4-434ea0701fc", who: "amy", text: "…대답이 손이야? 딜러답다.", tag: "[whispers] [surprised] ...대답이, 손이야? 딜러답다." },
  { id: "a4-6bab92c066c", who: "amy", text: "읽었어. 나 이제 너 손은 좀 읽어.", tag: "[whispers] [soft] 읽었어. 나, 이제 너 손은... 좀 읽어." },
  { id: "a4-c99dda3464", who: "amy", text: "오늘은 여기까지. 더 있으면 내가 무슨 말 할지 몰라.", tag: "[flustered] 오늘은 여기까지! [short pause] 더 있으면, 내가 무슨 말 할지 몰라." },
  { id: "a4-5dc68bbd09", who: "amy", text: "우산은 내일 돌려줘. 직원 할인 받은 거야. 비싸.", tag: "[playful] 우산은 내일 돌려줘. [chuckles] 직원 할인 받은 거야, 비싸." },
  { id: "a4-fa769a5352", who: "amy", text: "…발소리로 알았어. 너 걸음 소리 칩 쌓는 소리 같아. 탁, 탁, 탁.", tag: "[softly] ...발소리로 알았어. [short pause] 너 걸음 소리, 칩 쌓는 소리 같아. 탁, 탁, 탁." },
  { id: "a4-3d8050fcfc", who: "amy", text: "창문으로 줘. 문은 안 열 거야. 머리 안 감았어.", tag: "[sulky] 창문으로 줘. [short pause] 문은 안 열 거야. 머리 안 감았어." },
  { id: "a4-882848b50d", who: "amy", text: "우산 배달비. …어제 그 말, 아직 유효해. 아침에 일어나서 다시 생각해 봤는데도.", tag: "[flustered] 우산 배달비. [short pause] ...어제 그 말, 아직 유효해. 아침에 일어나서 다시 생각해 봤는데도." },
  { id: "a4-eb168eb801", who: "amy", text: "…그럼 됐어. 오늘은 그거면 됐어.", tag: "[softly] ...그럼 됐어. [short pause] 오늘은, 그거면 됐어." },
  { id: "a4-8b1c94a038", who: "amy", text: "오늘은 아무 데도 안 가. 방에서 과제나 할 거야.", tag: "[casual] 오늘은 아무 데도 안 가. [short pause] 방에서, 과제나 할 거야." },
  { id: "a4-5691335d52", who: "amy", text: "오늘은 아무 데도 안 가. 방에서 딜러곰이랑 과제나 할 거야.", tag: "[casual] 오늘은 아무 데도 안 가. [short pause] 방에서, 딜러곰이랑 과제나 할 거야." },
  { id: "a4-def661f874", who: "amy", text: "…응. 갈게. 떡볶이집은 '아무 데'가 아니니까.", tag: "[bright] ...응. 갈게. [chuckles] 떡볶이집은, '아무 데'가 아니니까." },
  { id: "a4-1fdc2972ba", who: "amy", text: "가. 출근 준비해. 창문 앞에 오래 있으면 동네 사람들이 수상하게 봐.", tag: "[bright] 가. 출근 준비해. [short pause] 창문 앞에 오래 있으면, 동네 사람들이 수상하게 봐." },
  { id: "a4-42aba49a77", who: "amy", text: "왔다, 구조대!", tag: "[excited] 왔다, 구조대!" },
  { id: "a4-8b4f8caa04", who: "amy", text: "어제 사진 얘기는 금지. 오늘은 숫자만 볼 거야. 숫자는 사람을 안 숨기잖아.", tag: "[forced brightness] 어제 사진 얘기는 금지. [short pause] 오늘은 숫자만 볼 거야. 숫자는, 사람을 안 숨기잖아." },
  { id: "a4-696d10f802", who: "amy", text: "목은 신경 쓰지 마. 소리는 반, 의지는 두 배야.", tag: "[hoarse] [confident] 목은 신경 쓰지 마. [short pause] 소리는 반, 의지는 두 배야." },
  { id: "a4-8ad84593d2", who: "amy", text: "이거 봐. '52장에서 에이스 두 장을 연달아 뽑을 확률.' 교수님이 나 노리고 낸 거야.", tag: "[sulky] 이거 봐. [short pause] '오십이 장에서 에이스 두 장을 연달아 뽑을 확률.' 교수님이, 나 노리고 낸 거야." },
  { id: "a4-e8888bdc14", who: "amy", text: "테이블에선 감으로 하지. 숫자로 하면 머리가 하얘져.", tag: "[sulky] 테이블에선 감으로 하지. [short pause] 숫자로 하면, 머리가 하얘져." },
  { id: "a4-ee582d61d8", who: "amy", text: "알바 전까지 두 시간. 다 풀면 라면은 내가 쏜다.", tag: "[confident] 알바 전까지 두 시간. [short pause] 다 풀면, 라면은 내가 쏜다." },
  { id: "a4-03108f374f", who: "amy", text: "저녁에 첫 출근이라 지금 끝내야 돼. 다 풀면 라면은 내가 쏜다.", tag: "[confident] 저녁에 첫 출근이라, 지금 끝내야 돼. [short pause] 다 풀면, 라면은 내가 쏜다." },
  { id: "a4-d9430609ba", who: "amy", text: "네 장.", tag: "[casual] 네 장." },
  { id: "a4-add29d5c28", who: "amy", text: "…52분의 4. 어, 이거 알겠는데?", tag: "[surprised] ...오십이 분의 사. [short pause] 어, 이거 알겠는데?" },
  { id: "a4-463417bc9e", who: "amy", text: "51장에… 에이스 세 장. 51분의 3!", tag: "[excited] 오십일 장에... 에이스 세 장. [short pause] 오십일 분의 삼!" },
  { id: "a4-622efb7d0cc", who: "amy", text: "둘이 곱하면 되는 거지? 맞지? 맞다고 해.", tag: "[excited] [shouting] 둘이 곱하면 되는 거지? 맞지?! 맞다고 해!" },
  { id: "a4-b3bd59031e", who: "amy", text: "다음 문제는 내가 설명해 볼게. 틀리면 말하지 말고 고개만 저어.", tag: "[confident] 다음 문제는, 내가 설명해 볼게. [short pause] 틀리면 말하지 말고, 고개만 저어." },
  { id: "a4-578155ad03", who: "amy", text: "…어디서?", tag: "[surprised] ...어디서?" },
  { id: "a4-f6886d2f1du", who: "amy", text: "아, 51이 아니라 50이구나. 두 장 뽑았으니까.", tag: "(직접 생성) [realizing] 아, 오십일이 아니라 오시비구나. [to herself, falling tone] 두 장 뽑았으니까." },
  { id: "a4-2284753b72", who: "amy", text: "근데 너 아까 바로 안 저었지? 내 얼굴 보느라.", tag: "[teasing] 근데, 너 아까 바로 안 저었지? [chuckles] 내 얼굴 보느라." },
  { id: "a4-3287451d93", who: "amy", text: "그건… 좀 좋은 대답이다. 봐줄게.", tag: "[flustered] 그건... 좀 좋은 대답이다. [short pause] 봐줄게." },
  { id: "a4-80e77d25ad", who: "amy", text: "완벽? 진짜? 그럼 제출—", tag: "[excited] 완벽? 진짜? [short pause] 그럼 제출—" },
  { id: "a4-e1d5c1e0fdu", who: "amy", text: "…51. 여기 50이어야 되잖아. 두 장 뽑았으니까.", tag: "(직접 생성) [surprised] ...오십일. 여기, 오시비어야 되잖아. [matter-of-fact, falling tone] 두 장 뽑았으니까." },
  { id: "a4-266bcc9e6a", who: "amy", text: "너 틀린 거 알면서 맞다고 했지? 왜?", tag: "[sulky] 너, 틀린 거 알면서 맞다고 했지? [short pause] 왜?" },
  { id: "a4-8609e330f3", who: "amy", text: "그런 이유로 내 학점을 걸지 마. F 받으면 네 책임이야.", tag: "[flustered] 그런 이유로, 내 학점을 걸지 마. [short pause] 에프 받으면 네 책임이야." },
  { id: "a4-867bd79387", who: "amy", text: "수업료. 다음 과제도 예약할게.", tag: "[playful] 수업료. [chuckles] 다음 과제도 예약할게." },
  { id: "a4-b4a9166da2", who: "amy", text: "알아. 그래서 라면이잖아. 다음엔 삼각김밥 추가.", tag: "[bright] 알아. [short pause] 그래서 라면이잖아. 다음엔, 삼각김밥 추가." },
  { id: "a4-661f4075d4", who: "amy", text: "…그건 보지 마. 과제랑 상관없어.", tag: "[flustered] ...그건 보지 마. [short pause] 과제랑 상관없어." },
  { id: "a4-f1a852917c", who: "amy", text: "…어제 얘기는 안 할 거야. 오늘은 손만 바쁘게 해 줘.", tag: "[quietly] ...어제 얘기는 안 할 거야. [short pause] 오늘은, 손만 바쁘게 해 줘." },
  { id: "a4-17a40eceed", who: "amy", text: "너 그때 '잘하고 있어'만 하고 안 가르쳐 줬지? 오늘은 가르쳐 줘. 손이 심심해서 죽겠어.", tag: "[sulky] 너 그때, '잘하고 있어'만 하고 안 가르쳐 줬지? [short pause] 오늘은 가르쳐 줘. 손이 심심해서 죽겠어." },
  { id: "a4-265dd03c9d", who: "amy", text: "드디어 셔플 과외. 수업료 선불이야.", tag: "[excited] 드디어 셔플 과외! [chuckles] 수업료 선불이야." },
  { id: "a4-f249d327e6", who: "amy", text: "…카드가 날 싫어해.", tag: "[sulky] ...카드가, 날 싫어해." },
  { id: "a4-9d5394e942u", who: "amy", text: "자, 잠깐. 잡을 거면 예고를 하고 잡아.", tag: "(직접 생성) [nervous] [flustered] 자, 잠깐! 잡을 거면, 예고를 하고 잡아." },
  { id: "a4-64867f6b3c", who: "amy", text: "…됐다. 방금 됐어!", tag: "[excited] ...됐다. [short pause] 방금 됐어!" },
  { id: "a4-f9a3c8c223", who: "amy", text: "반은 네 손이었지만, 소리는 내 거야.", tag: "[proud] 반은 네 손이었지만, [chuckles] 소리는 내 거야." },
  { id: "a4-9d9ebf52dd", who: "amy", text: "…예쁘다.", tag: "[awed] ...예쁘다." },
  { id: "a4-29322e4d15", who: "amy", text: "카드 말고. 아니, 카드도. 소리가.", tag: "[flustered] 카드 말고. [short pause] 아니, 카드도. 소리가." },
  { id: "a4-d4e47cb2b2c", who: "amy", text: "들었어? 들었지?!", tag: "[excited] [shouting] 들었어? 들었지?!" },
  { id: "a4-84f755d269", who: "amy", text: "이제 실전. 방금 섞은 걸로 한 판 하자. 사탕으로.", tag: "[confident] 이제 실전. [short pause] 방금 섞은 걸로 한 판 하자. 사탕으로." },
  { id: "a4-ced71791b9", who: "amy", text: "알아. 그래서 사탕이잖아. 테이블 말고 파라솔이고. 이건 포커가 아니라 과외 복습이야.", tag: "[casual] 알아. 그래서 사탕이잖아. [short pause] 테이블 말고 파라솔이고. 이건 포커가 아니라, 과외 복습이야." },
  { id: "a4-be81ae20f2", who: "amy", text: "…선생님 너무하네. 복습인데 봐주지도 않고.", tag: "[sulky] ...선생님 너무하네. [short pause] 복습인데, 봐주지도 않고." },
  { id: "a4-77f20e27c4", who: "amy", text: "근데 이상하다. 사탕 잃었는데 기분 안 나빠. 칩이었으면 지금쯤 손 떨렸을 텐데.", tag: "[thoughtful] 근데 이상하다. [short pause] 사탕 잃었는데, 기분 안 나빠. 칩이었으면 지금쯤 손 떨렸을 텐데." },
  { id: "a4-be50a8752au", who: "amy", text: "…설마 봐줬어? 봐줬으면 죽어.", tag: "(직접 생성) [suspicious] ...설마 봐줬어? [playful, half-laughing, pouty] 봐줬으면, 죽어~" },
  { id: "a4-59da22d4f0", who: "amy", text: "그럼 진짜 이긴 거네. 수첩에 적어 둘래.", tag: "[happy] 그럼, 진짜 이긴 거네. [short pause] 수첩에 적어 둘래." },
  { id: "a4-620b2181a0", who: "amy", text: "비겼네. 사탕 서른 개 그대로. 수첩엔 '0'이라고 적을게. 제일 좋은 숫자.", tag: "[bright] 비겼네. [short pause] 사탕 서른 개 그대로. 수첩엔 '영'이라고 적을게. 제일 좋은 숫자." },
  { id: "a4-797ec51d10", who: "amy", text: "근데 너 이거 어디서 배웠어? 딜러 학원 같은 데 있어?", tag: "[curious] 근데, 너 이거 어디서 배웠어? [short pause] 딜러 학원 같은 데 있어?" },
  { id: "a4-2c23aec2b2", who: "amy", text: "역시. 셔플이 그냥 딜러 셔플이 아니더라.", tag: "[knowing] 역시. [short pause] 셔플이, 그냥 딜러 셔플이 아니더라." },
  { id: "a4-45d90ecf90", who: "amy", text: "그래서 빚이구나. 지옥 동기가 아니라 지옥 선배님이었네.", tag: "[teasing] 그래서 빚이구나. [chuckles] 지옥 동기가 아니라, 지옥 선배님이었네." },
  { id: "a4-56cfe606f3", who: "amy", text: "해 줄게. 선배님, 다음 시간엔 카드 폭포 그거. 예약했다?", tag: "[playful] 해 줄게. [short pause] 선배님, 다음 시간엔 카드 폭포 그거. 예약했다?" },
  { id: "a4-6b1471c7e4", who: "amy", text: "수강 기념. 한 장 모자란 덱으로 연습해, 선배님.", tag: "[playful] 수강 기념. [chuckles] 한 장 모자란 덱으로 연습해, 선배님." },
  { id: "a4-7f4acd8ce6", who: "amy", text: "오늘은 생각 안 하는 날. 어제 일은 내일 생각할 거야.", tag: "[forced brightness] 오늘은 생각 안 하는 날. [short pause] 어제 일은, 내일 생각할 거야." },
  { id: "a4-5055fe1120", who: "amy", text: "이건 생활비 아니고 오락비. 수첩에 칸 따로 만들었어. 딱 세 판만 할 거야.", tag: "[proud] 이건 생활비 아니고 오락비. [short pause] 수첩에 칸 따로 만들었어. 딱 세 판만 할 거야." },
  { id: "a4-e7af5c401c", who: "amy", text: "목표는 저 작은 곰. 내 손으로만 뽑을 거야. 너는 구경만 해.", tag: "[determined] 목표는 저 작은 곰. [short pause] 내 손으로만 뽑을 거야. 너는 구경만 해." },
  { id: "a4-dbc93e2d80", who: "amy", text: "목표는 딜러곰 동생. 이번엔 내 손으로만 뽑을 거야. 손대면 반칙이야.", tag: "[determined] 목표는 딜러곰 동생. [short pause] 이번엔 내 손으로만 뽑을 거야. 손대면 반칙이야." },
  { id: "a4-5a29490b80", who: "amy", text: "…연습이야.", tag: "[sulky] ...연습이야." },
  { id: "a4-ce30015723", who: "amy", text: "말로만. 손은 안 대고. 그건 반칙 아니야. 인정해.", tag: "[firm] 말로만. [short pause] 손은 안 대고. 그건 반칙 아니야. 인정해." },
  { id: "a4-5e5a32fe5bc", who: "amy", text: "…뽑았다. 내가. 혼자!", tag: "[overjoyed] [shouting] ...뽑았다. 내가. 혼자!" },
  { id: "a4-b3166240a7", who: "amy", text: "봤지? 증인 해. 나중에 아무도 안 믿을 거야.", tag: "[proud] 봤지? 증인 해. [short pause] 나중에, 아무도 안 믿을 거야." },
  { id: "a4-04edbc67e3", who: "amy", text: "…그리고 고마워. 끝까지 한마디도 안 해 줘서. 이건 처음부터 끝까지 내 거야.", tag: "[softly] [flustered] ...그리고 고마워. [short pause] 끝까지 한마디도 안 해 줘서. 이건 처음부터 끝까지, 내 거야." },
  { id: "a4-7ec112d7c5", who: "amy", text: "이건 네 거. 너 휴대폰에 아무것도 안 달려 있잖아. 딜러 휴대폰이 너무 쓸쓸해.", tag: "[softly] 이건 네 거. [short pause] 너 휴대폰에 아무것도 안 달려 있잖아. 딜러 휴대폰이, 너무 쓸쓸해." },
  { id: "a4-bccc0d4a03", who: "amy", text: "이름은 무표정곰. 너 닮았어.", tag: "[playful] 이름은 무표정곰. [chuckles] 너 닮았어." },
  { id: "a4-703878adccu", who: "amy", text: "딜러곰 2호. 1호는 내 방, 2호는 네 주머니. 따로 살아도 형제야.", tag: "(직접 생성) [bright] 딜러곰 이 호. 일 호는 내 방, 이 호는 네 주머니. [proud, finishing the sentence] 따로 살아도, 형제야." },
  { id: "a4-8b439ea6a2", who: "amy", text: "이제 너 휴대폰 볼 때마다 나 생각나겠다. 작전 성공이다.", tag: "[confident] 이제 너, 휴대폰 볼 때마다 나 생각나겠다. [chuckles] 작전 성공이다." },
  { id: "a4-4e784f97f1", who: "amy", text: "…곰 말이야. 곰 생각.", tag: "[flustered] ...곰 말이야. [short pause] 곰 생각." },
  { id: "a4-95ecaadf19", who: "amy", text: "딜러. …오랜만이야.", tag: "[quietly] 딜러. [short pause] ...오랜만이야." },
  { id: "a4-2a6374696e", who: "amy", text: "그날 택시 뒷창문으로 봤어. 너 거기 남은 거. 그 언니 우산 밑에.", tag: "[sad] 그날, 택시 뒷창문으로 봤어. [short pause] 너 거기 남은 거. 그 언니 우산 밑에." },
  { id: "a4-e0e2ec3f40", who: "amy", text: "괜찮아. 딜러는 원래 손님 편 안 드는 거잖아. 알아.", tag: "[forced brightness] 괜찮아. [short pause] 딜러는 원래, 손님 편 안 드는 거잖아. 알아." },
  { id: "a4-d8928d4be9", who: "amy", text: "딜러. …어젯밤엔 비상계단에 그 언니랑 둘이 앉아 있더라?", tag: "[sulky] 딜러. [short pause] ...어젯밤엔, 비상계단에 그 언니랑 둘이 앉아 있더라?" },
  { id: "a4-b8befc8f43", who: "amy", text: "골목 끝에서 다 보여. 편의점이 거기 있잖아. 우산 펴다가 봤어.", tag: "[sulky] 골목 끝에서 다 보여. [short pause] 편의점이 거기 있잖아. 우산 펴다가 봤어." },
  { id: "a4-adad62abdbu", who: "amy", text: "딜러. 또 보네. 이번엔 내 구역 말고 네 구역이네.", tag: "(직접 생성) [bright] 딜러, 또 보네. [playful] 이번엔 내 구역 말고, 네 구역이네." },
  { id: "a4-853075f3fb", who: "amy", text: "봤지? 매주 5만씩. 월세 반도 오늘 냈어. 자랑 아니고 보고야, 보고.", tag: "[proud] 봤지? 매주 오 만씩. [short pause] 월세 반도 오늘 냈어. 자랑 아니고 보고야, 보고." },
  { id: "a4-65f22ac904", who: "amy", text: "저번 일요일에 아래층에서 진 거, 억울하진 않아. 그냥… 내가 못 쳤던 거니까.", tag: "[quietly] 저번 일요일에 아래층에서 진 거, 억울하진 않아. [short pause] 그냥... 내가 못 쳤던 거니까." },
  { id: "a4-0f6a9de96d", who: "amy", text: "콜라 한 잔만 마시고 갈게. 손님 아니고 구경꾼이야.", tag: "[bright] 콜라 한 잔만 마시고 갈게. [short pause] 손님 아니고, 구경꾼이야." },
  { id: "a4-c21f8335ca", who: "amy", text: "편의점 직원한테 새우깡 뜯어내려고? 태양, 너 이번 달 외상 얼마야?", tag: "[teasing] 편의점 직원한테 새우깡 뜯어내려고? [short pause] 태양, 너 이번 달 외상 얼마야?" },
  { id: "a4-b0c9b84a12", who: "amy", text: "너지? '이자 없음'이 뭐야? 완전 딜러 말투잖아.", tag: "[sulky] 너지? [short pause] '이자 없음'이 뭐야? 완전 딜러 말투잖아." },
  { id: "a4-5666088ab5", who: "amy", text: "거짓말할 때 카드 만지는 거, 나도 알거든.", tag: "[knowing] 거짓말할 때 카드 만지는 거, [short pause] 나도 알거든." },
  { id: "a4-d7ac2fcbe5", who: "amy", text: "갚을 거야. 누군지 몰라도. 이자는 없이.", tag: "[determined] 갚을 거야. [short pause] 누군지 몰라도, 이자는 없이." },
  { id: "a4-c9c3222182", who: "amy", text: "……필요 없어요.", tag: "[angry] ......필요 없어요." },
  { id: "a4-2decf9dd76", who: "amy", text: "어서 오세요. …아.", tag: "[surprised] 어서 오세요. [short pause] ...아." },
  { id: "a4-103e5613db", who: "amy", text: "알바 시작했어. 원래 저녁 타임인데, 오늘은 낮 사람이 아파서 대타. 혼자 구했어. 월세는 혼자 낼 거니까.", tag: "[sulky] 알바 시작했어. [short pause] 원래 저녁 타임인데, 오늘은 낮 사람이 아파서 대타. 혼자 구했어. 월세는 혼자 낼 거니까." },
  { id: "a4-d4253be41d", who: "amy", text: "오늘 교육 받는 날이야. 저녁부터 정식 출근. 혼자 구했어. 월세는 혼자 낼 거니까.", tag: "[sulky] 오늘 교육 받는 날이야. [short pause] 저녁부터 정식 출근. 혼자 구했어. 월세는 혼자 낼 거니까." },
  { id: "a4-307aa97545", who: "amy", text: "봐. 계산 틀린 적 한 번도 없어. 수습인데.", tag: "[proud] 봐. [short pause] 계산 틀린 적 한 번도 없어. 수습인데." },
  { id: "a4-e9f952f86b", who: "amy", text: "봐. 이제 알아. 누가 안 가르쳐 줘도.", tag: "[proud] 봐. [short pause] 이제 알아. 누가 안 가르쳐 줘도." },
  { id: "a4-bbba53a710", who: "amy", text: "하나는 놓고 가. 1+1은 원래 둘이 먹는 거라며. …아니, 그건 내가 한 말이구나.", tag: "[casual] 하나는 놓고 가. 원 플러스 원은, 원래 둘이 먹는 거라며. [short pause] ...아니, 그건 내가 한 말이구나." },
  { id: "a4-7c8bca19fb", who: "amy", text: "…진짜 놓고 가네. 농담 반이었는데.", tag: "[surprised] ...진짜 놓고 가네. [short pause] 농담 반이었는데." },
  { id: "a4-e275c4d178", who: "amy", text: "고마워. 오늘 저녁은 이걸로 해결. 폐기보다 맛있겠다.", tag: "[bright] 고마워. 오늘 저녁은 이걸로 해결. [chuckles] 폐기보다 맛있겠다." },
  { id: "a4-ce6e33c15bw", who: "amy", text: "어떻게 알았어? …아, 계산대 옆에 펼쳐 놨구나. 바보.", tag: "[sulky] 어떻게 알았어? [realizing] ...아, 계산대 옆에 펼쳐 놨구나. 바보." },
  { id: "a4-f83e0fb9de", who: "amy", text: "외상은 매주 5만. 월세는 반씩. 숫자 적으니까 덜 무서워. 이건 내가 찾은 거야.", tag: "[proud] 외상은 매주 오 만. 월세는 반씩. 숫자 적으니까, 덜 무서워. [firmly] 이건 내가 찾은 거야." },
  { id: "a4-42e74d3638", who: "amy", text: "…가. 줄 서 있어, 뒤에.", tag: "[quietly] ...가. 줄 서 있어, 뒤에." },
  { id: "a4-47dc2490e8", who: "amy", text: "…딜러? 왜 뛰어와? 비 오는데.", tag: "[surprised] ...딜러? 왜 뛰어와? 비 오는데." },
  { id: "a4-6655c4d03c", who: "amy", text: "그날 혼자 뛰어가더라? 빗속을. 영화 찍는 줄.", tag: "[sulky] 그날, 혼자 뛰어가더라? [teasing] 빗속을, 영화 찍는 줄." },
  { id: "a4-52882d104a", who: "amy", text: "이유 들고 오라고 했지. 삼각김밥 말고.", tag: "[sulky] 이유 들고 오라고 했지. 삼각김밥 말고." },
  { id: "a4-3cc23d2cd4w", who: "amy", text: "…설마 뛰어온 게 이유야? 빗속을, 또?", tag: "[disbelief] ...설마, 뛰어온 게 이유야? 빗속을, 또." },
  { id: "a4-0c658f5628", who: "amy", text: "…나 그날, 데려다줄 줄 알았어. 아주 조금.", tag: "[sad] ...나 그날, 데려다줄 줄 알았어. [softly, falling tone] 아주 조금." },
  { id: "a4-d5c2b001c6w", who: "amy", text: "늦었지. 엄청. 나흘이야. 그동안 나 알바도 구하고, 수첩도 쓰고, 혼자 다 했어.", tag: "[sulky] 늦었지. 엄청. 나흘이야. 그동안 나, 알바도 구하고, 수첩도 쓰고, 혼자 다 했어." },
  { id: "a4-99230d7220", who: "amy", text: "봐. 숫자 적는 거, 처음엔 무서웠는데.", tag: "[softly] 봐. 숫자 적는 거, 처음엔 무서웠는데." },
  { id: "a4-37c4fb4fc1", who: "amy", text: "…그거 좋다. 적어 둬야지. 딜러 명언 1호다.", tag: "[bright] ...그거 좋다. 적어 둬야지. [chuckles] 딜러 명언, 일 호다." },
  { id: "a4-ba023a6553", who: "amy", text: "근데 너는? 너도 숫자 있지? 그 얼굴, 남의 숫자 보는 얼굴 아니야.", tag: "[curious] 근데, 너는? 너도 숫자 있지? [knowing] 그 얼굴, 남의 숫자 보는 얼굴 아니야." },
  { id: "a4-030ba856a9", who: "amy", text: "그럼 우리 둘 다 지옥이네. 지옥 동기다.", tag: "[chuckles] 그럼 우리 둘 다 지옥이네. [bright] 지옥 동기다." },
  { id: "a4-98b3eb56f7w", who: "amy", text: "…나흘 늦은 동기. 그래도 동기는 동기야.", tag: "[flustered] ...나흘 늦은 동기. [softly] 그래도 동기는 동기야." },
  { id: "a4-8b2b4a8d82w", who: "amy", text: "데려다줘. 그날 몫까지. 이자는 없어.", tag: "[playful] 데려다줘. 그날 몫까지. 이자는 없어." },
  { id: "a4-f3db3a7ea1u", who: "amy", text: "어서 오세… 아.", tag: "(직접 생성) [bright, cheerful shop clerk voice] 어서 오세— [stops abruptly] [flat] ...아." },
  { id: "a4-5d4a76d2e8", who: "amy", text: "…낮 대타야. 원래 저녁 타임. …뭐. 삼각김밥 사러 왔으면 사.", tag: "[awkward] ...낮 대타야. 원래 저녁 타임. ...뭐. [flat] 삼각김밥 사러 왔으면, 사." },
  { id: "a4-5744873936", who: "amy", text: "오늘 교육 받는 날이야. 저녁부터 정식. …뭐. 삼각김밥 사러 왔으면 사.", tag: "[awkward] 오늘 교육 받는 날이야. 저녁부터 정식. ...뭐. [flat] 삼각김밥 사러 왔으면, 사." },
  { id: "a4-31d778026fw", who: "amy", text: "그날 혼자 뛰어가더라. 빗속을.", tag: "[sulky] 그날, 혼자 뛰어가더라. 빗속을." },
  { id: "a4-284ee8ef0f", who: "amy", text: "뭐라고 할 생각 없어. 딜러는 원래 손님 편 안 드는 거잖아.", tag: "[flat] 뭐라고 할 생각 없어. 딜러는 원래, 손님 편 안 드는 거잖아." },
  { id: "a4-2e54520ce1w", who: "amy", text: "…다음에 올 거면, 이유 하나 들고 와. 삼각김밥 말고.", tag: "[sad] ...다음에 올 거면, 이유 하나 들고 와. 삼각김밥 말고." },
  { id: "a4-4f3fc3b504", who: "amy", text: "…딜러?", tag: "[surprised] ...딜러?" },
  { id: "a4-63b2613498", who: "amy", text: "…왔구나. 얼굴 보니까 계단 뛰어 내려왔네.", tag: "[sulky] ...왔구나. [softly] 얼굴 보니까, 계단 뛰어 내려왔네." },
  { id: "a4-27a92c1494", who: "amy", text: "…새끼손가락 걸었는데. 미안.", tag: "[sad] ...새끼손가락 걸었는데. [falling tone] 미안." },
  { id: "a4-c2cd518e6a", who: "amy", text: "보기만 하면 약속 깨는 건 아닌 줄 알았어. 혼자 와 놓고.", tag: "[sad] 보기만 하면, 약속 깨는 건 아닌 줄 알았어. [falling tone] 혼자 와 놓고." },
  { id: "a4-ec61c25f70", who: "amy", text: "…같이 내려가자며. 그래서 문자 보낸 거야.", tag: "[sulky] ...같이 내려가자며. 그래서 문자 보낸 거야." },
  { id: "a4-e5c6bd9eb1w", who: "amy", text: "반은 지켰지? …반은 안 지켰고.", tag: "[sad] 반은 지켰지? ...반은 안 지켰고." },
  { id: "a4-a1e5fb0628", who: "amy", text: "떡볶이도 미안. 다섯 시에 신발까지 신었는데… 나가면 다 말할 것 같아서.", tag: "[sad] 떡볶이도 미안. 다섯 시에 신발까지 신었는데... 나가면, 다 말할 것 같아서." },
  { id: "a4-65480460b8wc", who: "amy", text: "……그 얘기 지금 하지 마. 여기서 울면 안 돼.", tag: "[whispers] [holding back tears] ......그 얘기, 지금 하지 마. 여기서 울면, 안 돼." },
  { id: "a4-60236dbe74", who: "amy", text: "안 앉았어. 진짜야. 봐, 손도 깨끗해.", tag: "[earnest] 안 앉았어. 진짜야. [softly] 봐, 손도 깨끗해." },
  { id: "a4-57c43aebb2", who: "amy", text: "눈이 했어. 들어오자마자 내 손부터 봤잖아.", tag: "[knowing] 눈이 했어. 들어오자마자, 내 손부터 봤잖아." },
  { id: "a4-a92e85eccfw", who: "amy", text: "그리고 이거 봐. 레일 끝.", tag: "[softly] 그리고 이거 봐. 레일 끝." },
  { id: "a4-d0db1d90daw", who: "amy", text: "아빠 버릇이야. 자기 자리엔 꼭 A를 새겨. 내 이름 첫 글자.", tag: "[softly] 아빠 버릇이야. 자기 자리엔 꼭 에이를 새겨. 내 이름 첫 글자." },
  { id: "a4-5d015f8fe8w", who: "amy", text: "부엌 식탁에도, 내 책상 모서리에도 있어. 여기가 진짜 아빠 자리야.", tag: "[sad] 부엌 식탁에도, 내 책상 모서리에도 있어. 여기가, 진짜 아빠 자리야." },
  { id: "a4-afde502699w", who: "amy", text: "여기서 기다렸어? 계단에서? 이 추운 데서?", tag: "[surprised] 여기서 기다렸어? 계단에서? 이 추운 데서?" },
  { id: "a4-4308ce1605w", who: "amy", text: "……응. 보기만 했어. 손도 안 댔어.", tag: "[quietly] ......응. 보기만 했어. 손도 안 댔어." },
  { id: "a4-85defe7755w", who: "amy", text: "'보기만'이라는 말 믿어 준 사람, 없었어. 다들 문 열고 들어와서 끌고 나가거든.", tag: "[sad] '보기만'이라는 말 믿어 준 사람, 없었어. 다들 문 열고 들어와서, 끌고 나가거든." },
  { id: "a4-a7bdc8a1d3w", who: "amy", text: "…또 믿어 주네. 뒷문 차양 밑에서도, 이 계단에서도. 두 번 다 너야.", tag: "[sad] [softly] ...또 믿어 주네. 뒷문 차양 밑에서도, 이 계단에서도. 두 번 다 너야." },
  { id: "a4-6cc9b03438w", who: "amy", text: "다들 문 열고 들어와서 끌고 나가거든.", tag: "[sad] 다들 문 열고 들어와서, 끌고 나가거든." },
  { id: "a4-f1e5d46bb2c", who: "amy", text: "…엄마가 아빠한테 맨날 그랬어.", tag: "[whispers] [sad] ...엄마가, 아빠한테... 맨날 그랬어." },
  { id: "a4-aaa9892216", who: "amy", text: "뭐야, 그게? 감동 깨지게.", tag: "[laughing] 뭐야, 그게? [chuckles] 감동 깨지게." },
  { id: "a4-78e6213488w", who: "amy", text: "아, 그리고 안에서 봤어. 아빠 자리. 레일 끝에 'A'가 새겨져 있었어. 아빠 버릇이야.", tag: "[softly] 아, 그리고 안에서 봤어. 아빠 자리. 레일 끝에 에이가 새겨져 있었어. 아빠 버릇이야." },
  { id: "a4-bdaf9c5292w", who: "amy", text: "내 이름 첫 글자. 부엌 식탁에도, 내 책상 모서리에도 있어.", tag: "[sad] 내 이름 첫 글자. 부엌 식탁에도, 내 책상 모서리에도 있어." },
  { id: "a4-d0943a7b9dwc", who: "amy", text: "…딜러. 나 때문에 그런 거 받지 마.", tag: "[whispers] [trembling] ...딜러. 나 때문에, 그런 거 받지 마." },
  { id: "a4-03b35e3c92w", who: "amy", text: "너 '하겠습니다' 했으면 정강이 찼어. 신발 끝 세우고 있었거든.", tag: "[relieved] [chuckles] 너, '하겠습니다' 했으면 정강이 찼어. 신발 끝 세우고 있었거든." },
  { id: "a4-098476c166", who: "amy", text: "이건 남은 긴장이야.", tag: "[sulky] 이건, 남은 긴장이야." },
  { id: "a4-dc7f3bafedw", who: "amy", text: "…생각을 왜 해? 바로 싫다고 하지.", tag: "[sulky] ...생각을 왜 해? 바로 싫다고 하지." },
  { id: "a4-d1b3427185u", who: "amy", text: "귀 막아. 그 숫자, 다 낚싯바늘이야.", tag: "(직접 생성) [urgent, worried] 귀 막아. [earnest] 그 숫자, 다 낚싯바늘이야." },
  { id: "a4-788074cffew", who: "amy", text: "고맙다고 안 할 거야. 이건 고마운 일이 아니니까.", tag: "[sad] 고맙다고 안 할 거야. 이건 고마운 일이 아니니까." },
  { id: "a4-3f6af840b2w", who: "amy", text: "의자에서 아빠 냄새 날 줄 알았어. 아빠 스킨. 귤 껍질 같은 거.", tag: "[sad] 의자에서, 아빠 냄새 날 줄 알았어. 아빠 스킨. [softly] 귤 껍질 같은 거." },
  { id: "a4-b718177312", who: "amy", text: "담배 냄새만 나더라. 아빠 담배 안 피웠는데.", tag: "[sad] 담배 냄새만 나더라. [falling tone] 아빠, 담배 안 피웠는데." },
  { id: "a4-ccdc74914cw", who: "amy", text: "사장님이 그랬어. 아빠는 그 자리에서 마지막까지 웃었대.", tag: "[quietly] 사장님이 그랬어. 아빠는 그 자리에서, 마지막까지 웃었대." },
  { id: "a4-878a562b2ew", who: "amy", text: "나 거기 앉아서 이기면, 아빠가 못 이긴 테이블을 이기는 거잖아.", tag: "[quietly] 나, 거기 앉아서 이기면, 아빠가 못 이긴 테이블을 이기는 거잖아." },
  { id: "a4-36782a5c3bc", who: "amy", text: "…그럼 좀 덜 아플 것 같아.", tag: "[whispers] [sad] ...그럼, 좀 덜 아플 것 같아." },
  { id: "a4-2cc5bca9f7w", who: "amy", text: "…그 얼굴 할 줄 알았어. 잔소리 얼굴.", tag: "[sulky] ...그 얼굴 할 줄 알았어. 잔소리 얼굴." },
  { id: "a4-c4385818eaw", who: "amy", text: "근데 아는 거랑 안 가는 건 달라. 너도 알잖아.", tag: "[sad] 근데, 아는 거랑 안 가는 건 달라. 너도 알잖아." },
  { id: "a4-d08fb68565", who: "amy", text: "…뭐 해?", tag: "[flustered] ...뭐 해?" },
  { id: "a4-a105c23296w", who: "amy", text: "딜러는 손님 손가락까지 관리해? 무슨 서비스야, 그게?", tag: "[flustered] 딜러는, 손님 손가락까지 관리해? 무슨 서비스야, 그게." },
  { id: "a4-4b7318529cw", who: "amy", text: "…팁이야. 손가락으로 줄게.", tag: "[softly] ...팁이야. [shyly] 손가락으로 줄게." },
  { id: "a4-5bde3fea46w", who: "amy", text: "이거 원래 두 개래. 군번줄. 똑같은 게 한 쌍이야.", tag: "[softly] 이거, 원래 두 개래. 군번줄. 똑같은 게 한 쌍이야." },
  { id: "a4-bb52bf5174", who: "amy", text: "아빠가 미국 떠날 때 하나 걸어 줬어. '나머지는 아빠가 갖고 있을게. 다시 만나면 한 쌍이야.'", tag: "[sad] 아빠가 미국 떠날 때 하나 걸어 줬어. [softly] '나머지는 아빠가 갖고 있을게. 다시 만나면, 한 쌍이야.'" },
  { id: "a4-ba49eb1481w", who: "amy", text: "오글거리지. 아빠는 맨날 그런 말만 했어. …이 얘기, 엄마 말고는 안 해 봤어.", tag: "[chuckles] 오글거리지. 아빠는 맨날 그런 말만 했어. [softly] ...이 얘기, 엄마 말고는 안 해 봤어." },
  { id: "a4-1366bc55a3w", who: "amy", text: "딜러. 나 토요일에 갈 거야. 아빠 자리.", tag: "[determined] 딜러. 나, 토요일에 갈 거야. 아빠 자리." },
  { id: "a4-1baaeffd53w", who: "amy", text: "말려도 돼. 말려도 갈 거니까. 미리 말하는 건 예의야.", tag: "[confident] 말려도 돼. 말려도 갈 거니까. 미리 말하는 건, 예의야." },
  { id: "a4-0a7e420984w", who: "amy", text: "방금 배웠어. 아래층에서.", tag: "[playful] 방금 배웠어. 아래층에서." },
  { id: "a4-1576f3b33fu", who: "amy", text: "어서 오세… 아, 딜러. 손님으로 계산대 앞에 서 있으니까 어색하다.", tag: "(직접 생성) [bright, cheerful shop clerk voice] 어서 오세— [stops] 아, 딜러. [chuckles] [awkward] 손님으로 계산대 앞에 서 있으니까, 어색하다." },
  { id: "a4-990f23c3f4", who: "amy", text: "나 이번 주부터 낮 근무야. 점장님이 밤엔 여자 혼자 위험하다고 바꿔 줬어.", tag: "[casual] 나, 이번 주부터 낮 근무야. 점장님이, 밤엔 여자 혼자 위험하다고 바꿔 줬어." },
  { id: "a4-eb9efefd5bu", who: "amy", text: "…그 말 뼈 있다. 지금 진열 중이라 바빠. 응대는 뭐라도 사야 해 줄 거야.", tag: "(직접 생성) [sulky, a little pouty] ...그 말, 뼈 있다. [busy, brisk] 지금 진열 중이라 바빠. [teasing, matter-of-fact statement] 응대는, 뭐라도 사야 해 줄 거야." },
  { id: "a4-3e8fb1e1edw", who: "amy", text: "품절이야. 마지막 거 아까 내가 샀거든.", tag: "[playful] 품절이야. 마지막 거, 아까 내가 샀거든." },
  { id: "a4-2d5fea0eb1w", who: "amy", text: "직원 할인 100퍼센트. 내 돈으로 산 거라서.", tag: "[playful] 직원 할인 백 퍼센트. 내 돈으로 산 거라서." },
  { id: "a4-129b0d2e36w", who: "amy", text: "선물이면 부담스럽잖아. 할인으로 해.", tag: "[sulky] 선물이면 부담스럽잖아. 할인으로 해." },
  { id: "a4-52255dd5cfw", who: "amy", text: "…봤어? 그건 계획이야. 계획은 숫자로 적는 거래.", tag: "[defensive] ...봤어? 그건 계획이야. 계획은 숫자로 적는 거래." },
  { id: "a4-6a15ca418ew", who: "amy", text: "20만으로 시작해서 딱 두 배 되면 일어날 거야. 수첩에 적었으니까 약속이야.", tag: "[determined] 이십 만으로 시작해서, 딱 두 배 되면 일어날 거야. 수첩에 적었으니까 약속이야." },
  { id: "a4-d95353296a", who: "amy", text: "두 배면 남은 월세 내고도 남아. 봐, 나 숫자 적을 줄 알아.", tag: "[bright] 두 배면, 남은 월세 내고도 남아. [proud] 봐, 나 숫자 적을 줄 알아." },
  { id: "a4-dbbe3f53a7", who: "amy", text: "…또 그 소리.", tag: "[sulky] ...또 그 소리." },
  { id: "a4-f411667706w", who: "amy", text: "맞는 말인 거 알아. 근데 맞는 말만 들으면 숨 막혀.", tag: "[sad] 맞는 말인 거 알아. 근데, 맞는 말만 들으면 숨 막혀." },
  { id: "a4-9794739854w", who: "amy", text: "나 숨 쉬려고 가는 거야. 이기려고 가는 게 아니라.", tag: "[sad] 나, 숨 쉬려고 가는 거야. 이기려고 가는 게 아니라." },
  { id: "a4-d9f04c9cff", who: "amy", text: "…뒤에?", tag: "[surprised] ...뒤에?" },
  { id: "a4-9c074a5487w", who: "amy", text: "두 번 두드리면 무조건 일어나? 이기고 있어도?", tag: "[sulky] 두 번 두드리면, 무조건 일어나? 이기고 있어도?" },
  { id: "a4-36fde88f79", who: "amy", text: "치사해. …근데 콜. 대신 마감 후에 연습해. 진짜 두드려 보는 거.", tag: "[sulky] 치사해. [chuckles] ...근데, 콜. [firm] 대신 마감 후에 연습해. 진짜 두드려 보는 거." },
  { id: "a4-7207e8d3b5w", who: "amy", text: "진짜? 딜러가 가르쳐 줘?", tag: "[excited] 진짜? 딜러가 가르쳐 줘?" },
  { id: "a4-541b4330ccw", who: "amy", text: "태양이가 그러던데. 너 혹시 그 '손' 아니냐고. 전설의.", tag: "[teasing] 태양이가 그러던데. 너 혹시, 그 '손' 아니냐고. 전설의." },
  { id: "a4-8247a2c0cew", who: "amy", text: "…그건 맞는 말이야. 우리 점장님 전설이야.", tag: "[chuckles] ...그건 맞는 말이야. 우리 점장님, 전설이야." },
  { id: "a4-ba4c152f5au", who: "amy", text: "아무튼 마감 후에 간다. 수업료는 사탕이야.", tag: "(직접 생성) [playful, bright] 아무튼, 마감 후에 간다! [chuckles] 수업료는 사탕이야." },
  { id: "a4-6672473ce7w", who: "amy", text: "낮에 그 소리 듣고 삐졌거든. 근데 삐진 채로 자면 내일 더 삐질 것 같아서.", tag: "[sulky] 낮에 그 소리 듣고 삐졌거든. [softly] 근데 삐진 채로 자면, 내일 더 삐질 것 같아서." },
  { id: "a4-a7f056213bw", who: "amy", text: "화해 사탕. 포도맛은 내 거야.", tag: "[playful] 화해 사탕. 포도맛은 내 거야." },
  { id: "a4-9d5682eaf2w", who: "amy", text: "화해는 반반이야. 원래 그래.", tag: "[confident] 화해는 반반이야. 원래 그래." },
  { id: "a4-aa28ce62df", who: "amy", text: "수업료 가져왔어요, 선생님.", tag: "[playful] 수업료 가져왔어요, 선생님." },
  { id: "a4-a96a5e0f5bw", who: "amy", text: "수업 시간이잖아. 끝나면 다시 반말할 거야.", tag: "[playful] 수업 시간이잖아. 끝나면, 다시 반말할 거야." },
  { id: "a4-bd68aaf4cew", who: "amy", text: "와. 숫자로 보니까 다 이길 수 있을 것 같아.", tag: "[excited] 와. 숫자로 보니까, 다 이길 수 있을 것 같아." },
  { id: "a4-1edacf7290", who: "amy", text: "선생님, 마지막 질문. 아웃츠가 하나도 없으면 어떡해요?", tag: "[playful] 선생님, 마지막 질문. [curious] 아웃츠가 하나도 없으면, 어떡해요?" },
  { id: "a4-797bcc1677w", who: "amy", text: "…그건 숫자가 아니라 그냥 잔소리잖아.", tag: "[sulky] ...그건 숫자가 아니라, 그냥 잔소리잖아." },
  { id: "a4-51f8fccce0w", who: "amy", text: "연습하러 왔어. 어깨 두 번.", tag: "[playful] 연습하러 왔어. 어깨 두 번." },
  { id: "a4-1bcd050a95", who: "amy", text: "…으. 간지러워. 다시. 이번엔 진지하게.", tag: "[flustered] ...으. 간지러워. 다시. [serious] 이번엔, 진지하게." },
  { id: "a4-cff061c8fdw", who: "amy", text: "됐다. 몸이 기억했어. 이거 은근 무섭다. 너 손가락이 리모컨이야.", tag: "[quietly] 됐다. 몸이 기억했어. [chuckles] 이거 은근 무섭다. 너 손가락이, 리모컨이야." },
  { id: "a4-b99b997465w", who: "amy", text: "알아. 그래서 지금 연습하는 거잖아.", tag: "[sad] 알아. 그래서 지금 연습하는 거잖아." },
  { id: "a4-21d2527f3aw", who: "amy", text: "딜러. 셔플 한 번만 해 봐. 여기서, 가까이서.", tag: "[softly] 딜러. 셔플 한 번만 해 봐. 여기서, 가까이서." },
  { id: "a4-4cf0b46488w", who: "amy", text: "…손 이렇게 빠른데 왜 손님한테 안 보여 줘?", tag: "[surprised] ...손 이렇게 빠른데, 왜 손님한테 안 보여 줘?" },
  { id: "a4-2a1d8729bbw", who: "amy", text: "…과외 때는 일부러 천천히 한 거였어? 진짜 속도는 이거고?", tag: "[surprised] ...과외 때는, 일부러 천천히 한 거였어? 진짜 속도는, 이거고?" },
  { id: "a4-81b8c09d44", who: "amy", text: "그럼 나한텐 보여 줘. 나 이제 손님 아니잖아.", tag: "[flustered] 그럼... 나한텐 보여 줘! 나 이제 손님 아니잖아." },
  { id: "a4-2c145b39d8", who: "amy", text: "손님은 마감 후에 뒷문으로 안 들어오니까. 그런 뜻이야.", tag: "[sulky] 손님은... 마감 후에 뒷문으로 안 들어오니까. 그런 뜻이야." },
  { id: "a4-c035a5cab8", who: "amy", text: "나도 해 볼래. 그 폭포 같은 거.", tag: "[excited] 나도 해 볼래! 그 폭포 같은 거!" },
  { id: "a4-f3172dafdeu", who: "amy", text: "……태양이한테 말하기만 해 봐. 진짜 죽는다?", tag: "(직접 생성) [embarrassed, annoyed] ...태양이한테 말하기만 해 봐. [whiny] 진짜 죽는다?" },
  { id: "a4-94c286781d", who: "amy", text: "지우러 가기 전에. 사탕 걸고 한 판. 칩은 안 돼. 사탕은 돼.", tag: "[playful] 지우러 가기 전에, 사탕 걸고 한 판! [chuckles] 칩은 안 돼. 사탕은, 돼." },
  { id: "a4-cd861fcd87", who: "amy", text: "그러니까. 손님 아니고, 테이블 아니고, 의자 두 개야.", tag: "[confident] 그러니까... 손님 아니고, 테이블 아니고, 의자 두 개야!" },
  { id: "a4-10bb42f80e", who: "amy", text: "…졌다. 이상하다. 칩으로 지면 숨이 막히는데, 사탕으로 지니까 웃겨.", tag: "[chuckles] ...졌다. [thoughtful] 이상하다. 칩으로 지면 숨이 막히는데, [laughing] 사탕으로 지니까 웃겨." },
  { id: "a4-1cc7a987ac", who: "amy", text: "이게 맞는 거겠지. 지는 게 웃긴 거.", tag: "[thoughtful] 이게 맞는 거겠지... 지는 게, 웃긴 거." },
  { id: "a4-e41c23f807", who: "amy", text: "…근데 이기니까 또 하고 싶어. 이건 좀 무섭다. 사탕인데도.", tag: "[uneasy] ...근데, 이기니까 또 하고 싶어. 이건 좀 무섭다. 사탕인데도." },
  { id: "a4-c706fb7d76", who: "amy", text: "비겼어. 사탕도 딱 반반. 오늘은 이게 제일 맘에 든다.", tag: "[happy] 비겼어! 사탕도 딱 반반... [chuckles] 오늘은 이게 제일 맘에 든다." },
  { id: "a4-f454172e0bc", who: "amy", text: "이제 CCTV 지우러 가자. 같이.", tag: "[determined] [shouting] 이제, 씨씨티비 지우러 가자! 같이!" },
  { id: "a4-5403f3be88", who: "amy", text: "왔어? 진짜 왔어?", tag: "[surprised] 왔어? [excited] 진짜 왔어?!" },
  { id: "a4-d1b0bc3a53c", who: "amy", text: "이게 제일 커! 냄비는 라면 끓여야 된단 말이야!", tag: "[defensive] [shouting] 이게 제일 커! 냄비는 라면 끓여야 된단 말이야!" },
  { id: "a4-0d8cd9e99d", who: "amy", text: "노트북, 수첩, 명찰은 책상 위로 올렸어. 지갑은 맨 꼭대기. 아빠 사진 들었으니까.", tag: "[earnest] 노트북, 수첩, 명찰은 책상 위로 올렸어. 지갑은 맨 꼭대기... [softly] 아빠 사진 들었으니까." },
  { id: "a4-4508c69cf6", who: "amy", text: "딜러곰은 책상 맨 위로 피난시켰어. 제일 가벼워서.", tag: "[earnest] 딜러곰은, 책상 맨 위로 피난시켰어. 제일 가벼워서." },
  { id: "a4-56b4c7bd82", who: "amy", text: "…그리고 젖으면 너 닮은 얼굴로 쳐다봐서.", tag: "[flustered] ...그리고 젖으면, 너 닮은 얼굴로 쳐다봐서." },
  { id: "a4-bfd463619f", who: "amy", text: "…오늘 여기서 못 자겠다. 이불도 다 젖었어.", tag: "[sighs] [tired] ...오늘 여기서 못 자겠다. 이불도 다 젖었어." },
  { id: "a4-422a9489b7", who: "amy", text: "찜질방 가면 돼. 나 찜질방 좋아해. 계란도 있고.", tag: "[forced brightness] 찜질방 가면 돼. [chuckles] 나 찜질방 좋아해! 계란도 있고." },
  { id: "a4-1a61c35765", who: "amy", text: "싫어. 돈 받는 거 싫어.", tag: "[stubborn] 싫어. 돈 받는 거, 싫어." },
  { id: "a4-a57bf13e22", who: "amy", text: "그리고 찜질방 혼자 가면 아저씨들이 말 걸어. '외국인이네~ 한국말 잘하네~'", tag: "[sad] 그리고 찜질방 혼자 가면, 아저씨들이 말 걸어... '외국인이네~ 한국말 잘하네~'" },
  { id: "a4-4f3a9e9c88", who: "amy", text: "…너네 집은 몇 분인데?", tag: "[softly] [flustered] ...너네 집은, 몇 분인데?" },
  { id: "a4-fd4a770f18", who: "amy", text: "거리만 물어본 거야. 거리만.", tag: "[flustered] 거리만 물어본 거야. 거리만!" },
  { id: "a4-648add4c39", who: "amy", text: "…진짜? 너네 집?", tag: "[surprised] ...진짜? 너네 집?" },
  { id: "a4-cef411a9d9", who: "amy", text: "…갈래. 추워서 고민할 힘도 없어. 말 바꾸기 전에 빨리 가.", tag: "[shivering] ...갈래. 추워서 고민할 힘도 없어. 말 바꾸기 전에, 빨리 가!" },
  { id: "a4-9cc8079332c", who: "amy", text: "그런 정보는 묻기 전에 말하지 마!", tag: "[panicked] [shouting] 그런 정보는, 묻기 전에 말하지 마!" },
  { id: "a4-7b3b021290", who: "amy", text: "…생각보다 깨끗하다. 칩 정리하듯이 사네.", tag: "[impressed] ...생각보다 깨끗하다. [chuckles] 칩 정리하듯이 사네." },
  { id: "a4-f2f96dcad3", who: "amy", text: "근데 왜 아무것도 없어? 사진도 포스터도. 이사 온 지 얼마 안 됐어?", tag: "[curious] 근데, 왜 아무것도 없어? 사진도, 포스터도... 이사 온 지 얼마 안 됐어?" },
  { id: "a4-fa8001b789", who: "amy", text: "3년? 3년 동안 뭐 했어?", tag: "[surprised] 삼 년? 삼 년 동안, 뭐 했어?" },
  { id: "a4-b43d7533e5", who: "amy", text: "……그거 좀 슬프다.", tag: "[sad] ...그거, 좀 슬프다." },
  { id: "a4-d66111df9c", who: "amy", text: "욕실 빌릴게. 엿보면 신고.", tag: "[playful] 욕실 빌릴게. [chuckles] 엿보면 신고!" },
  { id: "a4-f2c944ddd8", who: "amy", text: "니삭스는 안 벗어. 발 시려. 그리고 이건 내 마지막 자존심이야.", tag: "[flustered] 니삭스는 안 벗어. 발 시려. 그리고 이건, 내 마지막 자존심이야!" },
  { id: "a4-fd1f2dce1a", who: "amy", text: "뭘 봐? 티셔츠 입은 사람 구경났어?", tag: "[sulky] 뭘 봐? 티셔츠 입은 사람, 구경났어?" },
  { id: "a4-d49a73303f", who: "amy", text: "네가 큰 거야. 나는 정상이야.", tag: "[flustered] 네가 큰 거야. 나는, 정상이야!" },
  { id: "a4-42f41c81c2", who: "amy", text: "…섬유유연제 냄새 하나도 안 나. 그냥 너 냄새야.", tag: "[softly] [flustered] ...섬유유연제 냄새, 하나도 안 나. 그냥, 너 냄새야." },
  { id: "a4-d19f720584", who: "amy", text: "싫다는 거 아니야. 기록하는 거야.", tag: "[flustered] 싫다는 거 아니야. 기록하는 거야." },
  { id: "a4-f3c4b76036", who: "amy", text: "오늘 새로 안 거. 너네 집 주소, 너 냄새, 너 이불 하나인 거.", tag: "[shy] 오늘 새로 안 거... 너네 집 주소, 너 냄새, 너 이불 하나인 거." },
  { id: "a4-ce54648451u", who: "amy", text: "물 딱 맞췄네? 딜러는 라면 물도 칩처럼 세어?", tag: "(직접 생성) [impressed] 물 딱 맞췄네? [teasing] 딜러는 라면 물도, 칩처럼 세어?" },
  { id: "a4-d25907a9ce", who: "amy", text: "…3년 동안 라면만 먹었구나. 이 방에서 계량컵이 제일 비싼 살림이야.", tag: "[sympathetic] ...삼 년 동안 라면만 먹었구나. 이 방에서 계량컵이, 제일 비싼 살림이야." },
  { id: "a4-48e66d664f", who: "amy", text: "다음엔 내가 끓여 줄게. 계량컵 없이. 감으로.", tag: "[confident] 다음엔 내가 끓여 줄게! 계량컵 없이... 감으로!" },
  { id: "a4-8b44596660", who: "amy", text: "그럼 싱거운 거 먹어. 내 감을 믿어 봐. 포커 감보단 나아.", tag: "[playful] 그럼 싱거운 거 먹어. [chuckles] 내 감을 믿어 봐. 포커 감보단 나아!" },
  { id: "a4-f09a0251eb", who: "amy", text: "근데 저 상자는 뭐야? 책상 밑에. 테이프 감긴 거.", tag: "[curious] 근데, 저 상자는 뭐야? 책상 밑에... 테이프 감긴 거." },
  { id: "a4-f793af9166", who: "amy", text: "열라는 거 아니야. 궁금한 거랑 여는 건 다르니까.", tag: "[gentle] 열라는 거 아니야. 궁금한 거랑 여는 건, 다르니까." },
  { id: "a4-f515a506db", who: "amy", text: "…테이프 뜯겨 있네. 위에 종이 삐져나왔어. 'V-1'?", tag: "[curious] ...테이프 뜯겨 있네. 위에 종이 삐져나왔어. '브이 원'?" },
  { id: "a4-b2d3d5ab42", who: "amy", text: "V면… 사장님이 준 칩이랑 같은 V잖아.", tag: "[thoughtful] 브이면... [surprised] 사장님이 준 칩이랑, 같은 브이잖아." },
  { id: "a4-653bc9ed81", who: "amy", text: "V-1? V면 사장님이 준 칩이랑 같은 V잖아.", tag: "[surprised] 브이 원? [thoughtful] 브이면, 사장님이 준 칩이랑 같은 브이잖아." },
  { id: "a4-3218bc1709", who: "amy", text: "…사장님.", tag: "[softly] [sad] ...사장님." },
  { id: "a4-f4d7350d56", who: "amy", text: "그래서 안 앉는 거야? 그래서 맨날 서 있는 거야?", tag: "[sad] 그래서 안 앉는 거야? 그래서 맨날, 서 있는 거야?" },
  { id: "a4-c304b517fb", who: "amy", text: "그 기분 알아. …일어나기 싫은 거.", tag: "[softly] [sad] 그 기분 알아... 일어나기 싫은 거." },
  { id: "a4-30716319ad", who: "amy", text: "같은 테이블이었네. 너는 3년 전에, 아빠는 5년 전에.", tag: "[sad] 같은 테이블이었네... 너는 삼 년 전에, 아빠는 오 년 전에." },
  { id: "a4-1c5df6c186", who: "amy", text: "이거 아는 사람, 나 말고 또 있어?", tag: "[serious] 이거 아는 사람... 나 말고, 또 있어?" },
  { id: "a4-21fe6bb251", who: "amy", text: "그럼 됐어. 비밀 하나씩. 공평하네.", tag: "[shy] 그럼 됐어. 비밀 하나씩. [chuckles] 공평하네." },
  { id: "a4-0d8897aa3f", who: "amy", text: "그럼 하나 더 줄게. …나 사실 바나나우유보다 딸기우유가 더 좋아.", tag: "[playful] 그럼 하나 더 줄게. ...나 사실, 바나나우유보다 딸기우유가 더 좋아." },
  { id: "a4-7c01e0883b", who: "amy", text: "……비밀 하나 날렸네. 환불해 줘.", tag: "[sulky] ......비밀 하나 날렸네. 환불해 줘!" },
  { id: "a4-47e90a3182", who: "amy", text: "…3년 전.", tag: "[thoughtful] ...삼 년 전." },
  { id: "a4-d181a8f59a", who: "amy", text: "알았어. 안 물어. 나도 지갑 안쪽 칸은 아무한테나 안 보여 줘.", tag: "[gentle] 알았어. 안 물어. 나도 지갑 안쪽 칸은, 아무한테나 안 보여 줘." },
  { id: "a4-38316b402c", who: "amy", text: "대신 열 때 불러. 너 혼자 열면 울 것 같아. 휴지 담당 해 줄게.", tag: "[warm] 대신, 열 때 불러. 너 혼자 열면 울 것 같아. [chuckles] 휴지 담당 해 줄게." },
  { id: "a4-abfdc46abe", who: "amy", text: "네 티셔츠 소매 있잖아. 길어서 딱이야.", tag: "[playful] 네 티셔츠 소매 있잖아. [chuckles] 길어서 딱이야!" },
  { id: "a4-8e69786511c", who: "amy", text: "꺅! 뭐, 뭐야! 정전?!", tag: "[screaming] 꺅! 뭐, 뭐야?! 정전?!" },
  { id: "a4-891ccebd44", who: "amy", text: "천둥 무서운 거 아니야. 깜깜해서 놀란 거야. 둘은 달라.", tag: "[nervous] [defensive] 천둥 무서운 거 아니야. 깜깜해서 놀란 거야. 둘은 달라." },
  { id: "a4-50dd118982", who: "amy", text: "…방음.", tag: "[sulky] ...방음." },
  { id: "a4-ddf645fd5fc", who: "amy", text: "…딜러. 오늘 바닥에서 자?", tag: "[whispers] [shy] ...딜러. 오늘, 바닥에서 자?" },
  { id: "a4-9524738d36", who: "amy", text: "그럼 말 시키지 마. 나 잘 거야.", tag: "[sulky] 그럼 말 시키지 마. 나 잘 거야." },
  { id: "a4-ae8d63fbecc", who: "amy", text: "봐. 토끼.", tag: "[whispers] [playful] 봐... 토끼." },
  { id: "a4-1bedc20017", who: "amy", text: "토끼야! 귀가 길잖아!", tag: "[sulky] 토끼야! 귀가 길잖아!" },
  { id: "a4-da972a0d9b", who: "amy", text: "……딜러. 손가락 길쭉한 거. 셔플하는 중이야.", tag: "[playful] ...딜러. [chuckles] 손가락 길쭉한 거... 셔플하는 중이야." },
  { id: "a4-d536e41023", who: "amy", text: "딜러 손은 그림자로 봐도 빠르네. …한 번만 더 해 봐.", tag: "[delighted] 딜러 손은, 그림자로 봐도 빠르네. ...한 번만 더 해 봐!" },
  { id: "a4-fa6203859dc", who: "amy", text: "…아빠가 천둥 치는 날마다 그랬어. 침대 옆 바닥에서 자 주면서.", tag: "[whispers] [sad] ...아빠가, 천둥 치는 날마다 그랬어. 침대 옆 바닥에서... 자 주면서." },
  { id: "a4-e60b691144c", who: "amy", text: "너 아빠 닮았다는 거 아니야. 하나도 안 닮았어.", tag: "[whispers] [flustered] 너, 아빠 닮았다는 거 아니야. 하나도... 안 닮았어." },
  { id: "a4-83e9239f69", who: "amy", text: "…그래서 더 이상해.", tag: "[softly] [flustered] ...그래서, 더 이상해." },
  { id: "a4-83f7c74ddcc", who: "amy", text: "……반칙이야. 말도 없이.", tag: "[whispers] [shy] ......반칙이야. 말도 없이." },
  { id: "a4-b3abc72a07c", who: "amy", text: "천둥 그치면 놓을 거야? 그럼 천둥 계속 쳤으면 좋겠다.", tag: "[whispers] [playful] 천둥 그치면, 놓을 거야? 그럼... 천둥 계속 쳤으면 좋겠다." },
  { id: "a4-2a9135d12fc", who: "amy", text: "…방금 건 잠꼬대야.", tag: "[whispers] [flustered] ...방금 건, 잠꼬대야." },
  { id: "a4-85624e17e9c", who: "amy", text: "잘 자, 딜러.", tag: "[whispers] [sleepy] 잘 자, 딜러..." },
  { id: "a4-b53f003ac8", who: "amy", text: "…왜 왔어? 오후에 오기로 했잖아.", tag: "[flustered] ...왜 왔어? 오후에 오기로 했잖아!" },
  { id: "a4-c545849b6ac", who: "amy", text: "……그 얘기 여기서 하지 마. 점장님 창고에 있어.", tag: "[whispers] [panicked] ......그 얘기, 여기서 하지 마! 점장님, 창고에 있어!" },
  { id: "a4-86af85b840", who: "amy", text: "어젯밤은 비상사태였어. 비상사태엔 원래 손 잡는 거야. 매뉴얼에 있어.", tag: "[defensive] 어젯밤은 비상사태였어. 비상사태엔 원래 손 잡는 거야. 매뉴얼에 있어!" },
  { id: "a4-ffb904b3d1", who: "amy", text: "반지하 매뉴얼. 1년 차가 썼어. 방금.", tag: "[playful] 반지하 매뉴얼. [chuckles] 일 년 차가 썼어. 방금!" },
  { id: "a4-d89d137f99", who: "amy", text: "팔 저린 값. 이걸로 퉁. …오후에 장판 들 때 그 팔 써야 돼. 아껴.", tag: "[warm] 팔 저린 값. 이걸로 퉁. ...오후에 장판 들 때 그 팔 써야 돼. 아껴." },
  { id: "a4-8f4125711c", who: "amy", text: "왔다, 일꾼. 퇴근하자마자 왔어. 칭찬해.", tag: "[bright] 왔다, 일꾼! 퇴근하자마자 왔어. [chuckles] 칭찬해!" },
  { id: "a4-6c5cf5ed9d", who: "amy", text: "……아니야. 회색은 세상에 많아.", tag: "[flustered] ......아니야. 회색은, 세상에 많아." },
  { id: "a4-7006742a6c", who: "amy", text: "장판 걷자. 하나, 둘, 셋에 들어. 셋에. 둘에 들면 반칙이야.", tag: "[bossy] 장판 걷자. 하나, 둘, 셋에 들어. 셋에! 둘에 들면, 반칙이야." },
  { id: "a4-c5d3f7d057", who: "amy", text: "영차. 영차. …너 지금 힘 하나도 안 쓰지? 표정이 너무 편해.", tag: "[straining] 영차... 영차... [suspicious] 너 지금, 힘 하나도 안 쓰지? 표정이 너무 편해!" },
  { id: "a4-df10b63d7d", who: "amy", text: "그럼 이건? 왼쪽 끝까지 혼자 들어 봐.", tag: "[teasing] 그럼 이건? 왼쪽 끝까지, 혼자 들어 봐." },
  { id: "a4-1b3f14b5ce", who: "amy", text: "지금 잡은 건 장판 탓이야. 장판이 미끄러워서야.", tag: "[nervous] [flustered] 지금 잡은 건... 장판 탓이야. 장판이 미끄러워서야!" },
  { id: "a4-133858eb3f", who: "amy", text: "……바닥 아직 미끄러워. 좀만 있다가.", tag: "[softly] [flustered] ......바닥 아직 미끄러워. 좀만, 있다가." },
  { id: "a4-dcf6da4669c", who: "amy", text: "그러니까 넘어지기 직전이라고! 가만있어!", tag: "[flustered] [shouting] 그러니까, 넘어지기 직전이라고! 가만있어!" },
  { id: "a4-34fd25c510", who: "amy", text: "아, 이분은… 그, 우리 가게, 아니 제 가게 아니고, 펍의, 딜러… 아니 이삿짐센터 분이에요!", tag: "[panicked] 아, 이분은... 그, 우리 가게, 아니 제 가게 아니고, 펍의, 딜러... [stuttering] 아니, 이삿짐센터 분이에요!" },
  { id: "a4-2f6cb61476", who: "amy", text: "미끄러져서요! 장판 탓이에요! 장판이 미끄러워서요!", tag: "[panicked] 미끄러져서요! 장판 탓이에요! 장판이 미끄러워서요!" },
  { id: "a4-6923bb252du", who: "amy", text: "……반이나 내 준대? 저 아줌마가? 1년 동안 전구 하나 안 갈아 줬는데.", tag: "(직접 생성) [disbelief] 반이나 내 준대? 저 아줌마가? [incredulous, half-laughing] 일 년 동안, 전구 하나 안 갈아 줬는데." },
  { id: "a4-afec12e3fd", who: "amy", text: "너 진짜 이삿짐센터 같은 얼굴이었어. 성실해 보이는 얼굴.", tag: "[chuckles] 너 진짜, 이삿짐센터 같은 얼굴이었어. [teasing] 성실해 보이는 얼굴." },
  { id: "a4-22e026bf12", who: "amy", text: "칭찬이야. 아까 잡은 건 빼고. 그건 장판 탓이야.", tag: "[playful] 칭찬이야. 아까 잡은 건 빼고... 그건, 장판 탓이야." },
  { id: "a4-7f66582c3a", who: "amy", text: "아빠가 새긴 거야. 이 책상만 미국에서 들고 왔어. 이삿짐 값이 책상 값보다 비쌌어.", tag: "[fond] 아빠가 새긴 거야. 이 책상만, 미국에서 들고 왔어. [chuckles] 이삿짐 값이 책상 값보다 비쌌어." },
  { id: "a4-072d21c337", who: "amy", text: "물 들어올 때 이거부터 붙잡았어. 웃기지? 노트북보다 먼저.", tag: "[chuckles] [wry] 물 들어올 때, 이거부터 붙잡았어. 웃기지? 노트북보다 먼저." },
  { id: "a4-7776f38ac4", who: "amy", text: "이거. 비상 열쇠. 또 물 차면 네가 먼저 와.", tag: "[earnest] 이거... 비상 열쇠. 또 물 차면, 네가 먼저 와." },
  { id: "a4-a214bd2236", who: "amy", text: "…물 안 차도 와도 되고. 아니, 그건 취소. 물 찰 때만.", tag: "[flustered] ...물 안 차도 와도 되고. 아니, 그건 취소! 물 찰 때만." },
  { id: "a4-e409ca299c", who: "amy", text: "……비 오는 날도 포함.", tag: "[softly] [shy] ......비 오는 날도, 포함." },
  { id: "a4-9760a2cf64", who: "amy", text: "그러니까 알아서 해. 계산은 네 전문이잖아.", tag: "[playful] 그러니까, 알아서 해. [chuckles] 계산은 네 전문이잖아!" },
  { id: "a4-9aaa5ad4bd", who: "amy", text: "내 머리끈 여분. 열쇠 잃어버리면 하늘색 찾으면 돼. 이 동네에 하늘색은 나밖에 없어.", tag: "[proud] 내 머리끈 여분. 열쇠 잃어버리면, 하늘색 찾으면 돼. 이 동네에 하늘색은, 나밖에 없어." },
  { id: "a4-56dedee251u", who: "amy", text: "…그거, 우리 집 하나뿐인 여분이야. 잃어버리면 진짜 죽어.", tag: "(직접 생성) [flustered] ...그거, 우리 집 하나뿐인 여분이야. 잃어버리면, 진짜 죽어!" },
  { id: "a4-dd6c7be4c9", who: "amy", text: "이모님 안녕하세요! 태양, 정민, 이거 받아.", tag: "[cheerful] 이모님, 안녕하세요! 태양, 정민, 이거 받아." },
  { id: "a4-df1eb346ad", who: "amy", text: "어제 물난리 때 가게 정리 다 했다며. 이모님한테 들었어. 이건 수고비야.", tag: "[warm, a little proud] 어제 물난리 때, 가게 정리 다 했다며. 이모님한테 들었어. 이건 수고비야." },
  { id: "a4-c583fab23d", who: "amy", text: "무슨 티셔츠? 나 오늘 하루 종일 조끼만 입었는데.", tag: "[innocent, playing dumb] 무슨 티셔츠? 나 오늘 하루 종일, 조끼만 입었는데." },
  { id: "a4-dffcaa7bf5", who: "amy", text: "……정민. 바나나우유 도로 내놔.", tag: "[flustered] ......정민. [loud, embarrassed] 바나나우유, 도로 내놔!" },
  { id: "a4-1dc79a8a4ac", who: "amy", text: "딜러! 너 표정 관리해! 너 때문에 다 들키잖아!", tag: "[flustered] [shouting] 딜러! 너 표정 관리해! 너 때문에, 다 들키잖아!" },
  { id: "a4-eac859cfe0c", who: "amy", text: "그 '아무 말도'가 제일 시끄러워!", tag: "[flustered] [shouting] 그 아무 말도가, 제일 시끄러워!" },
  { id: "a4-81bbe373af", who: "amy", text: "…네! 이모님 김치찌개요. 덜 맵게요!", tag: "[brightening] ...네! 이모님 김치찌개요. [cute, pleading] 덜 맵게요!" },
  { id: "a4-1226e7bcf3", who: "amy", text: "수고비 환불이야.", tag: "[smug] 수고비, 환불이야." },
  { id: "a4-50b96b1b0f", who: "amy", text: "짠. 점장님이 워터파크 표 줬어. 두 장. 비 때문에 고생했다고 위로금이래.", tag: "[excited, smug] 짠! 점장님이 워터파크 표 줬어. 두 장. 비 때문에 고생했다고, 위로금이래." },
  { id: "a4-f0cfcfb213", who: "amy", text: "…오늘은 안 돼. 내일 때문에 머리가 꽉 찼어.", tag: "[hesitant, subdued] ...오늘은 안 돼. 내일 때문에, 머리가 꽉 찼어." },
  { id: "a4-378b4a578c", who: "amy", text: "내일 이기면 가자. 진 사람이 튜브 불기. 입으로.", tag: "[perking up, smug] 내일 이기면 가자. 진 사람이 튜브 불기. [teasing] 입으로." },
  { id: "a4-b45b861973", who: "amy", text: "…그러네. 그럼 그냥 네가 불어.", tag: "[realizing] ...그러네. [playful] 그럼, 그냥 네가 불어." },
  { id: "a4-b6bc1640de", who: "amy", text: "유효기간 다음 달 말까지야. 그 전엔 가는 거야.", tag: "[firm] 유효기간, 다음 달 말까지야. 그 전엔 가는 거야." },
  { id: "a4-43705c33cc", who: "amy", text: "손 줘 봐.", tag: "[gentle, serious] 손 줘 봐." },
  { id: "a4-bc189f5742", who: "amy", text: "부적. 내일 그 방에서 이거 보고 있어. 나도 네 손목 볼 거야.", tag: "[earnest] 부적. 내일 그 방에서, 이거 보고 있어. 나도 네 손목 볼 거야." },
  { id: "a4-5d39834667", who: "amy", text: "아니. 아침에 머리에 하나 더 묶고 나왔어. 줄 거니까. 따끈따끈한 진짜야.", tag: "[embarrassed, defensive] 아니. 아침에 머리에 하나 더 묶고 나왔어. 줄 거니까. [proud] 따끈따끈한 진짜야." },
  { id: "a4-2fd30b56b3", who: "amy", text: "내일 끝나면 돌려받을 거야. 짝은 맞춰야 하니까.", tag: "[smug] 내일 끝나면, 돌려받을 거야. 짝은 맞춰야 하니까." },
  { id: "a4-6b055a2382", who: "amy", text: "…잃어버리면 죽어. 진짜로.", tag: "[pouty, playful threat] ...잃어버리면 죽어. [mock serious] 진짜로." },
  { id: "a4-0e39a9eb19", who: "amy", text: "늦었어. 1분. 벌칙으로 이거 들어.", tag: "[teasing, bossy] 늦었어. 일 분! 벌칙으로, 이거 들어." },
  { id: "a4-6ec56c47a2", who: "amy", text: "돗자리, 튜브, 수건 세 장, 삼각김밥 여섯 개, 바나나우유 네 개.", tag: "[cheerful, listing] 돗자리, 튜브, 수건 세 장, 삼각김밥 여섯 개, 바나나우유 네 개." },
  { id: "a4-83d9e1224b", who: "amy", text: "물놀이하면 배고파. 아빠가 그랬어. 그리고 남으면 저녁이야. 계획적이지?", tag: "[matter-of-fact] 물놀이하면 배고파. 아빠가 그랬어. 그리고 남으면 저녁이야. [proud] 계획적이지?" },
  { id: "a4-83b52fe38c", who: "amy", text: "적었지. '워터파크 — 지출 0원'. 표도 공짜, 밥도 폐기 직전 할인.", tag: "[proud] 적었지. 워터파크, 지출 영 원. 표도 공짜, 밥도 폐기 직전 할인." },
  { id: "a4-f198d9bc68", who: "amy", text: "오늘 하루는 숫자가 다 0이야. 그게 제일 좋아.", tag: "[happy, content] 오늘 하루는, 숫자가 다 영이야. 그게 제일 좋아." },
  { id: "a4-7dff9d535f", who: "amy", text: "오늘은 아무 생각 안 할 거야. 숫자도, 아빠도, 의자도.", tag: "[resolute, bright] 오늘은 아무 생각 안 할 거야. 숫자도, 아빠도, 의자도." },
  { id: "a4-149797aba6", who: "amy", text: "오늘 하루는 데이트야. …아, 아니. 현장 학습이야.", tag: "[cheerful] 오늘 하루는 데이트야. [flustered, correcting herself] ...아, 아니. 현장 학습이야." },
  { id: "a4-340c737def", who: "amy", text: "물의 현장. 시끄러워.", tag: "[flustered, pouty] 물의 현장. [embarrassed] 시끄러워." },
  { id: "a4-522b3470fb", who: "amy", text: "그리고 내기. 오늘 슬라이드에서 소리 지르는 사람이 저녁 사기. 한 번이라도.", tag: "[smug, competitive] 그리고 내기. 오늘 슬라이드에서 소리 지르는 사람이, 저녁 사기. 한 번이라도." },
  { id: "a4-75fa9bb84f", who: "amy", text: "그걸 네가 어떻게 알아? 나 롤러코스터 맨 앞자리만 타는 사람이야.", tag: "[indignant] 그걸 네가 어떻게 알아? 나 롤러코스터, 맨 앞자리만 타는 사람이야." },
  { id: "a4-de30aade4e", who: "amy", text: "……그건 선크림 발라서 하얀 거야.", tag: "[flustered, defensive] ......그건, 선크림 발라서 하얀 거야." },
  { id: "a4-3361874abe", who: "amy", text: "아무튼 내기 콜이지? 저녁은 떡볶이. 진 사람이 맵기 고르는 권리 없음.", tag: "[smug] 아무튼, 내기 콜이지? 저녁은 떡볶이. 진 사람이, 맵기 고르는 권리 없음." },
  { id: "a4-788d54e7cb", who: "amy", text: "오늘은 안 나. 오늘 '콜'은 떡볶이 콜이야. 단어도 쉬는 날이 있어야지.", tag: "[relaxed, cheerful] 오늘은 안 나. 오늘 콜은, 떡볶이 콜이야. 단어도 쉬는 날이 있어야지." },
  { id: "a4-7dccc57d6f", who: "amy", text: "…일부러 아니야. 도망 못 가게 한 거야. 아, 그게 일부러인가.", tag: "[flustered] ...일부러 아니야. 도망 못 가게 한 거야. [realizing, mumbling] 아, 그게 일부러인가." },
  { id: "a4-2d5ba38813", who: "amy", text: "미아 방지야. 워터파크에서 딜러 잃어버리면 방송해야 되잖아. '딜러 손님 찾습니다.'", tag: "[teasing] 미아 방지야. 워터파크에서 딜러 잃어버리면 방송해야 되잖아. [playful announcer voice] 딜러 손님 찾습니다." },
  { id: "a4-f4fce48c13", who: "amy", text: "오늘 하루는 내 거야. 팔찌 번호도 붙어 있어. 1052, 1053.", tag: "[playful, sweet] 오늘 하루는 내 거야. 팔찌 번호도 붙어 있어. 천오십이, 천오십삼." },
  { id: "a4-b5cf4272e4", who: "amy", text: "탈의실 갔다 올게. 나오면 하나, 둘, 셋 하고 돌아봐. 둘에 돌아보면 물에 빠뜨릴 거야.", tag: "[playful] 탈의실 갔다 올게. 나오면, 하나, 둘, 셋 하고 돌아봐. [mock threat] 둘에 돌아보면, 물에 빠뜨릴 거야." },
  { id: "a4-8a1051c195", who: "amy", text: "…아까 셋 하고 돌아봤을 때. 왜 아무 말도 안 했어?", tag: "[pouty, quiet] ...아까 셋 하고 돌아봤을 때. 왜 아무 말도 안 했어?" },
  { id: "a4-8afe431652", who: "amy", text: "그건 반사야. 다시 해. 지금.", tag: "[embarrassed, bossy] 그건 반사야. 다시 해. 지금." },
  { id: "a4-e7908d2a8e", who: "amy", text: "……세일해서 산 거야. 세일한 게 잘 어울리는 거야.", tag: "[flustered, shy] ......세일해서 산 거야. [mumbling] 세일한 게, 잘 어울리는 거야." },
  { id: "a4-02521d3b6c", who: "amy", text: "일곱 살 때 아빠랑 이런 데 왔었어. 나 일부러 손 놓고 떠내려갔다? 아빠가 찾으러 오는 게 좋아서.", tag: "[nostalgic, smiling] 일곱 살 때, 아빠랑 이런 데 왔었어. 나 일부러 손 놓고 떠내려갔다? 아빠가 찾으러 오는 게 좋아서." },
  { id: "a4-248ffdf193", who: "amy", text: "엄청 혼나고, 아이스크림 얻어먹었어. 혼내고 사 주는 게 아빠 특기였어.", tag: "[fond] 엄청 혼나고, 아이스크림 얻어먹었어. 혼내고 사 주는 게, 아빠 특기였어." },
  { id: "a4-f24cc24cba", who: "amy", text: "오늘은 안 놓을 거야. 찾으러 올 사람이 너밖에 없는데, 너 수영 못할 것 같아.", tag: "[soft, tender] 오늘은 안 놓을 거야. 찾으러 올 사람이 너밖에 없는데, [teasing] 너 수영 못할 것 같아." },
  { id: "a4-a4677149f0u", who: "amy", text: "그럼 더 안 놔. 잘하는 사람한테 끌려가는 게 제일 편해.", tag: "(직접 생성) [whispers] [shy] 그럼, 더 안 놔... 잘하는 사람한테 끌려가는 게, 제일 편해." },
  { id: "a4-cec26a9f2d", who: "amy", text: "…떡볶이는 내가 사. 열한 번은 너무했어. 근데 다 너 들으라고 지른 거야.", tag: "[sheepish, pouty] ...떡볶이는 내가 사. 열한 번은 너무했어. [embarrassed] 근데, 다 너 들으라고 지른 거야." },
  { id: "a4-c0895ffa88", who: "amy", text: "배 안 고파. 긴장해서 그런 거 아니야. 아침을 많이 먹어서야.", tag: "[pouty, defensive] 배 안 고파. 긴장해서 그런 거 아니야. 아침을 많이 먹어서야." },
  { id: "a4-c8209ba03a", who: "amy", text: "……바나나우유. 반 개.", tag: "[sheepish, small voice] ......바나나우유. 반 개." },
  { id: "a4-cc90e19092", who: "amy", text: "…맵다. 근데 맵다는 생각만 하니까, 오늘 밤 생각이 안 나.", tag: "[wincing] ...맵다. [thoughtful] 근데, 맵다는 생각만 하니까, 오늘 밤 생각이 안 나." },
  { id: "a4-6070f88560", who: "amy", text: "마지막 하나는 남겨 둬. 오늘 밤 이기면 먹을 거야.", tag: "[quiet, resolute] 마지막 하나는 남겨 둬. 오늘 밤 이기면 먹을 거야." },
  { id: "a4-f8e5ec0e5a", who: "amy", text: "…생각보다 딱딱하다. 아빠 엉덩이 아팠겠네.", tag: "[wry, soft smile] ...생각보다 딱딱하다. 아빠 엉덩이 아팠겠네." },
  { id: "a4-1dc050b7d7", who: "amy", text: "언니네요. 또.", tag: "[dry, wary] 언니네요. 또." },
  { id: "a4-4bee7bf79e", who: "amy", text: "오늘은 안 져요. 여기 아빠 자리거든요.", tag: "[confident] 오늘은 안 져요. 여기, 아빠 자리거든요." },
  { id: "a4-c3aa39f660", who: "amy", text: "그럼 제 손이 쌓을 거예요. 보세요.", tag: "[confident, smug] 그럼, 제 손이 쌓을 거예요. 보세요." },
  { id: "a4-485ebe9088", who: "amy", text: "접었어요? 언니가? 저한테?", tag: "[surprised, elated] 접었어요? 언니가? 저한테?" },
  { id: "a4-5e4530a4eb", who: "amy", text: "한 판만 더. 아니 두 판. 오늘 진짜 되는 날이야.", tag: "[excited, giddy] 한 판만 더! 아니, 두 판... 오늘 진짜 되는 날이야!" },
  { id: "a4-bbcb40836b", who: "amy", text: "에이, 사장님! 이제 막 손 풀렸는데요!", tag: "[whiny, protesting] 에이, 사장님! 이제 막 손 풀렸는데요!" },
  { id: "a4-22a40d5c45", who: "amy", text: "…치사해. 진짜 지금이야?", tag: "[sulky] ...치사해. 진짜 지금이야?" },
  { id: "a4-3c19830665", who: "amy", text: "……알았어. 연습한 대로.", tag: "[reluctant] ......알았어. 연습한 대로." },
  { id: "a4-3f05d71abcc", who: "amy", text: "이겼어. 이겼어! 아빠 자리에서!", tag: "[ecstatic] [shouting] 이겼어. ...이겼어! 아빠 자리에서!" },
  { id: "a4-b365d5b057c", who: "amy", text: "I did it! 봤어? 아빠가 못 이긴 테이블이야!", tag: "[ecstatic] [shouting] I did it! 봤어?! 아빠가 못 이긴 테이블이야!" },
  { id: "a4-eb36b26178ww", who: "amy", text: "딜러. 나 오늘 멋있었지? 솔직히.", tag: "[tipsy, smug] 딜러어. 나 오늘 멋있었지? 솔직히." },
  { id: "a4-bc7b2b15b0", who: "amy", text: "판 내내 네 손목 봤어. 하늘색 보이니까 손이 덜 떨렸어.", tag: "[tipsy, shy] 판 내내, 네 손목 봤어. 하늘색 보이니까, 손이 덜 떨렸어." },
  { id: "a4-554c48c15f", who: "amy", text: "돌려받으려고 했는데… 하루만 더 차고 있어.", tag: "[soft] 돌려받으려고 했는데... 하루만 더 차고 있어." },
  { id: "a4-1801d0a6bf", who: "amy", text: "…이모님이? 나 주라고?", tag: "[surprised, touched] ...이모님이? 나 주라고?" },
  { id: "a4-5efa8e0977", who: "amy", text: "이긴 날에도 주먹밥이야? 원래 진 날 먹는 거 아니야?", tag: "[amused, puzzled] 이긴 날에도 주먹밥이야? 원래, 진 날 먹는 거 아니야?" },
  { id: "a4-d98517fd1d", who: "amy", text: "월세 내고, 남는 걸로 너 떡볶이 사 줄게. 맵기는 내가 골라. 복수야.", tag: "[cheerful, tipsy] 월세 내고, 남는 걸로 너 떡볶이 사 줄게. 맵기는 내가 골라. [mischievous] 복수야." },
  { id: "a4-f37ab34688", who: "amy", text: "네 폰에 나 아직 '복수'로 저장돼 있잖아. 이름값은 해야지.", tag: "[teasing] 네 폰에, 나 아직 복수로 저장돼 있잖아. 이름값은 해야지." },
  { id: "a4-9994d5fed4", who: "amy", text: "…아, 그리고 아빠 자리. 레일 밑에 뭐가 붙어 있었어. 테이프였어.", tag: "[remembering, slower] ...아, 그리고 아빠 자리. 레일 밑에 뭐가 붙어 있었어. 테이프였어." },
  { id: "a4-ec79a2eadb", who: "amy", text: "아빠는 식탁 밑에 사탕을 테이프로 붙여 놨었어. 이긴 날 상으로. 나만 아는 데.", tag: "[wistful, sad] 아빠는, 식탁 밑에 사탕을 테이프로 붙여 놨었어. 이긴 날 상으로. 나만 아는 데." },
  { id: "a4-6b47fc0b2cc", who: "amy", text: "…I did it, Dad. I beat your stupid table.", tag: "[whispers] [tearful, drowsy] ...I did it, Dad. I beat your stupid table." },
  { id: "a4-1db2a36cd0c", who: "amy", text: "계속 불러 보고 싶었어. 근데 부르면 진짜가 될 것 같아서.", tag: "[whispers] [drowsy, shy] 계속 불러 보고 싶었어. 근데... 부르면 진짜가 될 것 같아서." },
  { id: "a4-9b54885b63", who: "amy", text: "…진짜 돼도 되지?", tag: "[shy, whispering] ...진짜 돼도 되지?" },
  { id: "a4-32052cb8bdc", who: "amy", text: "……알아.", tag: "[hurt] ......알아." },
  { id: "a4-b896af820d", who: "amy", text: "언니가 접을 때마다 손이 미끄러졌어. 나 바보 아니야.", tag: "[sad, bitter] 언니가 접을 때마다, 손이 미끄러졌어. 나 바보 아니야." },
  { id: "a4-47aaee9a14", who: "amy", text: "근데 오늘만은 그 말 안 듣고 싶었어. 오늘만은 진짜로 이긴 사람이고 싶었어.", tag: "[sad, quiet, voice cracking] 근데, 오늘만은 그 말 안 듣고 싶었어. 오늘만은, 진짜로 이긴 사람이고 싶었어." },
  { id: "a4-bb948d250cc", who: "amy", text: "말해 줘서 고마워. …진짜 미운데, 고마워.", tag: "[holding back tears] 말해 줘서, 고마워. ...진짜 미운데, 고마워." },
  { id: "a4-793ab14073", who: "amy", text: "…사장님이요? 아빠 마지막 판을 보셨어요?", tag: "[shocked] ...사장님이요? 아빠 마지막 판을, 보셨어요?" },
  { id: "a4-caf8d6ba60", who: "amy", text: "……한 판만 할게요. 이야기 들으면서.", tag: "[steeling herself, quiet] ......한 판만 할게요. 이야기 들으면서." },
  { id: "a4-94eb614cc9", who: "amy", text: "괜찮아. 괜찮아. 원래 없던 돈이잖아. 본전이야. 그치?", tag: "[forced cheer, shaky] 괜찮아. 괜찮아. 원래 없던 돈이잖아. 본전이야. [small voice] 그치?" },
  { id: "a4-63ff776edb", who: "amy", text: "…괜찮아. 너는 아무 말 안 해도 돼. 이 방에서는.", tag: "[gentle, soft] ...괜찮아. 너는 아무 말 안 해도 돼. 이 방에서는." },
  { id: "a4-c99160f939", who: "amy", text: "내가 쓰는 거야. 네가 못 막은 게 아니라.", tag: "[quiet, resolute] 내가 쓰는 거야. [falling tone] 네가 못 막은 게 아니라." },
  { id: "a4-1bf159d063", who: "amy", text: "……놔.", tag: "[shaky, quiet] ......놔." },
  { id: "a4-0cc509e769c", who: "amy", text: "놔 줘. 이번에 안 들으면 평생 몰라.", tag: "[pleading, on the verge of tears] 놔 줘...! 이번에 안 들으면, 평생 몰라." },
  { id: "a4-731e9cb362", who: "amy", text: "어젯밤에 이름 불렀잖아. …그 값으로, 이번 한 번만.", tag: "[pleading, soft] 어젯밤에 이름 불렀잖아. ...그 값으로, 이번 한 번만." },
  { id: "a4-f17bcbccfec", who: "amy", text: "안 돼. 너는 앉지 마. 절대.", tag: "[desperate] [shouting] 안 돼! 너는 앉지 마. 절대!" },
  { id: "a4-47f15ca81bc", who: "amy", text: "너 앉는 거 보는 게, 내가 지는 것보다 싫어.", tag: "[crying] 너 앉는 거 보는 게... 내가 지는 것보다, 싫어." },
  { id: "a4-91ef47a3c9", who: "amy", text: "차용증에 회사 이름 칸이 비어 있더라. 그런 것도 되는구나.", tag: "[hollow, quiet] 차용증에, 회사 이름 칸이 비어 있더라. 그런 것도 되는구나." },
  { id: "a4-905fa83aa3", who: "amy", text: "……무섭게 말하지 마.", tag: "[scared, small voice] ......무섭게 말하지 마." },
  { id: "a4-d8acfb45a1u", who: "amy", text: "나 아빠랑 똑같아. '다음 주에 다시 올게요.' 그 말, 나도 속으로 했어.", tag: "(직접 생성) [whispers] [ashamed] 나, 아빠랑 똑같아... 다음 주에 다시 올게요. 그 말... 나도 속으로 했어." },
  { id: "a4-00dd5e3e28", who: "amy", text: "다음 주 일요일. 갈 거야. 이번엔 진짜 이길 거야.", tag: "[stubborn, resolute] 다음 주 일요일. 갈 거야. 이번엔, 진짜 이길 거야." },
  { id: "a4-3930e122b2", who: "amy", text: "…열쇠 썼네. 비도 안 오는데.", tag: "[surprised, faint] ...열쇠 썼네. 비도 안 오는데." },
  { id: "a4-277f9b18da", who: "amy", text: "……그건 맞네.", tag: "[deflated] ......그건 맞네." },
  { id: "a4-2b5a0e05c8", who: "amy", text: "계산 중이었어. 차용증 300 더하기 남은 월세 더하기 이것저것. 삼백오십이 조금 안 돼.", tag: "[flat, tired] 계산 중이었어. 차용증 삼백 더하기, 남은 월세 더하기, 이것저것. 삼백오시비 조금 안 돼." },
  { id: "a4-10594db328", who: "amy", text: "숫자는 적을수록 커지기만 해. 하나도 안 줄어.", tag: "[quiet, defeated] 숫자는, 적을수록 커지기만 해. 하나도 안 줄어." },
  { id: "a4-c336ad10b4", who: "amy", text: "엄마가 맨날 그랬어. '너는 네 아빠 닮았어.' 칭찬인 줄 알았는데.", tag: "[quiet, bitter] 엄마가 맨날 그랬어. 너는 네 아빠 닮았어. [falling tone] 칭찬인 줄 알았는데." },
  { id: "a4-01ab7c541d", who: "amy", text: "…반년?", tag: "[stunned, quiet] ...반년?" },
  { id: "a4-a6704b703a", who: "amy", text: "근데 왜 네 팁까지 넣었어? 빼. …안 빼도 되는데, 빼.", tag: "[flustered, teary] 근데, 왜 네 팁까지 넣었어? 빼. [mumbling] ...안 빼도 되는데, 빼." },
  { id: "a4-7c810a9e29c", who: "amy", text: "이기고 싶었어. 한 번만. 아빠 대신. …그게 다였는데.", tag: "[sobbing] 이기고 싶었어... 한 번만. 아빠 대신. ...그게, 다였는데..." },
  { id: "a4-7451ac8cf1c", who: "amy", text: "…이러지 마. 다 울었는데. 다 운 줄 알았는데.", tag: "[crying] ...이러지 마. 다 울었는데... 다 운 줄, 알았는데..." },
  { id: "a4-ae3b6385bd", who: "amy", text: "…셔츠에 콧물 묻었어. 그건 사과 안 할 거야.", tag: "[sniffling, pouty] ...셔츠에 콧물 묻었어. 그건, 사과 안 할 거야." },
  { id: "a4-7624bdf295", who: "amy", text: "…이모님 계란말이다. 이거 반칙이야. 울고 나서 이거 먹으면 또 울잖아.", tag: "[teary, sniffling] ...이모님 계란말이다. [whiny] 이거 반칙이야. 울고 나서 이거 먹으면, 또 울잖아." },
  { id: "a4-4c2f6bf435", who: "amy", text: "시멘트 바닥에서 소풍 하는 사람, 우리밖에 없을걸.", tag: "[small smile] 시멘트 바닥에서 소풍 하는 사람, 우리밖에 없을걸." },
  { id: "a4-c31e443eb7c", who: "amy", text: "그건 아직 축축해! 엉덩이 다 젖어!", tag: "[laughing] [shouting] 그건 아직 축축해! 엉덩이 다 젖어!" },
  { id: "a4-0997054178", who: "amy", text: "마지막 계란말이. 가위바위보로 정해. 하나, 둘, 셋.", tag: "[smug, playful] 마지막 계란말이. 가위바위보로 정해. 하나, 둘, 셋!" },
  { id: "a4-af8701b6ba", who: "amy", text: "…너 일부러 졌지? 내기 직전에 손가락이 펴지는 거 봤어. 주먹 내려다가 바꾼 손이야.", tag: "[pouty, suspicious] ...너 일부러 졌지? 내기 직전에 손가락이 펴지는 거 봤어. 주먹 내려다가 바꾼 손이야." },
  { id: "a4-77319efa03", who: "amy", text: "나도 이제 손부터 봐. 얼굴은 거짓말하니까. …그러니까 이건 반 잘라서 먹어.", tag: "[proud, warm] 나도 이제 손부터 봐. 얼굴은 거짓말하니까. [softer] ...그러니까 이건, 반 잘라서 먹어." },
  { id: "a4-13b5194233", who: "amy", text: "그리고 레일 밑 테이프. 사탕 아니었어. 종이였어. 두꺼운 공책 같은 거.", tag: "[serious, quiet] 그리고 레일 밑 테이프. 사탕 아니었어. 종이였어. 두꺼운 공책 같은 거." },
];
const V2_P2: VoiceLine[] = [
  { id: "a4-3c67712f38", who: "amy", text: "아빠가 붙인 거야. 아빠는 테이프를 꼭 X자로 붙였거든. 손끝으로 만져졌어.", tag: "[softly, sad] 아빠가 붙인 거야. 아빠는 테이프를 꼭 엑스 자로 붙였거든. 손끝으로 만져졌어." },
  { id: "a4-7e19d77e43", who: "amy", text: "…오늘이랑 내일?", tag: "[surprised] ...오늘이랑 내일?" },
  { id: "a4-3598d17dd4", who: "amy", text: "번호는 알아. 사장님 누를 때 봤어. 7, 1, 9, 4. 칩 세듯이 셌지.", tag: "[smug] 번호는 알아. 사장님 누를 때 봤어. 칠, 일, 구, 사. 칩 세듯이 셌지." },
  { id: "a4-effc364fa0", who: "amy", text: "내일 마감 후. 같이 가 줘.", tag: "[serious, quiet] 내일 마감 후. 같이 가 줘." },
  { id: "a4-fbc0d858ab", who: "amy", text: "혼자서도 갈 수 있어. 근데 너랑 가고 싶어.", tag: "[earnest] 혼자서도 갈 수 있어. 근데, 너랑 가고 싶어." },
  { id: "a4-dc88f32c7e", who: "amy", text: "……무서워서 그래. 그건 말 안 하려고 했는데.", tag: "[embarrassed, small voice] ......무서워서 그래. 그건, 말 안 하려고 했는데." },
  { id: "a4-d11ad8d7b1c", who: "amy", text: "이모님, 다 아시는 거지?", tag: "[whispers] [nervous] 이모님, 다 아시는 거지?" },
  { id: "a4-db112096be", who: "amy", text: "영화에선 그래. 웃지 말랬지.", tag: "[whispering, pouty] 영화에선 그래. 웃지 말랬지." },
  { id: "a4-1b4cb26475", who: "amy", text: "……뭐야, 이 사람들.", tag: "[stunned, touched] ......뭐야, 이 사람들." },
  { id: "a4-0d0caba13c", who: "amy", text: "기적은 일요일 끝나고 긁을래. 지금 긁었다가 꽝이면 기분 나빠.", tag: "[warm smile] 기적은, 일요일 끝나고 긁을래. 지금 긁었다가 꽝이면, 기분 나빠." },
  { id: "a4-696e726251c", who: "amy", text: "…있어. X자. 아빠 테이프야.", tag: "[whispers] [breathless] ...있어. 엑스 자. 아빠 테이프야." },
  { id: "a4-b65e0c0076c", who: "amy", text: "……한 쌍.", tag: "[whispers] [choked up] ......한 쌍." },
  { id: "a4-511a3d40eec", who: "amy", text: "아빠 거짓말쟁이. 갖고 있겠다며. 여기다 두고 갔잖아.", tag: "[whispers] [crying] 아빠 거짓말쟁이... 갖고 있겠다며. 여기다 두고 갔잖아..." },
  { id: "a4-3c1f3b1846c", who: "amy", text: "나 찾으라고 둔 거지? …나만 아는 데에. X자로.", tag: "[crying] 나 찾으라고 둔 거지...? 나만 아는 데에. ...엑스 자로." },
  { id: "a4-86abc8add3c", who: "amy", text: "…너 손 엄청 뜨거웠어. 쇠가 다 데워질 만큼.", tag: "[whispers] [shy] ...너 손, 엄청 뜨거웠어. 쇠가 다 데워질 만큼." },
  { id: "a4-db0156c3ecc", who: "amy", text: "내 심장 빨랐던 건 무서워서야. …반은.", tag: "[whispers] [shy] 내 심장 빨랐던 건, 무서워서야. ...반은." },
  { id: "a4-159de34970c", who: "amy", text: "그건 일요일 끝나고 말해 줄게. 살아서 나가면.", tag: "[whispers] [shy] 그건, 일요일 끝나고 말해 줄게. 살아서 나가면." },
  { id: "a4-fcdfb9fcf3", who: "amy", text: "오늘은 못 읽겠어. 아빠 글씨 보면 무너질 것 같아.", tag: "[quiet, shaky] 오늘은 못 읽겠어. 아빠 글씨 보면, 무너질 것 같아." },
  { id: "a4-3b6ca91a26", who: "amy", text: "내일. 너랑 같이 읽을래. 너네 집에서. 우리 집은 아직 바닥이 없으니까.", tag: "[soft, shy] 내일. 너랑 같이 읽을래. 너네 집에서. 우리 집은 아직, 바닥이 없으니까." },
  { id: "a4-28aa864b10", who: "amy", text: "…어서 오세요. 봉투 필요하세요?", tag: "[polite, stiff] ...어서 오세요. 봉투 필요하세요?" },
  { id: "a4-a01601c834", who: "amy", text: "손님이잖아. 손님한테는 존댓말 해. 점장님 규칙이야.", tag: "[pouty, stiff] 손님이잖아. 손님한테는 존댄말 해. 점장님 규칙이야." },
  { id: "a4-88eee218ba", who: "amy", text: "……그건 펍 얘기고. 여긴 편의점이야.", tag: "[sad, quiet] ......그건 펍 얘기고. 여긴 편의점이야." },
  { id: "a4-e42b49fb26", who: "amy", text: "테이프 얘기는 잊었어. 네 말대로. 그러니까 너도 잊어.", tag: "[cold, flat] 테이프 얘기는 잊었어. 네 말대로. 그러니까 너도 잊어." },
  { id: "a4-ab976255d7", who: "amy", text: "첫 장. '7194 — door. He never changes it.' …아빠 글씨야. 7에 가운데 줄 긋는 거.", tag: "[sad, reading slowly] 첫 장. 칠일구사, door. He never changes it. [softly] ...아빠 글씨야. 칠에 가운데 줄 긋는 거." },
  { id: "a4-642d7676d5c", who: "amy", text: "날짜, 금액, 테이블 번호. 줄마다 끝에 똑같은 게 있어. 'House — Y'.", tag: "[reading, focused] 날짜, 금액, 테이블 번호... 줄마다 끝에, 똑같은 게 있어. House, Y." },
  { id: "a4-6de029adfb", who: "amy", text: "'세 번째 판은 늘 하우스가 이긴다.' '딜러 손은 깨끗하다. 카드가 처음부터 그렇게 온다.'", tag: "[reading, quiet] 세 번째 판은, 늘 하우스가 이긴다. 딜러 손은 깨끗하다. 카드가 처음부터 그렇게 온다." },
  { id: "a4-4de72223ed", who: "amy", text: "'백 — always smiling. 이길 때만 손가락 세 개로 테이블을 두드린다.'", tag: "[reading, tense] 백, always smiling. 이길 때만, 손가락 세 개로 테이블을 두드린다." },
  { id: "a4-1270fecb8f", who: "amy", text: "아빠도 숫자 안 적는 사람이라며. 나처럼. 근데 다 적었잖아. 전부.", tag: "[shaky, upset] 아빠도 숫자 안 적는 사람이라며. 나처럼. 근데 다 적었잖아. 전부." },
  { id: "a4-b5d4adbe47c", who: "amy", text: "알면서 앉은 거야? 지는 판인 거 알면서? 왜?", tag: "[on the verge of tears] 알면서 앉은 거야...? 지는 판인 거 알면서? 왜...?" },
  { id: "a4-9db9e99fc3c", who: "amy", text: "…여기 하나 더 있어. 'House Y — 24살. 한쪽 손에만 검은 장갑. 손바닥을 다쳤다.'", tag: "[whispers] [reading] ...여기 하나 더 있어. House, Y. 스물네 살. 한쪽 손에만, 검은 장갑. 손바닥을 다쳤다." },
  { id: "a4-55343baf5e", who: "amy", text: "'그 애도 빚에 묶여 있다. 그 애 잘못 아니다.'", tag: "[reading, hushed] 그 애도 빚에 묶여 있다. 그 애 잘못 아니다." },
  { id: "a4-3dc94c190a", who: "amy", text: "……검은 장갑.", tag: "[stunned, hushed] ......검은 장갑." },
  { id: "a4-e24ba279ab", who: "amy", text: "한쪽 손에만. 스물넷. 5년 전이면… 지금은.", tag: "[stunned, hushed] 한쪽 손에만. 스물넷. 오 년 전이면... [falling tone] 지금은." },
  { id: "a4-45a38d227e", who: "amy", text: "연서 언니.", tag: "[shaky, breaking] 연서 언니." },
  { id: "a4-5281eadd1ac", who: "amy", text: "아빠 맞은편. 언니였어. 나 처음 내려간 날도, 지난 토요일도.", tag: "[trembling] 아빠 맞은편... 언니였어. 나 처음 내려간 날도... 지난 토요일도." },
  { id: "a4-9cb6410cd2c", who: "amy", text: "…마지막 장. 'Amy. My little gambler. 네가 이걸 읽으면, 너는 내 자리에 앉은 거다. 일어나라. 지금.'", tag: "[whispers] [tearful] ...마지막 장. Amy. My little gambler. 네가 이걸 읽으면, 너는 내 자리에 앉은 거다. 일어나라. 지금." },
  { id: "a4-0eeb7f31a6c", who: "amy", text: "'맞은편 그 아이를 미워하지 마라. 그 애는 울지 않고 울었다. 나도 그 애도, 백의 숫자였다.'", tag: "[crying] 맞은편 그 아이를, 미워하지 마라. 그 애는... 울지 않고 울었다. 나도 그 애도, 백의 숫자였다." },
  { id: "a4-f43df40b41cu", who: "amy", text: "'내일이 마지막 판이다. 이기면 너한테 간다. 지면, 이 공책이라도 간다. 한 쌍은 꼭 다시 만나니까. Love, Dad.'", tag: "(직접 생성) [whispers] [holding back tears] 내일이 마지막 판이다. 이기면, 너한테 간다. 지면... 이 공책이라도 간다. 한 쌍은, 꼭 다시 만나니까... Love, Dad." },
  { id: "a4-06247a0f80c", who: "amy", text: "미워하지 말래. 나 지금 미워하고 싶은데, 아빠가 하지 말래…!", tag: "[sobbing] [shouting] 미워하지 말래...! 나 지금 미워하고 싶은데, 아빠가 하지 말래...!" },
  { id: "a4-1076703b17", who: "amy", text: "…언니. 할 말 있으면 펍에서 하지, 왜 여기서요?", tag: "[pouty, guarded] ...언니. 할 말 있으면 펍에서 하지, 왜 여기서요?" },
  { id: "a4-ce7ad5e25e", who: "amy", text: "……네?", tag: "[stunned] ......네?" },
  { id: "a4-3235925407c", who: "amy", text: "…언니였어요? 아빠 마지막 판도? 나 처음 내려간 날도? 지난 토요일도?", tag: "[trembling, on the verge of tears] ...언니였어요? 아빠 마지막 판도? 나 처음 내려간 날도...? 지난 토요일도...?" },
  { id: "a4-2a04e73266c", who: "amy", text: "…왜 왔어? 오지 말랬잖아.", tag: "[crying] ...왜 왔어...? 오지 말랬잖아..." },
  { id: "a4-028fb6ef98", who: "amy", text: "이러면 너 젖잖아.", tag: "[sad, soft] 이러면, 너 젖잖아." },
  { id: "a4-25a8b1c4e1", who: "amy", text: "세 군데나? 우리 동네 놀이터 네 개야.", tag: "[sad, sniffling] 세 군데나? 우리 동네 놀이터, 네 개야." },
  { id: "a4-316485b1edcu", who: "amy", text: "데려가 줘. 너네 집. 오늘은 우리 집 바닥이 너무 차가울 것 같아.", tag: "(직접 생성) [whispers] [fragile] 데려가 줘... 너네 집. 오늘은, 우리 집 바닥이... 너무 차가울 것 같아." },
  { id: "a4-7854713f39", who: "amy", text: "…어떻게 알았어? 어디 있는지 말 안 했는데.", tag: "[surprised, teary] ...어떻게 알았어? 어디 있는지, 말 안 했는데." },
  { id: "a4-7a1a33bdb9", who: "amy", text: "……그거 보내 놓고 바로 후회했어. 찾으러 오라고 쓴 것 같아서.", tag: "[sad, sheepish] ......그거 보내 놓고, 바로 후회했어. 찾으러 오라고 쓴 것 같아서." },
  { id: "a4-e56da10437c", who: "amy", text: "…늦었어. 근데 한 번에 왔네.", tag: "[crying, small laugh] ...늦었어. 근데... 한 번에 왔네." },
  { id: "a4-b072354f59", who: "amy", text: "아빠는 일요일 아침마다 팬케이크 구웠어. 맨날 태웠어. 탄 쪽은 자기가, 안 탄 쪽은 나.", tag: "[nostalgic, quiet] 아빠는 일요일 아침마다 팬케이크 구웠어. 맨날 태웠어. 탄 쪽은 자기가, 안 탄 쪽은 나." },
  { id: "a4-92f808d7dc", who: "amy", text: "포커도 맨날 일부러 져 줬어. 내가 화내면 '아빠는 지는 게 이기는 거야' 그랬어.", tag: "[fond, smiling] 포커도 맨날 일부러 져 줬어. 내가 화내면, 아빠는 지는 게 이기는 거야, 그랬어." },
  { id: "a4-0318075eff", who: "amy", text: "…그 말이 제일 싫었어. 지는 게 어떻게 이기는 거야?", tag: "[sad] ...그 말이 제일 싫었어. 지는 게 어떻게 이기는 거야?" },
  { id: "a4-9f16af8669", who: "amy", text: "…불 꺼 줘. 지금 얼굴 엉망이야.", tag: "[softly, embarrassed] ...불 꺼 줘. 지금 얼굴 엉망이야." },
  { id: "a4-e89581d2ab", who: "amy", text: "머리 말려야지. …근데 손이 안 움직여.", tag: "[softly, tired] 머리 말려야지. ...근데, 손이 안 움직여." },
  { id: "a4-47bc5182bc", who: "amy", text: "아빠는 수건으로 막 비볐어. 너는… 칩 닦듯이 하네. 조심조심.", tag: "[softly, shy] 아빠는 수건으로 막 비볐어. 너는... 칩 닦듯이 하네. 조심조심." },
  { id: "a4-ac4680394e", who: "amy", text: "…그런 말은 어디서 배워?", tag: "[softly, flustered] ...그런 말은, 어디서 배워?" },
  { id: "a4-4fe996d51fc", who: "amy", text: "그때는 젖어서 어쩔 수 없었던 거고. 내 손으로 풀어서 보여 주는 건, 아빠 말고 네가 처음이야. 트윈테일 아닌 나는 나 같지가 않아서.", tag: "[vulnerable, soft] 그때는, 젖어서 어쩔 수 없었던 거고. 내 손으로 풀어서 보여 주는 건... 아빠 말고 네가 처음이야. 트윈테일 아닌 나는, 나 같지가 않아서." },
  { id: "a4-7c2d38c05dc", who: "amy", text: "…오늘은 혼자 있기 싫어.", tag: "[whispers] [vulnerable] ...오늘은, 혼자 있기 싫어." },
  { id: "a4-75edf648bbc", who: "amy", text: "…오늘만. 여기 있어 줘요. 네?", tag: "[whispers] [pleading] ...오늘만. 여기 있어 줘요. ...네?" },
  { id: "a4-2f85b48a1cc", who: "amy", text: "…그거, 칩 닦는 손 아니다. 지금은.", tag: "[whispers] [shy] ...그거, 칩 닦는 손 아니다. 지금은." },
  { id: "a4-fa6d452d5dc", who: "amy", text: "근데 그 말, 한 번 더 해 줘.", tag: "[whispers] [shy] 근데, 그 말... 한 번 더 해 줘." },
  { id: "a4-bd79007537", who: "amy", text: "……사실은 이번이 처음이야.", tag: "[whispering, shy] ......사실은, 이번이 처음이야." },
  { id: "a4-9f7d3a81f6c", who: "amy", text: "…소매 말고 손. 오늘은 손으로. 이건 무료야.", tag: "[sleepy] ...소매 말고, 손. 오늘은 손으로. 이건, 무료야." },
  { id: "a4-019d5db06ec", who: "amy", text: "……쫓아와 줘서 고마워.", tag: "[whispers] [sleepy] ......쫓아와 줘서, 고마워." },
  { id: "a4-654d5ebad6", who: "amy", text: "뭘 봐? 아침부터.", tag: "[sleepy, shy] 뭘 봐? 아침부터." },
  { id: "a4-b59ec33de2c", who: "amy", text: "어젯밤 얘기 꺼내면 죽어.", tag: "[embarrassed, pouty] 어젯밤 얘기 꺼내면... 죽어." },
  { id: "a4-b7592a3cd2", who: "amy", text: "괜찮아. 괜—", tag: "[shy] 괜찮아. 괜—" },
  { id: "a4-1abe89359d", who: "amy", text: "……한 번만 할게. 괜찮아. 이번 건 진짜로.", tag: "[soft, sincere] ......한 번만 할게. 괜찮아. 이번 건, 진짜로." },
  { id: "a4-8491f05788", who: "amy", text: "머리 푼 채로 아침 맞는 거, 아빠 말고는 너밖에 없어.", tag: "[soft, shy] 머리 푼 채로 아침 맞는 거, 아빠 말고는 너밖에 없어." },
  { id: "a4-1f1b5e219bu", who: "amy", text: "…Good morning. 두 개 국어로 했으니까 두 배야.", tag: "(직접 생성) [whispers] [sleepy, playful] ...Good morning. 두 개 국어로 했으니까, 두 배야." },
  { id: "a4-21cfcb44bac", who: "amy", text: "밤새 손 안 놨더라. 팔 저리지? 이번엔 내가 봤어. 너 자다가 팔 주무르는 거.", tag: "[teasing, soft] 밤새 손 안 놨더라. 팔 저리지? 이번엔 내가 봤어. 너, 자다가 팔 주무르는 거." },
  { id: "a4-3f2c4297e4", who: "amy", text: "아니. 이번엔 직접 말하잖아. 쪽지는 도망갈 때 쓰는 거야.", tag: "[soft, warm] 아니. 이번엔 직접 말하잖아. 쪽지는, 도망갈 때 쓰는 거야." },
  { id: "a4-a6af43ab55", who: "amy", text: "…좋은 아침.", tag: "[soft, warm] ...좋은 아침." },
  { id: "a4-b01536aa78", who: "amy", text: "아빠 레시피야. 우유 대신 바나나우유. 이건 비밀이야.", tag: "[smug, cheerful] 아빠 레시피야. 우유 대신 바나나우유. 이건 비밀이야." },
  { id: "a4-956392e5e4", who: "amy", text: "너 계량컵 있잖아. 레시피 지킬 사람이야.", tag: "[cheerful] 너 계량컵 있잖아. 레시피 지킬 사람이야." },
  { id: "a4-6aa049c6da", who: "amy", text: "감으로. 아빠도 감으로 했어. 그래서 맨날 탔나 봐.", tag: "[playful] 감으로. 아빠도 감으로 했어. 그래서 맨날 탔나 봐." },
  { id: "a4-ac9bb6a7c8c", who: "amy", text: "…아.", tag: "[sudden realization] ...아." },
  { id: "a4-9bb50a9153c", who: "amy", text: "나 지금 아빠처럼 했다. 탄 거 내가, 안 탄 거 너.", tag: "[moved, quiet] 나 지금... 아빠처럼 했다. 탄 거 내가, 안 탄 거 너." },
  { id: "a4-144f94780c", who: "amy", text: "아빠 날 진짜 좋아했나 봐. 이거 진짜 맛없거든.", tag: "[smiling, teary] 아빠, 날 진짜 좋아했나 봐. 이거 진짜 맛없거든." },
  { id: "a4-b378c61efd", who: "amy", text: "어서 오세요. …아, 딜러.", tag: "[polite, then softening] 어서 오세요. ...아, 딜러." },
  { id: "a4-3c4dbbaae3", who: "amy", text: "어젯밤? 괜찮아. 괜찮아. 나 원래 혼자 잘 있어. 1년 동안 그랬거든.", tag: "[forced cheer] 어젯밤? 괜찮아. 괜찮아. 나 원래 혼자 잘 있어. 일 년 동안 그랬거든." },
  { id: "a4-7ac57f3ac0c", who: "amy", text: "서운한 거 아니야.", tag: "[hurt, avoiding eye contact] 서운한 거, 아니야." },
  { id: "a4-e3bd37b31ec", who: "amy", text: "어젯밤? 괜—", tag: "[forced cheer] 어젯밤? 괜—" },
  { id: "a4-1a9cbfaaa4", who: "amy", text: "……두 번 말하면 들키지. 안 괜찮았어. 지금은 조금.", tag: "[quiet, honest] ......두 번 말하면 들키지. 안 괜찮았어. 지금은, 조금." },
  { id: "a4-c5411a4f29", who: "amy", text: "어젯밤? 언니한테 갔다며. …잘했어. 언니도 혼자였을 테니까.", tag: "[forced smile] 어젯밤? 언니한테 갔다며. ...잘했어. 언니도 혼자였을 테니까." },
  { id: "a4-8e05c6bde6", who: "amy", text: "괜찮아. 괜찮아. 나는 원래 혼자 잘 있어.", tag: "[forced cheer] 괜찮아. 괜찮아. 나는 원래 혼자 잘 있어." },
  { id: "a4-c8be41cec5", who: "amy", text: "…갈 거야.", tag: "[quiet, determined] ...갈 거야." },
  { id: "a4-3e8f6b3433", who: "amy", text: "이번엔 이길 수 있어. 언니가 왜 접는지, 사장님이 언제 웃는지 이제 알아. 몸으로.", tag: "[determined] 이번엔 이길 수 있어. 언니가 왜 접는지, 사장님이 언제 웃는지, 이제 알아. 몸으로." },
  { id: "a4-9c3aa3c9d5", who: "amy", text: "아빠 공책에 다 있어. 세 번째 판, 사장님 손가락. 아빠가 대신 다 알아 놨어.", tag: "[determined] 아빠 공책에 다 있어. 세 번째 판, 사장님 손가락. 아빠가 대신 다 알아 놨어." },
  { id: "a4-ac6fd3f23a", who: "amy", text: "아빠는 알고도 졌어. 나는 알고 이길 거야.", tag: "[firm] 아빠는 알고도 졌어. 나는, 알고 이길 거야." },
  { id: "a4-bfff70a7fc", who: "amy", text: "…리버까지?", tag: "[shocked] ...리버까지?" },
  { id: "a4-8837ceb531", who: "amy", text: "그럼 나 뭘 해도 져?", tag: "[sad, small voice] 그럼, 나 뭘 해도 져?" },
  { id: "a4-0e978641c6c", who: "amy", text: "…그럼 아빠 마지막 이야기는? 영원히 못 들어?", tag: "[on the verge of tears] ...그럼, 아빠 마지막 이야기는...? 영원히, 못 들어?" },
  { id: "a4-08d46c03c3", who: "amy", text: "…끝내러?", tag: "[surprised] ...끝내러?" },
  { id: "a4-c018aa7dd1", who: "amy", text: "이기지도 않고 어떻게 끝내?", tag: "[puzzled] 이기지도 않고, 어떻게 끝내?" },
  { id: "a4-9ef90c8fa4", who: "amy", text: "카드 걷는 거?", tag: "[puzzled] 카드 걷는 거?" },
  { id: "a4-c49e8f0a88", who: "amy", text: "무슨 말인지 하나도 모르겠어. 근데 '같이'는 알아들었어. 그거면 됐어.", tag: "[shy, warm] 무슨 말인지 하나도 모르겠어. 근데 같이는, 알아들었어. 그거면 됐어." },
  { id: "a4-dc5ebddeff", who: "amy", text: "…그치? 그치! 너도 그렇게 생각하지?", tag: "[excited] ...그치? 그치! 너도 그렇게 생각하지?" },
  { id: "a4-204fde6af4", who: "amy", text: "이기고 와서 떡볶이 쏠게. 제일 매운 걸로.", tag: "[cheerful, confident] 이기고 와서 떡볶이 쏠게. 제일 매운 걸로." },
  { id: "a4-5fc6059b5d", who: "amy", text: "…언니.", tag: "[tense, quiet] ...언니." },
  { id: "a4-2fcc029e2dc", who: "amy", text: "나 언니 미워요. 엄청. 어젯밤에 백 번은 미워했어요.", tag: "[pouty, hurt] 나, 언니 미워요. 엄청. 어젯밤에... 백 번은 미워했어요." },
  { id: "a4-790d3d4a3c", who: "amy", text: "근데 아빠가 매 판 내 얘기 했다면서요. 그거 끝까지 들어 준 사람, 언니밖에 없잖아요.", tag: "[sad, softening] 근데, 아빠가 매 판 내 얘기 했다면서요. 그거 끝까지 들어 준 사람, 언니밖에 없잖아요." },
  { id: "a4-42892c86cd", who: "amy", text: "아빠 글씨예요. 언니 미워하지 말래요.", tag: "[sad, gentle] 아빠 글씨예요. 언니 미워하지 말래요." },
  { id: "a4-4f0abbaabd", who: "amy", text: "언니. 아빠 마지막 날… 뭐라고 했어요? 사장님 말고. 언니가 들은 거.", tag: "[softly, pleading] 언니. 아빠 마지막 날... 뭐라고 했어요? 사장님 말고. 언니가 들은 거." },
  { id: "a4-350da017f1c", who: "amy", text: "…고마워요. 미워하는 거랑 별개로요.", tag: "[choked up] ...고마워요. 미워하는 거랑... 별개로요." },
  { id: "a4-b49d64e461", who: "amy", text: "숙제 하나 같이 하자. 제목은 '일요일 끝나면 할 거'.", tag: "[bright, determined] 숙제 하나 같이 하자. 제목은, 일요일 끝나면 할 거." },
  { id: "a4-09566a2b96", who: "amy", text: "1번, 떡볶이. 제일 매운 거. 2번, 아빠한테 편지. 영사관에 물어보면 된대.", tag: "[cheerful, listing] 일 번, 떡볶이. 제일 매운 거. 이 번, 아빠한테 편지. 영사관에 물어보면 된대." },
  { id: "a4-b6940f03ac", who: "amy", text: "3번, 워터파크. 표 유효기간 다음 달 말까지야. 튜브는 네가 불고.", tag: "[smug] 삼 번, 워터파크. 표 유효기간 다음 달 말까지야. 튜브는, 네가 불고." },
  { id: "a4-8af482722b", who: "amy", text: "3번, 워터파크 한 번 더. 이번엔 선크림 네가 발라. 등은 손 안 닿아.", tag: "[smug, teasing] 삼 번, 워터파크 한 번 더. 이번엔 선크림 네가 발라. 등은 손 안 닿아." },
  { id: "a4-8f0cde7fcd", who: "amy", text: "이긴 사람. 일요일에 이긴 사람.", tag: "[smug] 이긴 사람. 일요일에 이긴 사람." },
  { id: "a4-c972ee9f7a", who: "amy", text: "…그럼 둘이 같이 골라. 중간 맛. 나 지금 타협한 거야. 기록해 둬.", tag: "[grudging, playful] ...그럼 둘이 같이 골라. 중간 맛. 나 지금 타협한 거야. 기록해 둬." },
  { id: "a4-f6bc787b2d", who: "amy", text: "4번은 네가 써. 비워 뒀어.", tag: "[soft] 사 번은 네가 써. 비워 뒀어." },
  { id: "a4-7385c0811d", who: "amy", text: "…상자? 그 테이프 감긴 거?", tag: "[surprised] ...상자? 그 테이프 감긴 거?" },
  { id: "a4-86f498c6acc", who: "amy", text: "휴지 담당 하기로 했었지. 기억하고 있었어?", tag: "[touched, shy] 휴지 담당 하기로 했었지... 기억하고 있었어?" },
  { id: "a4-008d0be3e2", who: "amy", text: "일요일 끝나고. 둘 다 울 준비 되면. …적었다. 이제 못 물러.", tag: "[soft smile] 일요일 끝나고. 둘 다 울 준비 되면. [playful] ...적었다. 이제 못 물러." },
  { id: "a4-4e4caebb8e", who: "amy", text: "안 탄 거 누가 구울 건데? 나 못 하는 거 알잖아.", tag: "[pouty] 안 탄 거 누가 구울 건데? 나 못 하는 거 알잖아." },
  { id: "a4-18ecf6a369", who: "amy", text: "…그 계량컵, 이제 진짜 비싼 살림이네.", tag: "[warm, teasing] ...그 계량컵, 이제 진짜 비싼 살림이네." },
  { id: "a4-eb14247474", who: "amy", text: "라면? 목록에 라면을 써? 그거 맨날 먹는 거잖아.", tag: "[surprised, amused] 라면? 목록에 라면을 써? 그거 맨날 먹는 거잖아." },
  { id: "a4-ffcace3bf9", who: "amy", text: "…그걸 기억했어? 싱거워도 다 먹어야 돼. 적었으니까 이제 계약이야.", tag: "[touched, playful] ...그걸 기억했어? 싱거워도 다 먹어야 돼. 적었으니까, 이제 계약이야." },
  { id: "a4-0c5cb25e18", who: "amy", text: "…둘 다?", tag: "[surprised] ...둘 다?" },
  { id: "a4-80db267ae7c", who: "amy", text: "네가 쓴 거다. 지켜야 돼. 네 글씨로 적었으니까 네 거야.", tag: "[firm] 네가 쓴 거다. 지켜야 돼. 네 글씨로 적었으니까, 네 거야." },
  { id: "a4-1402268b0b", who: "amy", text: "……치사해. 근데 좋아.", tag: "[pouty, then soft] ......치사해. [shy] 근데 좋아." },
  { id: "a4-aa995577a4", who: "amy", text: "그리고 5번. …이건 내가 쓸게. 보지 마.", tag: "[shy, flustered] 그리고 오 번. [defensive] ...이건 내가 쓸게. 보지 마." },
  { id: "a4-ebd0f9654cc", who: "amy", text: "비밀. 일요일 끝나고 보여 줄게. 살아서 나오면.", tag: "[whispers] [shy] 비밀. 일요일 끝나고 보여 줄게. ...살아서 나오면." },
  { id: "a4-33a80b45da", who: "amy", text: "이거 다 하려면 일요일에 멀쩡히 나와야 돼. 그러니까 오늘 밤에 확인할 거야.", tag: "[earnest, determined] 이거 다 하려면, 일요일에 멀쩡히 나와야 돼. 그러니까, 오늘 밤에 확인할 거야." },
  { id: "a4-c612403fee", who: "amy", text: "마감 후에 기다려. 사탕 들고 갈게.", tag: "[smug] 마감 후에 기다려. 사탕 들고 갈게." },
  { id: "a4-6cc231c39c", who: "amy", text: "마지막 내기 하자. 딱 한 판.", tag: "[serious] 마지막 내기 하자. 딱 한 판." },
  { id: "a4-a00c70a683", who: "amy", text: "내가 이기면 일요일에 나 안 말리기. 네가 이기면… 안 갈게. 진짜로.", tag: "[serious, firm] 내가 이기면, 일요일에 나 안 말리기. 네가 이기면... [quietly] 안 갈게. 진짜로." },
  { id: "a4-5716414aea", who: "amy", text: "이건 사탕이야. 돈 아니야. 마감 후고, 손님도 사장님도 없어.", tag: "[pouty, defensive] 이건 사탕이야. 돈 아니야. 마감 후고, 손님도 사장님도 없어." },
  { id: "a4-58d379316e", who: "amy", text: "폐기 직전 할인 상품이야. 판돈도 착하지.", tag: "[smug] 폐기 직전 할인 상품이야. 판돈도 착하지." },
  { id: "a4-9a9a499247u", who: "amy", text: "…군번줄. 그거 봤구나.", tag: "(직접 생성) [whispers] [wistful] ...군번줄. 그거, 봤구나." },
  { id: "a4-46b145e44d", who: "amy", text: "머리 감는 건 일부러 했어. 센 패 쥔 사람처럼 보이려고. 영상에서 봤어.", tag: "[sad, rueful] 머리 감는 건, 일부러 했어. 센 패 쥔 사람처럼 보이려고. 영상에서 봤어." },
  { id: "a4-c4e1410cce", who: "amy", text: "시끄러우면 블러프, 조용하면 진짜. 네가 알려 준 거, 다 연습해서 고쳤는데.", tag: "[sad, rueful] 시끄러우면 블러프, 조용하면 진짜. 네가 알려 준 거, 다 연습해서 고쳤는데." },
  { id: "a4-73945f8962", who: "amy", text: "이건 몰랐어. 무서울 때 이거 쥐는 거. 아빠 붙잡는 거.", tag: "[softly, sad] 이건 몰랐어. 무서울 때 이거 쥐는 거. [falling tone] 아빠 붙잡는 거." },
  { id: "a4-e8a7848351c", who: "amy", text: "……응. 그래서 지고 싶었나 봐. 진짜로.", tag: "[trembling] ......응. 그래서, 지고 싶었나 봐. 진짜로." },
  { id: "a4-ad507a3f79", who: "amy", text: "약속. 혼자서는 안 가. 진 사람은 말 들어야 하니까.", tag: "[quiet, sincere] 약속. 혼자서는 안 가. 진 사람은, 말 들어야 하니까." },
  { id: "a4-09741fb3af", who: "amy", text: "근데 차용증은? 일요일에 안 가면 사장님 가만 안 있을 거야.", tag: "[worried] 근데 차용증은? 일요일에 안 가면, 사장님 가만 안 있을 거야." },
  { id: "a4-13e839c502", who: "amy", text: "……뭐?", tag: "[shocked] ......뭐?" },
  { id: "a4-b82b2c1268c", who: "amy", text: "안 돼. 너 앉으면 사장님이 원하는 대로 되는 거잖아. 언니가 그랬잖아.", tag: "[desperate] [shouting] 안 돼! 너 앉으면, 사장님이 원하는 대로 되는 거잖아! 언니가 그랬잖아!" },
  { id: "a4-e43d2cc21ac", who: "amy", text: "…이겼다. 너한테. 블러프로.", tag: "[stunned, breathless] ...이겼다. 너한테. ...블러프로." },
  { id: "a4-566c8b3500", who: "amy", text: "봤지? 나 이제 너도 속여. 그러니까 일요일엔 사장님도 속일 수 있어.", tag: "[proud, excited] 봤지? 나 이제 너도 속여. 그러니까 일요일엔, 사장님도 속일 수 있어." },
  { id: "a4-46dc749cb1", who: "amy", text: "약속이야. 안 말리기. 진 사람은 말 들어야 하니까.", tag: "[firm] 약속이야. 안 말리기. 진 사람은, 말 들어야 하니까." },
  { id: "a4-92762ed237", who: "amy", text: "휴지는 집들이 국룰이지. …근데 왜 두 묶음이야?", tag: "[cheerful, then curious] 휴지는 집들이 국룰이지. ...근데, 왜 두 묶음이야?" },
  { id: "a4-57939ab717", who: "amy", text: "…안 울 건데. 아마. 혹시 모르니까 안방에 둘게.", tag: "[pouty] ...안 울 건데. 아마. 혹시 모르니까, 안방에 둘게." },
  { id: "a4-6d6a9830dc", who: "amy", text: "여기 원룸이야. 다 안방이야. 놀리지 마.", tag: "[pouty, embarrassed] 여기 원룸이야. 다 안방이야. 놀리지 마." },
  { id: "a4-24fb2a6a72", who: "amy", text: "봐. 바닥 생겼어. 이제 우리 집에서도 잘 수 있어.", tag: "[happy, proud] 봐. 바닥 생겼어. 이제 우리 집에서도 잘 수 있어." },
  { id: "a4-f55bb506ebc", who: "amy", text: "…아니, 그런 뜻 아니야! 나 혼자 잘 수 있다는 뜻이야!", tag: "[panicked] [shouting] ...아니, 그런 뜻 아니야! 나 혼자 잘 수 있다는 뜻이야!" },
  { id: "a4-16bbbcadc4", who: "amy", text: "…거기서 그렇게 순순히 넘어가면 그것도 서운하거든?", tag: "[pouty, sulky] ...거기서 그렇게 순순히 넘어가면, 그것도 서운하거든?" },
  { id: "a4-eea50e86b7c", who: "amy", text: "이모님 보온병 아직 우리 집에 있다. '덜 맵게' 써진 거. 장판 걷던 날 네가 들고 온 거.", tag: "[fond] 이모님 보온병, 아직 우리 집에 있다. 덜 맵게, 써진 거. 장판 걷던 날, 네가 들고 온 거." },
  { id: "a4-81f9e9d638", who: "amy", text: "그날 그 보리차 마시고 장판 다 걷었어. 내일 아침에 돌려드릴 거야. 채워서.", tag: "[warm] 그날 그 보리차 마시고, 장판 다 걷었어. 내일 아침에 돌려드릴 거야. 채워서." },
  { id: "a4-945d37474c", who: "amy", text: "그거 알아? 물난리 다음 날 아침에 너 편의점 왔던 거. 팔 저리다고.", tag: "[teasing, fond] 그거 알아? 물난리 다음 날 아침에, 너 편의점 왔던 거. 팔 저리다고." },
  { id: "a4-8e16d34005", who: "amy", text: "그날 점장님이 나 왜 이렇게 웃냐고 했잖아. …그거, 그 바나나우유 때문이었어.", tag: "[shy] 그날 점장님이, 나 왜 이렇게 웃냐고 했잖아. [mumbling] ...그거, 그 바나나우유 때문이었어." },
  { id: "a4-79d70e73d1", who: "amy", text: "그리고 이거. 장판 깔던 아저씨가 방구석에서 찾았대. 제습제 두 통. 영수증까지 봉지에 같이.", tag: "[pouty, suspicious] 그리고 이거. 장판 깔던 아저씨가 방구석에서 찾았대. 제습제 두 통. 영수증까지 봉지에 같이." },
  { id: "a4-424353b4a9", who: "amy", text: "계산은 네 전문이라며. 이번엔 내가 셌어. 갚을 거야. 이자 없이.", tag: "[firm, proud] 계산은 네 전문이라며. 이번엔 내가 셌어. 갚을 거야. 이자 없이." },
  { id: "a4-0029d0cd61", who: "amy", text: "…화요일에 문고리에 걸린 딸기우유. 비밀 하나 날린 값이라며.", tag: "[quiet, fond] ...화요일에 문고리에 걸린 딸기우유. 비밀 하나 날린 값이라며." },
  { id: "a4-d3d405e500", who: "amy", text: "날린 게 아니었네. 네가 주워 간 거였네.", tag: "[shy, touched] 날린 게 아니었네. 네가 주워 간 거였네." },
  { id: "a4-e330ef432d", who: "amy", text: "빨았어. 돌려주려고 했는데.", tag: "[soft] 빨았어. 돌려주려고 했는데." },
  { id: "a4-9097a8aabe", who: "amy", text: "이건 내가 가질래. '언젠가' 준다고 했잖아. 그 언젠가를 좀 길게 하기로 했어.", tag: "[shy, playful] 이건 내가 가질래. 언젠가 준다고 했잖아. 그 언젠가를, 좀 길게 하기로 했어." },
  { id: "a4-f071769851", who: "amy", text: "…내일. 아니, 이따 새벽이구나. 네 시.", tag: "[quiet, tense] ...내일. 아니, 이따 새벽이구나. 네 시." },
  { id: "a4-bafe18931a", who: "amy", text: "어떻게 할 거야? 솔직하게. 나 이제 네 얼굴 읽을 수 있어.", tag: "[serious] 어떻게 할 거야? 솔직하게. 나 이제, 네 얼굴 읽을 수 있어." },
  { id: "a4-5694296d98", who: "amy", text: "두 번 두드리면 일어나는 거야? 이기고 있어도?", tag: "[pouty, unsure] 두 번 두드리면, 일어나는 거야? 이기고 있어도?" },
  { id: "a4-0fe6e9a69f", who: "amy", text: "역할 바꾸기야? 이번엔 내가 치사한 사람 하는 거야?", tag: "[pouty, half-teasing] 역할 바꾸기야? 이번엔, 내가 치사한 사람 하는 거야?" },
  { id: "a4-b3ed47befe", who: "amy", text: "근데 내가 두드리면 너 진짜 일어날 거야? 손이 칩을 기억해도?", tag: "[serious, doubtful] 근데 내가 두드리면, 너 진짜 일어날 거야? 손이 칩을 기억해도?" },
  { id: "a4-b2d7df1352", who: "amy", text: "…그 말 내가 한 거잖아. 표절이야.", tag: "[pouty, playful] ...그 말, 내가 한 거잖아. 표절이야." },
  { id: "a4-f950f9663e", who: "amy", text: "알았어. 뒤에 서 있을게. 대신 앉는 건 오늘 한 번만이야. 다음은 없어.", tag: "[softly, reluctant] 알았어. 뒤에 서 있을게. 대신 앉는 건, 오늘 한 번만이야. 다음은 없어." },
  { id: "a4-ad1c7776ff", who: "amy", text: "손가락 줘. 지난번 건 내가 깼으니까, 이번 건 네가 지켜.", tag: "[softly, earnest] 손가락 줘. 지난번 건 내가 깼으니까, 이번 건 네가 지켜." },
  { id: "a4-380e68989b", who: "amy", text: "응. 같이. 너는 숫자 세고, 나는 아빠 자리 지키고.", tag: "[warm, determined] 응. 같이. 너는 숫자 세고, 나는 아빠 자리 지키고." },
  { id: "a4-81e5fe0207", who: "amy", text: "같은 테이블에 앉는 거야. 처음부터 그랬어야 했나 봐.", tag: "[warm, soft] 같은 테이블에 앉는 거야. 처음부터, 그랬어야 했나 봐." },
  { id: "a4-9334a6a404c", who: "amy", text: "세 시에 깨워. 아니, 세 시 반. 화장은 안 할 거야. 전쟁에 화장하고 가는 사람 없잖아.", tag: "[whispers] [sleepy] 세 시에 깨워. 아니, 세 시 반. 화장은 안 할 거야. 전쟁에 화장하고 가는 사람, 없잖아." },
  { id: "a4-6251af335cc", who: "amy", text: "……무서워. 무섭다고 말하니까 좀 덜 무섭다. 신기하네.", tag: "[whispers] [scared] ......무서워. 무섭다고 말하니까... 좀 덜 무섭다. 신기하네." },
  { id: "a4-0016044233c", who: "amy", text: "…지난 토요일에 남긴 떡볶이 하나. 식은 거라도 그냥 먹을걸.", tag: "[whispers] [wistful] ...지난 토요일에 남긴 떡볶이 하나. 식은 거라도... 그냥 먹을걸." },
  { id: "a4-c3360819eec", who: "amy", text: "이기면 먹겠다고 남겨 둔 게 제일 바보 같았어. 이번엔 안 남길 거야.", tag: "[whispers] [resolute] 이기면 먹겠다고 남겨 둔 게, 제일 바보 같았어. 이번엔, 안 남길 거야." },
  { id: "a4-64a98d194ac", who: "amy", text: "…지난 토요일 낮에 혼자 빈 펍에서 카드 섞었다며. 정민이가 CCTV로 봤대. 엄청 무서운 얼굴이었대.", tag: "[whispers] [teasing] ...지난 토요일 낮에, 혼자 빈 펍에서 카드 섞었다며. 정민이가 씨씨티비로 봤대. 엄청, 무서운 얼굴이었대." },
  { id: "a4-689d5f553ac", who: "amy", text: "내일은 그 얼굴 하지 마. 뒤에서 보는 나도 무서우니까.", tag: "[whispers] [worried] 내일은, 그 얼굴 하지 마. 뒤에서 보는 나도... 무서우니까." },
  { id: "a4-314ccf118dc", who: "amy", text: "…지난 토요일 낮에 비상계단에서 언니 만났지? 이모님이 봤대.", tag: "[whispers] [pouty] ...지난 토요일 낮에, 비상계단에서 언니 만났지? 이모님이 봤대." },
  { id: "a4-5131822831c", who: "amy", text: "질투 아니야. 언니가 그날 너한테 뭐라고 했는지 궁금한 거야. …끝나면 말해 줘.", tag: "[whispers] [defensive] 질투 아니야. 언니가 그날 너한테 뭐라고 했는지, 궁금한 거야. ...끝나면, 말해 줘." },
  { id: "a4-299943a592c", who: "amy", text: "끝나면 떡볶이. 그건 약속이야. 수첩에도 1번으로 적었어.", tag: "[whispers] [sleepy, smiling] 끝나면... 떡볶이. 그건 약속이야. 수첩에도, 일 번으로 적었어." },
  { id: "a4-c385dff3e2c", who: "amy", text: "좋아해.", tag: "[whispers] [breathless] ...좋아해." },
  { id: "a4-ca70941dcfc", who: "amy", text: "일요일 끝나고도 이 말 유효한지는, 끝나고 다시 물어봐. 지금은 무서워서 반값이야.", tag: "[whispers] [shy] 일요일 끝나고도 이 말 유효한지는, 끝나고 다시 물어봐. 지금은... 무서워서, 반값이야." },
  { id: "a4-7f3e08dddcc", who: "amy", text: "…두 번이야. 내가 두 번 두드리면 일어나. 이기고 있어도.", tag: "[whispers] [tense] ...두 번이야. 내가 두 번 두드리면, 일어나. 이기고 있어도." },
  { id: "a4-e46de46a8ac", who: "amy", text: "그리고 얼면, 그냥 얼어 있어. 차용증 쓰던 날처럼. 이번에도 내가 눌러 줄게.", tag: "[whispers] [steady] 그리고 얼면, 그냥 얼어 있어. 차용증 쓰던 날처럼. 이번에도... 내가 눌러 줄게." },
  { id: "a4-501b792c95c", who: "amy", text: "둘이면 이겨. 그치?", tag: "[whispers] [hopeful] 둘이면, 이겨. ...그치?" },
  { id: "a4-4e4e6f94d9c", who: "amy", text: "……일어나. 두 번 했잖아.", tag: "[trembling] ......일어나. 두 번... 했잖아." },
  { id: "a4-fe707fe7a8c", who: "amy", text: "이기고 있어도 일어나는 거라며. 너 지금 지고 있잖아. 그러니까 더 일어나.", tag: "[desperate, on the verge of tears] 이기고 있어도 일어나는 거라며...! 너 지금, 지고 있잖아. 그러니까... 더 일어나!" },
  { id: "a4-1c60a94dd1c", who: "amy", text: "…아니. 아니야. 이번엔 내가 찾아 올게. 네 손.", tag: "[crying, determined] ...아니. 아니야. 이번엔... 내가 찾아 올게. 네 손." },
  { id: "a4-e7f9031ed6u", who: "amy", text: "…왜 접어? 나도 풀하우스야. 9 세 장에 7 두 장.", tag: "(직접 생성) [shaken] ...왜 접어?! 나도 풀하우스야. 구 세 장에... 칠 두 장." },
  { id: "a4-e1ace76157c", who: "amy", text: "둘이 앉았잖아. 네가 접으면 내가 받아야지. 올인.", tag: "[desperate] [shouting] 둘이 앉았잖아! 네가 접으면, 내가 받아야지. ...올인!" },
  { id: "a4-005d8141f0", who: "amy", text: "아빠가 이 방에서 본 판, 전부예요. 날짜, 금액, 테이블. 누가 하우스였는지. 몇 번째 판에서 졌는지.", tag: "[steady, firm] 아빠가 이 방에서 본 판, 전부예요. 날짜, 금액, 테이블. 누가 하우스였는지. 몇 번째 판에서 졌는지." },
  { id: "a4-0587cc1f09", who: "amy", text: "숫자 안 적는 사람이라고 다들 그랬는데. 다 적었어요.", tag: "[firm, voice wavering] 숫자 안 적는 사람이라고 다들 그랬는데. 다 적었어요." },
  { id: "a4-b4bf801782", who: "amy", text: "…안 해도 돼.", tag: "[softly, shaky] ...안 해도 돼." },
  { id: "a4-43dbd8bb28c", who: "amy", text: "이기지 않아도 돼. 너 이제 앉을 필요 없어. 아빠 판은 방금 끝났어.", tag: "[crying] 이기지 않아도 돼... 너 이제, 앉을 필요 없어. 아빠 판은... 방금 끝났어." },
  { id: "a4-54367ad15c", who: "amy", text: "네 편이면 돼. 그거면 돼.", tag: "[soft, smiling through tears] 네 편이면 돼. 그거면 돼." },
  { id: "a4-46a29c38d1c", who: "amy", text: "…Thanks. For staying.", tag: "[whispers] [tearful smile] ...Thanks. For staying." },
  { id: "a4-3a9ed999da", who: "amy", text: "…Thanks. For being on my side.", tag: "[softly, smiling] ...Thanks. For being on my side." },
  { id: "a4-f48da61403", who: "amy", text: "영어로 하면 덜 부끄러워서. …한국어로도 할게.", tag: "[shy, smiling] 영어로 하면, 덜 부끄러워서. ...한국어로도 할게." },
  { id: "a4-c05e09bc1b", who: "amy", text: "고마워. 내 편 해 줘서. 앞으로도 해. 부탁 아니고 명령이야.", tag: "[warm, then bossy] 고마워. 내 편 해 줘서. 앞으로도 해. [playful] 부탁 아니고, 명령이야." },
  { id: "a4-9c5f1bae33", who: "amy", text: "하우스 규칙 1번. 앞으로 내 앞에선 '딜러는 안 앉아요' 금지.", tag: "[smug, playful] 하우스 규칙 일 번. 앞으로 내 앞에선, 딜러는 안 앉아요, 금지." },
  { id: "a4-6286569d71", who: "amy", text: "…대신 떡볶이집 의자엔 앉아. 맞은편에. 이건 판 아니니까.", tag: "[warm, teasing] ...대신 떡볶이집 의자엔 앉아. 맞은편에. 이건 판 아니니까." },
  { id: "a4-6db469fe63", who: "amy", text: "시끄러워. 일곱 번째는 문법 고치는 중이야. 아빠는 문법 틀리면 답장 안 할 사람이야.", tag: "[pouty, flustered] 시끄러워. 일곱 번째는 문법 고치는 중이야. 아빠는 문법 틀리면, 답장 안 할 사람이야." },
  { id: "a4-feb30097c2", who: "amy", text: "…다 쓰면 같이 부치러 가자. 혼자 가면 우체국 줄이 너무 길어.", tag: "[shy] ...다 쓰면, 같이 부치러 가자. 혼자 가면, 우체국 줄이 너무 길어." },
  { id: "a4-04da34eefd", who: "amy", text: "같이 사는 거 아니다? 월세 아끼는 거다? 이삿짐 들고 온 날 한 말, 아직 유효해.", tag: "[smug, teasing] 같이 사는 거 아니다? 월세 아끼는 거다? 이삿짐 들고 온 날 한 말, 아직 유효해." },
  { id: "a4-43f61c55eb", who: "amy", text: "이번 달 숙제. 300에서 35 뺐어. 네 빚은 50 뺐고. 이자 없음. 사장님이 '천천히'래.", tag: "[smug, cheerful] 이번 달 숙제. 삼백에서 삼십오 뺐어. 네 빚은, 오십 뺐고. 이자 없음. 사장님이 천천히래." },
  { id: "a4-651259d4e0", who: "amy", text: "남은 거 계산하면… 둘이 합쳐서 2년 반. 테이블에 한 번도 안 앉으면.", tag: "[thoughtful] 남은 거 계산하면... 둘이 합쳐서, 이 년 반. 테이블에 한 번도 안 앉으면." },
  { id: "a4-5f3c89e1e5", who: "amy", text: "…2년 반 동안 이 방에서 같이 숙제해야 된다는 뜻이야. 계산상.", tag: "[shy] ...이 년 반 동안, 이 방에서 같이 숙제해야 된다는 뜻이야. 계산상." },
  { id: "a4-446c404716", who: "amy", text: "이번엔 내가 셌어. 불만 있어? 없지? 침대도 크잖아. 내 잠버릇이 나빠서 산 거야.", tag: "[playful, flirty] 이번엔 내가 셌어. 불만 있어? 없지? 침대도 크잖아. 내 잠버릇이 나빠서 산 거야." },
  { id: "a4-91be43d5f1", who: "amy", text: "아, 그리고 목록 5번. 보여 준다고 했지?", tag: "[shy] 아, 그리고 목록 오 번. 보여 준다고 했지?" },
  { id: "a4-379e510f1a", who: "amy", text: "맨 아래 봐. '5. 좋아한다고 말하기.' 그 옆에 다른 볼펜으로 '반값 말고 정가로.' 동그라미 두 번.", tag: "[shy, reading] 맨 아래 봐. 오 번, 좋아한다고 말하기. 그 옆에 다른 볼펜으로, 반값 말고 정가로. 동그라미 두 번." },
  { id: "a4-86c373bf97", who: "amy", text: "…정가로 두 번 말했어. 기억 안 나면 너 손해야.", tag: "[shy, sweet] ...정가로, 두 번 말했어. 기억 안 나면, 너 손해야." },
  { id: "a4-d45f0be8ac", who: "amy", text: "딜러! 오늘은 만 원어치만. 만 원 잃으면 일어나기. 수첩에 적어 왔어.", tag: "[cheerful, smug] 딜러! 오늘은 만 원어치만. 만 원 잃으면 일어나기. 수첩에 적어 왔어." },
  { id: "a4-07b261b9db", who: "amy", text: "태양아, 그거 내가 말하려던 거야. 내 자랑 뺏지 마.", tag: "[pouty] 태양아, 그거 내가 말하려던 거야. 내 자랑 뺏지 마." },
  { id: "a4-9a249b25b2", who: "amy", text: "이건 팁. 딜러 손 빠르더라. …이 말, 첫날에도 했지? 석 달째 인정 중이야.", tag: "[warm, playful] 이건 팁. 딜러 손 빠르더라. ...이 말, 첫날에도 했지? 석 달째 인정 중이야." },
  { id: "a4-fe2a8febe6", who: "amy", text: "…그날 새벽, 일어나 줘서 고마웠어. 그 말은 평생 유효해.", tag: "[sincere, soft] ...그날 새벽, 일어나 줘서 고마웠어. 그 말은, 평생 유효해." },
  { id: "a4-6d94a5813d", who: "amy", text: "그 이상은 아니고. 그 이하도 아니고.", tag: "[shy, light] 그 이상은 아니고. 그 이하도 아니고." },
  { id: "a4-43f0134e2d", who: "amy", text: "…그 반값짜리 말은, 아직 유효기간 안 정했어. 그러니까 묻지 마.", tag: "[shy, flustered] ...그 반값짜리 말은, 아직 유효기간 안 정했어. 그러니까, 묻지 마." },
  { id: "a4-a252a4132d", who: "amy", text: "펠트 위에 군번줄 있지? 그거 가져가. 나 이제 그거 걸 자격 없어.", tag: "[hollow, sad] 펠트 위에 군번줄 있지? 그거 가져가. 나 이제, 그거 걸 자격 없어." },
  { id: "a4-abda30e3fdc", who: "amy", text: "나는 아빠랑 달라. …달랐어야 했는데.", tag: "[whispers] [broken] 나는 아빠랑 달라. ...달랐어야, 했는데." },
  { id: "a4-2a9ef4d416c", who: "amy", text: "오늘도 안 봤지, 나. 테이블에서.", tag: "[whispers] [tired] 오늘도 안 봤지, 나. ...테이블에서." },
  { id: "a4-23071545ebc", who: "amy", text: "…나도.", tag: "[whispers] [sad] ...나도." },
  { id: "a4-a80c627243c", who: "amy", text: "같이 앉아 줘서 고마웠어. 진짜야.", tag: "[whispers] [tired] 같이 앉아 줘서... 고마웠어. 진짜야." },
  { id: "a4-10e3e28a6fc", who: "amy", text: "근데 같이 지면, 아무도 안 일으켜 줘. 둘 다 앉아 있으니까.", tag: "[whispers] [hollow] 근데 같이 지면, 아무도 안 일으켜 줘. ...둘 다 앉아 있으니까." },
  { id: "a4-1470302536c", who: "amy", text: "…내 대신 앉아 줘서 고마웠어. 그래서 이번엔 내가 앉은 거야.", tag: "[whispers] [sad] ...내 대신 앉아 줘서, 고마웠어. 그래서... 이번엔 내가 앉은 거야." },
  { id: "a4-62f19c5501c", who: "amy", text: "근데 둘 다 한 번씩 앉으니까, 아무도 안 일으켜 줘. 뒤에 서 있을 사람이 없어.", tag: "[whispers] [hollow] 근데 둘 다 한 번씩 앉으니까, 아무도 안 일으켜 줘. ...뒤에 서 있을 사람이, 없어." },
  { id: "a4-65e8c6167dc", who: "amy", text: "손 들어. 딜러 검문이야.", tag: "[playful, mock stern] 손 들어! 딜러 검문이야." },
  { id: "a4-786c826cab", who: "amy", text: "요즘 출근길에 여기 안 들르잖아. 사유서 내.", tag: "[pouty] 요즘 출근길에 여기 안 들르잖아. 사유서 내." },
  { id: "a4-01f1684d8a", who: "amy", text: "이름, 사유, 그리고 편의점 대신 들른 곳.", tag: "[smug, mock official] 이름, 사유, 그리고 편의점 대신 들른 곳." },
  { id: "a4-a7aa739014", who: "amy", text: "와, 솔직하네. 벌금은 삼각김밥 하나야.", tag: "[surprised, pouty] 와, 솔직하네. 벌금은, 삼각김밥 하나야." },
  { id: "a4-a958fe53c3", who: "amy", text: "그 언니랑 맨날 비상계단에 있더라? 골목 끝이라 여기서 다 보여.", tag: "[casual, probing] 그 언니랑 맨날 비상계단에 있더라? 골목 끝이라, 여기서 다 보여." },
  { id: "a4-011edbd67d", who: "amy", text: "알바는 원래 창밖을 봐. 손님 오나 안 오나. 그러다 보이는 거야.", tag: "[smug, defensive] 알바는 원래 창밖을 봐. 손님 오나 안 오나. 그러다 보이는 거야." },
  { id: "a4-62d9aed36e", who: "amy", text: "그리고 너 요즘 얼굴 좋아졌어. 그건 인정할게.", tag: "[grudging] 그리고 너 요즘, 얼굴 좋아졌어. 그건 인정할게." },
  { id: "a4-b934aefe9b", who: "amy", text: "검문은 공정해야 하거든.", tag: "[smug] 검문은, 공정해야 하거든." },
  { id: "a4-a7af555775", who: "amy", text: "…그건 됐고. 부탁 하나만 해도 돼?", tag: "[hesitant] ...그건 됐고. 부탁 하나만 해도 돼?" },
  { id: "a4-94df757172", who: "amy", text: "토요일에 편의점 마감하고, 집까지 좀 같이 걸어 줘. 요즘 골목에 이상한 아저씨가 있어.", tag: "[uneasy, small voice] 토요일에 편의점 마감하고, 집까지 좀 같이 걸어 줘. 요즘 골목에, 이상한 아저씨가 있어." },
  { id: "a4-f283d52fbf", who: "amy", text: "진짜 그것뿐이야. 이상한 아저씨 퇴치용이야.", tag: "[defensive] 진짜 그것뿐이야. 이상한 아저씨, 퇴치용이야." },
  { id: "a4-f44f4a5584", who: "amy", text: "오. 진짜? 그럼 토요일 우유는 내가 산다.", tag: "[bright] 오. 진짜? 그럼 토요일 우유는, 내가 산다." },
  { id: "a4-4157662606", who: "amy", text: "그리고 그 언니한테는… 말하지 마. 왠지 무서워.", tag: "[pouty, uneasy] 그리고 그 언니한테는... 말하지 마. 왠지 무서워." },
  { id: "a4-6499c205f8", who: "amy", text: "웃지도 않고 사람 보잖아. 바코드보다 정확하게.", tag: "[matter-of-fact] 웃지도 않고 사람 보잖아. 바코드보다 정확하게." },
  { id: "a4-34b896e0e9", who: "amy", text: "태양? 걔 걸으면서 노래 불러. 이상한 아저씨보다 시끄러워.", tag: "[pouty, annoyed] 태양? 걔 걸으면서 노래 불러. 이상한 아저씨보다 시끄러워." },
  { id: "a4-426badd6f8", who: "amy", text: "…뭐, 알았어. 시끄러운 게 무서운 것보단 낫지.", tag: "[resigned] ...뭐, 알았어. 시끄러운 게, 무서운 것보단 낫지." },
  { id: "a4-aa39ac7a20", who: "amy", text: "왔다, 퇴치 요원.", tag: "[cheerful] 왔다, 퇴치 요원." },
  { id: "a4-8282555c81", who: "amy", text: "근데 너 오늘 몸살이라며. 태양이 그러던데.", tag: "[smug, teasing] 근데 너, 오늘 몸살이라며. 태양이 그러던데." },
  { id: "a4-d2b0ddc06e", who: "amy", text: "하루 만에? 무슨 몸살이 내 퇴근 시간에 딱 맞춰 낫냐?", tag: "[smug, teasing] 하루 만에? 무슨 몸살이, 내 퇴근 시간에 딱 맞춰 낫냐?" },
  { id: "a4-17084b1aa4", who: "amy", text: "얼굴도 탔어. 몸살 걸린 사람이 왜 타?", tag: "[pouty, suspicious] 얼굴도 탔어. 몸살 걸린 사람이 왜 타?" },
  { id: "a4-eac7b55b8f", who: "amy", text: "흐응. 그런 걸로 해 줄게. 오늘은 퇴치가 먼저니까.", tag: "[knowing, playful] 흐응. 그런 걸로 해 줄게. 오늘은 퇴치가 먼저니까." },
  { id: "a4-027010b9f0", who: "amy", text: "오늘은 안 나왔네. 네 얼굴 보고 도망갔나 봐.", tag: "[smug] 오늘은 안 나왔네. 네 얼굴 보고 도망갔나 봐." },
  { id: "a4-4d57b39ead", who: "amy", text: "…같이 걸으니까 골목이 짧다. 십 분이 오 분 같아.", tag: "[soft, content] ...같이 걸으니까, 골목이 짧다. 십 분이 오 분 같아." },
  { id: "a4-503791c9b1", who: "amy", text: "고마워, 딜러. 우유는 다음에. 오늘 정산이 안 맞아서 내 돈으로 메꿨거든.", tag: "[sheepish] 고마워, 딜러. 우유는 다음에. 오늘 정산이 안 맞아서, 내 돈으로 메꿨거든." },
  { id: "a4-89e86673efc", who: "amy", text: "천 이백 원. 내일 그 할아버지 오면 동전부터 다시 셀 거야.", tag: "[determined, huffy] 천 이백 원! 내일 그 할아버지 오면, 동전부터 다시 셀 거야." },
  { id: "a4-99b5c5ee67", who: "amy", text: "딜러. 딱 오 분만 있어. 지금 집게 힘 센 타이밍이야.", tag: "[focused, smug] 딜러. 딱 오 분만 있어. 지금, 집게 힘 센 타이밍이야." },
  { id: "a4-08332b9654", who: "amy", text: "…오늘은 안 되는 날인가.", tag: "[deflated, pouty] ...오늘은 안 되는 날인가." },
  { id: "a4-74c06ca142", who: "amy", text: "나 오늘 밤에 펍 갈 거야. 그 언니한테 물어볼 게 있어.", tag: "[serious, quiet] 나 오늘 밤에 펍 갈 거야. 그 언니한테, 물어볼 게 있어." },
  { id: "a4-48689364b8", who: "amy", text: "비밀. 용기 모으는 중이니까 건드리지 마.", tag: "[guarded, nervous] 비밀. 용기 모으는 중이니까, 건드리지 마." },
  { id: "a4-64cd7409a5", who: "amy", text: "대신 한 판만 같이 해 줘. 딜러 손으로 하면 될 것 같아.", tag: "[small smile] 대신 한 판만 같이 해 줘. 딜러 손으로 하면, 될 것 같아." },
  { id: "a4-ac38a53f06", who: "amy", text: "딜러. 잠깐만. 나 저 언니한테 물어볼 거 있어.", tag: "[nervous, determined] 딜러. 잠깐만. 나 저 언니한테, 물어볼 거 있어." },
  { id: "a4-6dec513532", who: "amy", text: "지금 아니면 못 물어볼 것 같아. 용기는 유통기한이 짧아.", tag: "[determined] 지금 아니면, 못 물어볼 것 같아. 용기는 유통기한이 짧아." },
  { id: "a4-3d5148663a", who: "amy", text: "언니. 봉투 일은… 아직 화나 있어요. 그건 그거고요.", tag: "[stiff, guarded] 언니. 봉투 일은... 아직 화나 있어요. 그건 그거고요." },
  { id: "a4-bcf2bc4efb", who: "amy", text: "이건 다른 얘기예요. 하나만 물어볼게요.", tag: "[serious] 이건 다른 얘기예요. 하나만 물어볼게요." },
  { id: "a4-d943fb7f10", who: "amy", text: "언니. 하나만 물어봐도 돼요? 언니 여기 오래 있었잖아요.", tag: "[nervous, polite] 언니. 하나만 물어봐도 돼요? 언니 여기, 오래 있었잖아요." },
  { id: "a4-cfe21dbb80", who: "amy", text: "이 사람, 본 적 있어요? 우리 아빠예요. 5년 전에 여기 왔대요.", tag: "[hopeful, nervous] 이 사람, 본 적 있어요? 우리 아빠예요. 오 년 전에, 여기 왔대요." },
  { id: "a4-5dfe7df92a", who: "amy", text: "사장님이 아빠 자리가 아래층에 그대로 있대요. 언니는 아래층에서도 치잖아요. 혹시…", tag: "[hopeful, sad] 사장님이, 아빠 자리가 아래층에 그대로 있대요. 언니는 아래층에서도 치잖아요. [falling tone] 혹시..." },
  { id: "a4-0033fce85d", who: "amy", text: "…그렇구나. 고마워요, 언니. 물 쏟게 해서 미안해요.", tag: "[disappointed, sad] ...그렇구나. 고마워요, 언니. 물 쏟게 해서, 미안해요." },
  { id: "a4-18fc73202e", who: "amy", text: "딜러. 사장님이 내일 밤에 아빠 자리 보여 준대. 보기만.", tag: "[excited, nervous] 딜러. 사장님이 내일 밤에, 아빠 자리 보여 준대. 보기만." },
  { id: "a4-6ae0af37d7", who: "amy", text: "…같이 가 줄 수 있어? 옆에 서 있기만 하면 돼.", tag: "[hesitant, small voice] ...같이 가 줄 수 있어? 옆에 서 있기만 하면 돼." },
  { id: "a4-9713785e34", who: "amy", text: "혼자 보면 울 것 같아서. 우는 거 사장님한테 보이기 싫어.", tag: "[quiet, vulnerable] 혼자 보면, 울 것 같아서. 우는 거, 사장님한테 보이기 싫어." },
  { id: "a4-5be144ed69", who: "amy", text: "…약속이다. 새끼손가락 걸어.", tag: "[bright, relieved] ...약속이다. 새끼손가락 걸어." },
  { id: "a4-a390f4cf14", who: "amy", text: "그 언니한테는 말하지 마. …저번에도 이 말 했나? 왜 자꾸 하게 되지?", tag: "[pouty, puzzled] 그 언니한테는 말하지 마. [wondering] ...저번에도 이 말 했나? 왜 자꾸 하게 되지?" },
  { id: "a4-cca32622ac", who: "amy", text: "그리고 그 언니한테는 말하지 마. 왠지 그래야 할 것 같아.", tag: "[pouty, uneasy] 그리고 그 언니한테는 말하지 마. 왠지, 그래야 할 것 같아." },
  { id: "a4-376d704dc4", who: "amy", text: "…다들 그래. 이유는 안 알려 주고 가지 말래.", tag: "[sad, frustrated] ...다들 그래. 이유는 안 알려 주고, 가지 말래." },
  { id: "a4-79b704155f", who: "amy", text: "알았어. 고민은 해 볼게. 계산대 정산하면서.", tag: "[resigned] 알았어. 고민은 해 볼게. 계산대 정산하면서." },
  { id: "a4-6c5714e82a", who: "amy", text: "딜러. …보기만 하고 올게.", tag: "[nervous, quiet] 딜러. ...보기만 하고 올게." },
  { id: "a4-e8fd7fc53cc", who: "amy", text: "같이 가 준다며. 계단까지만이야?", tag: "[hurt] 같이 가 준다며... 계단까지만이야?" },
  { id: "a4-b3dd7d8dc1", who: "amy", text: "…그 말은 믿어 줄게. 이번만.", tag: "[grudging, soft] ...그 말은, 믿어 줄게. 이번만." },
  { id: "a4-a24ae25bf8", who: "amy", text: "가지 말라고 했지. 알아. 그래도 보고 싶어.", tag: "[stubborn, quiet] 가지 말라고 했지. 알아. 그래도, 보고 싶어." },
  { id: "a4-e1150f52ab", who: "amy", text: "응. 그건 좀 든든하다.", tag: "[relieved, soft] 응. 그건, 좀 든든하다." },
  { id: "a4-f00d05764d", who: "amy", text: "…딜러.", tag: "[dazed] ...딜러." },
  { id: "a4-95b03a1b4ac", who: "amy", text: "언니가… 안 쳤어. 사장님이 물잔에 손가락 올렸는데, 언니가 카드를 덮었어.", tag: "[stunned, breathless] 언니가... 안 쳤어. 사장님이 물잔에 손가락 올렸는데... 언니가, 카드를 덮었어." },
  { id: "a4-8924e643e7", who: "amy", text: "'오늘은 안 쳐요.' 그러고는 나보고 올라가래. 아빠 자리는 손님 없을 때 혼자 보래.", tag: "[recounting, quiet] 오늘은 안 쳐요. 그러고는 나보고 올라가래. 아빠 자리는, 손님 없을 때 혼자 보래." },
  { id: "a4-2185439878", who: "amy", text: "사장님이 웃었는데… 늘 웃던 그 웃음이 아니었어.", tag: "[uneasy, quiet] 사장님이 웃었는데... 늘 웃던 그 웃음이 아니었어." },
  { id: "a4-4938530906", who: "amy", text: "언니 아직 아래 있어. 사장님이랑 둘이.", tag: "[serious] 언니 아직 아래 있어. 사장님이랑 둘이." },
  { id: "a4-8f3895c076", who: "amy", text: "…응. 이번엔 진 사람 얼굴로 안 올라왔네, 나.", tag: "[small proud smile] ...응. 이번엔 진 사람 얼굴로 안 올라왔네, 나." },
  { id: "a4-84a4ee70d8", who: "amy", text: "…여기구나. 아빠가 앉던 데.", tag: "[quiet, awed] ...여기구나. 아빠가 앉던 데." },
  { id: "a4-d002dcf293", who: "amy", text: "…언니?", tag: "[surprised] ...언니?" },
  { id: "a4-e31f491e80", who: "amy", text: "언니 왜 그랬을까? 내가 앉으면 안 되는 이유라도 있었나.", tag: "[thoughtful, puzzled] 언니 왜 그랬을까? 내가 앉으면 안 되는 이유라도 있었나." },
  { id: "a4-d76b339753", who: "amy", text: "오늘 와 줘서 고마워. 계단 내려갈 때 다리 떨렸는데, 네 손이 등에 있어서 안 넘어졌어.", tag: "[warm, grateful] 오늘 와 줘서 고마워. 계단 내려갈 때 다리 떨렸는데, 네 손이 등에 있어서 안 넘어졌어." },
  { id: "a4-28cbbe357b", who: "amy", text: "…딜러. 언니가 오늘은 안 쳤어. 카드를 덮었어. 왜인지는 몰라.", tag: "[puzzled, quiet] ...딜러. 언니가 오늘은 안 쳤어. 카드를 덮었어. 왜인지는 몰라." },
  { id: "a4-53cb82a7f9", who: "amy", text: "너는 알아? …아니다. 얼굴 보니까 너도 모르는 척하는 얼굴이네.", tag: "[suspicious, sad] 너는 알아? [realizing] ...아니다. 얼굴 보니까, 너도 모르는 척하는 얼굴이네." },
  { id: "a4-772b1bd063", who: "amy", text: "왔네. 이거 마셔. 수요일 고마운 거, 아직 안 갚았어.", tag: "[casual, warm] 왔네. 이거 마셔. 수요일 고마운 거, 아직 안 갚았어." },
  { id: "a4-cd423c4136", who: "amy", text: "알아. 그래서 그 언니 몫도 샀어.", tag: "[pouty] 알아. 그래서 그 언니 몫도 샀어." },
  { id: "a4-b403082c59", who: "amy", text: "내가 직접 줄 거야. 근데 그 언니 요즘 안 보이잖아. 그러니까 여기 넣어 둘게. 유통기한은 일요일까지.", tag: "[determined] 내가 직접 줄 거야. 근데 그 언니, 요즘 안 보이잖아. 그러니까 여기 넣어 둘게. 유통기한은, 일요일까지." },
  { id: "a4-7e3edc11b5", who: "amy", text: "일요일 지나면 내가 마셔 버릴 거야. 그러니까 그 전에 데려와.", tag: "[smug, playful] 일요일 지나면, 내가 마셔 버릴 거야. 그러니까, 그 전에 데려와." },
  { id: "a4-e602d2c272", who: "amy", text: "딜러. …그 언니, 진짜 그만둬?", tag: "[worried] 딜러. ...그 언니, 진짜 그만둬?" },
  { id: "a4-61b3b1ecef", who: "amy", text: "태양이. 걔 입 엄청 가볍잖아.", tag: "[pouty] 태양이. 걔 입 엄청 가볍잖아." },
  { id: "a4-786324e6af", who: "amy", text: "수요일에 언니가 카드 덮은 거, 계속 생각나. 고맙다고 말도 못 했어.", tag: "[sad, regretful] 수요일에 언니가 카드 덮은 거, 계속 생각나. 고맙다고, 말도 못 했어." },
  { id: "a4-44ae04c87e", who: "amy", text: "너 그 언니 만나면 전해 줘. …아니다. 내가 직접 할래. 그런 건 직접 하는 거야.", tag: "[earnest] 너 그 언니 만나면 전해 줘. [decisive] ...아니다. 내가 직접 할래. 그런 건, 직접 하는 거야." },
  { id: "a4-650809ae86", who: "amy", text: "저번에 다음에 준다던 우유. 이자는 없어.", tag: "[warm smile] 저번에 다음에 준다던 우유. 이자는 없어." },
  { id: "a4-e8376fd754", who: "amy", text: "얼굴이 진 사람 얼굴이라서. 오늘은 내가 쏜다.", tag: "[gentle, teasing] 얼굴이 진 사람 얼굴이라서. 오늘은 내가 쏜다." },
  { id: "a4-ef8d7dfe16", who: "amy", text: "딜러? 웬일이야, 전화를 다 하고?", tag: "[surprised, cheerful] 딜러? 웬일이야, 전화를 다 하고?" },
  { id: "a4-4c650ea08d", who: "amy", text: "군번줄? …왜?", tag: "[puzzled] 군번줄? ...왜?" },
  { id: "a4-2adebb4182", who: "amy", text: "……어떻게 끝내는데? 아빠도 못 끝낸 판을.", tag: "[quiet, doubtful] ......어떻게 끝내는데? 아빠도 못 끝낸 판을." },
  { id: "a4-dd9db9c181", who: "amy", text: "알았어. 갈게. 대신 이번엔 보기만 하는 거 아니야.", tag: "[determined] 알았어. 갈게. 대신 이번엔, 보기만 하는 거 아니야." },
  { id: "a4-6e816866e3", who: "amy", text: "그리고 태양이랑 정민이도 데려갈 거야. 혼자 내려가는 건 이제 안 해.", tag: "[smug, resolute] 그리고 태양이랑 정민이도 데려갈 거야. 혼자 내려가는 건, 이제 안 해." },
  { id: "a4-17304925f7", who: "amy", text: "딜러! 문 앞에서 다 들었어. 태양이 끝날 때까지 들어가지 말라고 붙잡아서—", tag: "[urgent, breathless] 딜러! 문 앞에서 다 들었어. 태양이 끝날 때까지 들어가지 말라고 붙잡아서—" },
  { id: "a4-8d93fede0e", who: "amy", text: "……그거. 그 군번줄.", tag: "[stunned] ......그거. 그 군번줄." },
  { id: "a4-3a31542472c", who: "amy", text: "…아빠 거야. 아빠 글씨야.", tag: "[choked up] ...아빠 거야. 아빠... 글씨야." },
  { id: "a4-b869e06d3b", who: "amy", text: "날짜, 테이블, 사장님이 물잔에 손가락 몇 개 올렸는지. 다 적혀 있어.", tag: "[shaky, reading] 날짜, 테이블, 사장님이 물잔에 손가락 몇 개 올렸는지. 다 적혀 있어." },
  { id: "a4-2f6c5599b6", who: "amy", text: "'하우스 Y — 그 애 잘못 아니다.' 이것도 아빠 글씨야.", tag: "[sad, reading] 하우스 Y. 그 애 잘못 아니다. 이것도, 아빠 글씨야." },
  { id: "a4-a4271fe4adc", who: "amy", text: "…아빠 글씨예요, 언니. 아빠가 그렇게 써 놨어요.", tag: "[tearful, gentle] ...아빠 글씨예요, 언니. 아빠가... 그렇게 써 놨어요." },
  { id: "a4-b8d744d646", who: "amy", text: "용서한다는 말은 아직 못 해요. 아직은요.", tag: "[quiet, firm] 용서한다는 말은, 아직 못 해요. 아직은요." },
  { id: "a4-a908876365", who: "amy", text: "근데 언니가 그날 카드 덮은 거, 알아요. 그건 아빠도 봤으면 좋았을 텐데.", tag: "[softening, sad] 근데 언니가 그날 카드 덮은 거, 알아요. 그건, 아빠도 봤으면 좋았을 텐데." },
  { id: "a4-42ffd252d8", who: "amy", text: "…다음에 김치찌개 사 줘요. 덜 맵게. 그럼 생각해 볼게요.", tag: "[pouty, warm] ...다음에 김치찌개 사 줘요. 덜 맵게. 그럼, 생각해 볼게요." },
  { id: "a4-7361bb03ac", who: "amy", text: "두부는 언니 거 하나도 안 뺏을게요. 그건 약속해요.", tag: "[warm smile] 두부는, 언니 거 하나도 안 뺏을게요. 그건 약속해요." },
  { id: "a4-82202abf6b", who: "amy", text: "…괜찮아. 돌리는 사람이 너면 돼.", tag: "[quiet, trusting] ...괜찮아. 돌리는 사람이 너면 돼." },
  { id: "a4-0a3c0c4c57", who: "amy", text: "네 손은 정직하잖아. 그건 내가 알아.", tag: "[warm, trusting] 네 손은 정직하잖아. 그건, 내가 알아." },
  { id: "a4-cd808be87a", who: "amy", text: "컷은 깊게. 아빠가 그랬어.", tag: "[soft, confident] 컷은 깊게. 아빠가 그랬어." },
  { id: "a4-1985389b6c", who: "amy", text: "…그 덱. 내가 자른 거잖아. 왜 거기 있어?", tag: "[confused, shaky] ...그 덱. 내가 자른 거잖아. 왜 거기 있어?" },
  { id: "a4-e6a92a94d1c", who: "amy", text: "말하지 마. 지금 무슨 말을 해도, 숫자 세는 소리로 들릴 거야.", tag: "[cold, hurt] 말하지 마. 지금 무슨 말을 해도... 숫자 세는 소리로 들릴 거야." },
  { id: "a4-c598fac85ec", who: "amy", text: "딜러는 처음부터 손님 편이 아니었네. 나만 몰랐어.", tag: "[whispers] [bitter] 딜러는 처음부터, 손님 편이 아니었네. ...나만 몰랐어." },
  { id: "a4-6536edae3b", who: "amy", text: "이건 팁. 딜러 손 빠르더라.", tag: "[hollow, bitter] 이건 팁. 딜러 손 빠르더라." },
  { id: "a4-c3b3a30fc7c", who: "amy", text: "딜러. 일어나. 이기고 있을 때 일어나는 거야.", tag: "[desperate] [shouting] 딜러! 일어나...! 이기고 있을 때, 일어나는 거야!" },
  { id: "a4-7c8196ef49c", who: "amy", text: "딜러, 그만해. 나 이제 안 칠게. 너도 그만해.", tag: "[pleading, on the verge of tears] 딜러, 그만해...! 나 이제 안 칠게. 너도, 그만해..." },
  { id: "a4-03dcbbe017c", who: "amy", text: "너 지금 얼굴, 아빠 마지막 사진이랑 똑같아. 이기는 줄 아는 얼굴.", tag: "[scared, trembling] 너 지금 얼굴... 아빠 마지막 사진이랑 똑같아. ...이기는 줄 아는 얼굴." },
  { id: "a4-178d9df6f7c", who: "amy", text: "그 말… 내가 맨날 하던 말이잖아.", tag: "[whispers] [broken] 그 말... 내가 맨날, 하던 말이잖아." },
  { id: "a4-b775394d50", who: "amy", text: "…언니가 왜 여기 있어요?", tag: "[surprised, wary] ...언니가 왜 여기 있어요?" },
  { id: "a4-031a0c3ce0c", who: "amy", text: "아빠 자리 판이잖아요. 내가 안 오면 누가 와요?", tag: "[angry, on the verge of tears] 아빠 자리 판이잖아요...! 내가 안 오면, 누가 와요?!" },
  { id: "a4-93982b7581", who: "amy", text: "언니가 왜요? 언니가 왜 딜러 얼굴을 봐요?", tag: "[surprised, suspicious] 언니가 왜요? 언니가 왜, 딜러 얼굴을 봐요?" },
  { id: "a4-817ddf5ebdc", who: "amy", text: "그날 어디 갔었냐고 안 물어봤어. 물어보면 진짜 대답할까 봐.", tag: "[trembling, hurt] 그날 어디 갔었냐고... 안 물어봤어. 물어보면, 진짜 대답할까 봐." },
  { id: "a4-8d489ea65cc", who: "amy", text: "……나랑 있을 때도 그 얼굴이었어. 언니 얘기만 나오면.", tag: "[choked up] ......나랑 있을 때도, 그 얼굴이었어. 언니 얘기만... 나오면." },
  { id: "a4-a5a5f42788c", who: "amy", text: "내 편인 줄 알았어. 둘 다의 편이었어?", tag: "[furious] [shouting] 내 편인 줄 알았어...! 둘 다의 편이었어?!" },
  { id: "a4-ebfd1d0d43c", who: "amy", text: "on my side라며. 둘 다의 side였어?", tag: "[furious] [shouting] on my side라며...! 둘 다의 side였어?!" },
  { id: "a4-581b0120cf", who: "amy", text: "가게에 소문 다 났어요. 딜러가 오늘 새벽에 아래층 앉는다고.", tag: "[pouty, sharp] 가게에 소문 다 났어요. 딜러가 오늘 새벽에, 아래층 앉는다고." },
  { id: "a4-df7856fbdc", who: "amy", text: "혼자 앉게 둘 거 같아요? 내가?", tag: "[firm, challenging] 혼자 앉게 둘 거 같아요? 내가?" },
  { id: "a4-b4140223ee", who: "amy", text: "……그날 나한테 온 게, 언니 집에서 나와서였어요?", tag: "[stunned] ......그날 나한테 온 게, 언니 집에서 나와서였어요?" },
  { id: "a4-c9fe90053bc", who: "amy", text: "나는 그날, 딜러가 나 걱정돼서 온 줄 알았는데.", tag: "[crying] 나는 그날... 딜러가, 나 걱정돼서 온 줄 알았는데..." },
  { id: "a4-0a26d56145c", who: "amy", text: "나는? 나한테 웃어 준 건? 그것도 그냥 딜러 서비스였어?", tag: "[sobbing] [shouting] 나는?! 나한테 웃어 준 건...? 그것도 그냥, 딜러 서비스였어?!" },
  { id: "a4-7f87cc6895", who: "amy", text: "딜러는 빠져. 이건 우리 판이야.", tag: "[angry, cold] 딜러는 빠져. 이건 우리 판이야." },
  { id: "a4-219d75f542", who: "amy", text: "둘 다 좋아한 거 아니지? 그냥, 하나도 놓기 싫었던 거지.", tag: "[sad, bitter] 둘 다 좋아한 거 아니지? 그냥, 하나도 놓기 싫었던 거지." },
  { id: "a4-41d244d5a4c", who: "amy", text: "그게 더 나빠.", tag: "[whispers] [cold] ...그게, 더 나빠." },
  { id: "a4-b8d008ee45c", who: "amy", text: "…왜 왔어? 지금 얼굴 엉망이야.", tag: "[crying] ...왜 왔어...? 지금 얼굴, 엉망이야..." },
  { id: "a4-a8c8dc9fe2", who: "amy", text: "공책은 안 젖었어. 품에 넣었어. 아빠 거니까.", tag: "[sad, sniffling] 공책은 안 젖었어. 품에 넣었어. 아빠 거니까." },
  { id: "a4-45c2cc022cc", who: "amy", text: "나는 말리면 돼. 이건 말려도 안 돼.", tag: "[sniffling] 나는... 말리면 돼. [voice breaking] 이건, 말려도 안 돼." },
  { id: "a4-93e5997ce8u", who: "amy", text: "…언니는? 거기 혼자 두고 왔어?", tag: "(직접 생성) [worried] ...언니는? 거기, 혼자 두고 왔어?" },
  { id: "a4-02d3b13858", who: "amy", text: "바보. 그 언니가 지금 더 엉망일 텐데.", tag: "[sad, scolding] 바보. 그 언니가 지금, 더 엉망일 텐데." },
  { id: "a4-a883000f39", who: "amy", text: "…뭐? 오늘? 그 언니 얼굴을, 오늘?", tag: "[shocked] ...뭐? 오늘? 그 언니 얼굴을, 오늘?" },
  { id: "a4-f5fce27d6c", who: "amy", text: "……데려가. 대신 나 한마디도 안 할 수도 있어.", tag: "[pouty, reluctant] ......데려가. 대신, 나 한마디도 안 할 수도 있어." },
  { id: "a4-5b8a2f22d8", who: "amy", text: "화해하러 가는 거 아니야. 따지러 가는 거야.", tag: "[firm] 화해하러 가는 거 아니야. 따지러 가는 거야." },
  { id: "a4-b47b4c7926", who: "amy", text: "왜 왔어요?", tag: "[cold, pouty] 왜 왔어요?" },
  { id: "a4-2bb03d343a", who: "amy", text: "그 말 또 하네요. 그날도 그랬잖아요.", tag: "[pouty, bitter] 그 말 또 하네요. 그날도 그랬잖아요." },
  { id: "a4-f50e1fd47b", who: "amy", text: "공책에 다 있었어요. 검은 장갑, 스물넷.", tag: "[cold, steady] 공책에 다 있었어요. 검은 장갑, 스물넷." },
  { id: "a4-464bb97879", who: "amy", text: "아까 다 들었어요. 더 할 말이 있어요?", tag: "[cold] 아까 다 들었어요. 더 할 말이 있어요?" },
  { id: "a4-b13bda7567u", who: "amy", text: "…뭔데요? 셋이서 할 얘기가 뭔데요?", tag: "(직접 생성) [guarded, cold] ...뭔데요? 셋이서 할 얘기가, 뭔데요?" },
  { id: "a4-817c628998c", who: "amy", text: "…A는 내 이름이에요. 아빠는 칩마다 그걸 긁었어요. 행운 부적이라고.", tag: "[trembling] ...에이는, 내 이름이에요. 아빠는 칩마다... 그걸 긁었어요. 행운 부적이라고." },
  { id: "a4-41f5103c44c", who: "amy", text: "그 부적을, 아빠 돈 다 가져간 사람한테 줬다고요?", tag: "[hurt, disbelief] 그 부적을... 아빠 돈 다 가져간 사람한테, 줬다고요...?" },
  { id: "a4-b0e33604cfc", who: "amy", text: "나 처음 아래층 갔던 날, 언니한테 축하한다고 했어요. 진짜로!", tag: "[crying] [shouting] 나 처음 아래층 갔던 날, 언니한테 축하한다고 했어요! 진짜로!" },
  { id: "a4-311e8555d3c", who: "amy", text: "언니가 땄어요? 우리 아빠를? 하나도 안 틀리고?", tag: "[furious] [shouting] 언니가 땄어요?! 우리 아빠를?! 하나도 안 틀리고?!" },
  { id: "a4-7b0605b7edcu", who: "amy", text: "아까 파라솔에서, '네' 한 마디였죠. 그걸로 끝난 줄 알았어요?", tag: "(직접 생성) [angry, tearful] 아까 파라솔에서... 네, 한 마디였죠. 그걸로, 끝난 줄 알았어요?!" },
  { id: "a4-2714fc0115c", who: "amy", text: "숫자 얘기 말고요. 이거. 아빠 부적. 왜 5년 동안 갖고 있었어요?", tag: "[furious] [shouting] 숫자 얘기 말고요! 이거. 아빠 부적. 왜 오 년 동안 갖고 있었어요?!" },
  { id: "a4-6a1eb912f6c", who: "amy", text: "…That's not fair. 그렇게 쳐다보면, 내가 뭘 해야 되는데요?", tag: "[sobbing] ...That's not fair. 그렇게 쳐다보면... 내가 뭘 해야 되는데요...?" },
  { id: "a4-e0d5a0350b", who: "amy", text: "오늘은 아무 말도 하지 마요, 언니. …딜러, 너도.", tag: "[sad, exhausted] 오늘은 아무 말도 하지 마요, 언니. [quiet] ...딜러, 너도." },
  { id: "a4-9527d811a4", who: "amy", text: "…따라오지 말랬지.", tag: "[pouty, tired] ...따라오지 말랬지." },
  { id: "a4-a194e28303", who: "amy", text: "…오늘 두 번 뛰었어. 다리 아파서 여기까지야.", tag: "[pouty, tired] ...오늘 두 번 뛰었어. 다리 아파서, 여기까지야." },
  { id: "a4-907874102b", who: "amy", text: "따라오지 말랬는데. 두 번 다.", tag: "[sad, small voice] 따라오지 말랬는데. [falling tone] 두 번 다." },
  { id: "a4-c1de9363b0", who: "amy", text: "나 그 언니 미워하고 싶어. 엄청. 근데 잘 안 돼.", tag: "[sad, confused] 나 그 언니, 미워하고 싶어. 엄청. 근데, 잘 안 돼." },
  { id: "a4-20e3627c21", who: "amy", text: "비 오던 날, 우산 들고 서 있던 얼굴이 자꾸 생각나. 장갑이 하얗게 당겨져 있었거든.", tag: "[sad, quiet] 비 오던 날, 우산 들고 서 있던 얼굴이 자꾸 생각나. 장갑이 하얗게 당겨져 있었거든." },
  { id: "a4-75e881cfef", who: "amy", text: "딜러. 아빠가 그날 이겼으면, 집에 왔을까?", tag: "[quiet, searching] 딜러. 아빠가 그날 이겼으면, 집에 왔을까?" },
  { id: "a4-bc3aa7709c", who: "amy", text: "…알아. 그래서 더 미워. 언니 말고, 그 테이블이.", tag: "[sad, bitter] ...알아. 그래서 더 미워. 언니 말고, 그 테이블이." },
  { id: "a4-df3638575c", who: "amy", text: "근데 언니도 거기 묶여 있잖아. 표정 보면 알아. 그럼 나 누굴 미워해야 돼?", tag: "[sad, lost] 근데 언니도, 거기 묶여 있잖아. 표정 보면 알아. 그럼 나, 누굴 미워해야 돼?" },
  { id: "a4-4132b91345", who: "amy", text: "오늘은 데려다줘. 내일 생각할래.", tag: "[tired, soft] 오늘은 데려다줘. 내일 생각할래." },
  { id: "a4-5499905270c", who: "amy", text: "…추워서 그래. 소매가 제일 가까웠어.", tag: "[whispers] [flustered] ...추워서 그래. 소매가, 제일 가까웠어." },
  { id: "a4-84e7d82aa7", who: "amy", text: "늦었어. 참치마요는 내 거. 너는 전주비빔이야.", tag: "[pouty, bossy] 늦었어. 참치마요는 내 거. 너는 전주비빔이야." },
  { id: "a4-468cb0d70d", who: "amy", text: "…어젯밤에 내가 언니 어깨에 기대 잤다며. 기억 안 나. 기억 안 나는 걸로 해.", tag: "[embarrassed, flustered] ...어젯밤에, 내가 언니 어깨에 기대 잤다며. 기억 안 나. 기억 안 나는 걸로 해." },
  { id: "a4-16a246cd81", who: "amy", text: "거짓말. 너 표정 다 보여. 언니한테 배웠어.", tag: "[smug] 거짓말. 너 표정 다 보여. 언니한테 배웠어." },
  { id: "a4-36207bfd0a", who: "amy", text: "일요일에 나 안 울 거야. 울면 사장님이 좋아하니까.", tag: "[determined] 일요일에 나 안 울 거야. 울면, 사장님이 좋아하니까." },
  { id: "a4-a2afcad318", who: "amy", text: "…대신 너는 옆에서 웃고 있어. 그것만 하면 돼.", tag: "[soft, sincere] ...대신 너는, 옆에서 웃고 있어. 그것만 하면 돼." },
  { id: "a4-4ce001a3cc", who: "amy", text: "언니가 두부 아줌마한테 백 원 깎았어. 백 원!", tag: "[amazed, excited] 언니가 두부 아줌마한테, 백 원 깎았어. 백 원!" },
  { id: "a4-6fec4dc62c", who: "amy", text: "두부 값도 적어?", tag: "[pouty, amused] 두부 값도 적어?" },
  { id: "a4-fe6c54430a", who: "amy", text: "늦었어. 떡은 세 개 남았어. 어묵은 내가 다 먹었고.", tag: "[pouty] 늦었어. 떡은 세 개 남았어. 어묵은, 내가 다 먹었고." },
  { id: "a4-15c339fc34", who: "amy", text: "봐 봐. 컷 연습한 거.", tag: "[smug, excited] 봐 봐. 컷 연습한 거." },
  { id: "a4-0738d44527", who: "amy", text: "깊게. 운은 아래에 있다. …아빠 말이 맞나 봐. 어묵도 아래 게 제일 잘 익었어.", tag: "[pleased, thoughtful] 깊게. 운은 아래에 있다. [softly] ...아빠 말이 맞나 봐. 어묵도, 아래 게 제일 잘 익었어." },
  { id: "a4-c30f8bc597", who: "amy", text: "다 먹었지. 연습은 먹을 수 있는 걸로 하는 거야.", tag: "[playful] 다 먹었지. 연습은, 먹을 수 있는 걸로 하는 거야." },
  { id: "a4-4046e5c26e", who: "amy", text: "……일요일 끝나면, 여기 또 와. 떡볶이는 내가 살게. 이기든 지든.", tag: "[shy, earnest] ......일요일 끝나면, 여기 또 와. 떡볶이는 내가 살게. 이기든 지든." },
  { id: "a4-79cd92e8be", who: "amy", text: "…이게 뭔데? 손님, 이건 사는 게 아니라 사 온 거잖아요.", tag: "[pouty, puzzled] ...이게 뭔데? 손님, 이건 사는 게 아니라, 사 온 거잖아요." },
  { id: "a4-a3a4f0d94c", who: "amy", text: "……이제 안 떨어지겠다.", tag: "[softly, touched] ......이제 안 떨어지겠다." },
  { id: "a4-b83e8a8b65", who: "amy", text: "군번줄 두 장에, 아빠 칩에, 네 고리. 이제 한 줄이네.", tag: "[warm, smiling] 군번줄 두 장에, 아빠 칩에, 네 고리. 이제 한 줄이네." },
  { id: "a4-3d520e823d", who: "amy", text: "일요일에 이거 꼭 쥐고 있을게. 울어도. …아니, 안 울 거지만.", tag: "[shy] 일요일에 이거, 꼭 쥐고 있을게. 울어도. [flustered] ...아니, 안 울 거지만." },
  { id: "a4-6c97723940u", who: "amy", text: "어서 오세… 너구나. 손님 아니면 줄 서지 마.", tag: "(직접 생성) [bright] 어서 오세... [sulky] 너구나. 손님 아니면, 줄 서지 마." },
  { id: "a4-0f1c2c8331", who: "amy", text: "…그건 반칙이지.", tag: "[pouty, softening] ...그건 반칙이지." },
  { id: "a4-813b4f2fd6", who: "amy", text: "됐어. 내가 살게. 어제 소리 지른 값.", tag: "[sheepish] 됐어. 내가 살게. 어제 소리 지른 값." },
  { id: "a4-e6d7ce1ba7", who: "amy", text: "이번 주부터 낮 근무야. 밤엔 아빠 자리 생각나서 계산대 숫자가 안 맞더라.", tag: "[tired, honest] 이번 주부터 낮 근무야. 밤엔 아빠 자리 생각나서, 계산대 숫자가 안 맞더라." },
  { id: "a4-891a1ccb3e", who: "amy", text: "마지막 장, 또 읽었어. 밤새.", tag: "[tired, quiet] 마지막 장, 또 읽었어. 밤새." },
  { id: "a4-5f3c6bcfe9", who: "amy", text: "언니 미워하지 말래. 자기 돈 다 가져간 사람을.", tag: "[sad, bitter] 언니 미워하지 말래. 자기 돈 다 가져간 사람을." },
  { id: "a4-58802d9466", who: "amy", text: "아빠는 끝까지 바보야. 지는 판에서도 남 걱정이나 하고.", tag: "[sad, fond] 아빠는 끝까지 바보야. 지는 판에서도, 남 걱정이나 하고." },
  { id: "a4-c2863bbbd1", who: "amy", text: "아빠가 뭐라도 남겼으면 좋겠어. 미워해도 되는지, 안 되는지 알려 주는 거.", tag: "[sad, longing] 아빠가 뭐라도 남겼으면 좋겠어. 미워해도 되는지, 안 되는지 알려 주는 거." },
  { id: "a4-f7eb2b0a04", who: "amy", text: "근데 없어. 사진 한 장이랑, 이거 한 짝.", tag: "[sad, quiet] 근데 없어. [falling tone] 사진 한 장이랑, 이거 한 짝." },
  { id: "a4-9e64b82ba9", who: "amy", text: "아니, 하나 있지. 레일 밑에 X자 테이프.", tag: "[remembering] 아니, 하나 있지. 레일 밑에, 엑스 자 테이프." },
  { id: "a4-3f2120b9fd", who: "amy", text: "그때 안 꺼낸 거, 계속 생각나.", tag: "[regretful] 그때 안 꺼낸 거, 계속 생각나." },
  { id: "a4-689096071e", who: "amy", text: "아래층 문은 어떻게 열어? 영업하는 주잖아.", tag: "[practical, worried] 아래층 문은 어떻게 열어? 영업하는 주잖아." },
  { id: "a4-652ee12464", who: "amy", text: "……언니?", tag: "[surprised] ......언니?" },
  { id: "a4-8de019f138", who: "amy", text: "…뭐? 네가 그걸 어떻게 알아?", tag: "[surprised, suspicious] ...뭐? 네가 그걸 어떻게 알아?" },
  { id: "a4-d5d114e146", who: "amy", text: "…딜러 가끔 무서워. 근데 그 말, 믿을래.", tag: "[uneasy, then trusting] ...딜러 가끔 무서워. 근데 그 말, 믿을래." },
  { id: "a4-d960fc1a05", who: "amy", text: "…그거랑 이거랑 같아?", tag: "[surprised] ...그거랑 이거랑, 같아?" },
  { id: "a4-ac1bcd8f49", who: "amy", text: "……같네. 짜증 나게 같아.", tag: "[reluctant, sad] ......같네. 짜증 나게 같아." },
];
const V2_P3: VoiceLine[] = [
  { id: "a4-46efecee9d", who: "amy", text: "나 아빠 닮았구나. 진 날에 남한테 뭐 주는 거.", tag: "[soft smile] 나 아빠 닮았구나. 진 날에, 남한테 뭐 주는 거." },
  { id: "a4-1a53a533aa", who: "amy", text: "…별개?", tag: "[surprised] ...별개?" },
  { id: "a4-9219b2007d", who: "amy", text: "미워하면서 옆에 앉을 수 있는 거지? 포커처럼.", tag: "[thoughtful] 미워하면서, 옆에 앉을 수 있는 거지? 포커처럼." },
  { id: "a4-84d36f7ffe", who: "amy", text: "좋아. 용서는 나중에. 아마 아주 나중에. 할머니 돼서.", tag: "[pouty, playful] 좋아. 용서는 나중에. 아마 아주 나중에. 할머니 돼서." },
  { id: "a4-75bac926d6", who: "amy", text: "…네가 왜 그 말을 대신 해?", tag: "[pouty, offended] ...네가 왜, 그 말을 대신 해?" },
  { id: "a4-fbdd4e7d39c", who: "amy", text: "용서는 내가 정해. 숫자 정하듯이 남이 정해 주는 거 아니야.", tag: "[hurt, firm] 용서는, 내가 정해. 숫자 정하듯이... 남이 정해 주는 거 아니야." },
  { id: "a4-643bb1a092", who: "amy", text: "오늘 밤, 그 언니 만나게 해 줘.", tag: "[determined] 오늘 밤, 그 언니 만나게 해 줘." },
  { id: "a4-ce96d6a96a", who: "amy", text: "그 판에 있던 사람한테, 직접 들을 게 있어.", tag: "[serious] 그 판에 있던 사람한테, 직접 들을 게 있어." },
  { id: "a4-fc8eb4b2c5", who: "amy", text: "…실례합니다. 바닥은 내가 할게요. 익숙해요.", tag: "[stiff, polite] ...실례합니다. 바닥은 내가 할게요. 익숙해요." },
  { id: "a4-d2d89bce95", who: "amy", text: "이게 언니 빚이에요?", tag: "[surprised] 이게 언니 빚이에요?" },
  { id: "a4-34d1e1a3d0", who: "amy", text: "X가 엄청 많네요. 하루도 안 빼먹었어요?", tag: "[surprised, quiet] 엑스가 엄청 많네요. 하루도 안 빼먹었어요?" },
  { id: "a4-24a3c57956", who: "amy", text: "동그라미는요? X 사이에 끼어 있는 거.", tag: "[curious] 동그라미는요? 엑스 사이에 끼어 있는 거." },
  { id: "a4-70266bf1cc", who: "amy", text: "같이 읽어요. 언니 얘기도 있어요.", tag: "[steady] 같이 읽어요. 언니 얘기도 있어요." },
  { id: "a4-52e028b34cc", who: "amy", text: "…언니가 찾아 온 거예요? 아빠 거를?", tag: "[trembling] ...언니가, 찾아 온 거예요? 아빠 거를...?" },
  { id: "a4-1d831e205bu", who: "amy", text: "아빠 글씨야. 7에 꼭 줄 그어.", tag: "(직접 생성) [soft, wistful] 아빠 글씨야... 칠에, 꼭 줄 그어." },
  { id: "a4-dfa3f75fba", who: "amy", text: "…언니. 그날 아빠한테 뭐라고 했어요?", tag: "[quiet, searching] ...언니. 그날 아빠한테, 뭐라고 했어요?" },
  { id: "a4-8c33113e15", who: "amy", text: "언니. 나 이제 언니한테 반말할래.", tag: "[resolute] 언니. 나 이제, 언니한테 반말할래." },
  { id: "a4-a0bbb95f97c", who: "amy", text: "미워하는 사람한테 존댓말 쓰는 거 이상하잖아. 반은 아빠 말 듣고, 반은 내 맘대로 미워할 거야.", tag: "[trembling, stubborn] 미워하는 사람한테 존댄말 쓰는 거, 이상하잖아. 반은 아빠 말 듣고... 반은, 내 맘대로 미워할 거야." },
  { id: "a4-abe981c0ddc", who: "amy", text: "그러니까 이번엔 말해. 사장님한테. 아빠 대신 내가 옆에서 들을게.", tag: "[trembling, firm] 그러니까 이번엔 말해. 사장님한테. 아빠 대신... 내가 옆에서 들을게." },
  { id: "a4-3b9c512785", who: "amy", text: "…아빠 칩이네. 진짜 못생긴 A다.", tag: "[teary, smiling] ...아빠 칩이네. 진짜 못생긴 에이다." },
  { id: "a4-1bd46b06be", who: "amy", text: "…7 _ 9 4. 아빠 공책 첫 장엔 7194야. 같은 문이네.", tag: "[surprised] ...칠, 빈칸, 구, 사. 아빠 공책 첫 장엔, 칠일구사야. 같은 문이네." },
  { id: "a4-84b2a7494cc", who: "amy", text: "…나도. 섞어. 아빠가 일요일 아침마다 섞던 소리야.", tag: "[whispers] [sleepy] ...나도. 섞어. 아빠가 일요일 아침마다... 섞던 소리야." },
  { id: "a4-202145354c", who: "amy", text: "언니 그릇엔 두부가 왜 두 개야? 차별이야.", tag: "[pouty] 언니 그릇엔, 두부가 왜 두 개야? 차별이야." },
  { id: "a4-cec80b5d9f", who: "amy", text: "…아빠 공책에도 있어. '이길 때만 손가락 세 개로 테이블을 두드린다.'", tag: "[surprised] ...아빠 공책에도 있어. 이길 때만, 손가락 세 개로 테이블을 두드린다." },
  { id: "a4-ecf3fea060", who: "amy", text: "사장님이 그런 판에 앉겠어? 질 수도 있는 판에.", tag: "[doubtful] 사장님이 그런 판에 앉겠어? 질 수도 있는 판에." },
  { id: "a4-20209c2843", who: "amy", text: "뭐? 그럼 지잖아!", tag: "[shocked] 뭐? 그럼 지잖아!" },
  { id: "a4-b718b2a94f", who: "amy", text: "나는? 나는 뭐 해?", tag: "[pouty, eager] 나는? 나는 뭐 해?" },
  { id: "a4-5c4d2112d8", who: "amy", text: "…아빠가 그랬어. 컷은 깊게. 운은 아래에 있다고.", tag: "[soft smile] ...아빠가 그랬어. 컷은 깊게. 운은, 아래에 있다고." },
  { id: "a4-7111289f49", who: "amy", text: "…그럼 언니 두부 내가 다 뺏어 먹을 거야.", tag: "[smug] ...그럼 언니 두부, 내가 다 뺏어 먹을 거야." },
  { id: "a4-69871bcc12", who: "amy", text: "나도 나도! 밥상도 안 엎어 봤어!", tag: "[excited] 나도 나도! 밥상도 안 엎어 봤어!" },
  { id: "a4-1249ff0008", who: "amy", text: "내기 하나 하자. 해 질 때까지 내가 떨면, 이 딸기우유 값은 네가 갚는 거야.", tag: "[smug, playful] 내기 하나 하자. 해 질 때까지 내가 떨면, 이 딸기우유 값은 네가 갚는 거야." },
  { id: "a4-5fa162b45d", who: "amy", text: "여기 있지. 그러니까 나 안 떨게 해 봐.", tag: "[playful] 여기 있지. 그러니까, 나 안 떨게 해 봐." },
  { id: "a4-e4ddb32ff3", who: "amy", text: "…근데 벌써 떨려. 이번 판은, 포커인데도.", tag: "[quiet, nervous] ...근데 벌써 떨려. 이번 판은, 포커인데도." },
  { id: "a4-254495ab15", who: "amy", text: "아빠 자리에 앉을 거야. 앉아서, 컷만 할 거야. 칩은 안 만져.", tag: "[resolute] 아빠 자리에 앉을 거야. 앉아서, 컷만 할 거야. 칩은 안 만져." },
  { id: "a4-acbefd1fb4", who: "amy", text: "거기 앉으면 아빠처럼 될까 봐 무서웠어. 근데 이번엔 혼자 아니잖아.", tag: "[quiet, brave] 거기 앉으면, 아빠처럼 될까 봐 무서웠어. 근데 이번엔, 혼자 아니잖아." },
  { id: "a4-cdc8180285c", who: "amy", text: "수요일 밤에 소매 잡은 거. 추워서 그런 거 아니었어.", tag: "[whispers] [shy] 수요일 밤에 소매 잡은 거. ...추워서 그런 거, 아니었어." },
  { id: "a4-04392cc2c0u", who: "amy", text: "…그것도 알아 둬. 판 전에.", tag: "(직접 생성) [shy, trying to sound firm] ...그것도 알아 둬, 판 전에." },
  { id: "a4-381df020d0", who: "amy", text: "어젯밤 떡볶이는 내가 샀으니까, 이 딸기우유는 원래 네 차례야. 내기 안 해도.", tag: "[smug] 어젯밤 떡볶이는 내가 샀으니까, 이 딸기우유는 원래 네 차례야. 내기 안 해도." },
  { id: "a4-e92a9969ed", who: "amy", text: "끝나면 노래방 가. 아빠 노래. 이번엔 98점 받을 거야. 너도.", tag: "[cheerful] 끝나면 노래방 가. 아빠 노래. 이번엔 구십팔 점 받을 거야. 너도." },
  { id: "a4-3489acf8f0c", who: "amy", text: "…이기면 말해 줄게. 할 말 있어.", tag: "[whispers] [shy] ...이기면 말해 줄게. 할 말 있어." },
  { id: "a4-76384b9d10c", who: "amy", text: "지금 말하면 부정 타. 포커는 원래 그래.", tag: "[whispers] [playful] 지금 말하면, 부정 타. 포커는 원래 그래." },
  { id: "a4-7ecc34b8c9", who: "amy", text: "방금 만들었어. 내 징크스니까 내 맘이야.", tag: "[shy, playful] 방금 만들었어. 내 징크스니까, 내 맘이야." },
  { id: "a4-8093f4a10du", who: "amy", text: "봐, 떨리잖아. …딸기우유는 네가 갚아.", tag: "(직접 생성) [whispers] [playful] 봐, 떨리잖아... 딸기우유는, 네가 갚아." },
  { id: "a4-260043419cc", who: "amy", text: "혼자 거는 거 아니잖아.", tag: "[whispers] [firm] 혼자 거는 거, 아니잖아." },
  { id: "a4-2d7df88890c", who: "amy", text: "…안 울기로 약속했는데. 그건 못 지키겠다. 너는 웃고 있어. 약속이니까.", tag: "[whispers] [crying] ...안 울기로 약속했는데. 그건, 못 지키겠다... 너는 웃고 있어. 약속이니까." },
  { id: "a4-921901e56d", who: "amy", text: "컷은 깊게. 운은 아래에 있어.", tag: "[steady, soft] 컷은 깊게. 운은, 아래에 있어." },
  { id: "a4-82ddc9749cc", who: "amy", text: "……깊게 못 잘랐어. 미안.", tag: "[whispers] [trembling] ......깊게, 못 잘랐어. 미안." },
  { id: "a4-e7fc0352e8c", who: "amy", text: "아빠 버릇이에요. 이길 것 같을 때 두드리는 거.", tag: "[whispers] [steady] 아빠 버릇이에요. 이길 것 같을 때... 두드리는 거." },
  { id: "a4-e06894e0cccu", who: "amy", text: "…아빠 글씨다. 7에 줄 긋는 거.", tag: "(직접 생성) [tearful] ...아빠 글씨다. 칠에, 줄 긋는 거." },
  { id: "a4-2fb02e4112u", who: "amy", text: "…이건 내 거네. 아빠 거랑 같이 태워.", tag: "(직접 생성) [calm, relieved] ...이건 내 거네. 아빠 거랑, 같이 태워." },
  { id: "a4-86edc76909", who: "amy", text: "나도 같이 가. 아빠 공책도 같이.", tag: "[resolute] 나도 같이 가. 아빠 공책도 같이." },
  { id: "a4-8576237cb3", who: "amy", text: "나도. 아빠 공책, 백 번 읽었어. 다 외워.", tag: "[firm, proud] 나도. 아빠 공책, 백 번 읽었어. 다 외워." },
  { id: "a4-f34ca72990c", who: "amy", text: "안 돼! 그거 아빠 거야!", tag: "[screaming] 안 돼! 그거, 아빠 거야!" },
  { id: "a4-6e405cc714c", who: "amy", text: "…마지막 장은 살았어.", tag: "[trembling, relieved] ...마지막 장은... 살았어." },
  { id: "a4-672e434623cu", who: "amy", text: "…나도 외워. 아빠 공책 마지막 장. 백 번 읽었어.", tag: "(직접 생성) [shaky but determined] ...나도 외워. 아빠 공책 마지막 장. 백 번, 읽었어." },
  { id: "a4-040aaed941c", who: "amy", text: "…언니 거 뺏어 먹기로 했는데. 오늘은 봐준다.", tag: "[whispers] [smiling] ...언니 거 뺏어 먹기로 했는데. 오늘은, 봐준다." },
  { id: "a4-9b14c8cba8c", who: "amy", text: "다음엔 네가 두드려. 그거 엄청 떨렸단 말이야.", tag: "[whispers] [pouty] 다음엔, 네가 두드려. 그거... 엄청 떨렸단 말이야." },
  { id: "a4-759121372d", who: "amy", text: "뭐야, 그런 거 좋아해? 언니 의외로 감성적이다.", tag: "[smug, teasing] 뭐야, 그런 거 좋아해? 언니, 의외로 감성적이다." },
  { id: "a4-5ae1f8e906", who: "amy", text: "밤새 울어서 그래. 목 다 쉬었어.", tag: "[pouty, hoarse] 밤새 울어서 그래. 목 다 쉬었어." },
  { id: "a4-780e7e179ec", who: "amy", text: "…진짜 이겼어? 판도, 테이블도?", tag: "[whispers] [disbelief] ...진짜 이겼어? 판도... 테이블도?" },
  { id: "a4-a1811e642ec", who: "amy", text: "…이겼어? 우리. 이긴 거 맞아?", tag: "[whispers] [disbelief] ...이겼어? 우리. ...이긴 거 맞아?" },
  { id: "a4-b785326970", who: "amy", text: "…늦었어. 4주나 걸렸잖아.", tag: "[pouty, teary] ...늦었어. 사 주나 걸렸잖아." },
  { id: "a4-b08cfc9907", who: "amy", text: "근데 잡았으니까 봐줄게. 평생 이번 한 번만.", tag: "[shy] 근데 잡았으니까, 봐줄게. 평생, 이번 한 번만." },
  { id: "a4-8477a059cd", who: "amy", text: "자, 봐. 월세 완납. 외상 완납. 그리고 이거. 점장님 메시지. '다음 달부터 매니저 해 볼래요?'", tag: "[smug, excited] 자, 봐. 월세 완납. 외상 완납. 그리고 이거. 점장님 메시지. 다음 달부터, 매니저 해 볼래요?" },
  { id: "a4-2fae04f104", who: "amy", text: "나 매니저래. 계산대 숫자는 한 번도 안 틀렸대.", tag: "[proud, smug] 나 매니저래. 계산대 숫자는, 한 번도 안 틀렸대." },
  { id: "a4-6d7cb32b4e", who: "amy", text: "그건 칩이 날 싫어해서 그래.", tag: "[pouty] 그건, 칩이 날 싫어해서 그래." },
  { id: "a4-4a73027f01", who: "amy", text: "봐. 98점. 이번 건 진짜야. 둘이서 받은 거니까.", tag: "[happy, proud] 봐. 구십팔 점. 이번 건 진짜야. 둘이서 받은 거니까." },
  { id: "a4-fc2a8cc05bu", who: "amy", text: "아빠 노래 하나 있어. 일요일 아침에 팬케이크 구우면서 부르던 거.", tag: "(직접 생성) [warm, nostalgic] 아빠 노래, 하나 있어. 일요일 아침에... 팬케이크 구우면서 부르던 거." },
  { id: "a4-d792ba7466", who: "amy", text: "한 번도 끝까지 못 불렀어. 오늘은 부를래. 너 옆에 있으니까.", tag: "[soft, brave] 한 번도 끝까지 못 불렀어. 오늘은 부를래. 너 옆에 있으니까." },
  { id: "a4-452b2a16fdu", who: "amy", text: "98점. 오늘은 기계 말, 믿어 줄래.", tag: "(직접 생성) [happy, a little breathless] 구십팔 점! 오늘은, 기계 말 믿어 줄래." },
  { id: "a4-187e69c4d7", who: "amy", text: "아빠 공책은 재가 됐는데, 이상하지? 노래는 다 기억나. 백 번 들어서.", tag: "[wistful, smiling] 아빠 공책은 재가 됐는데, 이상하지? 노래는 다 기억나. 백 번 들어서." },
  { id: "a4-fb086c338c", who: "amy", text: "아빠 공책 마지막 장, 액자에 넣었어. 그을린 채로. 그게 더 아빠 같아서.", tag: "[warm, smiling] 아빠 공책 마지막 장, 액자에 넣었어. 그을린 채로. 그게 더, 아빠 같아서." },
  { id: "a4-dd4d3767f0c", who: "amy", text: "…이기면 말해 준다고 했지. 할 말.", tag: "[whispers] [shy] ...이기면 말해 준다고 했지. 할 말." },
  { id: "a4-9d189821c4c", who: "amy", text: "한 달이나 미뤘네. 부정 탈까 봐가 아니라, 그냥 무서워서.", tag: "[whispers] [shy] 한 달이나 미뤘네. 부정 탈까 봐가 아니라... 그냥, 무서워서." },
  { id: "a4-8f038dde5dc", who: "amy", text: "좋아해. 처음 진 날부터. 네가 내 칩 쓸어 가던 손부터.", tag: "[whispers] [breathless] 좋아해. 처음 진 날부터. ...네가 내 칩 쓸어 가던, 손부터." },
  { id: "a4-d3c3ae8cca", who: "amy", text: "…On my side. 앞으로도. 알았지?", tag: "[softly, smiling] ...On my side. 앞으로도. 알았지?" },
  { id: "a4-a7dc317479", who: "amy", text: "…앞으로도 내 편 해. 대답은 안 해도 돼. 얼굴에 써 있어.", tag: "[softly, smiling] ...앞으로도 내 편 해. 대답은 안 해도 돼. 얼굴에 써 있어." },
  { id: "a4-f2091d9194c", who: "amy", text: "언니! 왜 딜러한테 먼저 말 걸어! 오늘 사탕 내기는 나랑이잖아!", tag: "[jealous] [shouting] 언니! 왜 딜러한테 먼저 말 걸어?! 오늘 사탕 내기는, 나랑이잖아!" },
  { id: "a4-9b3a0a1faf", who: "amy", text: "…축하해, 언니. 이번엔 진짜로.", tag: "[warm, sincere] ...축하해, 언니. 이번엔 진짜로." },
  { id: "a4-54e04ceeb1", who: "amy", text: "어서 오세요! …아, 언니 남친이네. 어서 오지 마세요.", tag: "[cheerful, then teasing] 어서 오세요! [smug] ...아, 언니 남친이네. 어서 오지 마세요." },
  { id: "a4-65a20f6df7", who: "amy", text: "명찰 봤어? '매니저'. 계산대 숫자 한 번도 안 틀렸대. 칩은 맨날 틀리게 셌는데.", tag: "[proud, smug] 명찰 봤어? 매니저. 계산대 숫자, 한 번도 안 틀렸대. 칩은 맨날 틀리게 셌는데." },
  { id: "a4-4b6dc2a17d", who: "amy", text: "언니랑 일요일마다 쳐. 사탕 걸고. 아직 한 번도 못 이겼어.", tag: "[pouty] 언니랑 일요일마다 쳐. 사탕 걸고. 아직, 한 번도 못 이겼어." },
  { id: "a4-ec74f15927", who: "amy", text: "…근데 이상하지? 져 놓고 실실 웃고 있어, 내가.", tag: "[amused, warm] ...근데 이상하지? 져 놓고, 실실 웃고 있어. 내가." },
  { id: "a4-57050c215e", who: "amy", text: "야, 딜러. 언니 울리면 죽어. 이번엔 진짜로.", tag: "[playful threat, half-serious] 야, 딜러. 언니 울리면 죽어. [mock serious] 이번엔 진짜로." },
  { id: "a4-af70d47b75", who: "amy", text: "…뭐야? 왜 우리 손을 붙여?", tag: "[puzzled] ...뭐야? 왜 우리 손을 붙여?" },
  { id: "a4-0469498370", who: "amy", text: "언니, 레이즈. 사탕 다섯 개.", tag: "[smug, confident] 언니, 레이즈. 사탕 다섯 개." },
  { id: "a4-98d2c9d7d9c", who: "amy", text: "일부러야! 일부러 감은 거야! 역이용!", tag: "[panicked] [shouting] 일부러야! 일부러 감은 거야! 역이용!" },
  { id: "a4-b0b7ba683ac", who: "amy", text: "들었어? 기분 좋대! 진 사람이!", tag: "[ecstatic] [shouting] 들었어?! 기분 좋대! 진 사람이!" },
  { id: "a4-7a040882d4", who: "amy", text: "딜러. 오늘은 카드 안 돌려도 돼. 거기 앉아 있어.", tag: "[warm] 딜러. 오늘은 카드 안 돌려도 돼. 거기 앉아 있어." },
  { id: "a4-aa1cf34182", who: "amy", text: "너 없이도 이길 수 있어.", tag: "[soft, confident] 너 없이도, 이길 수 있어." },
  { id: "y6-69609f25b2", who: "yeonseo", text: "딜러님.", tag: "[calm] 딜러님." },
  { id: "y6-2a8496f15d", who: "yeonseo", text: "셔플할 때 엄지가 먼저 나가네요.", tag: "[calm] [observant] 셔플할 때, 엄지가 먼저 나가네요." },
  { id: "y6-28afe02e78", who: "yeonseo", text: "아니요. 열에 아홉은 검지가 먼저 나가요.", tag: "[deadpan] 아니요. 열에 아홉은, 검지가 먼저 나가요." },
  { id: "y6-0a7a166985", who: "yeonseo", text: "딜러님은 남은 하나고요.", tag: "[dry] 딜러님은, 남은 하나고요." },
  { id: "y7-7574c91ab5", who: "yeonseo", text: "7년 동안 딜러 손만 봤어요. 통계라고 해도 돼요.", tag: "[calm] 칠 년 동안, 딜러 손만 봤어요. 통계라고 해도 돼요." },
  { id: "y6-3535353c09", who: "yeonseo", text: "보는 게 일이라서요.", tag: "[deadpan] 보는 게, 일이라서요." },
  { id: "y6-f8bae34d68", who: "yeonseo", text: "손님 손이랑 딜러 손, 그리고 칩. 얼굴은 잘 안 봐요. 얼굴은 거짓말을 하니까.", tag: "[deadpan] 손님 손이랑 딜러 손, 그리고 칩. 얼굴은 잘 안 봐요. [cool] 얼굴은, 거짓말을 하니까." },
  { id: "y7-59b20554c1", who: "yeonseo", text: "…딜러님 손은 거짓말을 잘 못하네요.", tag: "[calm] ...딜러님 손은, 거짓말을 잘 못하네요." },
  { id: "y6-859d6af7ab", who: "yeonseo", text: "예전에 그렇게 섞던 사람이 하나 있었는데. …아니에요. 수고하셨어요.", tag: "[wistful] 예전에 그렇게 섞던 사람이, 하나 있었는데. [composing herself] ...아니에요. 수고하셨어요." },
  { id: "y6-21fe9e739d", who: "yeonseo", text: "딜러님. 앉으니까 어땠어요? 오랜만에.", tag: "[calm] [probing] 딜러님. 앉으니까 어땠어요? 오랜만에." },
  { id: "y6-93b03b0ccf", who: "yeonseo", text: "의자 끄는 소리를 한참 듣고 있었잖아요. 오래 못 들은 소리처럼.", tag: "[deadpan] 의자 끄는 소리를, 한참 듣고 있었잖아요. 오래 못 들은 소리처럼." },
  { id: "y7-6a203ef547", who: "yeonseo", text: "구석 자리는 할 일이 별로 없어요. 그래서 다 보여요.", tag: "[calm] 구석 자리는, 할 일이 별로 없어요. 그래서 다 보여요." },
  { id: "y6-7d0ed6a277", who: "yeonseo", text: "한 판이 두 판 되고, 두 판이 한 달 돼요. …제 얘기예요. 딜러님 얘기 아니고.", tag: "[distant] [self-deprecating] 한 판이 두 판 되고, 두 판이 한 달 돼요. [quiet] ...제 얘기예요. 딜러님 얘기 아니고." },
  { id: "y6-95d2d02174", who: "yeonseo", text: "딜러님. 아까 그거, 잘했어요.", tag: "[calm] 딜러님. 아까 그거, 잘했어요." },
  { id: "y6-ae66a6dc30", who: "yeonseo", text: "안 앉은 거요. 그 금발 손님, 이기든 지든 밤새 안 일어났을 거예요.", tag: "[deadpan] 안 앉은 거요. 그 금발 손님, 이기든 지든, 밤새 안 일어났을 거예요." },
  { id: "y6-97167f36f9", who: "yeonseo", text: "이기는 사람 옆에 있으면 자기도 이길 것 같거든요. 지금 그 손님한텐 딜러님이 그래요.", tag: "[deadpan] 이기는 사람 옆에 있으면, 자기도 이길 것 같거든요. 지금 그 손님한텐, 딜러님이 그래요." },
  { id: "y7-70e5c2b950", who: "yeonseo", text: "…방금 건 못 들은 걸로 해요. 하우스 플레이어가 할 말은 아니라서.", tag: "[a little embarrassed] ...방금 건, 못 들은 걸로 해요. 하우스 플레이어가 할 말은 아니라서." },
  { id: "y6-f6d0eaa38b", who: "yeonseo", text: "…이모.", tag: "[embarrassed] [protesting] ...이모." },
  { id: "y6-ad7162e79d", who: "yeonseo", text: "다른 것도 먹어요. 김치찌개를 더 먹을 뿐이에요.", tag: "[cool] [defensive] 다른 것도 먹어요. 김치찌개를 더 먹을 뿐이에요." },
  { id: "y6-4b7b517b1b", who: "yeonseo", text: "…이모. 무슨 말을 했는데요?", tag: "[embarrassed] [wary] ...이모. 무슨 말을 했는데요?" },
  { id: "y6-c729f7f82f", who: "yeonseo", text: "…그건 좋은 말이 아니라 정보예요.", tag: "[dry] ...그건 좋은 말이 아니라, 정보예요." },
  { id: "y6-8dbd904af6", who: "yeonseo", text: "딜러님도 이모 밥 먹어요?", tag: "[curious] 딜러님도, 이모 밥 먹어요?" },
  { id: "y7-6027f7d28e", who: "yeonseo", text: "그럼 됐어요. 이 가게에서 믿어도 되는 건 이모 밥이랑 이모뿐이에요.", tag: "[calm] 그럼 됐어요. 이 가게에서 믿어도 되는 건, 이모 밥이랑 이모뿐이에요." },
  { id: "y6-9135eaf9ca", who: "yeonseo", text: "…두 문장이었어요.", tag: "[embarrassed] [dry] ...두 문장이었어요." },
  { id: "y6-c7d2dfa823", who: "yeonseo", text: "…왜 줘요?", tag: "[surprised] ...왜 줘요?" },
  { id: "y6-996d6fd906", who: "yeonseo", text: "근거는요?", tag: "[cool] [probing] 근거는요?" },
  { id: "y6-aa82fe0d93", who: "yeonseo", text: "…표본이 하나잖아요.", tag: "[flustered] [defensive] ...표본이, 하나잖아요." },
  { id: "y6-1ca929a9e3", who: "yeonseo", text: "좋은 건 먼저 먹어요. 나중엔 없을 수도 있으니까.", tag: "[deadpan] 좋은 건 먼저 먹어요. [quiet] 나중엔, 없을 수도 있으니까." },
  { id: "y7-7e9af962ad", who: "yeonseo", text: "많이 잃어 본 사람 식사법이에요. 비슷한 말이지만.", tag: "[wry] 많이 잃어 본 사람 식사법이에요. 비슷한 말이지만." },
  { id: "y6-b61d32be6f", who: "yeonseo", text: "…잘 먹었습니다.", tag: "[shy] [polite] ...잘 먹었습니다." },
  { id: "y6-325a3cde6d", who: "yeonseo", text: "딜러님. '손'이라는 사람 알아요?", tag: "[calm] [probing] 딜러님. 손이라는 사람, 알아요?" },
  { id: "y6-47df1d5e25", who: "yeonseo", text: "3년 전에 이 바닥에서 제일 손이 빨랐대요. 다들 죽었다고 하던데.", tag: "[deadpan] 삼 년 전에, 이 바닥에서 제일 손이 빨랐대요. 다들 죽었다고 하던데." },
  { id: "y6-148a969d78", who: "yeonseo", text: "저는 안 믿어요. 그런 손은 쉽게 안 죽거든요.", tag: "[cool] [confident] 저는 안 믿어요. 그런 손은, 쉽게 안 죽거든요." },
  { id: "y6-a477d19283", who: "yeonseo", text: "그래요.", tag: "[cool] [unconvinced] 그래요." },
  { id: "y7-7f78c456ca", who: "yeonseo", text: "근데 딜러님, 거짓말할 때 카드를 한 장 더 만지네요. 지금처럼.", tag: "[knowing] 근데 딜러님, 거짓말할 때 카드를 한 장 더 만지네요. 지금처럼." },
  { id: "y6-9adb6b0fd6", who: "yeonseo", text: "직업이에요. 취미는 아직 못 찾았어요.", tag: "[dry] 직업이에요. 취미는, 아직 못 찾았어요." },
  { id: "y6-6e787417be", who: "yeonseo", text: "대답 안 하는 것도 대답이에요.", tag: "[calm] [knowing] 대답 안 하는 것도, 대답이에요." },
  { id: "y6-08bc04393e", who: "yeonseo", text: "그 사람이든 아니든 상관없어요. 카드 돌리는 손이 예뻐서 물어본 거예요.", tag: "[calm] [light] 그 사람이든 아니든, 상관없어요. 카드 돌리는 손이 예뻐서, 물어본 거예요." },
  { id: "y6-92a74cdfac", who: "yeonseo", text: "관찰이에요. 칭찬으로 들렸으면, 그것도 괜찮고요.", tag: "[flustered] [composed] 관찰이에요. [softer] 칭찬으로 들렸으면, 그것도 괜찮고요." },
  { id: "y6-1dc29f61ff", who: "yeonseo", text: "혼자 오는 게 아니라, 여기서 하우스 플레이어로 일하는 거예요. 가게 돈으로 앉아요.", tag: "[deadpan] 혼자 오는 게 아니라, 여기서 하우스 플레이어로 일하는 거예요. 가게 돈으로 앉아요." },
  { id: "y6-915dbbdbbd", who: "yeonseo", text: "이모가 말했죠.", tag: "[cool] 이모가 말했죠." },
  { id: "y6-7c1c37de0a", who: "yeonseo", text: "처음엔 1년만 하려고 했어요. 계산이 좀 틀렸죠.", tag: "[wry] 처음엔, 일 년만 하려고 했어요. 계산이 좀 틀렸죠." },
  { id: "y7-bed217208f", who: "yeonseo", text: "가끔요. 사람이 들어가면 숫자가 잘 안 맞아요.", tag: "[calm] 가끔요. 사람이 들어가면, 숫자가 잘 안 맞아요." },
  { id: "y6-64d49143c1", who: "yeonseo", text: "…같은 방향이에요?", tag: "[neutral] ...같은 방향이에요?" },
  { id: "y6-37811b31fc", who: "yeonseo", text: "저는 그 앞 오피스텔이에요. 그럼 역까지만.", tag: "[deadpan] 저는 그 앞 오피스텔이에요. 그럼, 역까지만." },
  { id: "y6-40e009be94", who: "yeonseo", text: "딜러님은 왜 서 있어요? 그 손이면 앉는 게 돈이 더 될 텐데.", tag: "[curious] [cool] 딜러님은 왜 서 있어요? 그 손이면, 앉는 게 돈이 더 될 텐데." },
  { id: "y6-d1f2c46cff", who: "yeonseo", text: "이기지도 않잖아요.", tag: "[dry] 이기지도 않잖아요." },
  { id: "y6-7d4f075b6d", who: "yeonseo", text: "낮에 한 대답, 진짜였어요?", tag: "[calm] [probing] 낮에 한 대답, 진짜였어요?" },
  { id: "y6-c8d5e15846", who: "yeonseo", text: "…그랬죠.", tag: "[quiet] ...그랬죠." },
  { id: "y6-a807b990f7", who: "yeonseo", text: "…저는 앉아서 7년째 이기고 있어요. 근데 이긴 것 같았던 적은 없어요.", tag: "[quiet] [wry] ...저는 앉아서, 칠 년째 이기고 있어요. 근데, 이긴 것 같았던 적은 없어요." },
  { id: "y7-95d02e271e", who: "yeonseo", text: "딜러님 방식이 맞는 걸지도 모르겠네요. 아니면 둘 다 틀렸거나.", tag: "[wistful] 딜러님 방식이 맞는 걸지도 모르겠네요. [falling tone] 아니면, 둘 다 틀렸거나." },
  { id: "y6-26aaab9a3a", who: "yeonseo", text: "그 칩, 갖고 있어요. 돌려 달라고 안 할게요.", tag: "[calm] 그 칩, 갖고 있어요. 돌려 달라고, 안 할게요." },
  { id: "y6-096820ae61", who: "yeonseo", text: "…보지 마요.", tag: "[embarrassed] [sharp] ...보지 마요." },
  { id: "y6-122a6eb286", who: "yeonseo", text: "봤잖아요. 3초.", tag: "[flustered] 봤잖아요. 삼 초." },
  { id: "y6-9921797ae7", who: "yeonseo", text: "세는 게 일이에요.", tag: "[dry] 세는 게, 일이에요." },
  { id: "y6-34e3c4758d", who: "yeonseo", text: "얘는 이름 없어요. 이름 붙이면 정 드니까.", tag: "[cool] [distant] 얘는, 이름 없어요. 이름 붙이면, 정 드니까." },
  { id: "y6-0732bfc5a4", who: "yeonseo", text: "정 들면 곤란해져요. 이 동네엔 오래 있는 게 별로 없어서.", tag: "[quiet] 정 들면 곤란해져요. 이 동네엔, 오래 있는 게 별로 없어서." },
  { id: "y6-825286aed5", who: "yeonseo", text: "…'콜'. 부르면 오니까.", tag: "[soft] [tender] ...콜. 부르면 오니까." },
  { id: "y6-8464e2208f", who: "yeonseo", text: "제가 아는 단어가 그쪽에 몰려 있어요.", tag: "[dry] 제가 아는 단어가, 그쪽에 몰려 있어요." },
  { id: "y6-da1bec95de", who: "yeonseo", text: "…얘, 저한테는 한 번도 먼저 손 안 내밀었어요.", tag: "[surprised] ...얘, 저한테는 한 번도, 먼저 손 안 내밀었어요." },
  { id: "y7-322b98b86c", who: "yeonseo", text: "딜러님은 칭찬을 그렇게 피하네요.", tag: "[calm] 딜러님은, 칭찬을 그렇게 피하네요." },
  { id: "y6-d8e1b435d6", who: "yeonseo", text: "부탁 하나 해도 돼요?", tag: "[hesitant] 부탁 하나, 해도 돼요?" },
  { id: "y6-349db4e6f5", who: "yeonseo", text: "제가 못 오는 날, 얘 밥 좀. 그리고 사진도. 살아 있는지 확인용이에요.", tag: "[deadpan] [a little awkward] 제가 못 오는 날, 얘 밥 좀. 그리고 사진도. 살아 있는지, 확인용이에요." },
  { id: "y6-19b675a661", who: "yeonseo", text: "네. 다른 용도는 없어요.", tag: "[cool] 네. 다른 용도는 없어요." },
  { id: "y6-5da3bbffac", who: "yeonseo", text: "…지금은요.", tag: "[shy] [under her breath] ...지금은요." },
  { id: "y6-31afccba39", who: "yeonseo", text: "가게 사람들한텐 비밀이에요. 하우스 플레이어가 길고양이 밥 주는 거, 무서워 보이지 않잖아요.", tag: "[cool] [slightly embarrassed] 가게 사람들한텐 비밀이에요. 하우스 플레이어가 길고양이 밥 주는 거, 무서워 보이지 않잖아요." },
  { id: "y6-f4547fe337", who: "yeonseo", text: "…일찍 왔네요.", tag: "[mildly surprised] ...일찍 왔네요." },
  { id: "y7-9fb9e3cde5", who: "yeonseo", text: "저는 매일 이 시간에 와요. 오늘은 관객이 생겼네요.", tag: "[calm] 저는 매일, 이 시간에 와요. 오늘은, 관객이 생겼네요." },
  { id: "y6-27ae7e6c58", who: "yeonseo", text: "그건 아래층 칩이에요. 위층에선 그냥 장난감이고요.", tag: "[deadpan] 그건 아래층 칩이에요. 위층에선, 그냥 장난감이고요." },
  { id: "y7-93cff3ccc8", who: "yeonseo", text: "딜러님 손에 뭐가 쥐어져 있는 게 보기 좋아서요. …농담이에요. 반쯤.", tag: "[calm] 딜러님 손에, 뭐가 쥐어져 있는 게 보기 좋아서요. [dry] ...농담이에요. 반쯤." },
  { id: "y6-01eda0be99", who: "yeonseo", text: "딜러님. 한 판 할래요? 칩 없이.", tag: "[calm] [inviting] 딜러님. 한 판 할래요? 칩 없이." },
  { id: "y6-dc80480dd7", who: "yeonseo", text: "근무 시간 전이니까 규정 위반도 아니에요. 확인했어요.", tag: "[deadpan] 근무 시간 전이니까, 규정 위반도 아니에요. 확인했어요." },
  { id: "y6-6ed3624a17", who: "yeonseo", text: "어제요. 혹시 몰라서.", tag: "[cool] [a little embarrassed] 어제요. [falling tone] 혹시 몰라서." },
  { id: "y6-3d71b99bd1", who: "yeonseo", text: "질문하세요. 약속은 약속이니까.", tag: "[calm] 질문하세요. 약속은 약속이니까." },
  { id: "y6-6e39c800b4", who: "yeonseo", text: "다쳤었어요. 7년 전에 카드를 너무 꽉 쥐어서. 손바닥에 카드 모서리 모양 흉터가 있어요.", tag: "[quiet] 다쳤었어요. 칠 년 전에, 카드를 너무 꽉 쥐어서. 손바닥에, 카드 모서리 모양 흉터가 있어요." },
  { id: "y6-daa2454d9f", who: "yeonseo", text: "손을 보이면 읽히니까 가려요.", tag: "[calm] 손을 보이면 읽히니까, 가려요." },
  { id: "y6-da64c2046c", who: "yeonseo", text: "…왜 이런 얘길 하는지 모르겠네요. 진 사람은 거짓말 없이 대답하기로 해서 그런가.", tag: "[hesitant] [quiet] ...왜 이런 얘길 하는지 모르겠네요. 진 사람은 거짓말 없이 대답하기로 해서, 그런가." },
  { id: "y6-9f2ee899ff", who: "yeonseo", text: "…싫어해요. 엄청.", tag: "[calm] [firm] ...싫어해요. 엄청." },
  { id: "y6-0b7d9b330d", who: "yeonseo", text: "근데 방금은 이상하게 별로 안 싫었어요. 원인은 분석 중이에요.", tag: "[puzzled] [quiet] 근데 방금은, 이상하게 별로 안 싫었어요. 원인은, 분석 중이에요." },
  { id: "y7-e031f38dc0", who: "yeonseo", text: "결과가 나와도 말 안 할 수도 있어요. 그건 규칙에 없으니까요.", tag: "[teasing] 결과가 나와도, 말 안 할 수도 있어요. 그건 규칙에 없으니까요." },
  { id: "y6-0d5f4596e0", who: "yeonseo", text: "제가 이겼으니까 질문할게요.", tag: "[quietly satisfied] 제가 이겼으니까, 질문할게요." },
  { id: "y6-d321dea358", who: "yeonseo", text: "딜러님은 왜 앉지 않아요?", tag: "[calm] [curious] 딜러님은, 왜 앉지 않아요?" },
  { id: "y6-1514cfd973", who: "yeonseo", text: "역 앞에서 물었죠. 왜 서 있냐고. 이번엔 거짓말 없이요.", tag: "[calm] [firm] 역 앞에서 물었죠. 왜 서 있냐고. 이번엔, 거짓말 없이요." },
  { id: "y6-bfb28ee53d", who: "yeonseo", text: "…그래요.", tag: "[quiet] ...그래요." },
  { id: "y6-8bce9b96e2", who: "yeonseo", text: "그 마음, 조금 알 것 같아요. 저는 앉았다가 못 일어난 쪽이라서.", tag: "[quiet] [wistful] 그 마음, 조금 알 것 같아요. 저는, 앉았다가 못 일어난 쪽이라서." },
  { id: "y6-4e7a256a1f", who: "yeonseo", text: "거짓말 없이 대답하기로 했잖아요.", tag: "[cool] [pointed] 거짓말 없이 대답하기로, 했잖아요." },
  { id: "y7-3b1196063c", who: "yeonseo", text: "대답을 다 안 했을 뿐이죠. 저도 자주 써요, 그 수.", tag: "[knowing] 대답을 다 안 했을 뿐이죠. 저도 자주 써요, 그 수." },
  { id: "y6-df46dcfbf9", who: "yeonseo", text: "그럼 섞기만 해 줄래요? 제 앞에서. 한 번만.", tag: "[hopeful] [hesitant] 그럼, 섞기만 해 줄래요? 제 앞에서. 한 번만." },
  { id: "y6-8e23d0075f", who: "yeonseo", text: "…역시.", tag: "[breathless] [awed] ...역시." },
  { id: "y7-fda87d8748", who: "yeonseo", text: "소리요. 제가 아는 소리 중에 제일 좋은 소리예요.", tag: "[soft] [calm] 소리요. 제가 아는 소리 중에, 제일 좋은 소리예요." },
  { id: "y6-fdebef684a", who: "yeonseo", text: "이 손, 다쳤었어요. 카드를 너무 꽉 쥐어서. 그래서 장갑 껴요.", tag: "[quiet] [vulnerable] 이 손, 다쳤었어요. 카드를 너무 꽉 쥐어서. 그래서, 장갑 껴요." },
  { id: "y6-23d2b62b1c", who: "yeonseo", text: "…방금 건 잊어요. 딜러님 셔플이 사람을 말 많게 하네요.", tag: "[flustered] [composed] ...방금 건 잊어요. 딜러님 셔플이, 사람을 말 많게 하네요." },
  { id: "y6-8bf991e212", who: "yeonseo", text: "…딜러님.", tag: "[surprised] ...딜러님." },
  { id: "y6-c4723ce81f", who: "yeonseo", text: "이 차림은 못 본 걸로 해요. 3초 줄게요.", tag: "[flustered] 이 차림은, 못 본 걸로 해요. 삼 초 줄게요." },
  { id: "y6-27ff15f772", who: "yeonseo", text: "…놀리는 거죠? 슬리퍼에 컵라면인데.", tag: "[embarrassed] [suspicious] ...놀리는 거죠? 슬리퍼에 컵라면인데." },
  { id: "y6-5ee86e1808", who: "yeonseo", text: "…놀리는 얼굴이 아니네요. 더 곤란해요.", tag: "[flustered] [quiet] ...놀리는 얼굴이 아니네요. [falling tone] 더 곤란해요." },
  { id: "y6-d95e57682b", who: "yeonseo", text: "딜러님은 이상한 데를 봐요.", tag: "[flustered] 딜러님은, 이상한 데를 봐요." },
  { id: "y6-5d8cc9351c", who: "yeonseo", text: "손목이요. 카드를 하루 열 시간 만지면 이렇게 되거든요. 딜러님도 곧 알 거예요.", tag: "[deadpan] 손목이요. 카드를 하루 열 시간 만지면, 이렇게 되거든요. 딜러님도, 곧 알 거예요." },
  { id: "y6-e6052a3c6e", who: "yeonseo", text: "…진짜로 셀 줄은 몰랐어요.", tag: "[surprised] [a little amused] ...진짜로 셀 줄은, 몰랐어요." },
  { id: "y6-d2b53c9288", who: "yeonseo", text: "가린 건 무효예요. 아직 보이잖아요.", tag: "[flustered] 가린 건, 무효예요. 아직 보이잖아요." },
  { id: "y6-3dcfacf317", who: "yeonseo", text: "하우스 플레이어는 돈을 벌어도 제 돈이 아니에요. 따는 건 가게 돈, 지는 건 제 빚.", tag: "[deadpan] 하우스 플레이어는, 돈을 벌어도 제 돈이 아니에요. 따는 건 가게 돈, 지는 건 제 빚." },
  { id: "y7-82e37ba08d", who: "yeonseo", text: "그래서 컵라면이 제일 맛있어요. 이건 제 돈이니까.", tag: "[calm] 그래서, 컵라면이 제일 맛있어요. 이건 제 돈이니까." },
  { id: "y6-c6bc5eaacd", who: "yeonseo", text: "안 찼어요.", tag: "[cool] [denying] 안 찼어요." },
  { id: "y6-5e96065838", who: "yeonseo", text: "…찼어요. 기록하지 마요.", tag: "[flustered] [admitting] ...찼어요. 기록하지 마요." },
  { id: "y6-f53d07b32b", who: "yeonseo", text: "딜러님은 왜 하필 이 가게예요? 펍은 많은데.", tag: "[curious] 딜러님은, 왜 하필 이 가게예요? 펍은 많은데." },
  { id: "y6-ed9cfa6abf", who: "yeonseo", text: "저도 이 가게밖에 갈 데가 없어요. 우리 비슷하네요.", tag: "[quiet] 저도, 이 가게밖에 갈 데가 없어요. 우리, 비슷하네요." },
  { id: "y7-cde2a77e2f", who: "yeonseo", text: "…비슷한 사람이랑 컵라면 먹는 거, 예상 승률보다 훨씬 괜찮네요.", tag: "[calm] ...비슷한 사람이랑 컵라면 먹는 거, 예상 승률보다 훨씬 괜찮네요." },
  { id: "y6-7788e089cd", who: "yeonseo", text: "…왜 여기 있어요?", tag: "[whispers] [surprised] …왜 여기 있어요?" },
  { id: "y6-0039c6f470", who: "yeonseo", text: "…숨 쉬지 마요.", tag: "[whispers] [flustered] ...숨 쉬지 마요." },
  { id: "y6-0a2ca70775", who: "yeonseo", text: "그럼 작게요. 딜러님 숨, 제 앞머리 날려요.", tag: "[whispers] [flustered] 그럼 작게요... 딜러님 숨, 제 앞머리 날려요." },
  { id: "y6-5ae1e0f2de", who: "yeonseo", text: "먼저 나가요. 저는 3분 뒤에 나갈게요.", tag: "[flustered] 먼저 나가요. 저는 삼 분 뒤에 나갈게요." },
  { id: "y6-28f7f09208", who: "yeonseo", text: "그리고 다시는 이 계단 내려오지 마요. 다음엔 제가 없을 수도 있어요.", tag: "[serious] 그리고 다시는 이 계단 내려오지 마요. 다음엔 제가 없을 수도 있어요." },
  { id: "y6-f676e9c469", who: "yeonseo", text: "…심장 소리, 다 들렸어요. 분당 백이십 정도.", tag: "[softly] [flustered] ...심장 소리, 다 들렸어요. 분당 백이십 정도." },
  { id: "y6-50b15942a4", who: "yeonseo", text: "세는 게 일이라니까요. 제 것도 셌는데, 그건 비밀이에요.", tag: "[whispers] [flustered] 세는 게 일이라니까요. [whispers] 제 것도 셌는데... 그건 비밀이에요." },
  { id: "y6-d4f607863f", who: "yeonseo", text: "뭐가요?", tag: "[flat] 뭐가요?" },
  { id: "y6-6159923b11", who: "yeonseo", text: "추워서요. 아래층은 에어컨이 세서.", tag: "[deadpan] 추워서요. 아래층은 에어컨이 세서." },
  { id: "y6-f699143f46p", who: "yeonseo", text: "그러니까 에어컨이 세죠.", tag: "[deadpan] 그러니까 에어컨이 쎄죠." },
  { id: "y6-2780afcb1f", who: "yeonseo", text: "…딜러님. 사장님이 무슨 말 하든, 아래층엔 내려가지 마요. 부탁이에요.", tag: "[earnest] [sad] ...딜러님. 사장님이 무슨 말 하든, 아래층엔 내려가지 마요. 부탁이에요." },
  { id: "y6-3e7b8b15a3", who: "yeonseo", text: "제가 추운 거, 어떻게 알았어요?", tag: "[surprised] 제가 추운 거... 어떻게 알았어요?" },
  { id: "y6-1de91cd658", who: "yeonseo", text: "…딜러님은 손님 손을 너무 잘 읽어요. 그거 이 가게에선 위험해요.", tag: "[deadpan] ...딜러님은 손님 손을 너무 잘 읽어요. 그거 이 가게에선 위험해요." },
  { id: "y6-a54e8b6cad", who: "yeonseo", text: "…수고하셨어요.", tag: "[flat] ...수고하셨어요." },
  { id: "y6-7ccf90e069", who: "yeonseo", text: "기념이면 기념품이 필요하겠네요.", tag: "[dry] 기념이면... 기념품이 필요하겠네요." },
  { id: "y6-cfd1dd40ce", who: "yeonseo", text: "…다음 달엔 기념하지 마요.", tag: "[deadpan] ...다음 달엔 기념하지 마요." },
  { id: "y6-6f3e619e73", who: "yeonseo", text: "…안 피워요. 쥐고만 있어요. 손이 뭘 쥐고 있어야 해서.", tag: "[deadpan] ...안 피워요. 쥐고만 있어요. 손이 뭘 쥐고 있어야 해서." },
  { id: "y6-2e720cebc6", who: "yeonseo", text: "…일이에요.", tag: "[flat] ...일이에요." },
  { id: "y6-5470c97181", who: "yeonseo", text: "월급날이라 오는 손님은, 월급날이라 오래 앉아요. 그걸 아는 게 제 일이에요.", tag: "[deadpan] 월급날이라 오는 손님은, 월급날이라 오래 앉아요. 그걸 아는 게 제 일이에요." },
  { id: "y6-6a9562d662", who: "yeonseo", text: "좋아하면 이상한 사람이죠. 저는 아직 그 정도는 아니에요.", tag: "[self-deprecating] 좋아하면 이상한 사람이죠. 저는 아직 그 정도는 아니에요." },
  { id: "y6-e18105fc26", who: "yeonseo", text: "…물어보면 대답 안 할 줄 알고, 안 묻는 거죠.", tag: "[deadpan] ...물어보면 대답 안 할 줄 알고, 안 묻는 거죠." },
  { id: "y6-93a8069f0e", who: "yeonseo", text: "…역시. 그래서… 그래서 편한 거예요. 오늘은 좀… 편하고 싶었어요.", tag: "[hesitant] ...역시. 그래서... 그래서 편한 거예요. 오늘은 좀... 편하고 싶었어요." },
  { id: "y6-a47bc1d05e", who: "yeonseo", text: "…딸기 맛이네요. 이거, 금발 손님 취향인데.", tag: "[dry] ...딸기 맛이네요. 이거, 금발 손님 취향인데." },
  { id: "y6-0cb0dc7327", who: "yeonseo", text: "그런 걸로 해 둘게요.", tag: "[dry] [amused] 그런 걸로 해 둘게요." },
  { id: "y7-eab782bc7f", who: "yeonseo", text: "들어가요. 감기 걸려요. 딜러님 손은 아껴야죠.", tag: "[calm] 들어가요. 감기 걸려요. 딜러님 손은 아껴야죠." },
  { id: "y6-022a6b99f2", who: "yeonseo", text: "장갑 얘기요. 이모 말고는 아무한테도 안 했던 거예요.", tag: "[deadpan] 장갑 얘기요. 이모 말고는 아무한테도 안 했던 거예요." },
  { id: "y6-cbb04571ee", who: "yeonseo", text: "저 손님 아닌데요. 가게 쪽 사람이에요.", tag: "[dry] 저 손님 아닌데요. 가게 쪽 사람이에요." },
  { id: "y6-8987802d19", who: "yeonseo", text: "…그래도, 고마워요.", tag: "[softly] [flustered] ...그래도, 고마워요." },
  { id: "y6-91084835e7", who: "yeonseo", text: "딜러님, 카드 돌려요. 손님들 기다려요.", tag: "[cold] 딜러님, 카드 돌려요. 손님들 기다려요." },
  { id: "y6-041cf04e3c", who: "yeonseo", text: "…축하해요.", tag: "[flat] ...축하해요." },
  { id: "y6-937db7457a", who: "yeonseo", text: "…딜러님은 눈이 너무 좋네요.", tag: "[surprised] ...딜러님은 눈이 너무 좋네요." },
  { id: "y6-8efb6702aa", who: "yeonseo", text: "이기는 맛을 한 번 본 사람은 다 다시 앉아요. 저도 그랬고.", tag: "[sad] 이기는 맛을 한 번 본 사람은... 다 다시 앉아요. 저도 그랬고." },
  { id: "y6-34dbcd386f", who: "yeonseo", text: "에이미 씨한테, 당분간 큰 판 하지 말라고 해 줘요. 제가 한 말이라고는 하지 말고.", tag: "[whispers] 에이미 씨한테, 당분간 큰 판 하지 말라고 해 줘요. [whispers] 제가 한 말이라고는 하지 말고." },
  { id: "y6-1d389cb58e", who: "yeonseo", text: "딜러님이 신경 쓸 일 아니에요.", tag: "[cold] 딜러님이 신경 쓸 일 아니에요." },
  { id: "y6-eca1e7746e", who: "yeonseo", text: "…받았네요. 그 제안.", tag: "[cold] ...받았네요. 그 제안." },
  { id: "y6-2018973917", who: "yeonseo", text: "얼굴에 써 있어요. 딜러님은 생각보다 읽기 쉬워요.", tag: "[cold] 얼굴에 써 있어요. 딜러님은 생각보다 읽기 쉬워요." },
  { id: "y6-3654376fd0", who: "yeonseo", text: "그 사람 제안은 한 번 받으면 끝이 없어요. 저도 처음엔 '한 번만'이었어요.", tag: "[sad] 그 사람 제안은 한 번 받으면 끝이 없어요. 저도 처음엔 '한 번만'이었어요." },
  { id: "y6-58216da40c", who: "yeonseo", text: "사장님이 뭐래요?", tag: "[deadpan] 사장님이 뭐래요?" },
  { id: "y6-e27746eeed", who: "yeonseo", text: "…딜러님, 덱 맨 위 카드 쓸고 있어요. 거짓말할 때 나오는 손이에요.", tag: "[calm] ...딜러님, 덱 맨 위 카드 쓸고 있어요. 거짓말할 때 나오는 손이에요." },
  { id: "y6-86ae862ba9", who: "yeonseo", text: "웃으면서 기다리는 사람이 제일 무서운 거예요. 기다리는 동안 이미 다 계산해 놨거든요.", tag: "[deadpan] 웃으면서 기다리는 사람이 제일 무서운 거예요. 기다리는 동안 이미 다 계산해 놨거든요." },
  { id: "y6-ecfd4b1992", who: "yeonseo", text: "…돌아가요.", tag: "[cold] ...돌아가요." },
  { id: "y6-028f8a6bd5", who: "yeonseo", text: "알아요. 제가 앉을 거니까요.", tag: "[whispers] [sad] 알아요. [whispers] 제가 앉을 거니까요." },
  { id: "y6-2fd073d12c", who: "yeonseo", text: "오늘 에이미 씨 맞은편은 저예요. 사장님이 정했어요.", tag: "[cold] 오늘 에이미 씨 맞은편은 저예요. 사장님이 정했어요." },
  { id: "y6-f5ee322c85p", who: "yeonseo", text: "딜러님이 들어오면, 사장님은 딜러님을 앉힐 거예요. 기다렸다는 듯이. 그럼 셋 다 끝나요.", tag: "[deadpan] 딜러님이 들어오면, 사장님은 딜러님을 앉힐 거예요. 기다렸다는 듯이. 그럼 셋다 끝나요." },
  { id: "y6-90d32fb3d2", who: "yeonseo", text: "끝내는 숫자는 제가 못 정해요. 처음부터 정해져서 와요.", tag: "[sad] 끝내는 숫자는 제가 못 정해요. 처음부터 정해져서 와요." },
  { id: "y6-60a4411824", who: "yeonseo", text: "어제 에이미 씨가 이긴 판도 그래요. 제가 져 준 거예요. 오늘은 그 반대예요.", tag: "[cold] 어제 에이미 씨가 이긴 판도 그래요. 제가 져 준 거예요. 오늘은 그 반대예요." },
  { id: "y6-208f8e5064", who: "yeonseo", text: "올라가요. 끝나면 에이미 씨는 제가 올려 보낼게요. 그것만은 약속할게요.", tag: "[sad] 올라가요. 끝나면 에이미 씨는 제가 올려 보낼게요. 그것만은 약속할게요." },
  { id: "y6-8fd2eb90f7c", who: "yeonseo", text: "…제발요.", tag: "[desperate] [trembling] ...제발요..." },
  { id: "y6-4f820e5119", who: "yeonseo", text: "…딜러님. 우산, 하나밖에 없어서요.", tag: "[hesitant] ...딜러님. 우산, 하나밖에 없어서요." },
  { id: "y6-b3486c268d", who: "yeonseo", text: "…에이미 씨, 택시는 제가 불러 줄 수 있어요.", tag: "[sad] [hesitant] ...에이미 씨, 택시는 제가 불러 줄 수 있어요." },
  { id: "y6-1105a1ef3b", who: "yeonseo", text: "기사님한테 주소 확인했어요. 집 앞까지 가요.", tag: "[deadpan] 기사님한테 주소 확인했어요. 집 앞까지 가요." },
  { id: "y6-c105ceca84", who: "yeonseo", text: "고맙단 말 들을 일은 아니에요. 에이미 씨 월세, 제가 땄으니까.", tag: "[deadpan] 고맙단 말 들을 일은 아니에요. 에이미 씨 월세, 제가 땄으니까." },
  { id: "y6-44da84761b", who: "yeonseo", text: "…어깨, 젖었어요. 딜러님 쪽만.", tag: "[deadpan] ...어깨, 젖었어요. 딜러님 쪽만." },
  { id: "y7-ee6659c956", who: "yeonseo", text: "우산은 안 작아요. 딜러님이 바깥쪽으로 서 있는 거죠.", tag: "[calm] 우산은 안 작아요. 딜러님이 바깥쪽으로 서 있는 거죠." },
  { id: "y6-dcfea10982", who: "yeonseo", text: "오늘 에이미 씨 돈, 정해진 숫자만큼 땄어요. 하나도 안 틀리고.", tag: "[sad] 오늘 에이미 씨 돈, 정해진 숫자만큼 땄어요. 하나도 안 틀리고." },
  { id: "y6-f8ddaaede1", who: "yeonseo", text: "근데 에이미 씨가 저한테 축하한대요. 진짜로.", tag: "[sad] 근데 에이미 씨가 저한테 축하한대요... 진짜로." },
  { id: "y6-95fd47615d", who: "yeonseo", text: "…딜러님이 에이미 씨를 데려다줄 줄 알았어요. 그래야 맞는 거니까. 근데 왜 여기 있어요?", tag: "[deadpan] ...딜러님이 에이미 씨를 데려다줄 줄 알았어요. 그래야 맞는 거니까. 근데 왜 여기 있어요?" },
  { id: "y6-deacb71c3b", who: "yeonseo", text: "그런 이유로 오는 사람이 어디 있어요?", tag: "[flustered] 그런 이유로 오는 사람이 어디 있어요?" },
  { id: "y6-acb10017db", who: "yeonseo", text: "…사장님이 딜러님에 대해 알아보라고 했어요. 진짜 '손'이 맞는지.", tag: "[whispers] ...사장님이 딜러님에 대해 알아보라고 했어요. [whispers] 진짜 '손'이 맞는지." },
  { id: "y7-3a476b6943", who: "yeonseo", text: "모르겠어요. 보고는 내일 할 거예요. '평범한 딜러였습니다'라고.", tag: "[calm] 모르겠어요. 보고는 내일 할 거예요. '평범한 딜러였습니다'라고." },
  { id: "y6-f69ca13f0c", who: "yeonseo", text: "대답을 다 안 하는 거예요. 제가 자주 쓰는 수예요.", tag: "[dry] 대답을 다 안 하는 거예요. 제가 자주 쓰는 수예요." },
  { id: "y7-41eb1e56ce", who: "yeonseo", text: "우산은 가져가요. 저는 바로 앞이니까.", tag: "[calm] 우산은 가져가요. 저는 바로 앞이니까." },
  { id: "y6-1154969a43", who: "yeonseo", text: "오늘 제 승률 100퍼센트였어요. 근데 이긴 것 같지가 않아요.", tag: "[quiet] [sad] 오늘 제 승률, 백 퍼센트였어요. 근데... 이긴 것 같지가 않아요." },
  { id: "y7-56fab16f36", who: "yeonseo", text: "…지금 이게, 오늘 중에 제일 이긴 것 같아요.", tag: "[soft] ...지금 이게, 오늘 중에 제일 이긴 것 같아요." },
  { id: "y6-1123f35c55", who: "yeonseo", text: "…어제, 잘 데려다줬어요?", tag: "[deadpan] ...어제, 잘 데려다줬어요?" },
  { id: "y6-098b35efc4", who: "yeonseo", text: "잘했어요. 그쪽이 맞아요.", tag: "[deadpan] 잘했어요. 그쪽이 맞아요." },
  { id: "y6-6c6ba181f3", who: "yeonseo", text: "에이미 씨 외상, 이번 주엔 늘리지 말라고 해 줘요. 늘어나는 속도가 너무 친절해서요.", tag: "[dry] 에이미 씨 외상, 이번 주엔 늘리지 말라고 해 줘요. 늘어나는 속도가 너무 친절해서요." },
  { id: "y6-32a0340d39", who: "yeonseo", text: "아니요. 딜러님 생각인 걸로 해요. 그 애, 딜러님 말은 더 잘 듣거든요.", tag: "[warm] 아니요. 딜러님 생각인 걸로 해요. 그 애, 딜러님 말은 더 잘 듣거든요." },
  { id: "y6-3ead0d7a6f", who: "yeonseo", text: "에이미 씨. 오늘은 들어가요.", tag: "[cold] 에이미 씨. 오늘은 들어가요." },
  { id: "y6-fb1007ba7d", who: "yeonseo", text: "비 와요. 우산 없잖아요.", tag: "[flat] 비 와요. 우산 없잖아요." },
  { id: "y6-553ed9da32", who: "yeonseo", text: "…또 관객이 생겼네요.", tag: "[dry] ...또 관객이 생겼네요." },
  { id: "y6-6bdf30840e", who: "yeonseo", text: "에이미 씨는요? 요즘 위층에 안 오던데요.", tag: "[deadpan] 에이미 씨는요? 요즘 위층에 안 오던데요." },
  { id: "y6-7b10bfe35b", who: "yeonseo", text: "에이미 씨는요? 어제 위층에 안 왔던데요.", tag: "[deadpan] 에이미 씨는요? 어제 위층에 안 왔던데요." },
  { id: "y6-46caa16c09", who: "yeonseo", text: "…잘됐네요. 진짜로.", tag: "[warm] ...잘됐네요. 진짜로." },
  { id: "y6-908c18d7fb", who: "yeonseo", text: "손 둘 데가 테이블 말고도 생긴 거니까요.", tag: "[deadpan] 손 둘 데가 테이블 말고도 생긴 거니까요." },
  { id: "y6-c2191463ac", who: "yeonseo", text: "딜러님. 위에서 세 번째 카드, 맞혀 봐요. 방금 섞은 거예요.", tag: "[deadpan] 딜러님. 위에서 세 번째 카드, 맞혀 봐요. 방금 섞은 거예요." },
  { id: "y6-c583f7c43a", who: "yeonseo", text: "에이스는 다들 한 번씩 말해요. 희망 사항이라서요.", tag: "[dry] [amused] 에이스는 다들 한 번씩 말해요. 희망 사항이라서요." },
  { id: "y6-56bf30b3a4", who: "yeonseo", text: "손 보는 눈은 녹이 안 슬었네요. 조심해요. 그 눈, 이 가게에선 비싸게 팔리거든요.", tag: "[deadpan] 손 보는 눈은 녹이 안 슬었네요. 조심해요. 그 눈, 이 가게에선 비싸게 팔리거든요." },
  { id: "y6-931081327f", who: "yeonseo", text: "정직하네요. 확률상 제일 많이 맞는 대답이에요.", tag: "[dry] 정직하네요. 확률상 제일 많이 맞는 대답이에요." },
  { id: "y6-5b3220c722", who: "yeonseo", text: "틀린 것도 하나도 없잖아요.", tag: "[dry] [amused] 틀린 것도 하나도 없잖아요." },
  { id: "y6-aca623c933", who: "yeonseo", text: "딜러님 오늘 표정이 좋아요. 이유는 안 물을게요. 대충 알 것 같아서.", tag: "[deadpan] 딜러님 오늘 표정이 좋아요. 이유는 안 물을게요. 대충 알 것 같아서." },
  { id: "y6-d613483cb1", who: "yeonseo", text: "그 애 손, 놓지 마요. 지금은 누가 잡고 있어야 하는 손이에요.", tag: "[serious] 그 애 손, 놓지 마요. 지금은 누가 잡고 있어야 하는 손이에요." },
  { id: "y6-404a6fc1ef", who: "yeonseo", text: "…방금 건 제 혼잣말이에요. 하우스 플레이어가 할 말은 아니라서.", tag: "[deadpan] ...방금 건 제 혼잣말이에요. 하우스 플레이어가 할 말은 아니라서." },
  { id: "y6-8a5da9f7db", who: "yeonseo", text: "…딜러님이 왜 여기 있어요?", tag: "[surprised] ...딜러님이 왜 여기 있어요?" },
  { id: "y6-e6a34f6ab0", who: "yeonseo", text: "들어와요. 문 앞에 서 있으면 이웃이 이상하게 봐요.", tag: "[deadpan] 들어와요. 문 앞에 서 있으면 이웃이 이상하게 봐요." },
  { id: "y6-457e348ac9", who: "yeonseo", text: "보지 마요. 그건 장식이에요.", tag: "[cold] 보지 마요. 그건 장식이에요." },
  { id: "y6-1b3a31e07d", who: "yeonseo", text: "큰 장식이에요.", tag: "[flat] 큰 장식이에요." },
  { id: "y6-296285eae2", who: "yeonseo", text: "이모가 보냈다고요. …이모가 먼저 그랬어요?", tag: "[a bit hoarse from fever] 이모가 보냈다고요. [suspicious] [probing] ...이모가 먼저 그랬어요?" },
  { id: "y6-b64ff4809c", who: "yeonseo", text: "…그래요. 그런 걸로 해요.", tag: "[flustered] ...그래요. 그런 걸로 해요." },
  { id: "y6-af04d43745", who: "yeonseo", text: "다음부턴 이모 통하지 말고 직접 물어봐요. 죽 심부름 같은 거.", tag: "[deadpan] 다음부턴 이모 통하지 말고 직접 물어봐요. 죽 심부름 같은 거." },
  { id: "y6-4829fb1732", who: "yeonseo", text: "안 아플 때도… 되긴 해요. 확률은 낮지만.", tag: "[flustered] 안 아플 때도... 되긴 해요. 확률은 낮지만." },
  { id: "y6-39134d5b62", who: "yeonseo", text: "다음부턴 이모 통하지 말고 저한테 직접 물어봐요. 번호 있잖아요.", tag: "[deadpan] 다음부턴 이모 통하지 말고 저한테 직접 물어봐요. 번호 있잖아요." },
  { id: "y6-bf7adbf075", who: "yeonseo", text: "…용도는 늘릴 수 있어요. 오늘부터.", tag: "[flustered] ...용도는 늘릴 수 있어요. 오늘부터." },
  { id: "y6-3d153faef5", who: "yeonseo", text: "…그러니까 이제 정식으로 줄게요. 몰래 아는 거랑 받은 거는 장부가 달라요.", tag: "[flustered] ...그러니까 이제 정식으로 줄게요. 몰래 아는 거랑 받은 거는 장부가 달라요." },
  { id: "y6-6f5bc2facb", who: "yeonseo", text: "부탁 하나 더요. 오늘 골목 박스, 저 대신 들러 줘요. 통조림은 현관 신발장 위에.", tag: "[deadpan] 부탁 하나 더요. 오늘 골목 박스, 저 대신 들러 줘요. 통조림은 현관 신발장 위에." },
  { id: "y6-0beb93bc43", who: "yeonseo", text: "비상식량이에요. 걔 거.", tag: "[quietly] 비상식량이에요. 걔 거." },
  { id: "y6-8a99bf6cd6", who: "yeonseo", text: "…그리고 하나만 더. 이건 진짜 마지막이에요.", tag: "[hesitant] ...그리고 하나만 더. 이건 진짜 마지막이에요." },
  { id: "y6-2d34299f62", who: "yeonseo", text: "카드 좀 섞어 줘요. 그 소리 들으면 잠이 오거든요. 7년째, 그렇게 자요.", tag: "[deadpan] 카드 좀 섞어 줘요. 그 소리 들으면 잠이 오거든요. 칠 년째, 그렇게 자요." },
  { id: "y6-44d1371e43", who: "yeonseo", text: "…딜러님은 이상한 순서로 일해요.", tag: "[flustered] ...딜러님은 이상한 순서로 일해요." },
  { id: "y6-f33031b28c", who: "yeonseo", text: "손님 아니에요. 집주인이에요.", tag: "[dry] 손님 아니에요. 집주인이에요." },
  { id: "y6-a6e1064dc0", who: "yeonseo", text: "아침에 전화로 보고했어요. 평범한 딜러였다고.", tag: "[whispers] [sleepy] 아침에 전화로 보고했어요. [whispers] [sleepy] 평범한 딜러였다고." },
  { id: "y6-2d205e5de5", who: "yeonseo", text: "사장님이 웃었어요. 그 사람은 믿을 때도 웃고 안 믿을 때도 웃어서… 모르겠어요.", tag: "[whispers] [sleepy] 사장님이 웃었어요. [whispers] [sleepy] 그 사람은 믿을 때도 웃고 안 믿을 때도 웃어서... 모르겠어요." },
  { id: "y6-6ba416c76d", who: "yeonseo", text: "…그래도 했어요. 거짓말. 사장님한테.", tag: "[whispers] [flustered] …그래도 했어요. [whispers] 거짓말, 사장님한테." },
  { id: "y6-ab0f6f5c8d", who: "yeonseo", text: "…그 의자, 두 개만 남겨 둬요.", tag: "[deadpan] ...그 의자, 두 개만 남겨 둬요." },
  { id: "y6-3c2e4eb41d", who: "yeonseo", text: "한 판 해요. 칩 대신 성냥. 이긴 사람이 질문 하나.", tag: "[deadpan] 한 판 해요. 칩 대신 성냥. 이긴 사람이 질문 하나." },
  { id: "y6-1f36506376", who: "yeonseo", text: "손님도 없고, 사장님은 아래층. …어제 죽값이에요. 갚게 해 줘요.", tag: "[deadpan] 손님도 없고, 사장님은 아래층. ...어제 죽값이에요. 갚게 해 줘요." },
  { id: "y6-35b3b7ef0a", who: "yeonseo", text: "…딜러님은 끝까지 안 앉네요.", tag: "[deadpan] ...딜러님은 끝까지 안 앉네요." },
  { id: "y6-9579fbb548", who: "yeonseo", text: "좋아요. 그럼 제가 먼저 해요. 공짜로.", tag: "[deadpan] 좋아요. 그럼 제가 먼저 해요. 공짜로." },
  { id: "y6-5aa789c8f2", who: "yeonseo", text: "제가 이겼으니까, 질문할게요. 그다음엔 진 사람도 하나. 죽값이니까요.", tag: "[dry] [amused] 제가 이겼으니까, 질문할게요. 그다음엔 진 사람도 하나. 죽값이니까요." },
  { id: "y6-f011b768ca", who: "yeonseo", text: "…읽었네요. 두드리는 손 다음까지.", tag: "[surprised] ...읽었네요. 두드리는 손 다음까지." },
  { id: "y6-1e8165ef5c", who: "yeonseo", text: "7년 동안 그걸 본 사람은 없었어요. 사장님도요.", tag: "[deadpan] 칠 년 동안 그걸 본 사람은 없었어요. 사장님도요." },
  { id: "y6-445c8c406b", who: "yeonseo", text: "그럼 이번엔 둘 다 하나씩 해요. 읽은 값으로. 제가 먼저.", tag: "[warm] 그럼 이번엔 둘 다 하나씩 해요. 읽은 값으로, 제가 먼저." },
  { id: "y6-3bf0d1a274", who: "yeonseo", text: "3년 전 그 판. 누구랑 쳤어요?", tag: "[serious] 삼 년 전 그 판. 누구랑 쳤어요?" },
  { id: "y6-5500adcfc9", who: "yeonseo", text: "이 가게에도 그렇게 웃는 사람이 하나 있죠.", tag: "[cold] 이 가게에도 그렇게 웃는 사람이 하나 있죠." },
  { id: "y6-ca3c597f07", who: "yeonseo", text: "딜러님 차례. 사적인 거 물어봐도 돼요. 오늘은 거짓말 안 할게요.", tag: "[deadpan] 딜러님 차례. 사적인 거 물어봐도 돼요. 오늘은 거짓말 안 할게요." },
  { id: "y6-5116f0ba3d", who: "yeonseo", text: "…좋아하는 거.", tag: "[surprised] ...좋아하는 거." },
  { id: "y6-92919013a6", who: "yeonseo", text: "비 그친 다음 날 아침이요. 골목이 다 젖어 있는데, 하늘은 맑은 거.", tag: "[thoughtful] 비 그친 다음 날 아침이요. 골목이 다 젖어 있는데, 하늘은 맑은 거." },
  { id: "y6-195f69e7f0", who: "yeonseo", text: "밤새 지하에 있다가 올라오면 가끔 그런 아침이 있어요. 오늘은 좀 괜찮겠다, 싶어요.", tag: "[thoughtful] 밤새 지하에 있다가 올라오면 가끔 그런 아침이 있어요. 오늘은 좀 괜찮겠다, 싶어요." },
  { id: "y6-b03e3cf015", who: "yeonseo", text: "이런 거 묻는 사람이 없었어요. 대답하는 데 십이 초 걸렸어요.", tag: "[flustered] 이런 거 묻는 사람이 없었어요. 대답하는 데 십이 초 걸렸어요." },
  { id: "y6-a63a9af93a", who: "yeonseo", text: "…스물두 살이었어요. 엄마 병원비요. 한 판만 이기면 된다고 했어요. 사장님이.", tag: "[deadpan] ...스물두 살이었어요. 엄마 병원비요. 한 판만 이기면 된다고 했어요, 사장님이." },
  { id: "y6-1b774420d1", who: "yeonseo", text: "이겼어요. 첫 판도, 두 번째 판도. 세 번째 판에서 카드를 너무 꽉 쥐었어요.", tag: "[sad] 이겼어요. 첫 판도, 두 번째 판도. 세 번째 판에서... 카드를 너무 꽉 쥐었어요." },
  { id: "y6-7d5259bb5c", who: "yeonseo", text: "손바닥에서 피가 났는데 몰랐어요. 지는 게 더 아파서.", tag: "[sad] 손바닥에서 피가 났는데 몰랐어요. 지는 게 더 아파서." },
  { id: "y6-4734abb066", who: "yeonseo", text: "엄마는 그해 겨울에 돌아가셨어요. 빚만 남기고. 그게 7년이에요.", tag: "[sad] 엄마는 그해 겨울에 돌아가셨어요. 빚만 남기고. 그게... 칠 년이에요." },
  { id: "y6-f6ed1883f7", who: "yeonseo", text: "…이 얘기, 이모 말고 아는 사람은 딜러님 하나예요. 생각보다 목소리가 안 떨리네요.", tag: "[deadpan] ...이 얘기, 이모 말고 아는 사람은 딜러님 하나예요. 생각보다 목소리가 안 떨리네요." },
  { id: "y6-df4dc7a03f", who: "yeonseo", text: "…그 칩요.", tag: "[flat] ...그 칩요." },
  { id: "y6-6fffbd4729", who: "yeonseo", text: "사장님이 딜러님 테이블에 두라고 했어요. 그걸 보고 표정이 변하면, 예전 그 사람이라고.", tag: "[cold] 사장님이 딜러님 테이블에 두라고 했어요. 그걸 보고 표정이 변하면, 예전 그 사람이라고." },
  { id: "y6-1adc4c6a83", who: "yeonseo", text: "딜러님은 표정이 안 변했어요. 대신 주머니에 넣었죠. 아주 조심스럽게.", tag: "[deadpan] 딜러님은 표정이 안 변했어요. 대신 주머니에 넣었죠. 아주 조심스럽게." },
  { id: "y6-12370403d9", who: "yeonseo", text: "그날 보고는 '반응 없음'이었어요. 사실… 그게 제 첫 번째 거짓말이에요.", tag: "[flustered] 그날 보고는 '반응 없음'이었어요. 사실... 그게 제 첫 번째 거짓말이에요." },
  { id: "y6-49f586ae72", who: "yeonseo", text: "…늦었어요. 들어가요.", tag: "[deadpan] ...늦었어요. 들어가요." },
  { id: "y6-76dba34595", who: "yeonseo", text: "가져가요. 다음 판 할 때 가져와요.", tag: "[deadpan] 가져가요. 다음 판 할 때 가져와요." },
  { id: "y6-86b737398f", who: "yeonseo", text: "다음 판이 있다는 계산이에요. 틀리면 곤란해요.", tag: "[warm] 다음 판이 있다는 계산이에요. 틀리면 곤란해요." },
  { id: "y6-4e5a1b0485", who: "yeonseo", text: "이모가 저도 불렀어요. 짐꾼이 둘이면 두부를 두 모 살 수 있대요.", tag: "[deadpan] 이모가 저도 불렀어요. 짐꾼이 둘이면 두부를 두 모 살 수 있대요." },
  { id: "y6-2854b0c7bc", who: "yeonseo", text: "…이모. 두부가 무거워서 온 거예요.", tag: "[flustered] ...이모. 두부가 무거워서 온 거예요." },
  { id: "y6-82225d6d67", who: "yeonseo", text: "두 사람, 무슨 얘기 했어요?", tag: "[suspicious] 두 사람, 무슨 얘기 했어요?" },
  { id: "y6-365900147b", who: "yeonseo", text: "두부 얘기를 그렇게 진지하게 해요?", tag: "[cold] 두부 얘기를 그렇게 진지하게 해요?" },
  { id: "y6-8e2e0a631f", who: "yeonseo", text: "방금 건 실수예요. 손이 계산을 틀렸어요.", tag: "[flustered] 방금 건 실수예요. 손이 계산을 틀렸어요." },
  { id: "y6-2b07f077c0", who: "yeonseo", text: "…방금 그 말. '시간 많으니까'.", tag: "[surprised] ...방금 그 말. '시간 많으니까'." },
  { id: "y6-2e09b962a6", who: "yeonseo", text: "그 빚, 어디예요?", tag: "[cold] 그 빚, 어디예요?" },
  { id: "y6-e67744aa2e", who: "yeonseo", text: "저랑 같은 데예요. 그 말… 사장님 입버릇이에요.", tag: "[sad] 저랑 같은 데예요. 그 말... 사장님 입버릇이에요." },
  { id: "y6-d9cb8732ed", who: "yeonseo", text: "…고마워요.", tag: "[flustered] ...고마워요." },
  { id: "y6-9cde2262a9", who: "yeonseo", text: "아직이에요, 이 손은. …아직.", tag: "[quietly] [sad] 아직이에요. 이 손은... 아직." },
  { id: "y6-563c1f3034", who: "yeonseo", text: "…숨기는 게 일이에요. 손을 보이면 읽히니까.", tag: "[cold] ...숨기는 게 일이에요. 손을 보이면 읽히니까." },
  { id: "y6-40e1658823", who: "yeonseo", text: "딜러님한테는 이미 너무 많이 읽혔지만.", tag: "[flustered] 딜러님한테는 이미 너무 많이 읽혔지만." },
  { id: "y6-eefc0eb181", who: "yeonseo", text: "…언젠가 보여 줄게요. 찢어져서 말고, 제 손으로 벗어서.", tag: "[softly] [flustered] ...언젠가 보여 줄게요. 찢어져서 말고, 제 손으로 벗어서." },
  { id: "y6-1f0f270c48", who: "yeonseo", text: "…배고파요.", tag: "[flat] ...배고파요." },
  { id: "y6-619448c6e6", who: "yeonseo", text: "여기 딜러님 말고 누가 있어요?", tag: "[deadpan] 여기 딜러님 말고 누가 있어요?" },
  { id: "y6-ad4d327ecc", who: "yeonseo", text: "술은 안 마셔요. 취하면 표정이 생길까 봐서요.", tag: "[deadpan] 술은 안 마셔요. 취하면 표정이 생길까 봐서요." },
  { id: "y6-41c4055d00", who: "yeonseo", text: "표정이 생기면 읽혀요. 읽히면 지고, 지면 빚이 늘고. …그래서 7년 동안 안 마셨어요.", tag: "[deadpan] 표정이 생기면 읽혀요. 읽히면 지고, 지면 빚이 늘고. ...그래서 칠 년 동안 안 마셨어요." },
  { id: "y6-80dfeb3a41", who: "yeonseo", text: "…물이에요.", tag: "[surprised] ...물이에요." },
  { id: "y6-6499c1d95a", who: "yeonseo", text: "…거짓말.", tag: "[flustered] ...거짓말." },
  { id: "y6-59a18b523f", who: "yeonseo", text: "그럼 이건 건배예요. 물이지만.", tag: "[dry] [amused] 그럼 이건 건배예요. 물이지만." },
  { id: "y6-b77f4af85b", who: "yeonseo", text: "딜러님이 읽잖아요. 그게 제일 문제예요.", tag: "[dry] 딜러님이 읽잖아요. 그게 제일 문제예요." },
  { id: "y6-08e9edccce", who: "yeonseo", text: "써요.", tag: "[flat] 써요." },
  { id: "y6-4d273f176c", who: "yeonseo", text: "…표정, 생겼어요?", tag: "[flustered] ...표정, 생겼어요?" },
  { id: "y6-f0397ce745", who: "yeonseo", text: "그럼 오늘은 져도 돼요. 칩이 없으니까.", tag: "[a little tipsy] [amused] 그럼 오늘은 져도 돼요. 칩이 없으니까." },
  { id: "y6-b9dddca6fd", who: "yeonseo", text: "…하나 물어봐도 돼요? 이건 내기 아니고.", tag: "[hesitant] ...하나 물어봐도 돼요? 이건 내기 아니고." },
  { id: "y6-303257afab", who: "yeonseo", text: "딜러님 이름. 불러 봐도 돼요?", tag: "[flustered] 딜러님 이름. 불러 봐도 돼요?" },
  { id: "y6-89c381a5eb", who: "yeonseo", text: "…이상해요. 이름 하나 부르는 게, 올인보다 떨려요.", tag: "[softly] [flustered] ...이상해요. 이름 하나 부르는 게, 올인보다 떨려요." },
  { id: "y6-9f690fd104", who: "yeonseo", text: "누가 그래요?", tag: "[flustered] 누가 그래요?" },
  { id: "y6-dcd378e337", who: "yeonseo", text: "달력 봤죠? 우리 집 벽에.", tag: "[deadpan] 달력 봤죠? 우리 집 벽에." },
  { id: "y6-1f6d487329", who: "yeonseo", text: "하루 끝날 때마다 X 쳐요. 오늘도 빚을 못 줄였다는 표시. 7년 치요.", tag: "[deadpan] 하루 끝날 때마다 엑스 쳐요. 오늘도 빚을 못 줄였다는 표시. 칠 년 치요." },
  { id: "y6-5c1c9c0c38", who: "yeonseo", text: "근데 오늘은… 칠 수 있을지 모르겠어요. 오늘은 그런 날 같지 않아서.", tag: "[hesitant] 근데 오늘은... 칠 수 있을지 모르겠어요. 오늘은 그런 날 같지 않아서." },
  { id: "y6-15188376de", who: "yeonseo", text: "그건 무슨 표시인데요?", tag: "[curious] 그건 무슨 표시인데요?" },
  { id: "y6-06b18db6d9", who: "yeonseo", text: "볼펜이 검은색밖에 없는데. 동그라미가 X처럼 보이면 어떡해요.", tag: "[amused] 볼펜이 검은색밖에 없는데. 동그라미가 엑스처럼 보이면 어떡해요." },
  { id: "y6-f1f1400810", who: "yeonseo", text: "저랑… 딜러님이요. 둘이 알면 돼요.", tag: "[flustered] 저랑... 딜러님이요. 둘이 알면 돼요." },
  { id: "y6-f208ef8e3d", who: "yeonseo", text: "여름에 붕어빵 굽는 데는 이 동네에 여기 하나예요. 희귀 표본이에요.", tag: "[deadpan] 여름에 붕어빵 굽는 데는 이 동네에 여기 하나예요. 희귀 표본이에요." },
  { id: "y6-e203efc1ff", who: "yeonseo", text: "다섯 개요. 표본이 적으면 결론을 못 내요.", tag: "[deadpan] 다섯 개요. 표본이 적으면 결론을 못 내요." },
  { id: "y6-bec462d833", who: "yeonseo", text: "하나, 꼬리 비었어요. 둘, 비었어요. 셋… 들어 있어요.", tag: "[focused] 하나, 꼬리 비었어요. 둘, 비었어요. 셋... 들어 있어요." },
  { id: "y6-4543e94516", who: "yeonseo", text: "다섯 개 중 두 개. 40퍼센트. 생각보다 높아요.", tag: "[surprised] 다섯 개 중 두 개. 사십 퍼센트. 생각보다 높아요." },
  { id: "y6-761ec83907", who: "yeonseo", text: "결론. '꼬리까지 들어 있는 날도 있다.' 오늘처럼요.", tag: "[softly] 결론. '꼬리까지 들어 있는 날도 있다.' 오늘처럼요." },
  { id: "y6-a10ea9587f", who: "yeonseo", text: "결과 공유예요. 연구 윤리상.", tag: "[dry] 결과 공유예요. 연구 윤리상." },
  { id: "y6-b7068f39b5", who: "yeonseo", text: "…다음 실험도 같이 해요. 표본은 많을수록 좋으니까.", tag: "[softly] [flustered] ...다음 실험도 같이 해요. 표본은 많을수록 좋으니까." },
  { id: "y6-9c31c7ad35", who: "yeonseo", text: "…에이미 씨한테 전해 줘요. 42만 원이에요.", tag: "[deadpan] ...에이미 씨한테 전해 줘요. 사십이 만 원이에요." },
  { id: "y6-94119f9ac4", who: "yeonseo", text: "그 애 월세요. 제가 땄어요. 정해진 숫자만큼, 하나도 안 틀리고.", tag: "[sad] 그 애 월세요. 제가 땄어요. 정해진 숫자만큼, 하나도 안 틀리고." },
  { id: "y6-730d3eec3a", who: "yeonseo", text: "제가 줬다고는 하지 마요. 그럼 안 받을 거예요. 받아도, 저를 미워할 거고요.", tag: "[deadpan] 제가 줬다고는 하지 마요. 그럼 안 받을 거예요. 받아도, 저를 미워할 거고요." },
  { id: "y6-55c93bf1d7", who: "yeonseo", text: "…딜러님은 가끔 사장님보다 무서워요.", tag: "[sad] ...딜러님은 가끔 사장님보다 무서워요." },
  { id: "y6-3c894cfdd4", who: "yeonseo", text: "옆에 있는다고 했죠. 말만이면 안 돼요.", tag: "[deadpan] 옆에 있는다고 했죠. 말만이면 안 돼요." },
  { id: "y6-3b3af95132", who: "yeonseo", text: "에이미 씨 월세예요. 제가 딴 거고, 돌려드리는 거예요.", tag: "[deadpan] 에이미 씨 월세예요. 제가 딴 거고, 돌려드리는 거예요." },
  { id: "y6-87a88ccd33", who: "yeonseo", text: "그날 판은 진 게 아니라, 진 걸로 정해져 있던 거예요. 그러니까 받아요.", tag: "[firm] 그날 판은 진 게 아니라, 진 걸로 정해져 있던 거예요. 그러니까 받아요." },
  { id: "y6-e3220d181d", who: "yeonseo", text: "네. 그거면 돼요.", tag: "[sad] 네. 그거면 돼요." },
  { id: "y6-5c05414fef", who: "yeonseo", text: "…태양 씨. 레이즈할 거예요, 말 거예요?", tag: "[cold] ...태양 씨. 레이즈할 거예요, 말 거예요?" },
  { id: "y6-5ecc93e7b5", who: "yeonseo", text: "…앉아요. 오늘은 계산 안 하고 싶어요.", tag: "[deadpan] ...앉아요. 오늘은 계산 안 하고 싶어요." },
  { id: "y6-478f289a19", who: "yeonseo", text: "딜러님이 오고 나서, 제 계산이 자꾸 틀려요.", tag: "[deadpan] 딜러님이 오고 나서, 제 계산이 자꾸 틀려요." },
  { id: "y6-46d259dce9", who: "yeonseo", text: "져 줘야 하는 판에서 이기고 싶고, 이겨야 하는 판에서 딜러님 쪽을 봐요. 3.2초나요.", tag: "[deadpan] 져 줘야 하는 판에서 이기고 싶고, 이겨야 하는 판에서 딜러님 쪽을 봐요. 삼 점 이 초나요." },
  { id: "y6-99b49cd236", who: "yeonseo", text: "다 들려요. 그 사람 목소리는 칩보다 커요.", tag: "[dry] [amused] 다 들려요. 그 사람 목소리는 칩보다 커요." },
  { id: "y6-9d7b3b17e5", who: "yeonseo", text: "이유는 알아요. 숫자 안 봐도. …그래서 무서워요.", tag: "[quietly] [sad] 이유는 알아요. 숫자 안 봐도. ...그래서 무서워요." },
  { id: "y6-483d240242", who: "yeonseo", text: "…같은 쪽으로 틀리네요. 그럼 그건 오차가 아니에요.", tag: "[flustered] ...같은 쪽으로 틀리네요. 그럼 그건 오차가 아니에요." },
  { id: "y6-1cafe6e630", who: "yeonseo", text: "…세지 마요. 오늘은 저도 안 셀게요.", tag: "[whispers] [flustered] ...세지 마요. [whispers] 오늘은 저도 안 셀게요." },
  { id: "y6-66d3a02877", who: "yeonseo", text: "내일 밤, 아래층에서 보고해요.", tag: "[whispers] 내일 밤, 아래층에서 보고해요." },
  { id: "y6-108ea8695e", who: "yeonseo", text: "…어떤 말을 듣더라도, 저를 믿을 수 있어요?", tag: "[whispers] [sad] ...어떤 말을 듣더라도, 저를 믿을 수 있어요?" },
  { id: "y6-4ed7a6d148", who: "yeonseo", text: "…대답 안 하네요.", tag: "[whispers] ...대답 안 하네요." },
  { id: "y6-8c5313efaa", who: "yeonseo", text: "다행이에요. 바로 믿는다고 했으면, 저 오늘 밤 그 말을 밤새 계산했을 거예요.", tag: "[whispers] [softly] 다행이에요. [whispers] 바로 믿는다고 했으면, 저 오늘 밤 그 말을 밤새 계산했을 거예요." },
  { id: "y6-584dc85eac", who: "yeonseo", text: "망설인 사람이 믿어 주는 게 제일 무거워요. …그 무게는, 내일 밤 확인할게요.", tag: "[whispers] 망설인 사람이 믿어 주는 게 제일 무거워요. [whispers] ...그 무게는, 내일 밤 확인할게요." },
  { id: "y6-28a6e8bb48", who: "yeonseo", text: "…쉽게 믿네요. 딜러님 같은 사람이.", tag: "[whispers] [surprised] ...쉽게 믿네요. [whispers] 딜러님 같은 사람이." },
  { id: "y6-91f515885c", who: "yeonseo", text: "그래서 무서워요. 제가 그 믿음보다 나쁜 사람일까 봐요.", tag: "[whispers] [sad] 그래서 무서워요. [whispers] 제가 그 믿음보다, 나쁜 사람일까 봐요." },
  { id: "y6-c7eb1d688f", who: "yeonseo", text: "…그런 방법도 있네요. 수첩에 적어 둘게요.", tag: "[whispers] [softly] ...그런 방법도 있네요. [whispers] 수첩에 적어 둘게요." },
  { id: "y6-efbbae6521", who: "yeonseo", text: "…말할 수 없어요. 지금 말하면, 그게 거짓말이 될 수도 있어서.", tag: "[whispers] ...말할 수 없어요. [whispers] 지금 말하면, 그게 거짓말이 될 수도 있어서." },
  { id: "y6-9cfef76282", who: "yeonseo", text: "그냥 기억해 줘요. 오늘 이걸 물어본 게, 저였다는 거.", tag: "[whispers] [sad] 그냥 기억해 줘요. [whispers] 오늘 이걸 물어본 게, 저였다는 거." },
  { id: "y6-a3ffd4911b", who: "yeonseo", text: "집에 가서 동그라미 칠게요. 두 번째예요. X만 그리던 달력에.", tag: "[softly] [a small smile] 집에 가서 동그라미 칠게요. 두 번째예요... 엑스만 그리던 달력에." },
  { id: "y6-02e18bb385", who: "yeonseo", text: "…이모. 그건 실수예요.", tag: "[flustered] ...이모. 그건 실수예요." },
  { id: "y6-3cb3559bad", who: "yeonseo", text: "지우세요, 정민 씨. 백업도요.", tag: "[cold] 지우세요, 정민 씨. 백업도요." },
  { id: "y6-917b58b408", who: "yeonseo", text: "이모, 두부 모자란 거 아니에요. 냉장고에 세 모 있는 거 봤어요.", tag: "[deadpan] 이모, 두부 모자란 거 아니에요. 냉장고에 세 모 있는 거 봤어요." },
  { id: "y6-ba6489ab2b", who: "yeonseo", text: "알면서 나왔어요.", tag: "[dry] [amused] 알면서 나왔어요." },
];
const V2_P4: VoiceLine[] = [
  { id: "y6-0dab84ca8d", who: "yeonseo", text: "딜러님 주머니에 성냥 있죠?", tag: "[deadpan] 딜러님 주머니에 성냥 있죠?" },
  { id: "y6-51e6c53b9c", who: "yeonseo", text: "…그거, 다음 판 약속이에요. 오늘 밤 아래층에서 무슨 일이 있어도, 그 약속은 그대로예요.", tag: "[whispers] ...그거, 다음 판 약속이에요. [whispers] 오늘 밤 아래층에서 무슨 일이 있어도, 그 약속은 그대로예요." },
  { id: "y6-252edbb792", who: "yeonseo", text: "다음 주 달력에, 동그라미 칠 칸 하나 비워 뒀어요.", tag: "[deadpan] 다음 주 달력에... 동그라미칠 칸, 하나 비워 뒀어요." },
  { id: "y6-1f5dcb5f20", who: "yeonseo", text: "…아직 몰라요. 오늘 밤 아래층에서 무슨 일이 있어도, 그 칸은 비워 둘 거예요.", tag: "[whispers] ...아직 몰라요. [whispers] 오늘 밤 아래층에서 무슨 일이 있어도, 그 칸은 비워 둘 거예요." },
  { id: "y6-8e1e99c0a4", who: "yeonseo", text: "…어제 대답 안 한 거, 잘한 거예요.", tag: "[whispers] [sad] ...어제 대답 안 한 거, 잘한 거예요." },
  { id: "y6-77e8da7ad7", who: "yeonseo", text: "믿는다고 했으면, 지금 딜러님 얼굴 보기가 더 힘들었을 거예요.", tag: "[whispers] 믿는다고 했으면, 지금 딜러님 얼굴 보기가 더 힘들었을 거예요." },
  { id: "y6-086fa96140", who: "yeonseo", text: "…이번엔 대답해 줘요. 다음에 물을 때는요.", tag: "[whispers] ...이번엔 대답해 줘요. [whispers] 다음에 물을 때는요." },
  { id: "y6-f946c180cf", who: "yeonseo", text: "…어제 물어봤죠? 무슨 말을 하냐고.", tag: "[whispers] [sad] ...어제 물어봤죠? [whispers] 무슨 말을 하냐고." },
  { id: "y6-c8002ceede", who: "yeonseo", text: "이게 그 대답이에요.", tag: "[whispers] 이게 그 대답이에요." },
  { id: "y6-ad2c31b8dc", who: "yeonseo", text: "…믿는다고, 했죠.", tag: "[whispers] [sad] ...믿는다고, 했죠." },
  { id: "y6-5e9cdc0a2b", who: "yeonseo", text: "나았어요. 이모 죽이랑, 셔플 소리 덕분. 비율은 비밀이에요.", tag: "[deadpan] 나았어요. 이모 죽이랑, 셔플 소리 덕분. 비율은 비밀이에요." },
  { id: "y6-42c331403a", who: "yeonseo", text: "…보지 마요. 하우스 플레이어가 고양이 밥 주는 거, 무서워 보이지 않잖아요.", tag: "[flustered] ...보지 마요. 하우스 플레이어가 고양이 밥 주는 거, 무서워 보이지 않잖아요." },
  { id: "y6-c7e860f929", who: "yeonseo", text: "이 가게에선요.", tag: "[deadpan] 이 가게에선요." },
  { id: "y6-887491e4fa", who: "yeonseo", text: "이름은 없어요. 이름 붙이면 정 드니까.", tag: "[deadpan] 이름은 없어요. 이름 붙이면, 정 드니까." },
  { id: "y6-47935115e4", who: "yeonseo", text: "얘가 딜러님을 기억하나 봐요. 도망을 안 가요.", tag: "[deadpan] 얘가 딜러님을 기억하나 봐요. 도망을 안 가요." },
  { id: "y6-757986cdaf", who: "yeonseo", text: "얘가 딜러님 냄새를 알아요. 월요일 밤에 밥 준 사람이라고.", tag: "[deadpan] 얘가 딜러님 냄새를 알아요. 월요일 밤에 밥 준 사람이라고." },
  { id: "y6-048a6a1d7b", who: "yeonseo", text: "…아직 이름은 없어요. 붙일까 말까, 일주일째 계산 중이에요.", tag: "[deadpan] ...아직 이름은 없어요. 붙일까 말까, 일주일째 계산 중이에요." },
  { id: "y6-5539093c63", who: "yeonseo", text: "콜, 이리 와. …봐요, 부르면 와요.", tag: "[high] [sweet voice] [calling a kitten] 콜, 이리 와. [softly] ...봐요, 부르면 와요." },
  { id: "y6-633178ec44", who: "yeonseo", text: "딜러님 쪽으로 먼저 가네요. 배신이에요.", tag: "[dry] 딜러님 쪽으로 먼저 가네요. 배신이에요." },
  { id: "y6-68f0e184aa", who: "yeonseo", text: "…정 들면 곤란해져요. 이 동네엔 오래 있는 게 별로 없어서.", tag: "[deadpan] ...정 들면 곤란해져요. 이 동네엔, 오래 있는 게 별로 없어서." },
  { id: "y6-020c7e1211", who: "yeonseo", text: "'콜'. 부르면 오니까.", tag: "[softly] '콜'. 부르면 오니까." },
  { id: "y6-373a8df407", who: "yeonseo", text: "제가 아는 단어가 그쪽에 몰려 있어요. …딜러님이 이름 붙이자고 했으니까, 정 드는 건 딜러님 책임이에요.", tag: "[deadpan] 제가 아는 단어가, 그쪽에 몰려 있어요. ...딜러님이 이름 붙이자고 했으니까, 정 드는 건 딜러님 책임이에요." },
  { id: "y6-df5e65abf4", who: "yeonseo", text: "…기다려 준다는 말, 오랜만에 들어요.", tag: "[surprised] ...기다려 준다는 말, 오랜만에 들어요." },
  { id: "y6-a6b25c9c7e", who: "yeonseo", text: "그럼 다음 주까지 정할게요. 기한이 있어야 계산이 끝나요.", tag: "[deadpan] 그럼 다음 주까지 정할게요. 기한이 있어야 계산이 끝나요." },
  { id: "y6-02bca12ec7", who: "yeonseo", text: "…안아 봐요. 얘, 저 말고는 사람 신발에 안 올라가요.", tag: "[surprised] ...안아 봐요. 얘, 저 말고는 사람 신발에 안 올라가요." },
  { id: "y6-f81ac8674a", who: "yeonseo", text: "…딜러님 팔이 따뜻한가 봐요. 눈 감았어요.", tag: "[soft] [tender] ...딜러님 팔이 따뜻한가 봐요. 눈 감았어요." },
  { id: "y6-f0e4213935", who: "yeonseo", text: "…고양이 보느라 계산을 놓쳤어요. 무효예요.", tag: "[flustered] ...고양이 보느라 계산을 놓쳤어요. 무효예요." },
  { id: "y6-06fc5981aa", who: "yeonseo", text: "돌의 각도가 20도일 때 제일 많이 튄대요. 논문에서 봤어요.", tag: "[deadpan] 돌의 각도가 이십 도일 때 제일 많이 튄대요. 논문에서 봤어요." },
  { id: "y6-77ca35544c", who: "yeonseo", text: "……논문이 틀렸어요.", tag: "[flat] ......논문이 틀렸어요." },
  { id: "y6-2eb1084625", who: "yeonseo", text: "논문 탓이에요.", tag: "[flat] 논문 탓이에요." },
  { id: "y6-ebdc9b6b45", who: "yeonseo", text: "한 번만 가르쳐 줘요. 지는 채로 끝나는 건 싫어요.", tag: "[deadpan] 한 번만 가르쳐 줘요. 지는 채로 끝나는 건 싫어요." },
  { id: "y6-7ffd44465e", who: "yeonseo", text: "…손목은 비싸요. 함부로 만지면 요금 받아요.", tag: "[flustered] ...손목은 비싸요. 함부로 만지면 요금 받아요." },
  { id: "y6-f2b1e23858", who: "yeonseo", text: "…계산 중이에요. 지금 던질게요.", tag: "[softly] [flustered] ...계산 중이에요. 지금 던질게요." },
  { id: "y6-e04ad985c7", who: "yeonseo", text: "검지로 돌려요. 손목은 수평으로요.", tag: "[focused] 검지로 돌려요. 손목은 수평으로요." },
  { id: "y6-dc3f5550f7", who: "yeonseo", text: "…네 번.", tag: "[surprised] ...네 번." },
  { id: "y7-233a36969cb", who: "yeonseo", text: "확률보다 나아요. 딜러님 다섯 번보다는 못하지만.", tag: "[dry] 확률보다 나아요. 딜러님 다섯 번보다는 못하지만." },
  { id: "y6-ccec604ccc", who: "yeonseo", text: "다음이 있으면요. …있죠?", tag: "[deadpan] 다음이 있으면요. ...있죠?" },
  { id: "y6-99df968d35", who: "yeonseo", text: "방금 건 확률 질문이에요. 다른 뜻 없어요.", tag: "[flustered] 방금 건 확률 질문이에요. 다른 뜻 없어요." },
  { id: "y6-a35d7da7a4", who: "yeonseo", text: "게임 하나 해요. 제가 네 가지를 말할 테니까, 진짜는 하나. 맞히면 딜러님이 이겨요.", tag: "[deadpan] 게임 하나 해요. 제가 네 가지를 말할 테니까, 진짜는 하나. 맞히면 딜러님이 이겨요." },
  { id: "y6-ac09484124", who: "yeonseo", text: "첫째. 저는 김치찌개를 싫어해요.", tag: "[deadpan] 첫째. 저는 김치찌개를 싫어해요." },
  { id: "y6-628ff9813b", who: "yeonseo", text: "둘째. 7년 동안 한 번도 안 울었어요.", tag: "[deadpan] 둘째. 칠 년 동안, 한 번도 안 울었어요." },
  { id: "y6-af01f917bb", who: "yeonseo", text: "셋째. 목요일에 딜러님 이름 부르기 전에, 화장실에서 열 번 연습했어요.", tag: "[deadpan] 셋째. 목요일에 딜러님 이름 부르기 전에, 화장실에서 열 번 연습했어요." },
  { id: "y6-f7db9ae1e3", who: "yeonseo", text: "넷째. 저는 확률을 믿어요.", tag: "[deadpan] 넷째. 저는 확률을 믿어요." },
  { id: "y6-7a71124b0a", who: "yeonseo", text: "…정답이에요. 그건 거짓말 칸에 넣으려던 건데. 표정 관리가 안 됐나 봐요.", tag: "[flustered] ...정답이에요. 그건 거짓말 칸에 넣으려던 건데. 표정 관리가 안 됐나 봐요." },
  { id: "y6-d34e474828", who: "yeonseo", text: "열한 번이에요. 열 번이라고 한 게 거짓말이었어요.", tag: "[softly] [flustered] 열한 번이에요. 열 번이라고 한 게, 거짓말이었어요." },
  { id: "y6-93f6724c8d", who: "yeonseo", text: "…틀렸어요. 운 적 있어요. 작년 겨울에 한 번. 아무도 없을 때.", tag: "[deadpan] ...틀렸어요. 운 적 있어요. 작년 겨울에 한 번. 아무도 없을 때." },
  { id: "y6-36d9a6ac18", who: "yeonseo", text: "그걸 진짜라고 생각해 줘서, 조금 놀랐어요. 딜러님 눈엔 제가 그렇게 보이나 싶어서.", tag: "[deadpan] 그걸 진짜라고 생각해 줘서, 조금 놀랐어요. 딜러님 눈엔, 제가 그렇게 보이나 싶어서." },
  { id: "y6-14be11f0d7", who: "yeonseo", text: "정답은 안 알려 줄 거예요. 진 사람 특권이에요.", tag: "[dry] [amused] 정답은 안 알려 줄 거예요. 진 사람 특권이에요." },
  { id: "y6-f0e690af0b", who: "yeonseo", text: "틀렸어요. 요즘은 확률을 잘 안 믿어요.", tag: "[deadpan] 틀렸어요. 요즘은 확률을 잘 안 믿어요." },
  { id: "y6-c51915efff", who: "yeonseo", text: "확률대로면 지금쯤 딜러님은 저를 귀찮아해야 하거든요.", tag: "[deadpan] 확률대로면, 지금쯤 딜러님은 저를 귀찮아해야 하거든요." },
  { id: "y6-bfe7d13917", who: "yeonseo", text: "다음엔 딜러님 차례예요. 네 가지 준비해 와요. 하나만 진짜로.", tag: "[deadpan] 다음엔 딜러님 차례예요. 네 가지 준비해 와요. 하나만 진짜로." },
  { id: "y6-7afef90920", who: "yeonseo", text: "…진짜 하나는, 제 얘기였으면 좋겠어요.", tag: "[softly] [flustered] ...진짜 하나는, 제 얘기였으면 좋겠어요." },
  { id: "y6-540814e537", who: "yeonseo", text: "오픈까지 아직 한 시간 있어요. 한 판만 해요. 칩 말고 이걸로.", tag: "[deadpan] 오픈까지 아직 한 시간 있어요. 한 판만 해요. 칩 말고, 이걸로." },
  { id: "y6-7b7d1c6339", who: "yeonseo", text: "끝나면 전부 통에 돌려놔야 해요. 이모가 세거든요.", tag: "[deadpan] 끝나면 전부 통에 돌려놔야 해요. 이모가 세거든요." },
  { id: "y6-827056be8f", who: "yeonseo", text: "…졌어요.", tag: "[surprised] ...졌어요." },
  { id: "y6-9e1fe87a69", who: "yeonseo", text: "딜러님 손은 앉아 있어도 안 읽혀요. 서 있을 때보다 더요.", tag: "[deadpan] 딜러님 손은, 앉아 있어도 안 읽혀요. 서 있을 때보다 더요." },
  { id: "y6-0f79f29c75", who: "yeonseo", text: "제가 이겼어요. 계산대로예요.", tag: "[dry] [amused] 제가 이겼어요. 계산대로예요." },
  { id: "y6-812a307b6c", who: "yeonseo", text: "…근데 이겼는데 하나도 안 무서워요. 손도 안 떨리고.", tag: "[softly] [flustered] ...근데, 이겼는데 하나도 안 무서워요. 손도 안 떨리고." },
  { id: "y6-6b99e451e7", who: "yeonseo", text: "비겼어요. 둘 다 안 잃은 판. …이런 판도 있네요.", tag: "[deadpan] 비겼어요. 둘 다 안 잃은 판. ...이런 판도 있네요." },
  { id: "y6-c6a27cd40f", who: "yeonseo", text: "그날 빗속으로 뛰어갔죠. 우산은 하나 남았고요.", tag: "[deadpan] 그날 빗속으로 뛰어갔죠. 우산은 하나 남았고요." },
  { id: "y6-0e18053577", who: "yeonseo", text: "돌려받을 사람이 없는 우산은, 생각보다 무거웠어요.", tag: "[sad] 돌려받을 사람이 없는 우산은, 생각보다 무거웠어요." },
  { id: "y6-535fe1826a", who: "yeonseo", text: "골목에서 넓다고 했던 우산이요. 며칠 혼자 쓰니까, 무거워지더라고요.", tag: "[deadpan] 골목에서 넓다고 했던 우산이요. 며칠 혼자 쓰니까, 무거워지더라고요." },
  { id: "y6-a9e7102f27", who: "yeonseo", text: "네. 많이.", tag: "[cold] 네. 많이." },
  { id: "y6-8b96b71cc2", who: "yeonseo", text: "…그래도 앉아요. 비 오니까요.", tag: "[deadpan] ...그래도 앉아요. 비 오니까요." },
  { id: "y6-4fdba76efd", who: "yeonseo", text: "오늘 이길 확률, 계산 안 했어요. 7년 동안 하루도 안 빠뜨렸는데. 그래서 여기 있었나 봐요.", tag: "[deadpan] 오늘 이길 확률, 계산 안 했어요. 칠 년 동안 하루도 안 빠뜨렸는데. 그래서 여기 있었나 봐요." },
  { id: "y6-b4e08d6089", who: "yeonseo", text: "…들어와요. 문 앞에 서 있으면 이웃이 이상하게 봐요.", tag: "[deadpan] ...들어와요. 문 앞에 서 있으면, 이웃이 이상하게 봐요." },
  { id: "y6-4d030682ea", who: "yeonseo", text: "하루 끝날 때마다 X 쳐요. 오늘도 빚을 못 줄였다는 표시예요. 7년 치.", tag: "[deadpan] 하루 끝날 때마다 엑스 쳐요. 오늘도 빚을 못 줄였다는 표시예요. 칠 년 치." },
  { id: "y6-642da6af87", who: "yeonseo", text: "맨 위 숫자는 이름 없는 회사 거예요. 사장님이 소개해 준.", tag: "[deadpan] 맨 위 숫자는, 이름 없는 회사 거예요. 사장님이 소개해 준." },
  { id: "y6-e880b7be9e", who: "yeonseo", text: "그럼 우리, 같은 주머니에 이자를 넣고 있었네요.", tag: "[sad] 그럼 우리, 같은 주머니에 이자를 넣고 있었네요." },
  { id: "y6-d929f6c344", who: "yeonseo", text: "다음부턴 이모 통하지 말고 제가 직접 부를게요.", tag: "[deadpan] 다음부턴 이모 통하지 말고, 제가 직접 부를게요." },
  { id: "y6-3c4aa90b84", who: "yeonseo", text: "어제 일은… 동그라미 같은 날이었어요. 그런 표시가 있으면요.", tag: "[hesitant] 어제 일은... 동그라미 같은 날이었어요. 그런 표시가 있으면요." },
  { id: "y6-fdcc0ab62b", who: "yeonseo", text: "볼펜이 검은색밖에 없어요. X처럼 보이면 어떡해요.", tag: "[surprised] 볼펜이 검은색밖에 없어요. 엑스처럼 보이면 어떡해요." },
  { id: "y6-11968e0e34", who: "yeonseo", text: "…첫 번째예요.", tag: "[warm] ...첫 번째예요." },
  { id: "y6-0ae5fd3be8", who: "yeonseo", text: "카드 좀 섞어 줘요. 그 소리 들으면 잠이 오거든요. 밤엔 출근할 거예요. 해열제 먹었어요.", tag: "[deadpan] 카드 좀 섞어 줘요. 그 소리 들으면 잠이 오거든요. 밤엔 출근할 거예요. 해열제 먹었어요." },
  { id: "y6-36a12f2a25", who: "yeonseo", text: "딜러님 셔플은 제 승률을 떨어뜨려요. 이유는… 계산 중…", tag: "[whispers] [sleepy] 딜러님 셔플은, 제 승률을 떨어뜨려요. [whispers] [sleepy] 이유는... 계산 중..." },
  { id: "y6-34287e5919", who: "yeonseo", text: "…딜러님. 여긴 왜요?", tag: "[surprised] ...딜러님. 여긴 왜요?" },
  { id: "y6-c6e4aad98c", who: "yeonseo", text: "…얘 밥 주러 왔어요. 딜러님도요?", tag: "[deadpan] ...얘 밥 주러 왔어요. 딜러님도요?" },
  { id: "y6-4486fd418a", who: "yeonseo", text: "그날 우산, 결국 혼자 썼어요. 혼자 쓰니까 넓더라고요.", tag: "[deadpan] 그날 우산, 결국 혼자 썼어요. 혼자 쓰니까, 넓더라고요." },
  { id: "y6-b314d90afa", who: "yeonseo", text: "딜러님은 젖었겠네요. 다 뛰어갔으니까.", tag: "[dry] 딜러님은 젖었겠네요. 다 뛰어갔으니까." },
  { id: "y6-e7e1053060", who: "yeonseo", text: "…감기 조심해요. 그 손으로 카드 돌리는 사람, 이 가게에 하나뿐이니까.", tag: "[deadpan] ...감기 조심해요. 그 손으로 카드 돌리는 사람, 이 가게에 하나뿐이니까." },
  { id: "y6-c2bbea5eac", who: "yeonseo", text: "토요일 자정. 에이미 씨 아버님 자리, 예약됐어요.", tag: "[deadpan] 토요일 자정. 에이미 씨 아버님 자리, 예약됐어요." },
  { id: "y6-b521cffd6e", who: "yeonseo", text: "맞은편은 저예요.", tag: "[cold] 맞은편은 저예요." },
  { id: "y6-35e33548c5", who: "yeonseo", text: "또요. 이번엔 반대예요. 에이미 씨가 이기는 날.", tag: "[sad] 또요. 이번엔 반대예요. 에이미 씨가 이기는 날." },
  { id: "y6-33b91f1d7e", who: "yeonseo", text: "이기는 날 다음에 뭐가 오는지는, 딜러님이 저보다 잘 알 텐데요.", tag: "[cold] 이기는 날 다음에 뭐가 오는지는, 딜러님이 저보다 잘 알 텐데요." },
  { id: "y6-8a57c07858", who: "yeonseo", text: "…제가 말했다고는 하지 마요. 그 판에 앉을 사람이 할 말은 아니라서요.", tag: "[deadpan] ...제가 말했다고는 하지 마요. 그 판에 앉을 사람이 할 말은 아니라서요." },
  { id: "y6-6b7bf6713d", who: "yeonseo", text: "보자고 해서 왔어요. 3분이에요.", tag: "[deadpan] 보자고 해서 왔어요. 삼 분이에요." },
  { id: "y6-71d402b20c", who: "yeonseo", text: "…그건 인사였어요. 대답을 바란 질문이 아니라.", tag: "[deadpan] ...그건 인사였어요. 대답을 바란 질문이 아니라." },
  { id: "y6-aa53faf04e", who: "yeonseo", text: "토요일엔 제 쪽 보지 마요. 딜러님 얼굴은 너무 잘 읽히거든요. 사장님도 읽고.", tag: "[serious] 토요일엔 제 쪽 보지 마요. 딜러님 얼굴은 너무 잘 읽히거든요. 사장님도 읽고." },
  { id: "y6-f000458ec6", who: "yeonseo", text: "저는 읽고 모른 척하고, 사장님은 읽고 계산하죠. 그 차이예요.", tag: "[cold] 저는 읽고 모른 척하고, 사장님은 읽고 계산하죠. 그 차이예요." },
  { id: "y6-d0c71f1ba8", who: "yeonseo", text: "…3분 됐어요. 들어가요.", tag: "[deadpan] ...삼 분 됐어요. 들어가요." },
  { id: "y6-017e4a97c5", who: "yeonseo", text: "…오늘은 여기 오면 안 되는 날인데요.", tag: "[deadpan] ...오늘은, 여기 오면 안 되는 날인데요." },
  { id: "y6-34e64907a8", who: "yeonseo", text: "또 그 질문이네요. 오늘은 대답할게요. 안 괜찮아요.", tag: "[deadpan] 또 그 질문이네요. 오늘은 대답할게요. 안 괜찮아요." },
  { id: "y6-ed93577014", who: "yeonseo", text: "오늘 밤 저는 지는 연기를 해요. 잘해요, 그거. 7년 했으니까.", tag: "[deadpan] 오늘 밤 저는, 지는 연기를 해요. 잘해요, 그거. 칠 년 했으니까." },
  { id: "y6-be8b247e45", who: "yeonseo", text: "그 애가 웃으면 같이 웃어 주지 마요. 딜러님 얼굴은 사장님이 제일 잘 읽어요.", tag: "[cold] 그 애가 웃으면, 같이 웃어 주지 마요. 딜러님 얼굴은 사장님이 제일 잘 읽어요." },
  { id: "y6-b99d1b72a5", who: "yeonseo", text: "…3분 됐어요. 오늘 밤엔 제 쪽 보지 마요. 끝까지.", tag: "[deadpan] ...삼 분 됐어요. 오늘 밤엔 제 쪽 보지 마요. 끝까지." },
  { id: "y6-d6852f856a", who: "yeonseo", text: "잘 부탁해요.", tag: "[cold] 잘 부탁해요." },
  { id: "y6-1526ef6712", who: "yeonseo", text: "자리는 칩을 안 쌓아 줘요. 손이 쌓죠.", tag: "[deadpan] 자리는 칩을 안 쌓아 줘요. 손이 쌓죠." },
  { id: "y6-25a8deddb2", who: "yeonseo", text: "오늘은 패가 안 오네요.", tag: "[flat] 오늘은, 패가 안 오네요." },
  { id: "y6-f798b4386a", who: "yeonseo", text: "내일, 에이미 씨를 만날 거예요. 딜러님도 같이 있어 줘요.", tag: "[deadpan] 내일, 에이미 씨를 만날 거예요. 딜러님도 같이 있어 줘요." },
  { id: "y6-f642bbd3fa", who: "yeonseo", text: "5년 동안 못 한 말이요. 혼자 하면 중간에 도망칠 것 같아서요.", tag: "[sad] 오 년 동안 못 한 말이요. 혼자 하면, 중간에 도망칠 것 같아서요." },
  { id: "y6-1b6b0e62ae", who: "yeonseo", text: "딜러님이 있으면 도망칠 확률이 반으로 줄어요. 제 계산으로는.", tag: "[quietly] 딜러님이 있으면, 도망칠 확률이 반으로 줄어요. [flat] [falling tone] 제 계산으로는." },
  { id: "y6-a228683dd8", who: "yeonseo", text: "펍에서는 못 하는 말이에요.", tag: "[deadpan] 펍에서는 못 하는 말이에요." },
  { id: "y6-cb6a8550c6", who: "yeonseo", text: "5년 전. 아래층 구석 테이블. 금발 손님 맞은편.", tag: "[serious] 오 년 전. 아래층 구석 테이블, 금발 손님 맞은편." },
  { id: "y6-dc50a4b4df", who: "yeonseo", text: "그분, 매 판 딸 얘기를 했어요. 트윈테일 묶은 꼬맹이. 이기면 데리러 간다고.", tag: "[sad] 그분, 매 판 딸 얘기를 했어요. 트윈테일 묶은 꼬맹이. 이기면 데리러 간다고." },
  { id: "y6-24f097f324", who: "yeonseo", text: "저는 사장님이 정해 준 숫자를 채웠어요. 하나도 안 틀리고.", tag: "[sad] 저는, 사장님이 정해 준 숫자를 채웠어요. 하나도 안 틀리고." },
  { id: "y6-89d27d1b40", who: "yeonseo", text: "미워해도 돼요. 미워해야 맞아요.", tag: "[cold] 미워해도 돼요. 미워해야 맞아요." },
  { id: "y6-e94563cca4", who: "yeonseo", text: "네.", tag: "[flat] 네." },
  { id: "y6-9848681aa2", who: "yeonseo", text: "…가요. 저 말고, 그 애한테.", tag: "[sad] ...가요. 저 말고, 그 애한테." },
  { id: "y6-d80e5309cd", who: "yeonseo", text: "…왜 이쪽으로 왔어요?", tag: "[surprised] ...왜, 이쪽으로 왔어요?" },
  { id: "y6-94c710a55a", who: "yeonseo", text: "저는 괜찮아요. 7년 동안 이런 밤 많았어요.", tag: "[deadpan] 저는 괜찮아요. 칠 년 동안, 이런 밤 많았어요." },
  { id: "y6-9734d93487", who: "yeonseo", text: "그 애는 아니에요. 아빠를 두 번 잃은 밤이에요, 오늘이.", tag: "[sad] 그 애는 아니에요. 아빠를 두 번 잃은 밤이에요, 오늘이." },
  { id: "y6-277f240f6b", who: "yeonseo", text: "가요. 지금 그 애한테 필요한 건 딜러님이에요. 확률로 말하면, 거의 전부.", tag: "[firm] 가요. 지금 그 애한테 필요한 건 딜러님이에요. 확률로 말하면, 거의 전부." },
  { id: "y6-3898dca991", who: "yeonseo", text: "무슨 일 있었죠? 얼굴에 다 써 있어요.", tag: "[surprised] 무슨 일 있었죠? 얼굴에 다 써 있어요." },
  { id: "y6-ab930e1eaa", who: "yeonseo", text: "저였다고… 적혀 있었겠네요.", tag: "[sad] 저였다고... 적혀 있었겠네요." },
  { id: "y6-f02525d2cd", who: "yeonseo", text: "그 말은 제가 들을 말이 아니에요. 그 애가 들을 말이죠.", tag: "[sad] 그 말은, 제가 들을 말이 아니에요. 그 애가 들을 말이죠." },
  { id: "y6-7dad59d36a", who: "yeonseo", text: "가요. 오늘 그 애한테 필요한 건 제가 아니라 딜러님이에요.", tag: "[firm] 가요. 오늘 그 애한테 필요한 건, 제가 아니라 딜러님이에요." },
  { id: "y6-07343d81ed", who: "yeonseo", text: "대신 하나만 들어 줘요. 일요일 판, 덱부터 사장님 거예요. 리버까지.", tag: "[serious] 대신 하나만 들어 줘요. 일요일 판, 덱부터 사장님 거예요. 리버까지." },
  { id: "y6-bc8e146151", who: "yeonseo", text: "그리고 사장님이 진짜 원하는 건 에이미 씨가 아니에요.", tag: "[cold] 그리고 사장님이 진짜 원하는 건, 에이미 씨가 아니에요." },
  { id: "y6-cfc7e0015c", who: "yeonseo", text: "딜러님이 그 의자에 앉는 거예요. 3년 동안, 그거 하나 기다렸어요.", tag: "[serious] 딜러님이 그 의자에 앉는 거예요. 삼 년 동안, 그거 하나 기다렸어요." },
  { id: "y6-b725690d6b", who: "yeonseo", text: "……'내 딸은 나보다 잘 칠 거예요. 근데 안 쳤으면 좋겠어요.'", tag: "[softly] [sad] ......'내 딸은 나보다 잘 칠 거예요. 근데, 안 쳤으면 좋겠어요.'" },
  { id: "y6-a18bfa75ba", who: "yeonseo", text: "저한테도 존댓말을 쓰셨어요. 마지막 판 내기 전에 웃으면서요.", tag: "[sad] 저한테도 존댓말을 쓰셨어요. 마지막 판 내기 전에, 웃으면서요." },
  { id: "y6-3b4f06d29d", who: "yeonseo", text: "…왔네요.", tag: "[quietly] [settled] 왔네요." },
  { id: "y6-f7ff692293", who: "yeonseo", text: "쪽지, 읽었어요?", tag: "[deadpan] 쪽지, 읽었어요?" },
  { id: "y6-c290511dcc", who: "yeonseo", text: "세 번 고쳐 썼어요. 그걸 세는 사람이 있을 줄은 몰랐어요.", tag: "[flustered] 세 번 고쳐 썼어요. 그걸 세는 사람이 있을 줄은 몰랐어요." },
  { id: "y6-448a577d53", who: "yeonseo", text: "오늘은 딜러님이 했네요. 일 뺏겼어요.", tag: "[dry] 오늘은 딜러님이 했네요. 일 뺏겼어요." },
  { id: "y6-c134f7558e", who: "yeonseo", text: "쪽지엔 다 못 쓴 거, 말로 할게요. 한 번만.", tag: "[serious] 쪽지엔 다 못 쓴 거, 말로 할게요. 한 번만." },
  { id: "y6-3e05d7f305", who: "yeonseo", text: "…왔네요. 안 와도 된다고 했는데.", tag: "[deadpan] ...왔네요. 안 와도 된다고 했는데." },
  { id: "y6-0ee3c495d8", who: "yeonseo", text: "그 해석은 반칙이에요.", tag: "[dry] 그 해석은, 반칙이에요." },
  { id: "y6-2d3bf922dc", who: "yeonseo", text: "…부르지도 않았는데 왔네요.", tag: "[surprised] ...부르지도 않았는데, 왔네요." },
  { id: "y6-468acb6a76", who: "yeonseo", text: "손이 심심해서요. 저는 매일 이 시간에 여기 있어요. 딜러님은 몰랐을 텐데.", tag: "[deadpan] 손이 심심해서요. 저는 매일 이 시간에 여기 있어요. 딜러님은 몰랐을 텐데." },
  { id: "y6-be4d6cd6d9", who: "yeonseo", text: "…발이 저보다 계산을 잘하네요.", tag: "[softly] ...발이, 저보다 계산을 잘하네요." },
  { id: "y6-c1c5eb0126", who: "yeonseo", text: "화났죠. 설명할게요. 한 번만.", tag: "[deadpan] 화났죠. 설명할게요. 한 번만." },
  { id: "y6-901f765b1e", who: "yeonseo", text: "사장님은 이미 알고 있었어요. 딜러님이 '손'이라는 거.", tag: "[serious] 사장님은 이미 알고 있었어요. 딜러님이 '손'이라는 거." },
  { id: "y6-3f5a1dd41c", who: "yeonseo", text: "아니라고 계속 버티면, 저를 빼고 다른 사람을 붙여요.", tag: "[cold] 아니라고 계속 버티면, 저를 빼고 다른 사람을 붙여요." },
  { id: "y6-e9ad9da7ea", who: "yeonseo", text: "그 사람은 딜러님을 앉힐 거예요. 저는 그게 싫어서 맞다고 했어요.", tag: "[deadpan] 그 사람은 딜러님을 앉힐 거예요. 저는 그게 싫어서, 맞다고 했어요." },
  { id: "y6-f97a247760", who: "yeonseo", text: "확률로 말하면, 반반이에요.", tag: "[deadpan] 확률로 말하면, 반반이에요." },
  { id: "y6-e2668958af", who: "yeonseo", text: "제가 믿을 만한 사람일 확률이요. 7년 치 기록이 별로 안 좋아서.", tag: "[sad] 제가 믿을 만한 사람일 확률이요. 칠 년 치 기록이, 별로 안 좋아서." },
  { id: "y6-3f67321714", who: "yeonseo", text: "나머지 반은… 딜러님이 정해 줘요.", tag: "[deadpan] 나머지 반은... 딜러님이 정해 줘요." },
  { id: "y6-f8d69ebe55", who: "yeonseo", text: "……그대로예요?", tag: "[surprised] ......그대로예요?" },
  { id: "y6-bdeaf4702bb", who: "yeonseo", text: "그 근거는 통계적으로 약해요. …그래도 받을게요.", tag: "[composed] [slightly embarrassed] 그 근거는 통계적으로 약해요. ...그래도 받을게요." },
  { id: "y6-1e5095496d", who: "yeonseo", text: "놀란 얼굴이 화난 얼굴보다 오래가요. 제 통계로는.", tag: "[deadpan] 놀란 얼굴이, 화난 얼굴보다 오래가요. [flat] [falling tone] 제 통계로는." },
  { id: "y6-6b6d24193f", who: "yeonseo", text: "…아까보단 덜 놀란 얼굴이요. 십 퍼센트쯤.", tag: "[softly] 아까보단 덜 놀란 얼굴이요. [a small smile] [falling tone] 십 퍼센트쯤." },
  { id: "y6-021dbee42b", who: "yeonseo", text: "그리고 오늘 밤. 사장님이 딜러님한테 제안을 할 거예요.", tag: "[serious] 그리고 오늘 밤. 사장님이 딜러님한테 제안을 할 거예요." },
  { id: "y6-f33f0af92b", who: "yeonseo", text: "아래층 딜러 자리요. 시급 다섯 배. 빚도 깎아 준다고 할 거예요.", tag: "[serious] 아래층 딜러 자리요. 시급 다섯 배. 빚도 깎아 준다고 할 거예요." },
  { id: "y6-6dfacceb61", who: "yeonseo", text: "네. 딜러님 규칙에 딱 맞는 자리예요. 그래서 더 나빠요.", tag: "[cold] 네. 딜러님 규칙에 딱 맞는 자리예요. 그래서 더 나빠요." },
  { id: "y6-4def8d199b", who: "yeonseo", text: "깨끗한 손이 제일 더러운 일을 잘한대요. 사장님 말이에요.", tag: "[sad] 깨끗한 손이, 제일 더러운 일을 잘한대요. 사장님 말이에요." },
  { id: "y6-f01ca1e27e", who: "yeonseo", text: "받지 마요. 부탁하는 거 아니에요. 그냥… 받지 마요.", tag: "[deadpan] 받지 마요. 부탁하는 거 아니에요. 그냥... 받지 마요." },
  { id: "y6-042bf67254", who: "yeonseo", text: "…그 말, 기록해 둘게요. 사장님 앞에서 바뀌면 안 돼요.", tag: "[deadpan] ...그 말, 기록해 둘게요. 사장님 앞에서 바뀌면 안 돼요." },
  { id: "y6-80fdc40869", who: "yeonseo", text: "제 장부에 한 줄 생겨요. '거짓말 1회.' 딜러님 이름으로 쓰는 첫 줄이에요.", tag: "[dry] 제 장부에 한 줄 생겨요. '거짓말 일 회.' 딜러님 이름으로 쓰는 첫 줄이에요." },
  { id: "y6-266065a868", who: "yeonseo", text: "…아니에요.", tag: "[flustered] ...아니에요." },
  { id: "y6-0f729157d5", who: "yeonseo", text: "…맞아요. 부탁이에요. 말하는 내내 장갑 안에 땀이 찼거든요.", tag: "[softly] [flustered] ...맞아요. 부탁이에요. 말하는 내내, 장갑 안에 땀이 찼거든요." },
  { id: "y6-44a2a74701", who: "yeonseo", text: "번호 줘요. 이미 알고 있어도 줘요.", tag: "[deadpan] 번호 줘요. 이미 알고 있어도 줘요." },
  { id: "y6-c44db8a7f2", who: "yeonseo", text: "몰래 아는 거랑 받은 거는, 장부가 달라요.", tag: "[deadpan] 몰래 아는 거랑 받은 거는, 장부가 달라요." },
  { id: "y6-dccba2beae", who: "yeonseo", text: "기밀이에요.", tag: "[flat] 기밀이에요." },
  { id: "y6-b317d81750", who: "yeonseo", text: "밤에 봐요. 저는 딜러님 안 볼 거예요. 연습도 했고.", tag: "[deadpan] 밤에 봐요. 저는 딜러님 안 볼 거예요. 연습도 했고." },
  { id: "y6-e74d3aa73d", who: "yeonseo", text: "…카메라 점검이래요. 그래서 아래층이 쉬어요.", tag: "[whispers] ...카메라 점검이래요. [whispers] 그래서 아래층이 쉬어요." },
  { id: "y6-a4833e1bc7", who: "yeonseo", text: "지금이면 아무도 안 봐요. 내일이면 다시 보고요.", tag: "[whispers] 지금이면 아무도 안 봐요. [whispers] 내일이면, 다시 보고요." },
  { id: "y6-4a9e54277d", who: "yeonseo", text: "보여 줄 수 있어요. 제가 매일 어디 앉는지. 3년 전에 딜러님이 어디 앉았는지.", tag: "[whispers] [sad] 보여 줄 수 있어요. [whispers] 제가 매일 어디 앉는지. [whispers] 삼 년 전에, 딜러님이 어디 앉았는지." },
  { id: "y6-f704e94588", who: "yeonseo", text: "…다음 달부터 딜러님이 서게 될 자리도요.", tag: "[whispers] [cold] ...다음 달부터, 딜러님이 서게 될 자리도요." },
  { id: "y6-3992cfe20b", who: "yeonseo", text: "번호, 어떻게 알아요?", tag: "[surprised] 번호, 어떻게 알아요?" },
  { id: "y6-55446a8f5b", who: "yeonseo", text: "3년 동안 안 바뀌었어요. 사장님은 아무것도 안 바꿔요.", tag: "[cold] 삼 년 동안 안 바뀌었어요. 사장님은, 아무것도 안 바꿔요." },
  { id: "y6-7ef150295d", who: "yeonseo", text: "여기가 V-1이에요. 딜러님이 앉았던 자리는 저기예요. 사장님 맞은편.", tag: "[deadpan] 여기가 브이 원이에요. 딜러님이 앉았던 자리는 저기예요. 사장님 맞은편." },
  { id: "y6-9b947e294c", who: "yeonseo", text: "다들 그렇게 말해요. 편한 의자는 일어나기 어렵게 만든 거예요.", tag: "[cold] 다들 그렇게 말해요. 편한 의자는, 일어나기 어렵게 만든 거예요." },
  { id: "y6-495bab1f1b", who: "yeonseo", text: "저건 사장님이 아무도 안 앉히는 자리예요. 이유는… 아직 말 못 해요.", tag: "[deadpan] 저건, 사장님이 아무도 안 앉히는 자리예요. 이유는... 아직 말 못 해요." },
  { id: "y6-ac6bcdca29", who: "yeonseo", text: "보여 줄게요. 어떻게 하는지.", tag: "[cold] 보여 줄게요. 어떻게 하는지." },
  { id: "y6-5b6a918f0c", who: "yeonseo", text: "컷하세요. 공정하게. 여기까지는 진짜예요.", tag: "[deadpan] 컷하세요. 공정하게. 여기까지는 진짜예요." },
  { id: "y6-7ad071b2b8", who: "yeonseo", text: "…바뀌었어요. 방금.", tag: "[deadpan] 바뀌었어요. [flat] [falling tone] 방금." },
  { id: "y6-e4371675f7", who: "yeonseo", text: "그게 정상이에요. 딜러님이 컷한 덱은 지금 제 무릎 위. 올라온 건 미리 맞춰 둔 덱이고요.", tag: "[deadpan] 그게 정상이에요. 딜러님이 컷한 덱은 지금 제 무릎 위. 올라온 건, 미리 맞춰 둔 덱이고요." },
  { id: "y6-efafcda43d", who: "yeonseo", text: "그리고 이거.", tag: "[deadpan] 그리고, 이거." },
  { id: "y6-7e970b5a75", who: "yeonseo", text: "사장님은 물잔 가장자리에 손가락을 올려요. 하나는 져 줘라. 둘은 비슷하게.", tag: "[deadpan] 사장님은 물잔 가장자리에 손가락을 올려요. 하나는 져 줘라. 둘은 비슷하게." },
  { id: "y6-caffc37f75", who: "yeonseo", text: "셋은… 전부 가져와라.", tag: "[quietly] [sad] 셋은... 전부 가져와라." },
  { id: "y6-167e8f92a8", who: "yeonseo", text: "값이 아니라, 손에 밴 신호예요. 7년 동안 저는 그 손가락만 봤어요.", tag: "[sad] 값이 아니라, 손에 밴 신호예요. 칠 년 동안, 저는 그 손가락만 봤어요." },
  { id: "y6-80b87c609f", who: "yeonseo", text: "그날 딜러는 지금도 있는 사람이에요. 위층엔 한 번도 안 올라와요.", tag: "[cold] 그날 딜러는, 지금도 있는 사람이에요. 위층엔 한 번도 안 올라와요." },
  { id: "y6-8711e4b83e", who: "yeonseo", text: "사장님 맞은편에 앉은 사람은 다 졌어요. 딜러님 손이 나빠서가 아니었어요.", tag: "[sad] 사장님 맞은편에 앉은 사람은, 다 졌어요. 딜러님 손이 나빠서가 아니었어요." },
  { id: "y6-976915afa3", who: "yeonseo", text: "그럼 오늘 3년 치 이자를 조금 돌려받은 거예요. 아주 조금이지만.", tag: "[deadpan] 그럼 오늘, 삼 년 치 이자를 조금 돌려받은 거예요. 아주 조금이지만." },
  { id: "y6-a15bcbe7e4", who: "yeonseo", text: "…한 번 보고 따라 해요?", tag: "[surprised] ...한 번 보고, 따라 해요?" },
  { id: "y6-95e0850ead", who: "yeonseo", text: "그래서 사장님이 그 손을 갖고 싶어 하는 거예요.", tag: "[sad] 그래서, 사장님이 그 손을 갖고 싶어 하는 거예요." },
  { id: "y6-49e29d7cdf", who: "yeonseo", text: "방금 건… 솔직히 좀 멋있었어요. 기록은 안 할게요.", tag: "[softly] [flustered] 방금 건... 솔직히, 좀 멋있었어요. 기록은 안 할게요." },
  { id: "y6-e2e739bd10", who: "yeonseo", text: "내일부터 저건 다시 켜져요. 문 열린 기록도 남고요.", tag: "[deadpan] 내일부터, 저건 다시 켜져요. 문 열린 기록도 남고요." },
  { id: "y6-2ec13ed397", who: "yeonseo", text: "제가 열었다고 할게요. 청소하러. 저 청소 잘해요. 이 방 바닥은 눈 감고도 닦아요.", tag: "[deadpan] 제가 열었다고 할게요. 청소하러. 저 청소 잘해요. 이 방 바닥은, 눈 감고도 닦아요." },
  { id: "y6-78e82465d7", who: "yeonseo", text: "잘했어요. 이 문은 한 번 열면, 그다음부터는 안에서 잠기는 문이에요.", tag: "[deadpan] 잘했어요. 이 문은 한 번 열면, 그다음부터는 안에서 잠기는 문이에요." },
  { id: "y6-174b10acb8", who: "yeonseo", text: "사실 조금 안심했어요. 딜러님이 그 방 보는 거, 싫었어요.", tag: "[whispers] [sad] 사실, 조금 안심했어요. [whispers] 딜러님이 그 방 보는 거, 싫었어요." },
  { id: "y6-7e3296de45", who: "yeonseo", text: "제가 매일 앉는 데니까요. 지저분한 방은 손님한테 안 보여 주는 거예요.", tag: "[whispers] 제가 매일 앉는 데니까요. [whispers] 지저분한 방은, 손님한테 안 보여 주는 거예요." },
  { id: "y6-3ce94a95dc", who: "yeonseo", text: "집에서만요. 이것도 기밀. 오늘 기밀이 많네요.", tag: "[flustered] 집에서만요. 이것도 기밀. 오늘 기밀이 많네요." },
  { id: "y6-1391f0d52b", who: "yeonseo", text: "…달력은 보지 마요. 그건 나중 순서예요.", tag: "[deadpan] ...달력은 보지 마요. 그건 나중 순서예요." },
  { id: "y6-bc6e5dae2b", who: "yeonseo", text: "…2분 일찍 왔네요.", tag: "[deadpan] ...이 분 일찍 왔네요." },
  { id: "y6-0522f61df5", who: "yeonseo", text: "우연이에요. 신발 정리하고 있었어요. 2분 동안.", tag: "[flustered] 우연이에요. 신발 정리하고 있었어요. 이 분 동안." },
  { id: "y6-6016e7c1e4", who: "yeonseo", text: "손님은 성한 거 써요. 오늘은 제가 털어놓는 쪽이니까, 깨진 쪽이 맞아요.", tag: "[deadpan] 손님은 성한 거 써요. 오늘은 제가 털어놓는 쪽이니까, 깨진 쪽이 맞아요." },
  { id: "y6-d1ac9667ad", who: "yeonseo", text: "질문 없이 들어 줘요. 중간에 멈추면 다시 못 해요.", tag: "[serious] 질문 없이 들어 줘요. 중간에 멈추면, 다시 못 해요." },
  { id: "y6-0540a6ccc7", who: "yeonseo", text: "저는 하우스 플레이어예요. 사장님 돈으로 앉고, 사장님이 정한 숫자만큼 이기거나 져요.", tag: "[deadpan] 저는 하우스 플레이어예요. 사장님 돈으로 앉고, 사장님이 정한 숫자만큼 이기거나 져요." },
  { id: "y6-c416366e4e", who: "yeonseo", text: "에이미 씨 월세도요. 그 전에 다른 사람들 것도. 저 수첩 일곱 권에 다 있어요.", tag: "[deadpan] 에이미 씨 월세도요. 그 전에, 다른 사람들 것도. 저 수첩 일곱 권에, 다 있어요." },
  { id: "y6-987e8dc138", who: "yeonseo", text: "그리고 딜러님. 첫날 엄지 얘기요.", tag: "[deadpan] 그리고 딜러님. 첫날 엄지 얘기요." },
  { id: "y6-895908f5fd", who: "yeonseo", text: "그것도 시켜서 한 말이에요. '그 손이 맞는지 봐라.'", tag: "[cold] 그것도 시켜서 한 말이에요. [flat] '그 손이 맞는지 봐라.'" },
  { id: "y6-cbc309bc5b", who: "yeonseo", text: "다가간 것도 처음엔 그래서였어요.", tag: "[deadpan] 다가간 것도, 처음엔 그래서였어요." },
  { id: "y6-50ad0afcab", who: "yeonseo", text: "…지금은 아니고.", tag: "[quiet] [sad] ...지금은 아니고." },
  { id: "y6-24e988868c", who: "yeonseo", text: "어제 그 말 하나로요?", tag: "[a little surprised] [skeptical] 어제 그 말, 하나로요?" },
  { id: "y6-65f93cfb34", who: "yeonseo", text: "표본 하나로 결론 내면 안 돼요. 포커에선 그러다 다 잃어요.", tag: "[deadpan] 표본 하나로 결론 내면 안 돼요. 포커에선, 그러다 다 잃어요." },
  { id: "y6-d3084f9c1b", who: "yeonseo", text: "…근데 맞아요. 그 결론.", tag: "[flustered] [admitting] ...근데, 맞아요, 그 결론." },
  { id: "y6-57436323c4", who: "yeonseo", text: "지금은…", tag: "[hesitant] 지금은..." },
  { id: "y6-29009176b0", who: "yeonseo", text: "…일곱 권 어디에도 안 적혀 있는 거예요. 지금은.", tag: "[hesitant] [sincere] ...일곱 권 어디에도 안 적혀 있는 거예요, 지금은." },
  { id: "y6-66f46cf437", who: "yeonseo", text: "더는 못 해요. 오늘 할당량 넘었어요.", tag: "[flustered] 더는 못 해요. 오늘 할당량 넘었어요." },
  { id: "y6-ca5df50e21", who: "yeonseo", text: "…그것까지 말하면, 저는 진짜로 사장님 사람이 아니게 돼요.", tag: "[serious] ...그것까지 말하면, 저는 진짜로 사장님 사람이 아니게 돼요." },
  { id: "y6-993e7cf621", who: "yeonseo", text: "바뀌었어요. 방금. 컷한 덱은 무릎 위, 올라온 건 미리 맞춰 둔 덱이에요.", tag: "[deadpan] 바뀌었어요, 방금. 컷한 덱은 무릎 위, 올라온 건 미리 맞춰 둔 덱이에요." },
  { id: "y6-a718658d59", who: "yeonseo", text: "그리고 사장님 물잔. 가장자리에 손가락 하나는 져 줘라, 둘은 비슷하게.", tag: "[deadpan] 그리고, 사장님 물잔. 가장자리에 손가락 하나는 져 줘라, 둘은 비슷하게." },
  { id: "y6-55f936391e", who: "yeonseo", text: "셋은 전부 가져와라.", tag: "[quietly] [sad] 셋은, 전부 가져와라." },
  { id: "y6-da8ea669a6", who: "yeonseo", text: "네. 값이 아니라 신호예요. …이제 저는 사장님 비밀을 판 사람이에요. 커피 한 잔 값에.", tag: "[quietly] [sad] 네. 값이 아니라 신호예요. ...이제 저는, 사장님 비밀을 판 사람이에요. [falling tone] 커피 한 잔 값에." },
  { id: "y6-dd00c14d96c", who: "yeonseo", text: "…가지 마요.", tag: "[trembling] [on the verge of tears] ...가지 마요." },
  { id: "y6-e7f56c55b7", who: "yeonseo", text: "…오늘만요. 커피 식을 때까지만.", tag: "[softly] [flustered] ...오늘만요. [falling tone] 커피 식을 때까지만." },
  { id: "y6-549451e591", who: "yeonseo", text: "…안 가네요.", tag: "[quiet] [sad] ...안 가네요." },
  { id: "y6-7df3c33d33", who: "yeonseo", text: "대답도 안 하고, 손도 안 잡고. 그냥 안 가요.", tag: "[quiet] [sad] 대답도 안 하고, 손도 안 잡고. 그냥, 안 가요." },
  { id: "y6-b421371384", who: "yeonseo", text: "그게 제일 무서운 대답인 줄 알았어요. 다들 대답을 잘하고 나서 갔으니까.", tag: "[quiet] 그게, 제일 무서운 대답인 줄 알았어요. 다들 대답을 잘하고 나서, 갔으니까." },
  { id: "y6-d3f31efcd6", who: "yeonseo", text: "말은 다들 해요. 가겠다는 말도, 안 가겠다는 말도. …서 있는 사람은 처음이에요.", tag: "[soft] [small smile] 말은 다들 해요. 가겠다는 말도, 안 가겠다는 말도. ...서 있는 사람은, 처음이에요." },
  { id: "y6-b9262e126f", who: "yeonseo", text: "알아요. 그래서 믿겨요. 그 얼굴은 연습한 얼굴이 아니라서.", tag: "[shy] 알아요. 그래서 믿겨요. [falling tone] 그 얼굴은, 연습한 얼굴이 아니라서." },
  { id: "y6-acfd4d2149", who: "yeonseo", text: "…차갑죠? 손.", tag: "[shy] [quiet] ...차갑죠? [falling tone] 손." },
  { id: "y6-fd0844e25c", who: "yeonseo", text: "…그건 계산이 아니라 물리예요. 근데 맞는 것 같아요.", tag: "[soft] [small smile] ...그건 계산이 아니라 물리예요. 근데, 맞는 것 같아요." },
  { id: "y6-2c191358db", who: "yeonseo", text: "…식으면요.", tag: "[softly] [sad] ...식으면요." },
  { id: "y6-9ec05f51d2", who: "yeonseo", text: "전자레인지 한 번에 2분이에요. 몇 번까지 버티는지 볼게요.", tag: "[softly] [flustered] 전자레인지 한 번에, 이 분이에요. 몇 번까지 버티는지 볼게요." },
  { id: "y6-06b8863e9e", who: "yeonseo", text: "…세 번이에요. 6분.", tag: "[dry] [amused] ...세 번이에요. [falling tone] 육 분." },
  { id: "y6-a1dc85bd9d", who: "yeonseo", text: "버릇이에요, 숫자 세는 거. …오늘은 버릇 말고, 그냥 셌어요.", tag: "[flustered] 버릇이에요, 숫자 세는 거. ...오늘은 버릇 말고, 그냥 셌어요." },
  { id: "y6-2e203807e5", who: "yeonseo", text: "근데 오늘은 저만 다 말했어요. 불공평해요.", tag: "[dry] [playfully complaining] 근데, 오늘은 저만- 다말했어요. 불공평해요." },
  { id: "y6-606d4a35d0", who: "yeonseo", text: "하나만 물어볼게요. 딜러님은 3년 동안, 누구한테 거짓말했어요?", tag: "[deadpan] 하나만 물어볼게요. 딜러님은 삼 년 동안, 누구한테 거짓말했어요?" },
  { id: "y6-32ce600d78", who: "yeonseo", text: "무슨 회사요?", tag: "[curious] 무슨 회사요?" },
  { id: "y6-240cfdd78a", who: "yeonseo", text: "거짓말에 디테일이 많아요. 오래 한 사람 거짓말이에요.", tag: "[dry] 거짓말에 디테일이 많아요. 오래 한 사람 거짓말이에요." },
  { id: "y6-bf7c37ca82", who: "yeonseo", text: "우리 둘 다 가족한테 하나씩 숨기고 있었네요. 저는 이제 숨길 가족이 없지만.", tag: "[sad] 우리 둘 다, 가족한테 하나씩 숨기고 있었네요. [falling tone] 저는 이제, 숨길 가족이 없지만." },
  { id: "y6-bbb51d9387", who: "yeonseo", text: "아뇨. 거짓말은 늘 제가 찾아내는 쪽이었어요. 먼저 건네받은 건 없었는데.", tag: "[deadpan] 아뇨. 거짓말은 늘, 제가 찾아내는 쪽이었어요. 먼저 건네받은 건 없었는데." },
  { id: "y6-9288df918b", who: "yeonseo", text: "…기록할게요. 지게차.", tag: "[dry] [amused] ...기록할게요. [falling tone] 지게차." },
  { id: "y6-842a1fc3e8", who: "yeonseo", text: "…역시 X처럼 보여요. 검은색이라.", tag: "[dry] [amused] ...역시, 엑스처럼 보여요. 검은색이라." },
  { id: "y6-19e1db29dd", who: "yeonseo", text: "딜러님 눈은 가끔 너무 후해요.", tag: "[flustered] 딜러님 눈은, 가끔 너무 후해요." },
  { id: "y6-889b3d9b10", who: "yeonseo", text: "…또 늘었어요. 이 달력, 이제 X만 있는 달력이 아니에요.", tag: "[warm] ...또 늘었어요. 이 달력, 이제 엑스만 있는 달력이 아니에요." },
  { id: "y6-626123492a", who: "yeonseo", text: "…두 번째예요. 7년 동안 X만 그리던 달력에.", tag: "[warm] ...두 번째예요. [falling tone] 칠 년 동안, 엑스만 그리던 달력에." },
  { id: "y6-78c439b372", who: "yeonseo", text: "…세 번째예요. 7년 동안 하나도 없다가, 일주일 사이에 셋.", tag: "[warm] ...세 번째예요. [falling tone] 칠 년 동안 하나도 없다가, 일주일 사이에 셋." },
  { id: "y6-95a38cdf90", who: "yeonseo", text: "하루 끝날 때마다 X 쳐요. 오늘도 빚을 못 줄였다는 표시. 7년 치예요.", tag: "[deadpan] 하루 끝날 때마다 엑스 쳐요. 오늘도 빚을 못 줄였다는 표시. 칠 년 치예요." },
  { id: "y6-26d0ace9e7", who: "yeonseo", text: "근데 오늘은… X가 안 맞는 날 같아요.", tag: "[deadpan] 근데 오늘은... 엑스가 안 맞는 날 같아요." },
  { id: "y6-90d26819c3", who: "yeonseo", text: "그건 무슨 표시인데요.", tag: "[curious] 그건, 무슨 표시인데요." },
  { id: "y6-aabed267a3", who: "yeonseo", text: "…첫 번째예요. 7년 만에.", tag: "[warm] ...첫 번째예요. [falling tone] 칠 년 만에." },
  { id: "y6-3fd238bd3c", who: "yeonseo", text: "…왔네요. 이거 받아요.", tag: "[deadpan] ...왔네요. 이거 받아요." },
  { id: "y6-5c0e5cd6b7", who: "yeonseo", text: "어머니한테 하는 거짓말이요. 디테일이 많을수록 오래가요. 디테일이 틀리면 한 번에 무너지고요.", tag: "[deadpan] 어머니한테 하는 거짓말이요. 디테일이 많을수록 오래가요. 디테일이 틀리면, 한 번에 무너지고요." },
  { id: "y6-fcb7a968ac", who: "yeonseo", text: "어머니가 면허 언제 땄냐고 물으면, 작년 봄. 실기는 한 번 떨어졌고요. 그게 더 진짜 같거든요.", tag: "[deadpan] 어머니가 면허 언제 땄냐고 물으면, 작년 봄. 실기는 한 번 떨어졌고요. 그게 더 진짜 같거든요." },
  { id: "y6-6727736ba7", who: "yeonseo", text: "기록한다고 했잖아요. 지게차.", tag: "[deadpan] 기록한다고 했잖아요. [falling tone] 지게차." },
  { id: "y6-41fbdecb23", who: "yeonseo", text: "…그날이 오면 이 표는 버려요.", tag: "[deadpan] ...그날이 오면, 이 표는 버려요." },
  { id: "y6-ae5f17689d", who: "yeonseo", text: "그리고 그날은 저한테도 알려 줘요. 달력에 쳐 둘게요.", tag: "[warm] 그리고 그날은, 저한테도 알려 줘요. 달력에 쳐 둘게요." },
  { id: "y6-2702fe5a6f", who: "yeonseo", text: "…딜러님한테 하는 거짓말은 이제 없어요. 관리할 게 없을걸요.", tag: "[deadpan] ...딜러님한테 하는 거짓말은, 이제 없어요. 관리할 게 없을걸요." },
  { id: "y6-45f24caebd", who: "yeonseo", text: "있어요. 오늘 밤 휴식 시간에 알게 될 거예요.", tag: "[softly] [flustered] 있어요. 오늘 밤 휴식 시간에, 알게 될 거예요." },
  { id: "y6-8d7b59a2ef", who: "yeonseo", text: "…거짓말 관리 시작한 날이에요. 이것도 동그라미예요.", tag: "[softly] [flustered] ...거짓말 관리 시작한 날이에요. 이것도 동그라미예요." },
  { id: "y6-b250495946", who: "yeonseo", text: "…두 분, 휴식 시간 끝났어요.", tag: "[cold] ...두 분, 휴식 시간 끝났어요." },
  { id: "y6-981449da47", who: "yeonseo", text: "…편의점 앞에서, 오래 있었네요.", tag: "[deadpan] ...편의점 앞에서, 오래 있었네요." },
  { id: "y6-60808caebb", who: "yeonseo", text: "구석 자리는 창문이 잘 보여요. 칩 세다가 보였어요. …그래서 오늘은 여기 앉았어요. 여기선 창문이 안 보이니까.", tag: "[deadpan] 구석 자리는 창문이 잘 보여요. 칩 세다가 보였어요. ...그래서 오늘은 여기 앉았어요. 여기선 창문이 안 보이니까." },
  { id: "y6-260427437a", who: "yeonseo", text: "그래요. 좋은 일이네요.", tag: "[cold] 그래요. [flat] 좋은 일이네요." },
  { id: "y6-0aad324d94", who: "yeonseo", text: "휴식 시간엔 여기 앉을래요. 앞으로도.", tag: "[deadpan] 휴식 시간엔, 여기 앉을래요. [falling tone] 앞으로도." },
  { id: "y6-86b93080fc", who: "yeonseo", text: "구석은 칩 세기엔 좋은데, 딜러님 손이 안 보여요.", tag: "[deadpan] 구석은 칩 세기엔 좋은데, 딜러님 손이 안 보여요." },
  { id: "y6-e4572d380e", who: "yeonseo", text: "딜러님 손은 기분을 다 말해요. 오늘은 칩을 세 번 고쳐 쌓았죠. 낮에 안 좋은 전화라도 받은 손이에요.", tag: "[deadpan] 딜러님 손은, 기분을 다 말해요. 오늘은 칩을 세 번 고쳐 쌓았죠. 낮에 안 좋은 전화라도 받은 손이에요." },
  { id: "y6-ac96188a59", who: "yeonseo", text: "구석에선 안 보였는데, 여기선 보여요. 그래서 앉은 거예요.", tag: "[deadpan] 구석에선 안 보였는데, 여기선 보여요. 그래서 앉은 거예요." },
  { id: "y6-71a9059595", who: "yeonseo", text: "…내일도 앉을 거예요. 휴식 시간 15분. 매일.", tag: "[softly] [flustered] ...내일도 앉을 거예요. [falling tone] 휴식 시간 십오 분, 매일." },
  { id: "y6-086cabfcee", who: "yeonseo", text: "…낮에 전화 왔죠? 대부 회사에서.", tag: "[knowing] 낮에 전화 왔죠? [flatly] [falling tone] 대부회사 에서." },
  { id: "y6-4c0c548c89", who: "yeonseo", text: "저한테도 왔어요. 같은 시간에. 그 사람들은 한 번에 돌려요.", tag: "[deadpan] 저한테도 왔어요, 같은 시간에. 그 사람들은, 한 번에 돌려요." },
  { id: "y6-de52931fca", who: "yeonseo", text: "그 사람들 귀는 다 같은 데 붙어 있어요. 조심해요.", tag: "[cold] 그 사람들 귀는, 다 같은 데 붙어 있어요. 조심해요." },
  { id: "y6-b436b099d2", who: "yeonseo", text: "이모 주방에서 집어 왔어요. 그 전화 받은 날은 입이 쓰거든요. 저도 알아요.", tag: "[deadpan] 이모 주방에서 집어 왔어요. 그 전화 받은 날은, 입이 쓰거든요. 저도 알아요." },
  { id: "y6-5524912020", who: "yeonseo", text: "한 판만 해요. 이걸로요.", tag: "[deadpan] 한 판만 해요. 이걸로요." },
  { id: "y6-cb77b3ef37", who: "yeonseo", text: "성냥은 진짜 판 할 때 쓰는 거예요. 이건 연습이에요.", tag: "[deadpan] 성냥은, 진짜 판 할 때 쓰는 거예요. 이건 연습이에요." },
  { id: "y6-70a58c5d8e", who: "yeonseo", text: "낮에 안 좋은 전화 받은 손 맞아요? 하나도 안 흔들렸어요.", tag: "[surprised] 낮에 안 좋은 전화 받은 손, 맞아요? 하나도 안 흔들렸어요." },
  { id: "y6-d56c647933", who: "yeonseo", text: "이긴 사람이 사탕 다 가져가요. 입 쓴 날엔 그게 필요해요.", tag: "[deadpan] 이긴 사람이 사탕 다 가져가요. 입 쓴 날엔, 그게 필요해요." },
  { id: "y6-85be3e994f", who: "yeonseo", text: "딜러님은 질 때 귀가 먼저 빨개져요. 기록해 둘게요.", tag: "[dry] [amused] 딜러님은, 질 때 귀가 먼저 빨개져요. 기록해 둘게요." },
  { id: "y6-271c8efd1f", who: "yeonseo", text: "…이런 결과가 제일 오래 기억나요.", tag: "[deadpan] ...이런 결과가, 제일 오래 기억나요." },
  { id: "y6-6e15c9d6df", who: "yeonseo", text: "딜러님. 게임 하나 해요. 칩 없이.", tag: "[deadpan] 딜러님. 게임 하나 해요. [falling tone] 칩 없이." },
  { id: "y6-4c9e8ea61c", who: "yeonseo", text: "한쪽에 박하사탕이 있어요. 맞히면 가져가요.", tag: "[deadpan] 한쪽에 박하사탕이 있어요. 맞히면 가져가요." },
  { id: "y6-6038374c1e", who: "yeonseo", text: "아뇨. 제 얼굴을 보면 어느 쪽인지 알 수 있어요. 그러니까 백 퍼센트예요. 딜러님이 제 얼굴을 보면.", tag: "[matter-of-fact] 아뇨. 제 얼굴을 보면, 어느 쪽인지 알 수 있어요. 그러니까 백 퍼센트예요. [softly] [falling tone] 딜러님이, 제 얼굴을 보면." },
  { id: "y6-5d3f329ed1", who: "yeonseo", text: "…반칙이에요. 그렇게 오래 보면 제가 질 수밖에 없어요.", tag: "[flustered] ...반칙이에요. 그렇게 오래 보면, 제가 질 수밖에 없어요." },
  { id: "y6-6d7822860c", who: "yeonseo", text: "어느 쪽을 골라도 이기게 해 놨어요. 하우스 플레이어 버릇이에요.", tag: "[dry] [amused] 어느 쪽을 골라도, 이기게 해 놨어요. 하우스 플레이어 버릇이에요." },
  { id: "y6-c09f97312a", who: "yeonseo", text: "…손을 봤네요. 얼굴 말고.", tag: "[surprised] [impressed] ...손을 봤네요, 얼굴 말고." },
  { id: "y6-3f9e2d7e55", who: "yeonseo", text: "어느 쪽이든 이기게 해 놨어요. 그래도 손을 읽은 건 맞아요. 반칙이에요, 그 눈.", tag: "[dry] [amused] 어느 쪽이든 이기게 해 놨어요. 그래도, 손을 읽은 건 맞아요. [falling tone] 반칙이에요, 그 눈." },
  { id: "y6-f00520eb77", who: "yeonseo", text: "안 돼요.", tag: "[cold] 안 돼요." },
  { id: "y6-604e3c3219", who: "yeonseo", text: "…안 앉아요. 그리고 앉아도 못 이겨요.", tag: "[cold] ...안 앉아요. 그리고 앉아도, 못 이겨요." },
  { id: "y6-c9b0e23f28", who: "yeonseo", text: "손이 떨려요. 셔플할 때 봤어요. 3년 전 그 손이 아니에요.", tag: "[cold] 손이 떨려요. 셔플할 때 봤어요. [flat] 삼 년 전 그 손이 아니에요." },
  { id: "y6-1523543464", who: "yeonseo", text: "사장님은 카드를 안 만지시니까요.", tag: "[cold] 사장님은, 카드를 안 만지시니까요." },
  { id: "y6-08ba74c17e", who: "yeonseo", text: "…괜찮아요.", tag: "[whispers] [cold] ...괜찮아요." },
  { id: "y6-03e8440294", who: "yeonseo", text: "…들었어요?", tag: "[deadpan] ...들었어요?" },
  { id: "y6-63d8776d34", who: "yeonseo", text: "거짓말했어요. 사장님한테. 이번엔 처음부터 끝까지.", tag: "[deadpan] 거짓말했어요, 사장님한테. 이번엔, 처음부터 끝까지." },
  { id: "y6-d76074fd03", who: "yeonseo", text: "반은 버렸어요. 7년 치 장부의 반. 딜러님 손 하나랑 바꿨어요.", tag: "[sad] 반은 버렸어요. 칠 년 치 장부의 반. 딜러님 손 하나랑, 바꿨어요." },
  { id: "y6-471ead6490", who: "yeonseo", text: "수지가 안 맞는 거래예요. …알아요.", tag: "[deadpan] 수지가 안 맞는 거래예요. ...알아요." },
  { id: "y6-d0c4e55419", who: "yeonseo", text: "그리고 이번엔 혼자 숨겨서 미안해요. 둘이 들어가면, 심장 소리가 너무 커서요.", tag: "[softly] [flustered] 그리고 이번엔, 혼자 숨겨서 미안해요. 둘이 들어가면, 심장 소리가 너무 커서요." },
  { id: "y6-6fae280428", who: "yeonseo", text: "알아요. 떨리는 손이 무슨 값어치가 있어요?", tag: "[dry] 알아요. 떨리는 손이, 무슨 값어치가 있어요?" },
  { id: "y6-185faec4e2", who: "yeonseo", text: "…했어요. 딜러님 손 깎아내리는 농담은 연습을 안 해 봐서, 타이밍을 몰랐어요.", tag: "[flustered] ...했어요. 딜러님 손 깎아내리는 농담은 연습을 안 해 봐서, 타이밍을 몰랐어요." },
  { id: "y6-14018c97e7", who: "yeonseo", text: "그럼 기록해 둘게요. 농담 1회, 성공.", tag: "[dry] [amused] 그럼 기록해 둘게요. [falling tone] 농담 일 회, 성공." },
  { id: "y6-1958d1a447", who: "yeonseo", text: "빨리 끝나서 뭐 해요? 끝난 날, 딜러님이 아래층에 앉아 있으면.", tag: "[deadpan] 빨리 끝나서 뭐 해요? [falling tone] 끝난 날, 딜러님이 아래층에 앉아 있으면." },
  { id: "y6-68b061cc57", who: "yeonseo", text: "그런 날 이기는 건 지는 거랑 똑같아요. 질리게 계산해 봤어요.", tag: "[sad] 그런 날 이기는 건, 지는 거랑 똑같아요. 질리게 계산해 봤어요." },
  { id: "y6-e6b54c45a7", who: "yeonseo", text: "내일 마감 후에, 남아 줘요. 보여 줄 게 있어요.", tag: "[whispers] [flustered] 내일 마감 후에, 남아 줘요. [whispers] 보여 줄 게 있어요." },
  { id: "y6-34ad2d996f", who: "yeonseo", text: "시계는 칩 계산할 때 보는 거예요.", tag: "[cold] 시계는, 칩 계산할 때 보는 거예요." },
  { id: "y6-8186669347", who: "yeonseo", text: "두 시간 남았어요. 마감까지.", tag: "[deadpan] 두 시간 남았어요. 마감까지." },
  { id: "y6-2f0b29e896", who: "yeonseo", text: "…기다리는 계산이요. 오늘은 그런 것도 해요.", tag: "[softly] [flustered] ...기다리는 계산이요. 오늘은, 그런 것도 해요." },
  { id: "y6-66f38425f2", who: "yeonseo", text: "아래층 딜러. 아직 할 거예요?", tag: "[deadpan] 아래층 딜러. 아직, 할 거예요?" },
  { id: "y6-7bb788c7fa", who: "yeonseo", text: "다음 달부터라고 했죠. 내일 옷 치수 재러 사람이 올 거예요.", tag: "[cold] 다음 달부터라고 했죠. 내일, 옷 치수 재러 사람이 올 거예요." },
  { id: "y6-a30584965a", who: "yeonseo", text: "'안 받아요'라고 했던 사람이요. 제 장부에 그 줄은 아직 비워 뒀어요.", tag: "[deadpan] '안 받아요'라고 했던 사람이요. 제 장부에 그 줄은, 아직 비워 뒀어요." },
  { id: "y6-b025f9fc88", who: "yeonseo", text: "…사장님이 웃을 거예요. 거절당하면 더 웃어요.", tag: "[dry] ...사장님이 웃을 거예요. 거절당하면, 더 웃어요." },
  { id: "y6-a86f8bc8b0", who: "yeonseo", text: "그래도 다행이에요. 그 손이 그 테이블에 서 있는 거, 저는 못 봐요.", tag: "[softly] 그래도 다행이에요. 그 손이 그 테이블에 서 있는 거, 저는 못 봐요." },
  { id: "y6-94f38cb2b2", who: "yeonseo", text: "제가 돌려보낼게요. 치수는 제가 알아요. 눈대중으로.", tag: "[deadpan] 제가 돌려보낼게요. 치수는 제가 알아요. 눈대중으로." },
  { id: "y6-08659b8ce1", who: "yeonseo", text: "어깨 너비, 소매 길이. 3주 동안 봤으니까요. 틀리면 제 계산이 틀린 거고요.", tag: "[flustered] 어깨 너비, 소매 길이. 삼 주 동안 봤으니까요. 틀리면, 제 계산이 틀린 거고요." },
  { id: "y6-8bbcf7ccb3", who: "yeonseo", text: "저도 처음엔 그렇게 말했어요. 카드만 보면 된다고.", tag: "[sad] 저도 처음엔, 그렇게 말했어요. 카드만 보면 된다고." },
  { id: "y6-885b87f30d", who: "yeonseo", text: "아까 일, 아직 화나 있어요.", tag: "[cold] 아까 일, 아직 화나 있어요." },
  { id: "y6-1a3036ecc3", who: "yeonseo", text: "그래도 남아 달라고 한 건 저니까요. 약속은 지킬게요.", tag: "[deadpan] 그래도 남아 달라고 한 건 저니까요. 약속은 지킬게요." },
  { id: "y6-5cf704f463", who: "yeonseo", text: "저는 손님 자리. 딜러님은 딜러 자리. 처음 만난 날처럼 서 있어 줘요.", tag: "[deadpan] 저는 손님 자리. 딜러님은 딜러 자리. 처음 만난 날처럼, 서 있어 줘요." },
  { id: "y6-03db9df432", who: "yeonseo", text: "선이 있어야 넘을 수 있으니까요. …방금 말은 잊어요. 연습한 대사가 아니라서.", tag: "[flustered] 선이 있어야 넘을 수 있으니까요. ...방금 말은 잊어요. 연습한 대사가 아니라서." },
  { id: "y6-7230f079e6", who: "yeonseo", text: "카운터에서 장갑 찢어진 날. 그때 봤죠, 이 손.", tag: "[deadpan] 카운터에서 장갑 찢어진 날. 그때 봤죠, 이 손." },
  { id: "y6-24253d518f", who: "yeonseo", text: "네. 그래서 그건 안 셀래요. 찢어져서 보인 건.", tag: "[deadpan] 네. 그래서 그건 안 셀래요. 찢어져서 보인 건." },
  { id: "y6-5df7f22103", who: "yeonseo", text: "오늘은 제 손으로 벗을게요.", tag: "[resolute] 오늘은, 제 손으로 벗을게요." },
  { id: "y6-75b3003a72", who: "yeonseo", text: "약속했죠. 언젠가 보여 준다고. 제 손으로 벗어서.", tag: "[resolute] 약속했죠. 언젠가 보여 준다고. 제 손으로, 벗어서." },
  { id: "y6-d575a70444", who: "yeonseo", text: "오늘이요. 내일이면 또 핑계를 찾을 것 같아서.", tag: "[resolute] 오늘이요. 내일이면, 또 핑계를 찾을 것 같아서." },
  { id: "y6-c5e6d518c2", who: "yeonseo", text: "장갑 얘기, 했었죠. 말로만.", tag: "[deadpan] 장갑 얘기, 했었죠. 말로만." },
  { id: "y6-09402f629e", who: "yeonseo", text: "말로 하는 거랑 보여 주는 거는 달라요. 오늘은 보여 줄게요.", tag: "[resolute] 말로 하는 거랑 보여 주는 거는 달라요. 오늘은 보여 줄게요." },
  { id: "y6-930e6c3648", who: "yeonseo", text: "장갑, 왜 한쪽만 끼는지 한 번도 안 물어봤죠?", tag: "[deadpan] 장갑, 왜 한쪽만 끼는지, 한 번도 안 물어봤죠?" },
  { id: "y6-4de91673c8", who: "yeonseo", text: "맞아요. 그래서 오늘은, 안 묻는 사람한테 먼저 보여 줄게요.", tag: "[resolute] 맞아요. 그래서 오늘은, 안 묻는 사람한테 먼저 보여 줄게요." },
  { id: "y6-1576c52da3", who: "yeonseo", text: "아래층 테이블에 오래 앉은 손이 어떻게 되는지도요.", tag: "[cold] 아래층 테이블에 오래 앉은 손이, 어떻게 되는지도요." },
  { id: "y6-2a5961630d", who: "yeonseo", text: "…스물두 살. 세 번째 판. 이렇게 쥐었어요.", tag: "[softly] [sad] ...스물두 살. 세 번째 판. 이렇게 쥐었어요." },
  { id: "y6-efee0bb40e", who: "yeonseo", text: "이 손을 일부러 보여 준 사람은 없어요. 딜러님이 처음이에요.", tag: "[softly] 이 손을 일부러 보여 준 사람은 없어요. 딜러님이 처음이에요." },
  { id: "y6-fef5b0d82e", who: "yeonseo", text: "…간지러워요.", tag: "[softly] [flustered] ...간지러워요." },
  { id: "y6-61a2a6dc3a", who: "yeonseo", text: "딜러는… 손님 손 잡으면 안 되는데요.", tag: "[softly] [flustered] 딜러는... 손님 손 잡으면 안 되는데요." },
  { id: "y6-51a856e6a2", who: "yeonseo", text: "그럼 뭔데요?", tag: "[flustered] 그럼, 뭔데요?" },
  { id: "y6-f304b8ec58", who: "yeonseo", text: "…무섭지 않아요? 남의 돈을 매일 밤 가져온 손이에요.", tag: "[sad] ...무섭지 않아요? 남의 돈을, 매일 밤 가져온 손이에요." },
  { id: "y6-d0357f5d77", who: "yeonseo", text: "그럼 둘 다 나쁜 손이네요. 짝은 맞아요.", tag: "[chuckles] 그럼 둘 다 나쁜 손이네요. 짝은 맞아요." },
  { id: "y6-d66710071f", who: "yeonseo", text: "…근데 짝이 맞는 손 하나가, 다음 달부터 아래층에 서요.", tag: "[sad] ...근데 짝이 맞는 손 하나가, 다음 달부터 아래층에 서요." },
  { id: "y6-2386ba1f50", who: "yeonseo", text: "그럼 저는 그 테이블 맞은편에서, 그 손이 돌린 카드로 져 줘야 해요. 손가락 하나 보고.", tag: "[softly] [sad] 그럼 저는 그 테이블 맞은편에서, 그 손이 돌린 카드로 져 줘야 해요. 손가락 하나 보고." },
  { id: "y6-1e0777aaa8", who: "yeonseo", text: "…이제 핑계가 없네요. X처럼 보인다는 핑계.", tag: "[softly] [flustered] ...이제 핑계가 없네요. 엑스처럼 보인다는 핑계." },
  { id: "y6-0574c801b0", who: "yeonseo", text: "오늘 받은 것도 기록할게요. 이 볼펜으로 쓰는 첫 기록이에요.", tag: "[warm] 오늘 받은 것도 기록할게요. 이 볼펜으로 쓰는 첫 기록이에요." },
  { id: "y6-7fcef1d284", who: "yeonseo", text: "딜러님. 이 손이 7년 만에 맨손으로 잡은 게 두 개예요. 볼펜이랑, 딜러님 손.", tag: "[softly] [flustered] 딜러님. 이 손이 칠 년 만에 맨손으로 잡은 게 두 개예요. 볼펜이랑, 딜러님 손." },
  { id: "y6-02e55cd644", who: "yeonseo", text: "손이 먼저예요. 기록에 그렇게 남길 거예요.", tag: "[warm] 손이 먼저예요. 기록에 그렇게 남길 거예요." },
  { id: "y6-c475bc430e", who: "yeonseo", text: "…두부가 다 온전해요.", tag: "[surprised] ...두부가, 다 온전해요." },
  { id: "y6-6b9c630d31", who: "yeonseo", text: "이모 거랑 맛이 달라요.", tag: "[deadpan] 이모 거랑, 맛이 달라요." },
  { id: "y6-f0477b1cf1", who: "yeonseo", text: "아뇨. 이모 거는 매일 먹은 맛이고, 이건 방금 한 숟가락 먹은 맛이에요.", tag: "[deadpan] 아뇨. 이모 거는 매일 먹은 맛이고, 이건 방금 한 숟가락 먹은 맛이에요." },
  { id: "y6-bbeaa7fcfa", who: "yeonseo", text: "한 숟가락이 7년을 이길 확률은 원래 낮은데. …오늘은 모르겠어요.", tag: "[flustered] 한 숟가락이 칠 년을 이길 확률은 원래 낮은데. ...오늘은 모르겠어요." },
  { id: "y6-27573872fc", who: "yeonseo", text: "아뇨. 이 맛, 알아요. 지난주 구석 자리 그릇. 그때도 딜러님 거였죠.", tag: "[deadpan] 아뇨. 이 맛, 알아요. 지난주 구석 자리 그릇. 그때도 딜러님 거였죠." },
  { id: "y6-79ec8f7526", who: "yeonseo", text: "두부가 하나도 안 부서져 있었어요. 이모 찌개는 바쁜 날이면 꼭 하나씩 부서져요.", tag: "[deadpan] 두부가 하나도 안 부서져 있었어요. 이모 찌개는 바쁜 날이면, 꼭 하나씩 부서져요." },
  { id: "y6-f6c61466a9", who: "yeonseo", text: "두 번째 먹는 맛이 이모 7년을 이길 확률은 원래 낮은데. …오늘은 모르겠어요.", tag: "[flustered] 두 번째 먹는 맛이, 이모 칠 년을 이길 확률은 원래 낮은데. ...오늘은 모르겠어요." },
  { id: "y6-6712256922", who: "yeonseo", text: "이모 거는 매일 먹으니까 아껴 먹는 거예요. 이건… 내일 없을 수도 있으니까요.", tag: "[flustered] 이모 거는 매일 먹으니까 아껴 먹는 거예요. 이건... 내일 없을 수도 있으니까요." },
  { id: "y6-5408643424", who: "yeonseo", text: "……그럼 내일은 아껴 먹을게요.", tag: "[softly] ......그럼 내일은, 아껴 먹을게요." },
  { id: "y6-d66bc7c6cb", who: "yeonseo", text: "엄마랑 마지막으로 간 데예요. 열아홉 살 때.", tag: "[deadpan] 엄마랑 마지막으로 간 데예요. 열아홉 살 때." },
  { id: "y6-af27a29a15", who: "yeonseo", text: "지하엔 창문이 없어서, 여름이 언제 오는지 몰랐어요. 7년 동안.", tag: "[sad] 지하엔 창문이 없어서, 여름이 언제 오는지 몰랐어요. 칠 년 동안." },
  { id: "y6-48f39a9eac", who: "yeonseo", text: "다 끝나면 가 보고 싶어요. 장갑 안 끼고.", tag: "[wistful] 다 끝나면, 가 보고 싶어요. 장갑 안 끼고." },
  { id: "y6-7ff72a1a91", who: "yeonseo", text: "…'다 끝나면'은 포커에서 제일 안 믿는 말이에요.", tag: "[dry] ...'다 끝나면'은, 포커에서 제일 안 믿는 말이에요." },
  { id: "y6-754a13549a", who: "yeonseo", text: "…그건 불공평해요. 저도 믿을래요. 오늘은.", tag: "[warm] ...그건 불공평해요. 저도 믿을래요. 오늘은." },
  { id: "y6-1c5860b4d0", who: "yeonseo", text: "기차표는 왕복으로요. 편도는 도망 같아서 싫어요.", tag: "[deadpan] 기차표는, 왕복으로요. 편도는 도망 같아서 싫어요." },
  { id: "y6-c22d2fb79f", who: "yeonseo", text: "…약속은 기록해 둘게요. 빨간색으로.", tag: "[warm] ...약속은 기록해 둘게요. 빨간색으로." },
  { id: "y6-60c78111ed", who: "yeonseo", text: "…한 장만요. 제 사진첩엔 저 등대 하나뿐이에요.", tag: "[softly] [flustered] ...한 장만요. 제 사진첩엔, 저 등대 하나뿐이에요." },
  { id: "y6-75632ab849", who: "yeonseo", text: "…두 번째 사진이에요. 남은 휴식 시간은 안 셀래요. 세면 끝나니까.", tag: "[softly] ...두 번째 사진이에요. 남은 휴식 시간은 안 셀래요. 세면 끝나니까." },
  { id: "y6-aae6a17c79", who: "yeonseo", text: "…휴가 냈어요. 7년 만에.", tag: "[deadpan] ...휴가 냈어요. 칠 년 만에." },
  { id: "y6-69fd9a98fa", who: "yeonseo", text: "이모요. 반찬통 배달 주소. 이모는 다 적어 둬요.", tag: "[deadpan] 이모요. 반찬통 배달 주소. 이모는 다 적어 둬요." },
  { id: "y6-9e0dc007aa", who: "yeonseo", text: "10시 기차예요. 바다요. 막차로 돌아와요.", tag: "[deadpan] 열 시 기차예요. 바다요. 막차로 돌아와요." },
  { id: "y6-8b5a308c43", who: "yeonseo", text: "…안 가도 돼요.", tag: "[hesitant] ...안 가도 돼요." },
  { id: "y6-cd2273be85", who: "yeonseo", text: "알아요. 그래서 '안 가도 돼요'를 붙였어요. 확률을 반반으로 맞추려고.", tag: "[dry] 알아요. 그래서 '안 가도 돼요'를 붙였어요. 확률을 반반으로 맞추려고." },
  { id: "y6-4649f21260", who: "yeonseo", text: "…답장 왔어요? 표정 보니까 왔네요.", tag: "[dry] ...답장 왔어요? 표정 보니까, 왔네요." },
  { id: "y6-f176090800", who: "yeonseo", text: "그럼 바다에서 푹 쉬어요. 사장님 지시니까.", tag: "[warm] 그럼 바다에서 푹 쉬어요. 사장님 지시니까." },
  { id: "y6-2673a4966e", who: "yeonseo", text: "…따로요.", tag: "[surprised] ...따로요." },
  { id: "y6-a0bf570046", who: "yeonseo", text: "생각보다 조심성이 많네요. 그 계산은 맞아요.", tag: "[deadpan] 생각보다 조심성이 많네요. 그 계산은 맞아요." },
  { id: "y6-c9c72e5380", who: "yeonseo", text: "…그럼 바다에서 기다릴게요. 빨간 등대 앞에서. 한 시간 먼저.", tag: "[warm] ...그럼 바다에서 기다릴게요. 빨간 등대 앞에서. 한 시간 먼저." },
  { id: "y6-ecbd923647", who: "yeonseo", text: "…사진이랑 똑같아요. 등대 색까지.", tag: "[surprised] ...사진이랑 똑같아요. 등대 색까지." },
  { id: "y6-412d3603c6", who: "yeonseo", text: "엄마랑 마지막으로 온 데예요. 열아홉 살. 휴대폰에 그 사진 하나 남아 있어요.", tag: "[deadpan] 엄마랑 마지막으로 온 데예요. 열아홉 살. 휴대폰에, 그 사진 하나 남아 있어요." },
  { id: "y6-563684e208", who: "yeonseo", text: "…그래서 오늘 확인하러 왔어요. 여름이 진짜 왔는지.", tag: "[wistful] ...그래서 오늘 확인하러 왔어요. 여름이, 진짜 왔는지." },
  { id: "y6-c8a98ef153", who: "yeonseo", text: "머리카락이 자꾸 날려요. 그럼 온 거예요.", tag: "[warm] 머리카락이 자꾸 날려요. 그럼, 온 거예요." },
  { id: "y6-3a8dbfd9a9", who: "yeonseo", text: "…세상에 이런 것도 있었네요.", tag: "[amazed] ...세상에, 이런 것도 있었네요." },
  { id: "y6-4b3efb7715", who: "yeonseo", text: "이모한테는 비밀이에요. 배신은 장부에 안 남길 거예요.", tag: "[flustered] 이모한테는 비밀이에요. 배신은, 장부에 안 남길 거예요." },
  { id: "y6-aabee4c54d", who: "yeonseo", text: "…제 말투 따라 하지 마요. 생각보다 얄미워요.", tag: "[dry] ...제 말투 따라 하지 마요. 생각보다 얄미워요." },
  { id: "y6-2d67ac3ebb", who: "yeonseo", text: "…태양 씨예요? 휴대폰 쥔 손이 들켰다고 말하는데요.", tag: "[dry] ...태양 씨예요? 휴대폰 쥔 손이, 들켰다고 말하는데요." },
  { id: "y6-ace5dff017", who: "yeonseo", text: "그럼 결과가 나오기 전에 즐겨야겠네요. 계산은 늘 늦게 나와요.", tag: "[warm] 그럼 결과가 나오기 전에, 즐겨야겠네요. 계산은 늘 늦게 나와요." },
  { id: "y6-0a0dcadb71", who: "yeonseo", text: "…보지 마요. 아니, 봐도 되는데. 말은 하지 마요.", tag: "[flustered] ...보지 마요. 아니, 봐도 되는데. 말은 하지 마요." },
  { id: "y6-2a057cd1d6", who: "yeonseo", text: "말 안 하는 얼굴도 시끄러워요, 딜러님은.", tag: "[dry] 말 안 하는 얼굴도 시끄러워요, 딜러님은." },
  { id: "y6-570bfbce00", who: "yeonseo", text: "지워지는 게 좋아요. 여기선 장부가 안 남아서.", tag: "[warm] 지워지는 게 좋아요. 여기선 장부가 안 남아서." },
  { id: "y6-3f69b3e4c0", who: "yeonseo", text: "…딜러님 발자국은 제 것보다 커요. 파도가 지우는 데 1초 더 걸려요.", tag: "[deadpan] ...딜러님 발자국은 제 것보다 커요. 파도가 지우는 데, 일 초 더 걸려요." },
  { id: "y6-36ceeed181", who: "yeonseo", text: "오늘은 세는 게 휴가예요.", tag: "[warm] 오늘은, 세는 게 휴가예요." },
  { id: "y6-b7e946782c", who: "yeonseo", text: "장갑 없는 손이요. 바다랑. …어울려요?", tag: "[shy] 장갑 없는 손이요. 바다랑. ...어울려요?" },
  { id: "y6-6759473958", who: "yeonseo", text: "…장갑보다요. 비교 대상이 너무 약해요.", tag: "[flustered] ...장갑보다요. 비교 대상이, 너무 약해요." },
  { id: "y6-153c140d57", who: "yeonseo", text: "……그건 반칙이에요.", tag: "[flustered] ......그건, 반칙이에요." },
  { id: "y6-13d65d2175", who: "yeonseo", text: "…대답 안 했어요.", tag: "[softly] ...대답, 안 했어요." },
  { id: "y6-2861a70fb0", who: "yeonseo", text: "…손으로 대답하는 사람, 딜러님밖에 없어요.", tag: "[warm] ...손으로 대답하는 사람, 딜러님밖에 없어요." },
  { id: "y6-999b642b2e", who: "yeonseo", text: "다음 여름에도 와요. 그때는 장갑, 안 가져올게요.", tag: "[softly] 다음 여름에도 와요. 그때는 장갑, 안 가져올게요." },
  { id: "y6-59b553541c", who: "yeonseo", text: "…서른한 대. 일요일 낮엔 자전거가 이렇게 많은 줄 몰랐어요.", tag: "[deadpan] ...서른한 대. 일요일 낮엔 자전거가, 이렇게 많은 줄 몰랐어요." },
  { id: "y6-2459624020", who: "yeonseo", text: "일요일 낮엔 자요. 토요일 밤에 진 숫자만큼.", tag: "[dry] 일요일 낮엔 자요. 토요일 밤에 진 숫자만큼." },
  { id: "y6-c33927ff38", who: "yeonseo", text: "근데 오늘은 눈이 일찍 떠졌어요. 이상하게, 셀 게 없어서.", tag: "[deadpan] 근데 오늘은 눈이 일찍 떠졌어요. 이상하게, 셀 게 없어서." },
  { id: "y6-7ae5f4e7a4", who: "yeonseo", text: "…한 명이요. 세기 쉬워서 좋네요.", tag: "[flustered] ...한 명이요. 세기 쉬워서 좋네요." },
  { id: "y6-5cecf00cc5", who: "yeonseo", text: "다음 일요일에도 이 숫자면 좋겠어요. 늘지도, 줄지도 말고.", tag: "[softly] 다음 일요일에도, 이 숫자면 좋겠어요. 늘지도, 줄지도 말고." },
  { id: "y6-d31a32e322", who: "yeonseo", text: "…아뇨. 본 적 없어요.", tag: "[cold] ...아뇨. 본 적 없어요." },
  { id: "y6-21910908b6", who: "yeonseo", text: "…카드 돌려요, 딜러님. 지금 저 쳐다보면, 무너질 것 같아요.", tag: "[whispers] [sad] ...카드 돌려요, 딜러님. [whispers] 지금 저 쳐다보면, 무너질 것 같아요." },
  { id: "y6-a3c95d14c9", who: "yeonseo", text: "…수요일에 말할게요. 그 사진에 대해서.", tag: "[softly] [sad] ...수요일에 말할게요. 그 사진에 대해서." },
  { id: "y6-5ab72bf85f", who: "yeonseo", text: "그 전엔 묻지 마요. 지금 말하면, 거짓말이 섞일 것 같아요.", tag: "[softly] 그 전엔, 묻지 마요. 지금 말하면, 거짓말이 섞일 것 같아요." },
  { id: "y6-8500ae1da2", who: "yeonseo", text: "…고마워요. 사흘이에요. …아뇨, 수요일 두 시까지 59시간. 사흘은 반올림이에요.", tag: "[matter-of-fact] ...고마워요. 사흘이에요. ...아뇨, 수요일 두 시까지 오십구 시간. [chuckles] 사흘은 반올림이에요." },
  { id: "y6-5c6b296a3f", who: "yeonseo", text: "그 사이에 제가 도망갈 확률은… 계산 안 할게요.", tag: "[dry] 그 사이에 제가 도망갈 확률은... 계산 안 할게요." },
  { id: "y6-407b78f4b1", who: "yeonseo", text: "…세 번째는 안 떨어뜨릴게요.", tag: "[softly] ...세 번째는, 안 떨어뜨릴게요." },
  { id: "y6-d3a567acbb", who: "yeonseo", text: "…1분만요. 60초 세고 갈게요.", tag: "[whispers] [sad] ...일 분만요. [whispers] 육십 초 세고 갈게요." },
  { id: "y6-72eb69f7bd", who: "yeonseo", text: "속으로요. 지금 32. …말 시키면 처음부터 다시 세야 해요.", tag: "[whispers] [flustered] 속으로요. [whispers] 지금, 삼십이. [whispers] ...말 시키면 처음부터 다시 세야 해요." },
  { id: "y6-67840fc622", who: "yeonseo", text: "…그 얘기를 듣고 나면, 딜러님은—", tag: "[whispers] [sad] ...그 얘기를 듣고 나면, 딜러님은—" },
  { id: "y6-11029db540", who: "yeonseo", text: "아니에요. 수요일에요.", tag: "[firm] 아니에요. 수요일에요." },
  { id: "y6-dbe027251c", who: "yeonseo", text: "방금 그 1분 동안, 무슨 생각 했어요?", tag: "[curious] 방금 그 일 분 동안, 무슨 생각 했어요?" },
  { id: "y6-dd29d7cf7d", who: "yeonseo", text: "저도요. 같은 걸 생각했을 확률, 계산 안 해도 높네요.", tag: "[warm] 저도요. [chuckles] 같은 걸 생각했을 확률, 계산 안 해도 높네요." },
  { id: "y6-6dbbad1e2e", who: "yeonseo", text: "…오면 안 되는데. 사장님 사람들, 이 건물 주차장도 알아요.", tag: "[whispers] [tense] ...오면 안 되는데. [whispers] 사장님 사람들, 이 건물 주차장도 알아요." },
  { id: "y6-cf6ada94da", who: "yeonseo", text: "얼굴 보면 말해 버릴 것 같아서 안 열어요. 수요일까진.", tag: "[sad] 얼굴 보면, 말해 버릴 것 같아서 안 열어요. 수요일까진." },
  { id: "y6-9cb50ebc79", who: "yeonseo", text: "이거 하나만 받아 가요. 오늘 할당량이에요.", tag: "[shy] 이거 하나만 받아 가요. 오늘 할당량이에요." },
  { id: "y6-adfdfe4ee6", who: "yeonseo", text: "수요일 두 시. …2분 일찍 와도 돼요.", tag: "[small smile] 수요일 두 시. ...이 분 일찍 와도 돼요." },
  { id: "y6-95b725f004", who: "yeonseo", text: "…전화는 처음이라서요. 첫마디를 정해 놓고 걸었는데, 잊어버렸어요.", tag: "[nervous] ...전화는 처음이라서요. 첫마디를 정해 놓고 걸었는데, 잊어버렸어요." },
  { id: "y6-0610a87083", who: "yeonseo", text: "'늦은 시간에 죄송해요.' 너무 평범해서 잊어버린 것 같아요.", tag: "[sheepish] 늦은 시간에 죄송해요. 너무 평범해서, 잊어버린 것 같아요." },
  { id: "y6-fcb8ed6c6d", who: "yeonseo", text: "…목소리 듣고 싶었어요. 이건 기록 안 할게요.", tag: "[shy] ...목소리 듣고 싶었어요. 이건, 기록 안 할게요." },
  { id: "y6-32c103b03b", who: "yeonseo", text: "지금 뭐 하고 있었어요?", tag: "[curious] 지금, 뭐 하고 있었어요?" },
  { id: "y6-7e4c385649", who: "yeonseo", text: "저도요. 천장 보는 사람 둘이 전화하는 거, 효율이 너무 안 좋아요.", tag: "[dry humor] 저도요. 천장 보는 사람 둘이 전화하는 거, 효율이 너무 안 좋아요." },
  { id: "y6-9ed555ab5a", who: "yeonseo", text: "효율은… 오늘만 포기할게요.", tag: "[shy] 효율은... 오늘만 포기할게요." },
];
const V2_P5: VoiceLine[] = [
  { id: "y6-ae4edfba3e", who: "yeonseo", text: "…그 소리요. 어제 못 들은 거.", tag: "[content] ...그 소리요. [falling tone] 어제 못 들은 거." },
  { id: "y6-30a5496c8d", who: "yeonseo", text: "이제 잘 수 있을 것 같아요. 87퍼센트쯤.", tag: "[sleepy] 이제 잘 수 있을 것 같아요. [sleepy] [falling tone] 팔십칠 퍼센트쯤." },
  { id: "y6-305e2b33e0", who: "yeonseo", text: "…무슨 얘기든, 이라고 했어요. 그 말 내일 다시 할 수 있어요?", tag: "[serious] ...무슨 얘기든, 이라고 했어요. 그 말, 내일 다시 할 수 있어요?" },
  { id: "y6-73f46bdc5f", who: "yeonseo", text: "그럼 그 말 하나 믿고 자 볼게요. 통계 없이.", tag: "[sleepy] 그럼, 그 말 하나 믿고 자 볼게요. [sleepy] [falling tone] 통계 없이." },
  { id: "y6-9ff7e93cdd", who: "yeonseo", text: "내일 무슨 얘기를 들어도, 이 전화는 따로 기억해 줘요. 장부 따로 쓰듯이.", tag: "[earnest] 내일 무슨 얘기를 들어도, 이 전화는 따로 기억해 줘요. [falling tone] 장부 따로 쓰듯이." },
  { id: "y6-898129ee06", who: "yeonseo", text: "내일 두 시. 집으로 와요. 약속한 수요일이에요.", tag: "[firm] 내일 두 시. 집으로 와요. 약속한 수요일이에요." },
  { id: "y6-7ea3f450aa", who: "yeonseo", text: "…끊을게요. 근데 엄지가 버튼 위에서 안 내려가요.", tag: "[reluctant] ...끊을게요. 근데, 엄지가 버튼 위에서 안 내려가요." },
  { id: "y6-b501bfd3fe", who: "yeonseo", text: "…앉아요. 오래 안 걸려요. 오래 걸리면 못 하니까.", tag: "[steeling herself] ...앉아요. 오래 안 걸려요. [falling tone] 오래 걸리면, 못 하니까." },
  { id: "y6-c19f27530a", who: "yeonseo", text: "오늘은 없어요. 커피 데우는 동안 마음이 바뀔까 봐요.", tag: "[tense] 오늘은 없어요. 커피 데우는 동안, 마음이 바뀔까 봐요." },
  { id: "y6-0ec4b27f16", who: "yeonseo", text: "5년 전이에요. 저는 스물네 살이었어요.", tag: "[steady] 오 년 전이에요. 저는, 스물네 살이었어요." },
  { id: "y6-764d8dbf17", who: "yeonseo", text: "사장님이 그 손님 맞은편에 저를 앉혔어요. 금발 아저씨. 계속 웃었어요.", tag: "[flat] 사장님이 그 손님 맞은편에 저를 앉혔어요. 금발 아저씨. 계속 웃었어요." },
  { id: "y6-d2c2f0724d", who: "yeonseo", text: "판마다 지갑에서 사진을 꺼냈어요. 트윈테일 묶은 여자애. '마이 리틀 갬블러'라고.", tag: "[sad] 판마다 지갑에서 사진을 꺼냈어요. 트윈테일 묶은 여자애. [falling tone] 마이 리틀 갬블러, 라고." },
  { id: "y6-7304e6aa30", who: "yeonseo", text: "새벽 네 시에, 사장님이 물잔에 손가락 세 개를 올렸어요.", tag: "[flat] 새벽 네 시에, 사장님이 물잔에, 손가락 세 개를 올렸어요." },
  { id: "y6-008099ab99", who: "yeonseo", text: "…가져왔어요. 하나도 안 틀리고.", tag: "[cold] ...가져왔어요. [falling tone] 하나도 안 틀리고." },
  { id: "y6-5e603ac90c", who: "yeonseo", text: "그분이 일어나면서 저한테 칩 하나를 밀어 줬어요. 팁이라고.", tag: "[sad] 그분이 일어나면서, 저한테 칩 하나를 밀어 줬어요. [falling tone] 팁이라고." },
  { id: "y6-223cb2e461", who: "yeonseo", text: "'딸이 이제 열일곱이에요. 그 애도 이길 때 꼭 당신 같은 얼굴을 해요.'", tag: "[sad] [quoting] 딸이 이제 열일곱이에요. 그 애도 이길 때, 꼭 당신 같은 얼굴을 해요." },
  { id: "y6-54e32da9e6", who: "yeonseo", text: "그분, 그 뒤로 안 왔어요. 어디 있는지 몰라요. 사장님은 알겠죠.", tag: "[flat] 그분, 그 뒤로 안 왔어요. 어디 있는지 몰라요. 사장님은 알겠죠." },
  { id: "y6-fa03421ddfc", who: "yeonseo", text: "에이미 씨 아빠예요. 일요일에 에이미 씨가 보여 준, 그 사진.", tag: "[trembling] 에이미 씨... 아빠예요. [trembling] 일요일에 에이미 씨가 보여 준... 그 사진." },
  { id: "y6-fe3b2398abc", who: "yeonseo", text: "그 애 월세를 딴 날, 그 애가 저한테 축하한다고 했어요. 진짜로. 그 말이… 제일 아팠어요.", tag: "[pained] [holding back tears] 그 애 월세를 딴 날, 그 애가 저한테 축하한다고 했어요. [holding back tears] 진짜로. [holding back tears] 그 말이... 제일, 아팠어요." },
  { id: "y6-8207d3a415", who: "yeonseo", text: "오늘 밤, 사장님이 에이미 씨한테 아빠 자리를 보여 줘요. 그 맞은편에 저를 세운대요.", tag: "[tense] 오늘 밤, 사장님이 에이미 씨한테 아빠 자리를 보여 줘요. 그 맞은편에 저를 세운대요." },
  { id: "y6-a5119ab5b4", who: "yeonseo", text: "5년 전이랑 똑같이. 같은 자리, 같은 손가락.", tag: "[cold] 오 년 전이랑 똑같이. [falling tone] 같은 자리, 같은 손가락." },
  { id: "y6-45adcb125e", who: "yeonseo", text: "…이제 다 알았어요. 제가 어떤 손인지.", tag: "[hollow] ...이제 다 알았어요. [falling tone] 제가 어떤 손인지." },
  { id: "y6-008e553d90", who: "yeonseo", text: "…왜요? 방금 다 들었으면서.", tag: "[surprised] ...왜요? 방금 다 들었으면서." },
  { id: "y6-ea42baaef7", who: "yeonseo", text: "…그날 현관에서처럼요? 아무 말 없이, 그냥 서 있는 거.", tag: "[sad] ...그날 현관에서처럼요? 아무 말 없이, 그냥 서 있는 거." },
  { id: "y6-18127bfd6dc", who: "yeonseo", text: "그럼 오늘은… 다르게 해 볼게요.", tag: "[trembling] 그럼 오늘은... 다르게, 해 볼게요." },
  { id: "y6-c4ea2f5a33", who: "yeonseo", text: "5년 전에 못 한 거. 7년 동안 한 번도 못 한 거.", tag: "[determined] 오 년 전에 못 한 거. [falling tone] 칠 년 동안 한 번도 못 한 거." },
  { id: "y6-c83f128728", who: "yeonseo", text: "비밀은 오늘 하나로 충분해요. 이건 밤에 봐요.", tag: "[evasive] 비밀은, 오늘 하나로 충분해요. 이건 밤에 봐요." },
  { id: "y6-d9046ff478", who: "yeonseo", text: "…네.", tag: "[subdued] ...네." },
  { id: "y6-e9a9b6e5fe", who: "yeonseo", text: "그게 맞아요. 그 애 옆엔 누가 있어야 해요. 5년 전엔 아무도 없었으니까.", tag: "[sad] 그게 맞아요. 그 애 옆엔 누가 있어야 해요. [falling tone] 오 년 전엔, 아무도 없었으니까." },
  { id: "y6-07ff3a4492", who: "yeonseo", text: "가요. 저는 괜찮아요. 늘 괜찮았어요.", tag: "[cold] [composed] 가요. 저는 괜찮아요. 늘 괜찮았어요." },
  { id: "y6-8819c51263", who: "yeonseo", text: "…그래요. 그게 맞아요.", tag: "[resigned] ...그래요. 그게 맞아요." },
  { id: "y6-3e8c1ec9a9", who: "yeonseo", text: "저라도 그럴 거예요. 생각할 시간. 저는 7년 동안 그것만 했어요.", tag: "[distant] 저라도 그럴 거예요. 생각할 시간. 저는 칠 년 동안, 그것만 했어요." },
  { id: "y6-8b66fe7e63", who: "yeonseo", text: "…기다렸어요?", tag: "[surprised] ...기다렸어요?" },
  { id: "y6-9fdc868ba7", who: "yeonseo", text: "…두 개 꽂혀 있었네요. 이모죠.", tag: "[small smile] ...두 개 꽂혀 있었네요. 이모죠." },
  { id: "y6-d9a48d9c0a", who: "yeonseo", text: "사장님 장부예요. 금고에 있던 거.", tag: "[calm] 사장님 장부예요. [falling tone] 금고에 있던 거." },
  { id: "y6-19132acbcb", who: "yeonseo", text: "금고 비밀번호도 7194였어요. 딜러님이 맞힌 그 숫자.", tag: "[deadpan] 금고 비밀번호도 칠일구사였어요. [falling tone] 딜러님이 맞힌 그 숫자." },
  { id: "y6-9092bb9467", who: "yeonseo", text: "금고 비밀번호도 문이랑 같았어요. 사장님은 아무것도 안 바꿔요.", tag: "[dry] 금고 비밀번호도, 문이랑 같았어요. 사장님은 아무것도 안 바꿔요." },
  { id: "y6-1ce9c9e400", who: "yeonseo", text: "에이미 씨 올려 보내고, 사장님이랑 네 시간 마주 앉아 있었어요. 아무 말도 안 하고.", tag: "[calm] 에이미 씨 올려 보내고, 사장님이랑 네 시간 마주 앉아 있었어요. [falling tone] 아무 말도 안 하고." },
  { id: "y6-171583c7f5", who: "yeonseo", text: "사장님이 먼저 일어나서 나갔어요. 그 틈에 열었어요.", tag: "[calm] 사장님이 먼저 일어나서 나갔어요. 그 틈에 열었어요." },
  { id: "y6-c7f0e4d814", who: "yeonseo", text: "그리고 이건 알아 둬요. 아래층 판이 어떻게 돌아가는지.", tag: "[serious] 그리고 이건 알아 둬요. [falling tone] 아래층 판이 어떻게 돌아가는지." },
  { id: "y6-4ba003ca2e", who: "yeonseo", text: "손님이 컷하면, 딜러가 칩 트레이 정리하는 척 무릎 위의 덱이랑 바꿔요.", tag: "[deadpan] 손님이 컷하면, 딜러가 칩 트레이 정리하는 척, 무릎 위의 덱이랑 바꿔요." },
  { id: "y6-9d36a9f0ca", who: "yeonseo", text: "사장님은 물잔에 손가락을 올려요. 하나는 져 줘라, 둘은 비슷하게, 셋은 전부.", tag: "[deadpan] 사장님은 물잔에 손가락을 올려요. 하나는 져 줘라, 둘은 비슷하게, [falling tone] 셋은 전부." },
  { id: "y6-d70f392112", who: "yeonseo", text: "사장님 얼굴, 봤어야 했어요. 손가락 세 개 펴 놓고 그대로 굳었어요.", tag: "[delighted] [still laughing] 사장님 얼굴, 봤어야 했어요. 손가락 세 개 펴 놓고, 그대로 굳었어요." },
  { id: "y6-3a7b058637", who: "yeonseo", text: "7년 동안 그 손가락만 봤는데. 오늘은 안 봤어요. 하나도.", tag: "[glowing] 칠 년 동안 그 손가락만 봤는데. 오늘은 안 봤어요. [falling tone] 하나도." },
  { id: "y6-53318db0a6", who: "yeonseo", text: "…비품 창고 때보다 심장 소리가 커요. 분당 백삼십.", tag: "[whispers] [shy] ...비품 창고 때보다 심장 소리가 커요. [whispers] [falling tone] 분당 백삼십." },
  { id: "y6-64945757af", who: "yeonseo", text: "이번엔 숨 참으라고 안 할게요.", tag: "[smiling] 이번엔, 숨 참으라고 안 할게요." },
  { id: "y6-3d280c59da", who: "yeonseo", text: "…심장 소리 커요. 딜러님 거예요, 제 거예요.", tag: "[whispers] [shy] ...심장 소리 커요. [whispers] 딜러님 거예요, 제 거예요." },
  { id: "y6-b0b93cc6f0", who: "yeonseo", text: "…그럼 세기 어렵겠네요. 오늘은 안 셀게요.", tag: "[smiling] ...그럼 세기 어렵겠네요. 오늘은 안 셀게요." },
  { id: "y6-3df1b3d558", who: "yeonseo", text: "…시키면 안 나와요, 웃음은.", tag: "[flustered] ...시키면 안 나와요, 웃음은." },
  { id: "y6-4ad328fca2", who: "yeonseo", text: "…아하.", tag: "[a small laugh slipping out] ...아하." },
  { id: "y6-4655deed2e", who: "yeonseo", text: "방금 건 반쯤이에요. 나머지 반은… 가면서요.", tag: "[shy] 방금 건, 반쯤이에요. 나머지 반은... 가면서요." },
  { id: "y6-5fb8cf259a", who: "yeonseo", text: "집에 가요. …같이.", tag: "[shy] 집에 가요. ...같이." },
  { id: "y6-609e36a18d", who: "yeonseo", text: "네. 싫다는 생각, 해 본 적이 없어서요. 신기해서 몇 번 더 해 봤어요.", tag: "[sleepy] [shy] 네. [sleepy] 싫다는 생각, 해 본 적이 없어서요. [sleepy] 신기해서, 몇 번 더 해 봤어요." },
  { id: "y6-90bd9b7343", who: "yeonseo", text: "싫어요. 싫어요. 싫어요. 세 번 다 싫어요.", tag: "[playful] 싫어요. 싫어요. 싫어요. 세 번 다 싫어요." },
  { id: "y6-0d391c7a73", who: "yeonseo", text: "딜러님 잠들고 나서요. 손이 떨려서 두 번 그리느라, 3분 걸렸어요.", tag: "[sleepy] [shy] 딜러님 잠들고 나서요. [sleepy] 손이 떨려서 두 번 그리느라, 삼 분 걸렸어요." },
  { id: "y6-f1cc7ff345", who: "yeonseo", text: "…한 번이에요. 아껴 쓸 거예요. 이제 막 생긴 거니까.", tag: "[shy] [tender] ...한 번이에요. 아껴 쓸 거예요. [falling tone] 이제 막 생긴 거니까." },
  { id: "y6-de464b96d6", who: "yeonseo", text: "…알아요. 아껴 쓰는 중이에요. 자주 부르면 효과가 떨어지거든요. 통계예요.", tag: "[shy] [teasing] ...알아요. 아껴 쓰는 중이에요. 자주 부르면, 효과가 떨어지거든요. 통계예요." },
  { id: "y6-5617800428", who: "yeonseo", text: "사장님은 오늘 안에 알아챌 거예요. 장부를 매일 세는 사람이니까.", tag: "[calm] 사장님은 오늘 안에 알아챌 거예요. [falling tone] 장부를 매일 세는 사람이니까." },
  { id: "y6-69e781e5ce", who: "yeonseo", text: "그러니까 오늘 밤엔 평소처럼 해 줘요. 아무것도 모르는 얼굴로. 저는 가게 안 나갈게요.", tag: "[serious] 그러니까 오늘 밤엔, 평소처럼 해 줘요. 아무것도 모르는 얼굴로. 저는 가게 안 나갈게요." },
  { id: "y6-b0213eb1df", who: "yeonseo", text: "연습해요. 지금. …아뇨, 그 얼굴 말고. 그건 다 아는 얼굴이에요.", tag: "[playful] 연습해요. 지금. [amused] ...아뇨, 그 얼굴 말고. 그건 다 아는 얼굴이에요." },
  { id: "y6-a9c006b5fa", who: "yeonseo", text: "오늘은 안 쳐요.", tag: "[cold] [firm] 오늘은 안 쳐요." },
  { id: "y6-6f2c101e06", who: "yeonseo", text: "에이미 씨, 올라가요. 아빠 자리는 손님 없을 때 혼자 봐요. 그게 맞아요.", tag: "[gentle but firm] 에이미 씨, 올라가요. 아빠 자리는, 손님 없을 때 혼자 봐요. 그게 맞아요." },
  { id: "y6-1d3d8c5b7c", who: "yeonseo", text: "고양이 이름, 다음 주까지 정한다고 했었죠. 기한 넘겼어요. 제 계산 중에 제일 늦게 끝난 거예요.", tag: "[wry] 고양이 이름, 다음 주까지 정한다고 했었죠. 기한 넘겼어요. 제 계산 중에, 제일 늦게 끝난 거예요." },
  { id: "y6-2696852ca9", who: "yeonseo", text: "'콜'로 했어요. 부르면 오니까. 이모한테 그렇게 부르라고 해 뒀어요. 가게 뒤 박스에 담요도 하나 더 깔아 준대요.", tag: "[warm] 콜, 로 했어요. 부르면 오니까. 이모한테 그렇게 부르라고 해 뒀어요. 가게 뒤 박스에, 담요도 하나 더 깔아 준대요." },
  { id: "y6-0a2eb998ce", who: "yeonseo", text: "…이름 붙이면 정 들까 봐 미뤘는데. 안 붙여도 들었더라고요.", tag: "[wistful] ...이름 붙이면 정 들까 봐 미뤘는데. 안 붙여도, 들었더라고요." },
  { id: "y6-679a284dac", who: "yeonseo", text: "콜은 이모한테 맡겼어요. 가게 뒤 박스에 담요를 하나 더 깔아 준대요.", tag: "[calm] 콜은 이모한테 맡겼어요. 가게 뒤 박스에, 담요를 하나 더 깔아 준대요." },
  { id: "y6-e539433110", who: "yeonseo", text: "…이제 이모가 불러도 와요. 다행이에요. 저만 부를 줄 아는 고양이면 곤란하니까.", tag: "[wistful] ...이제 이모가 불러도 와요. 다행이에요. [falling tone] 저만 부를 줄 아는 고양이면, 곤란하니까." },
  { id: "y6-a381249638", who: "yeonseo", text: "'기타'에 뭐 들었는지는 묻지 마요.", tag: "[guarded] 기타에, 뭐 들었는지는 묻지 마요." },
  { id: "y6-707d8945e2", who: "yeonseo", text: "…묻지 말라니까요. 박하사탕 포장지랑, 볼펜 뚜껑이에요. 버리려다 못 버린 거.", tag: "[flustered] ...묻지 말라니까요. 박하사탕 포장지랑, 볼펜 뚜껑이에요. [falling tone] 버리려다 못 버린 거." },
  { id: "y6-38a1875c94", who: "yeonseo", text: "두고 갈 거예요. 동그라미가 너무 많아져서, 가져가면 무거워요.", tag: "[evasive] 두고 갈 거예요. 동그라미가 너무 많아져서, 가져가면 무거워요." },
  { id: "y6-4d041e7ca7", who: "yeonseo", text: "…거짓말이에요. 가져가면 매일 볼 거고, 그럼 못 떠나요.", tag: "[sad] [confessing] ...거짓말이에요. 가져가면 매일 볼 거고, 그럼 못 떠나요." },
  { id: "y6-be33c12c38", who: "yeonseo", text: "커피, 마지막 거예요. 머그잔은 깨진 것만 남겨 뒀어요.", tag: "[calm] 커피, 마지막 거예요. 머그잔은, 깨진 것만 남겨 뒀어요." },
  { id: "y6-6a3a74980b", who: "yeonseo", text: "싸 버렸어요. 깨진 건 가져갈 이유가 없어서요.", tag: "[flat] 싸 버렸어요. 깨진 건, 가져갈 이유가 없어서요." },
  { id: "y6-db3de14d4e", who: "yeonseo", text: "요즘은 다 읽히네요. 장갑을 바꿔야 할까 봐요.", tag: "[sad] [rueful] 요즘은 다 읽히네요. 장갑을 바꿔야 할까 봐요." },
  { id: "y6-5be4fe4276", who: "yeonseo", text: "…봤네요. 결국.", tag: "[resigned] ...봤네요. [falling tone] 결국." },
  { id: "y6-53537189c3", who: "yeonseo", text: "수요일 밤. 에이미 씨 등에 있던 손, 봤어요.", tag: "[sad] 수요일 밤. 에이미 씨 등에 있던 손, 봤어요." },
  { id: "y6-355806ba51", who: "yeonseo", text: "잘한 거예요. 그래서 표는 한 장만 끊었어요.", tag: "[composed] 잘한 거예요. 그래서 표는, 한 장만 끊었어요." },
  { id: "y6-ffe77e6f84", who: "yeonseo", text: "…네. 맞아요. 도망이에요. 그래서 혼자 끊었어요.", tag: "[sad] ...네. 맞아요. 도망이에요. 그래서, 혼자 끊었어요." },
  { id: "y6-54547e1d23", who: "yeonseo", text: "장부를 들고 사라지면, 사장님은 저를 쫓아요. 딜러님 쪽은 신경 쓸 틈이 없어요.", tag: "[calm] 장부를 들고 사라지면, 사장님은 저를 쫓아요. 딜러님 쪽은, 신경 쓸 틈이 없어요." },
  { id: "y6-91fe247c93", who: "yeonseo", text: "장부가 제 손에 있는 동안은 저를 함부로 못 해요. 제 마지막 블러프예요.", tag: "[cold] 장부가 제 손에 있는 동안은, 저를 함부로 못 해요. 제 마지막 블러프예요." },
  { id: "y6-2b3d8855da", who: "yeonseo", text: "어디로 가는지는 말 안 할게요. 말하면 따라올 거니까.", tag: "[evasive] 어디로 가는지는 말 안 할게요. [falling tone] 말하면, 따라올 거니까." },
  { id: "y6-c461f2bb38", who: "yeonseo", text: "…처음부터 이렇게 끝날 판이었어요. 숫자가 정해져 있는 판.", tag: "[hollow] ...처음부터 이렇게 끝날 판이었어요. [falling tone] 숫자가 정해져 있는 판." },
  { id: "y6-ab2f67b59d", who: "yeonseo", text: "…같이 들면, 같이 쫓겨요.", tag: "[hesitant] ...같이 들면, 같이 쫓겨요." },
  { id: "y6-029648db01", who: "yeonseo", text: "7년 동안 제가 친 판이에요. 날짜, 손님, 손가락 수. 하나도 안 빼고.", tag: "[steady] 칠 년 동안 제가 친 판이에요. 날짜, 손님, 손가락 수. [falling tone] 하나도 안 빼고." },
  { id: "y6-b10b4a99ea", who: "yeonseo", text: "사장님 장부랑 짝이 맞는 장부. 검은 건 제가 들게요. 이건… 맡길게요.", tag: "[shy] [trusting] 사장님 장부랑 짝이 맞는 장부. 검은 건 제가 들게요. 이건... 맡길게요." },
  { id: "y6-cf1d248a68", who: "yeonseo", text: "7년 치예요. 가벼우면 거짓말이죠.", tag: "[small smile] 칠 년 치예요. 가벼우면 거짓말이죠." },
  { id: "y6-71df23839a", who: "yeonseo", text: "…같이요?", tag: "[surprised] ...같이요?" },
  { id: "y6-60edc0b6ad", who: "yeonseo", text: "빚은 안 없어져요. 도망가도. 이자도 따라오고요.", tag: "[serious] 빚은 안 없어져요. 도망가도. 이자도 따라오고요." },
  { id: "y6-f36f96c703", who: "yeonseo", text: "그 말, 7년 동안 무섭기만 했는데.", tag: "[smiling] [moved] 그 말, 칠 년 동안 무섭기만 했는데." },
  { id: "y6-7c334b7214", who: "yeonseo", text: "…그 말, 제가 먼저 했는데. 돌려받으니까 이상하네요.", tag: "[quiet] [wry] ...그 말, 제가 먼저 했는데. 돌려받으니까, 이상하네요." },
  { id: "y6-2f32068b1a", who: "yeonseo", text: "…생각해 볼게요. 일요일까지.", tag: "[quiet] [evasive] ...생각해 볼게요. [falling tone] 일요일까지." },
  { id: "y6-e0757a1f98", who: "yeonseo", text: "…마지막으로 한 번만, 섞어 줘요. 여기서.", tag: "[soft] [hesitant] ...마지막으로 한 번만, 섞어 줘요. 여기서." },
  { id: "y6-ef9d8c00ce", who: "yeonseo", text: "…역시 제일 좋은 소리예요. 이 방에서 들은 소리 중에.", tag: "[soft] [moved] ...역시, 제일 좋은 소리예요. [falling tone] 이 방에서 들은 소리 중에." },
  { id: "y6-8c82337ca3", who: "yeonseo", text: "마지막으로 하나 알려 줄게요. 7년 치 중에 제일 비싼 거.", tag: "[calm] [serious] 마지막으로, 하나 알려 줄게요. [falling tone] 칠 년 치 중에, 제일 비싼 거." },
  { id: "y6-12939222f8", who: "yeonseo", text: "사장님은 이길 때, 웃고 나서 말해요. 블러프일 때는 말이 먼저 나와요. 웃음은 반 박자 뒤에.", tag: "[calm] [precise] 사장님은 이길 때, 웃고 나서 말해요. 블러프일 때는, 말이 먼저 나와요. [falling tone] 웃음은 반 박자 뒤에." },
  { id: "y6-c0746b45a0", who: "yeonseo", text: "7년 동안 딱 두 번 봤어요. 말이 먼저 나오는 거.", tag: "[quiet] 칠 년 동안, 딱 두 번 봤어요. [falling tone] 말이 먼저 나오는 거." },
  { id: "y6-191615ed33", who: "yeonseo", text: "…혹시 몰라서요. 딜러님이 그 의자에 앉게 될 확률, 0이 아니라서.", tag: "[quiet] [sad] ...혹시 몰라서요. 딜러님이 그 의자에 앉게 될 확률, [falling tone] 영이 아니라서." },
  { id: "y6-1857d68c7b", who: "yeonseo", text: "일요일 새벽에 연락할게요. 연락 못 하면… 동그라미 친 날만 기억해 줘요.", tag: "[soft] [sad smile] 일요일 새벽에, 연락할게요. 연락 못 하면... 동그라미 친 날만, 기억해 줘요." },
  { id: "y6-24c0456fe9c", who: "yeonseo", text: "…왜 왔어요? 바보.", tag: "[crying] ...왜 왔어요...? 바보..." },
  { id: "y6-36a2ab64aac", who: "yeonseo", text: "딜러님이 연락받기 전에 끝내려고 했는데. 계산이 또 틀렸어요.", tag: "[crying] 딜러님이 연락받기 전에, 끝내려고 했는데... 계산이, 또 틀렸어요." },
  { id: "y6-428e6d733ec", who: "yeonseo", text: "가지 말라고 해서… 그 말은 못 들어줘도, 딜러님 빚만은 두고 가고 싶었어요.", tag: "[sobbing] 가지 말라고 해서... 그 말은 못 들어줘도... 딜러님 빚만은, 두고 가고 싶었어요..." },
  { id: "y6-bd19e62d44c", who: "yeonseo", text: "……바보.", tag: "[crying] ......바보." },
  { id: "y6-88656053cc", who: "yeonseo", text: "……봤어요? 그걸.", tag: "[stunned] [quiet] ......봤어요? 그걸." },
  { id: "y6-c972035b7b", who: "yeonseo", text: "…공정하게 돌릴게요. 처음으로.", tag: "[steady] [resolute] ...공정하게 돌릴게요. 처음으로." },
  { id: "y6-83d661fc32c", who: "yeonseo", text: "…바보예요. 진짜로.", tag: "[trembling] [tearful] ...바보예요. [trembling] [tearful] 진짜로..." },
  { id: "y6-35d93ff5ecc", who: "yeonseo", text: "지면 어쩌려고 했어요? 그 손, 다시는 테이블에 못 올리는 거였어요.", tag: "[crying] [scolding] 지면, 어쩌려고 했어요...? 그 손, 다시는 테이블에 못 올리는 거였어요." },
  { id: "y6-6ca40e022b", who: "yeonseo", text: "미지근해요.", tag: "[soft] [small smile] 미지근해요." },
  { id: "y6-3fc6ea51ad", who: "yeonseo", text: "그럼 어젯밤부터 기다린 물이에요. 제일 맛있는 물이에요.", tag: "[warm] [smiling] 그럼 어젯밤부터 기다린 물이에요. 제일 맛있는 물이에요." },
  { id: "y6-ed91f2df1c", who: "yeonseo", text: "……아직 들고 다녀요?", tag: "[surprised] [touched] ......아직 들고 다녀요?" },
  { id: "y6-5484ec9217", who: "yeonseo", text: "…그럼 다음 판은 이 방 말고, 위층에서 해요. 칩 대신 성냥으로. 이긴 사람이 질문 하나.", tag: "[warm] [smiling] ...그럼 다음 판은, 이 방 말고 위층에서 해요. 칩 대신 성냥으로. 이긴 사람이, 질문 하나." },
  { id: "y6-fe826599a2", who: "yeonseo", text: "첫 질문은 벌써 정해 놨어요. 이기면 물어볼게요.", tag: "[shy] 첫 질문은, 벌써 정해 놨어요. 이기면 물어볼게요." },
  { id: "y6-2e490cae7b", who: "yeonseo", text: "…첫차, 아직 안 놓쳤어요. 시간 맞춰 갈게요.", tag: "[quiet] [sad] ...첫차, 아직 안 놓쳤어요. 시간 맞춰 갈게요." },
  { id: "y6-089c84e239", who: "yeonseo", text: "네. 같은 날짜예요.", tag: "[steady] [quiet] 네. 같은 날짜예요." },
  { id: "y6-b09ffbc4f8", who: "yeonseo", text: "아뇨.", tag: "[cold] [firm] 아뇨." },
  { id: "y6-db81a435ad", who: "yeonseo", text: "사장님은 이제 시간 없어요.", tag: "[cold] [calm] 사장님은, 이제 시간 없어요." },
  { id: "y6-8f3c57d240", who: "yeonseo", text: "금색이에요. 뒷면에 V. 5년 동안 갖고 있었어요. 돌려줄 사람을 몰라서.", tag: "[quiet] [steady] 금색이에요. 뒷면에, 브이. 오 년 동안 갖고 있었어요. [falling tone] 돌려줄 사람을 몰라서." },
  { id: "y6-7868096808", who: "yeonseo", text: "미안하다는 말로 안 되는 거, 알아요. 그래도 할게요. 미안해요.", tag: "[sincere] [sad] 미안하다는 말로 안 되는 거, 알아요. 그래도 할게요. 미안해요." },
  { id: "y6-140afe43a1", who: "yeonseo", text: "…두부는 많이요?", tag: "[soft] [hopeful] ...두부는, 많이요?" },
  { id: "y6-f9b750a9ed", who: "yeonseo", text: "이모가 싸 줬어요. 김치찌개 두 그릇. …그리고 늦었어요. 2분.", tag: "[cheerful] [teasing] 이모가 싸 줬어요. 김치찌개 두 그릇. [mock stern] ...그리고, 늦었어요. 이 분." },
  { id: "y6-116ecfb6c7", who: "yeonseo", text: "네. 이제 제 시간이니까요.", tag: "[bright] [smiling] 네. 이제, 제 시간이니까요." },
  { id: "y6-9febead7aa", who: "yeonseo", text: "세지 마요. 이제 세는 건 그만할래요. 다 셀 수 없을 만큼 할 거니까.", tag: "[happy] [tender] 세지 마요. 이제 세는 건 그만할래요. 다 셀 수 없을 만큼, 할 거니까." },
  { id: "y6-7a89c5b6cc", who: "yeonseo", text: "횟집 할머니가 또 칭찬했다면서요. 칼 쥐는 손이 카드 쥐는 손이랑 똑같다고.", tag: "[warm] [teasing] 횟집 할머니가, 또 칭찬했다면서요. 칼 쥐는 손이, 카드 쥐는 손이랑 똑같다고." },
  { id: "y6-687226fe23", who: "yeonseo", text: "숫자 하나도 안 틀린다고, 벌써 유명해요. 마을이 작아서요.", tag: "[proud] [light] 숫자 하나도 안 틀린다고, 벌써 유명해요. 마을이 작아서요." },
  { id: "y6-0109ef0b1e", who: "yeonseo", text: "이번 달 이자, 보냈어요. 남은 거 계산해 봤는데요.", tag: "[calm] 이번 달 이자, 보냈어요. 남은 거, 계산해 봤는데요." },
  { id: "y6-4142ad6084", who: "yeonseo", text: "…서른여덟 살이요. 둘이 갚으면. 생각보다 빨라요.", tag: "[warm] [smiling] ...서른여덟 살이요. 둘이 갚으면. 생각보다 빨라요." },
  { id: "y6-cde5765ccc", who: "yeonseo", text: "그 말, 이제 우리 거예요. 그 사람 거 말고.", tag: "[warm] [firm] 그 말, 이제 우리 거예요. 그 사람 거 말고." },
  { id: "y6-38ac636228", who: "yeonseo", text: "빨간 동그라미가 빼곡해요. X는 하나도 없고. 어떤 날은 동그라미가 두 개예요.", tag: "[shy] [happy] 빨간 동그라미가 빼곡해요. 엑스는 하나도 없고. 어떤 날은, 동그라미가 두 개예요." },
  { id: "y6-dfe7753fe4", who: "yeonseo", text: "기밀이에요. …오늘 밤에 하나 더 칠 거예요.", tag: "[shy] [teasing] 기밀이에요. [softer] ...오늘 밤에, 하나 더 칠 거예요." },
  { id: "y6-964900133d", who: "yeonseo", text: "뭘 봐요?", tag: "[shy] 뭘 봐요?" },
  { id: "y6-1841f3b39f", who: "yeonseo", text: "안 숨겨요. 이 마을엔 이 손 읽으려는 사람이 없으니까요.", tag: "[calm] [content] 안 숨겨요. 이 마을엔, 이 손 읽으려는 사람이 없으니까요." },
  { id: "y6-9a2913eb9a", who: "yeonseo", text: "…그러니까 보세요, 그럼. 실컷.", tag: "[shy] [sweet] ...그러니까 보세요, 그럼. 실컷." },
  { id: "y6-0c47a799a4", who: "yeonseo", text: "오늘도 김치찌개예요. 이모 레시피, 이제 안 보고 해요.", tag: "[warm] [proud] 오늘도 김치찌개예요. 이모 레시피, 이제 안 보고 해요." },
  { id: "y6-095f076708", who: "yeonseo", text: "셔플해 줘요. 그 소리 들어야 자요.", tag: "[shy] [sweet] 셔플해 줘요. 그 소리 들어야 자요." },
  { id: "y6-bb5b980fa6", who: "yeonseo", text: "…오늘 테이블에 몇 명 앉았어요?", tag: "[calm] [too even] ...오늘 테이블에, 몇 명 앉았어요?" },
  { id: "y6-dca976e993", who: "yeonseo", text: "그중에 여자는요. 금발은요.", tag: "[flat] [probing] 그중에 여자는요. [falling tone] 금발은요." },
  { id: "y6-15f66ea907", who: "yeonseo", text: "…지운 적 없어요.", tag: "[cold] [flat] ...지운 적 없어요." },
  { id: "y6-64283f1c42", who: "yeonseo", text: "오늘은 X예요. 열한 시 사십 분이니까.", tag: "[cold] [flat] 오늘은 엑스예요. 열한 시 사십 분이니까." },
  { id: "y6-f7e753a211", who: "yeonseo", text: "…다른 사람 테이블엔 서지 마요.", tag: "[quiet] [cold] [intense] ...다른 사람 테이블엔, 서지 마요." },
  { id: "y6-963df764cc", who: "yeonseo", text: "저 말고 다른 사람한테 카드 돌리지 마요.", tag: "[jealous] [sulky] 저 말고 다른 사람한테, 카드 돌리지 마요." },
  { id: "y6-f969371e68", who: "yeonseo", text: "그 손, 제 거예요. 장부 반을 버리고 산 거예요.", tag: "[cold] [possessive] 그 손, 제 거예요. 장부 반을 버리고, 산 거예요." },
  { id: "y6-ee7a91dd89", who: "yeonseo", text: "장부는 사장님한테 돌려줬어요. 딜러님이 앞치마를 안 벗길래, 들고 갈 이유가 없어졌어요.", tag: "[cold] [flat] 장부는, 사장님한테 돌려줬어요. 딜러님이 앞치마를 안 벗길래, 들고 갈 이유가 없어졌어요." },
  { id: "y6-794c5ab359", who: "yeonseo", text: "…같은 편이네요. 이제.", tag: "[cold] [wry] ...같은 편이네요. 이제." },
  { id: "y6-2ceedea237", who: "yeonseo", text: "딜러님이 돌리고, 제가 받고. 사장님이 제일 좋아하는 그림이에요.", tag: "[cold] [bitter] 딜러님이 돌리고, 제가 받고. 사장님이 제일 좋아하는 그림이에요." },
  { id: "y6-2b334b025a", who: "yeonseo", text: "봤어요. 반 뼘.", tag: "[flat] [quiet] 봤어요. [falling tone] 반 뼘." },
  { id: "y6-9f86b3ba69", who: "yeonseo", text: "7년 동안 수백 번 본 손이에요. 그런데 딜러님 손이라서, 낯설었어요.", tag: "[sad] [quiet] 칠 년 동안, 수백 번 본 손이에요. 그런데 딜러님 손이라서, 낯설었어요." },
  { id: "y6-a918eb2e9dc", who: "yeonseo", text: "끝까지 돌려줄 줄 알았어요. 그 앞치마. …그것만은 계산 안 했어요.", tag: "[hurt] 끝까지 돌려줄 줄 알았어요. 그 앞치마. ...그것만은, 계산 안 했어요." },
  { id: "y6-dc01a25553", who: "yeonseo", text: "…일어나요. 지금.", tag: "[urgent] [shaky] ...일어나요. 지금." },
  { id: "y6-e03aab6d13c", who: "yeonseo", text: "제가 7년 걸려서 배운 거, 4주 만에 따라 하지 마요.", tag: "[upset] [trembling] 제가 칠 년 걸려서 배운 거... 사 주 만에, 따라 하지 마요...!" },
  { id: "y6-21bb1a01bfc", who: "yeonseo", text: "사장님이 저한테 한 말이에요. 7년 전에. 토씨 하나 안 틀리고.", tag: "[devastated] 사장님이, 저한테 한 말이에요. 칠 년 전에... 토씨 하나, 안 틀리고." },
  { id: "y6-48cb9ea77b", who: "yeonseo", text: "에이미 씨야말로요.", tag: "[cold] 에이미 씨야말로요." },
  { id: "y6-7667747221", who: "yeonseo", text: "하우스 자리는 제 자리예요. 오늘도 앉으래요.", tag: "[cold] [deadpan] 하우스 자리는, 제 자리예요. 오늘도 앉으래요." },
  { id: "y6-34eb7fb6a0", who: "yeonseo", text: "…그리고 딜러님 얼굴, 판 전에 한 번 보고 싶었어요.", tag: "[quiet] [vulnerable] ...그리고 딜러님 얼굴, 판 전에 한 번 보고 싶었어요." },
  { id: "y6-d4e056471d", who: "yeonseo", text: "수요일 밤에, 저한테 왔었어요. 비 맞고. 에이미 씨가 뛰쳐나간 그 밤에요.", tag: "[cold] [deliberate] 수요일 밤에, 저한테 왔었어요. 비 맞고. 에이미 씨가 뛰쳐나간, 그 밤에요." },
  { id: "y6-1a6768a893", who: "yeonseo", text: "에이미 씨 얘기 할 때 딜러님 얼굴이랑, 저랑 있을 때 얼굴. 똑같았어요.", tag: "[cold] [quiet] 에이미 씨 얘기 할 때 딜러님 얼굴이랑, 저랑 있을 때 얼굴. 똑같았어요." },
  { id: "y6-8045615772", who: "yeonseo", text: "…저는 알았어요. 딜러님이 누구 쪽을 먼저 보는지.", tag: "[sad] [quiet] ...저는 알았어요. 딜러님이, 누구 쪽을 먼저 보는지." },
  { id: "y6-c97e4df50e", who: "yeonseo", text: "…저는 알았어요. 비 오던 날, 딜러님이 누구를 먼저 데려다줬는지.", tag: "[sad] [quiet] ...저는 알았어요. 비 오던 날, 딜러님이 누구를 먼저 데려다줬는지." },
  { id: "y6-adb6d53f17", who: "yeonseo", text: "그래도 왔어요. 바보같이.", tag: "[sad] [wry] 그래도 왔어요. [falling tone] 바보같이." },
  { id: "y6-619ce17fe3", who: "yeonseo", text: "오늘 새벽 판은 제 일이에요. 딜러님 일이 아니라요.", tag: "[cold] [firm] 오늘 새벽 판은, 제 일이에요. 딜러님 일이 아니라요." },
  { id: "y6-3028c0205c", who: "yeonseo", text: "수요일 낮에, 딜러님 저희 집에 있었어요. 그러다 에이미 씨한테 간다고 일어났고요.", tag: "[cold] [deliberate] 수요일 낮에, 딜러님 저희 집에 있었어요. 그러다 에이미 씨한테 간다고, 일어났고요." },
  { id: "y6-4629804562c", who: "yeonseo", text: "저는 딜러님 때문에, 사장님 앞에서 장부 반을 버렸어요. 거짓말 하나로요.", tag: "[upset] [trembling] 저는 딜러님 때문에, 사장님 앞에서 장부 반을 버렸어요...! 거짓말 하나로요." },
  { id: "y6-f8d418692c", who: "yeonseo", text: "…좋아요. 이번엔 정해진 숫자 없이 칠게요.", tag: "[cold] [resolute] ...좋아요. 이번엔, 정해진 숫자 없이 칠게요." },
  { id: "y6-24866efd33", who: "yeonseo", text: "…딜러님은 한 번도 고르지 않았어요.", tag: "[quiet] [hollow] ...딜러님은, 한 번도 고르지 않았어요." },
  { id: "y6-bb958e6ae2", who: "yeonseo", text: "고르지 않으면 지지 않는다고 생각했죠. 얼굴에 다 써 있었어요.", tag: "[sad] [bitter] 고르지 않으면, 지지 않는다고 생각했죠. 얼굴에, 다 써 있었어요." },
  { id: "y6-62b65a9c96", who: "yeonseo", text: "불러서요. 우산은 하나밖에 없었고요.", tag: "[quiet] [steady] 불러서요. 우산은, 하나밖에 없었고요." },
  { id: "y6-b84a3dc5f7", who: "yeonseo", text: "…그날 못 한 말이 있어서 왔어요.", tag: "[sad] [sincere] ...그날 못 한 말이 있어서, 왔어요." },
  { id: "y6-568fc1354d", who: "yeonseo", text: "…네. 그게 저예요.", tag: "[quiet] [steady] ...네. 그게 저예요." },
  { id: "y6-7d05370fe1", who: "yeonseo", text: "하나 더요. 이거요.", tag: "[quiet] 하나 더요. 이거요." },
  { id: "y6-944ffdf1f1", who: "yeonseo", text: "그분이 마지막 판이 끝나고, 이걸 저한테 팁으로 줬어요.", tag: "[sad] [quiet] 그분이, 마지막 판이 끝나고, 이걸 저한테 팁으로 줬어요." },
  { id: "y6-1d3a6cb3a1", who: "yeonseo", text: "진 사람이 팁을 주는 건… 그날 처음 봤어요.", tag: "[quiet] [sad] 진 사람이 팁을 주는 건... 그날 처음 봤어요." },
  { id: "y6-228daadcb7", who: "yeonseo", text: "…셋이서요?", tag: "[surprised] ...셋이서요?" },
  { id: "y6-7ab4bd01d0", who: "yeonseo", text: "알아요. 그래야 맞아요.", tag: "[quiet] [resolute] 알아요. 그래야 맞아요." },
  { id: "y6-3d5d2fcdc1c", who: "yeonseo", text: "근데 혼자서는 못 하겠어요. …무서워요.", tag: "[scared] [small voice] 근데, 혼자서는 못 하겠어요. ...무서워요." },
  { id: "y6-c9c3905757", who: "yeonseo", text: "셋이라는 변수는, 제 계산에 없었어요.", tag: "[wry] [quiet] 셋이라는 변수는, 제 계산에 없었어요." },
  { id: "y6-51cee05e79", who: "yeonseo", text: "…넣었어요. 아직 답은 안 나와요.", tag: "[faint smile] ...넣었어요. 아직, 답은 안 나와요." },
  { id: "y6-c1b8cfa3d1", who: "yeonseo", text: "제가 먼저 말할게요. 이걸 숨기고는 같은 편이 될 수 없어요.", tag: "[steady] [serious] 제가 먼저 말할게요. 이걸 숨기고는, 같은 편이 될 수 없어요." },
  { id: "y6-a7926a2761", who: "yeonseo", text: "일요일에 사진 보여 줬죠. 본 적 없다고 했어요.", tag: "[steady] 일요일에, 사진 보여 줬죠. 본 적 없다고 했어요." },
  { id: "y6-b5856af371", who: "yeonseo", text: "거짓말이었어요.", tag: "[quiet] [firm] 거짓말이었어요." },
  { id: "y6-4f226ab4fa", who: "yeonseo", text: "5년 전 여름. 아래층 구석 테이블. 그분 맞은편에 앉은 게, 저예요.", tag: "[steady] [quiet] 오 년 전 여름. 아래층 구석 테이블. 그분 맞은편에 앉은 게, 저예요." },
  { id: "y6-1a96b1b296", who: "yeonseo", text: "숫자는 사장님이 정했어요. 저는 하나도 안 틀리고 땄어요.", tag: "[sad] [steady] 숫자는, 사장님이 정했어요. 저는 하나도 안 틀리고, 땄어요." },
  { id: "y6-cd7689fbc0", who: "yeonseo", text: "…쓸 수도, 버릴 수도 없었어요.", tag: "[sad] [quiet] ...쓸 수도, 버릴 수도 없었어요." },
  { id: "y6-2f4192a7d2", who: "yeonseo", text: "…따라가지 그랬어요.", tag: "[quiet] ...따라가지 그랬어요." },
  { id: "y6-1ea90e8d21", who: "yeonseo", text: "5년 동안 못 한 말이에요. 막상 하니까 생각보다 짧았어요.", tag: "[quiet] [hollow] 오 년 동안 못 한 말이에요. 막상 하니까, 생각보다 짧았어요." },
  { id: "y6-2cc8af0876", who: "yeonseo", text: "그날 그분이 저한테 물었어요. 영어로. 'Is this fixed?'", tag: "[sad] [quiet] 그날 그분이, 저한테 물었어요. 영어로. Is this fixed?" },
  { id: "y6-f973e94340", who: "yeonseo", text: "못 알아들은 척했어요. 다 알아들었는데.", tag: "[sad] [bitter] 못 알아들은 척했어요. [falling tone] 다 알아들었는데." },
  { id: "y6-9808449f62", who: "yeonseo", text: "늦은 건 맞아요. 5년이요.", tag: "[quiet] 늦은 건 맞아요. 오 년이요." },
  { id: "y6-9f43fb6fad", who: "yeonseo", text: "…그래도 '잘한 거'라는 말은, 이 일 하면서 한 번도 못 들었어요.", tag: "[quiet] [moved] ...그래도 잘한 거라는 말은, 이 일 하면서 한 번도 못 들었어요." },
  { id: "y6-ac354706a2", who: "yeonseo", text: "…지금 그러면 반칙이에요. 표정 관리가 안 돼요.", tag: "[flustered] [shaky] ...지금 그러면 반칙이에요. 표정 관리가 안 돼요." },
  { id: "y6-877b50a6ac", who: "yeonseo", text: "에이미 씨한테 가 봐요. 저는 혼자 있는 거 잘하거든요. 7년 했어요.", tag: "[quiet] [brave] 에이미 씨한테 가 봐요. 저는, 혼자 있는 거 잘하거든요. 칠 년 했어요." },
  { id: "y6-7e1311386a", who: "yeonseo", text: "……딜러님은 가끔, 정말 이상한 순서로 일해요.", tag: "[flustered] [touched] ......딜러님은 가끔, 정말 이상한 순서로 일해요." },
  { id: "y6-cd0e2977d5", who: "yeonseo", text: "…딜러님. 여기 어떻게 알았어요?", tag: "[surprised] ...딜러님. 여기, 어떻게 알았어요?" },
  { id: "y6-52e18b0a6c", who: "yeonseo", text: "거짓말할 때 얼굴이에요. …그래도 받아 줄게요.", tag: "[dry] [faint smile] 거짓말할 때 얼굴이에요. ...그래도, 받아 줄게요." },
  { id: "y6-bf231776c1", who: "yeonseo", text: "어젯밤 일 때문에 못 잤어요. 그래서 나왔어요. 확률 실험 하러.", tag: "[calm] 어젯밤 일 때문에, 못 잤어요. 그래서 나왔어요. [falling tone] 확률 실험 하러." },
  { id: "y6-3b487dc61f", who: "yeonseo", text: "팥이 꼬리까지 들어 있을 확률. 지금까지 열한 개 중에 네 개요.", tag: "[deadpan] 팥이 꼬리까지 들어 있을 확률. 지금까지, 열한 개 중에 네 개요." },
  { id: "y6-922db7ac49", who: "yeonseo", text: "…다섯 개째. 오늘은 좀 괜찮을 것 같아요.", tag: "[soft] [smiling] ...다섯 개째. 오늘은, 좀 괜찮을 것 같아요." },
  { id: "y6-ab36ff3355", who: "yeonseo", text: "세 모 사면 백 원 빼 주는 게 이 시장 평균이에요. 수첩에 있어요.", tag: "[matter-of-fact] [faint smile] 세 모 사면 백 원 빼 주는 게, 이 시장 평균이에요. 수첩에 있어요." },
  { id: "y6-9bf12652cc", who: "yeonseo", text: "7년 동안 뭐든 적었어요. 두부도요.", tag: "[dry] 칠 년 동안, 뭐든 적었어요. [falling tone] 두부도요." },
  { id: "y6-931877bef8", who: "yeonseo", text: "…보고했어요. 딜러님이 장부 들고 앉는다고. 사장님이 웃었어요. 믿었어요.", tag: "[quiet] [steady] ...보고했어요. 딜러님이 장부 들고 앉는다고. 사장님이 웃었어요. 믿었어요." },
  { id: "y6-41b4e24046", who: "yeonseo", text: "보고는 진짜인데, 속은 거짓말이에요. 7년 만에 처음 그 사람을 속이는데, 손이 하나도 안 떨렸어요.", tag: "[quiet] 보고는 진짜인데, 속은 거짓말이에요. 칠 년 만에 처음 그 사람을 속이는데, 손이 하나도 안 떨렸어요." },
  { id: "y6-9782d112b4", who: "yeonseo", text: "그게 좀 무서워요. 저도 웃으면서 속일 수 있는 사람이었나 봐요.", tag: "[uneasy] [quiet] 그게 좀 무서워요. 저도, 웃으면서 속일 수 있는 사람이었나 봐요." },
  { id: "y6-d6445b9fef", who: "yeonseo", text: "…그건 맞아요.", tag: "[faint smile] ...그건 맞아요." },
  { id: "y6-268d24fb80", who: "yeonseo", text: "…토요일 오전에 오는 사람은 택배 기사님밖에 없었는데요.", tag: "[surprised] [dry] ...토요일 오전에 오는 사람은, 택배 기사님밖에 없었는데요." },
  { id: "y6-cf877fbb08", who: "yeonseo", text: "…이 볼펜으로 쓰는 첫 동그라미, 오늘 칠게요. 내일 칸에.", tag: "[soft] [smiling] ...이 볼펜으로 쓰는 첫 동그라미, 오늘 칠게요. [falling tone] 내일 칸에." },
  { id: "y6-2cd4e457c9", who: "yeonseo", text: "…반 남았어요. 아끼느라.", tag: "[shy] ...반 남았어요. [falling tone] 아끼느라." },
  { id: "y6-a5a1c2f2e6", who: "yeonseo", text: "아끼지 말라는 뜻이죠, 이거. …알았어요. 오늘부터 막 쓸게요.", tag: "[warm] [smiling] 아끼지 말라는 뜻이죠, 이거. ...알았어요. 오늘부터, 막 쓸게요." },
  { id: "y6-63a3544e97", who: "yeonseo", text: "들어와요. 의자가 하나라서, 누군가는 바닥이에요.", tag: "[calm] [dry] 들어와요. 의자가 하나라서, 누군가는 바닥이에요." },
  { id: "y6-1870dce6b9", who: "yeonseo", text: "빼먹으면 숫자가 안 줄어드는 것 같아서요. 어차피 잘 안 줄지만요.", tag: "[quiet] 빼먹으면, 숫자가 안 줄어드는 것 같아서요. 어차피, 잘 안 줄지만요." },
  { id: "y6-6addc8f234", who: "yeonseo", text: "괜찮았던 날이요. 빚이랑 상관없이.", tag: "[soft] 괜찮았던 날이요. [falling tone] 빚이랑 상관없이." },
  { id: "y6-64a9282cdb", who: "yeonseo", text: "…오늘 오후에, 아래층 청소하면서 봤어요.", tag: "[quiet] ...오늘 오후에, 아래층 청소하면서 봤어요." },
  { id: "y6-64b135ee30", who: "yeonseo", text: "딜러님이 말한 데 있었어요. 레일 밑, X자 테이프.", tag: "[quiet] [steady] 딜러님이 말한 데 있었어요. 레일 밑, [falling tone] 엑스 자 테이프." },
  { id: "y6-5377b58760", who: "yeonseo", text: "5년 동안 매일 그 옆에 앉았는데. 한 번도 몰랐어요.", tag: "[sad] [quiet] 오 년 동안, 매일 그 옆에 앉았는데. [falling tone] 한 번도 몰랐어요." },
  { id: "y6-03ac29078d", who: "yeonseo", text: "제가 할 수 있는 게, 이거밖에 없어서요.", tag: "[quiet] [sad] 제가 할 수 있는 게, 이거밖에 없어서요." },
  { id: "y6-8f5a8db62e", who: "yeonseo", text: "아무 말도 안 했어요. 그게 제일 나빴어요.", tag: "[sad] [quiet] 아무 말도 안 했어요. 그게, 제일 나빴어요." },
  { id: "y6-addd3aa0cd", who: "yeonseo", text: "…그럼 저는 계속 존댓말 할게요. 미움받는 쪽이 예의라도 있어야죠.", tag: "[quiet] [wry] ...그럼 저는, 계속 존댓말 할게요. 미움받는 쪽이, 예의라도 있어야죠." },
  { id: "y6-5ca9d98ef9", who: "yeonseo", text: "5년 동안 못 썼어요. 쓸 수가 없어서. 돌려줄게요.", tag: "[quiet] [sad] 오 년 동안 못 썼어요. 쓸 수가 없어서. 돌려줄게요." },
  { id: "y6-5aeb37bef6", who: "yeonseo", text: "5년 전, 3년 전, 그리고 7년. 다 같은 테이블이에요.", tag: "[quiet] [serious] 오 년 전, 삼 년 전, 그리고 칠 년. 다 같은 테이블이에요." },
  { id: "y6-272ba109d5", who: "yeonseo", text: "5년 전 공책이랑, 제 7년. 숫자 정한 사람은 하나예요.", tag: "[quiet] [serious] 오 년 전 공책이랑, 제 칠 년. 숫자 정한 사람은, 하나예요." },
  { id: "y6-91d2f2f80f", who: "yeonseo", text: "…카드 좀 섞어 줘요. 그 소리 들으면 잠이 와요.", tag: "[sleepy] ...카드 좀 섞어 줘요. [sleepy] 그 소리 들으면, 잠이 와요." },
  { id: "y6-c85cef02d8", who: "yeonseo", text: "7년 치 단골 할인이에요.", tag: "[dry] 칠 년 치, 단골 할인이에요." },
  { id: "y6-36f5864d01", who: "yeonseo", text: "아래층 판이 어떻게 돌아가는지, 에이미 씨도 알아야 해요. 전부 말할게요.", tag: "[serious] 아래층 판이 어떻게 돌아가는지, 에이미 씨도 알아야 해요. 전부 말할게요." },
  { id: "y6-59d59322d6", who: "yeonseo", text: "딜러님은 한 번 들었죠. 에이미 씨를 위해서, 처음부터 다시 할게요.", tag: "[calm] 딜러님은 한 번 들었죠. 에이미 씨를 위해서, 처음부터 다시 할게요." },
  { id: "y6-5e4791edda", who: "yeonseo", text: "손님이 컷해요. 그건 진짜. 진짜는 거기까지고요.", tag: "[calm] [deadpan] 손님이 컷해요. 그건 진짜. 진짜는, 거기까지고요." },
  { id: "y6-b8754e779b", who: "yeonseo", text: "딜러가 그 덱을 받아서, 칩 트레이 정리하듯 테이블 아래로 반 뼘 내려요. 올라오는 건 미리 맞춰 둔 덱이에요.", tag: "[calm] [deadpan] 딜러가 그 덱을 받아서, 칩 트레이 정리하듯 테이블 아래로 반 뼘 내려요. 올라오는 건, 미리 맞춰 둔 덱이에요." },
  { id: "y6-c608564b93", who: "yeonseo", text: "사장님은 물잔 가장자리에 손가락을 올려요. 하나는 져 줘라. 둘은 비슷하게. 셋은… 전부.", tag: "[cold] 사장님은 물잔 가장자리에 손가락을 올려요. 하나는 져 줘라. 둘은 비슷하게. 셋은... [falling tone] 전부." },
  { id: "y6-6aac677acd", who: "yeonseo", text: "물잔은 저한테 보내는 신호예요. 두드리는 건… 자기한테 하는 거고요.", tag: "[calm] 물잔은, 저한테 보내는 신호예요. 두드리는 건... 자기한테 하는 거고요." },
  { id: "y6-217f2892f2", who: "yeonseo", text: "마지막 판은 늘 같아요. 풀하우스 대 포카드. 제 수첩엔 스물세 번 있어요. '시나리오 — 쿨러'.", tag: "[quiet] [sad] 마지막 판은, 늘 같아요. 풀하우스 대 포카드. 제 수첩엔 스물세 번 있어요. [falling tone] 시나리오, 쿨러." },
  { id: "y6-61c8d04980", who: "yeonseo", text: "딜러님이 앉는다면, 앉을 거예요.", tag: "[calm] [certain] 딜러님이 앉는다면, 앉을 거예요." },
  { id: "y6-510c56760d", who: "yeonseo", text: "그 사람이 제일 갖고 싶은 건 돈이 아니에요. 딜러님이 그 테이블에서 다시 지는 얼굴이에요.", tag: "[cold] 그 사람이 제일 갖고 싶은 건, 돈이 아니에요. 딜러님이 그 테이블에서, 다시 지는 얼굴이에요." },
  { id: "y6-3a808bbb65", who: "yeonseo", text: "앉아요. 월요일에 사장님이 먼저 하자고 했어요. 일요일 새벽, 딜러님이 앉는 걸로.", tag: "[calm] 앉아요. 월요일에, 사장님이 먼저 하자고 했어요. [falling tone] 일요일 새벽, 딜러님이 앉는 걸로." },
  { id: "y6-542b0e0916", who: "yeonseo", text: "…제가 앉지 말라고 했던 판이에요. 이번엔 제가 앉으라고 하네요.", tag: "[wry] [quiet] ...제가 앉지 말라고 했던 판이에요. 이번엔, 제가 앉으라고 하네요." },
  { id: "y6-13570b208a", who: "yeonseo", text: "그리고 제가 다시 바꿔요. 딜러가 바꾼 덱을, 에이미 씨가 컷한 덱으로.", tag: "[calm] [confident] 그리고 제가 다시 바꿔요. 딜러가 바꾼 덱을, [falling tone] 에이미 씨가 컷한 덱으로." },
  { id: "y6-bd770230fe", who: "yeonseo", text: "하우스 자리는 딜러 바로 옆이고, 바꿔 놓은 원래 덱은 딜러 무릎 위에 있어요. 손만 뻗으면 되죠.", tag: "[calm] [deadpan] 하우스 자리는 딜러 바로 옆이고, 바꿔 놓은 원래 덱은 딜러 무릎 위에 있어요. 손만 뻗으면 되죠." },
  { id: "y6-08f0db9067", who: "yeonseo", text: "대신 1초가 필요해요. 모두가 딴 데를 보는 1초.", tag: "[serious] 대신, 일 초가 필요해요. [falling tone] 모두가 딴 데를 보는 일 초." },
  { id: "y6-bc195bebdf", who: "yeonseo", text: "덱이 바뀌는 순간은 딜러님이 봐 줘요. 저는 사장님 손가락을 봐야 하니까요.", tag: "[calm] 덱이 바뀌는 순간은, 딜러님이 봐 줘요. 저는, 사장님 손가락을 봐야 하니까요." },
  { id: "y6-562dcb8441", who: "yeonseo", text: "바뀐 걸 봤으면, 테이블을 두 번 두드려요. 손끝으로.", tag: "[calm] 바뀐 걸 봤으면, 테이블을 두 번 두드려요. [falling tone] 손끝으로." },
  { id: "y6-c089f9cad1", who: "yeonseo", text: "못 보면… 제가 손바닥을 펠트 위에 엎을게요. 그럼 짜인 판이라는 뜻. 무슨 패든 접어요.", tag: "[cold] [serious] 못 보면... 제가 손바닥을 펠트 위에 엎을게요. 그럼 짜인 판이라는 뜻. 무슨 패든, 접어요." },
  { id: "y6-1b64011f94", who: "yeonseo", text: "사장님한테는 제가 보고할게요. 딜러님이 장부를 들고 앉겠다고.", tag: "[calm] 사장님한테는, 제가 보고할게요. [falling tone] 딜러님이 장부를 들고 앉겠다고." },
  { id: "y6-17afe6b9b1", who: "yeonseo", text: "제 보고는 7년 동안 한 번도 안 틀렸으니까, 믿을 거예요.", tag: "[dry] [confident] 제 보고는, 칠 년 동안 한 번도 안 틀렸으니까. 믿을 거예요." },
  { id: "y6-d4986948aa", who: "yeonseo", text: "이번엔 진짜 보고예요. 사장님이 제일 듣고 싶던 거니까, 믿을 거예요.", tag: "[cold] [confident] 이번엔 진짜 보고예요. 사장님이 제일 듣고 싶던 거니까, 믿을 거예요." },
  { id: "y6-0665354f30", who: "yeonseo", text: "그럼 저는 에이미 씨 밥을 뺏을게요. 공평하게.", tag: "[playful] [faint smile] 그럼 저는, 에이미 씨 밥을 뺏을게요. 공평하게." },
  { id: "y6-d812450536", who: "yeonseo", text: "판 엎는 거, 7년 동안 한 번도 못 해 봤어요.", tag: "[quiet] [wondering] 판 엎는 거, 칠 년 동안 한 번도 못 해 봤어요." },
  { id: "y6-c58cd1ff22", who: "yeonseo", text: "…오늘 달력에 동그라미 쳤어요. 내일 칸에.", tag: "[shy] [quiet] ...오늘 달력에, 동그라미 쳤어요. [falling tone] 내일 칸에." },
  { id: "y6-acc920a6c9", who: "yeonseo", text: "처음이에요. 아직 안 온 날에 그리는 거.", tag: "[soft] 처음이에요. [falling tone] 아직 안 온 날에 그리는 거." },
  { id: "y6-b6935729af", who: "yeonseo", text: "…제 달력, 봤죠? X만 있는 거.", tag: "[quiet] ...제 달력, 봤죠? [falling tone] 엑스만 있는 거." },
  { id: "y6-5e6a2270fd", who: "yeonseo", text: "오늘 하나 다른 걸 그렸어요. 내일 칸에, 동그라미.", tag: "[soft] 오늘, 하나 다른 걸 그렸어요. 내일 칸에, [falling tone] 동그라미." },
  { id: "y6-d177da9161", who: "yeonseo", text: "아직 안 온 날에 뭘 그려 본 적, 없었거든요.", tag: "[soft] 아직 안 온 날에, 뭘 그려 본 적, 없었거든요." },
  { id: "y6-abfdfd28fa", who: "yeonseo", text: "수요일에, 안 간다고 했죠. 그 말 아직 계산 중이에요.", tag: "[quiet] 수요일에, 안 간다고 했죠. 그 말, 아직 계산 중이에요." },
  { id: "y6-5420f0f1d6", who: "yeonseo", text: "답이 잘 안 나와요. 좋은 쪽으로요.", tag: "[shy] 답이 잘 안 나와요. [falling tone] 좋은 쪽으로요." },
  { id: "y6-4168378864", who: "yeonseo", text: "…아침에 받은 볼펜으로요. 빨간색이라, 멀리서 봐도 X 같지 않아요.", tag: "[shy] ...아침에 받은 볼펜으로요. 빨간색이라, 멀리서 봐도 엑스 같지 않아요." },
  { id: "y6-2a826c98e0", who: "yeonseo", text: "붕어빵, 그 뒤로 세 개 더 먹어 봤어요. 셋 다 꼬리까지 들어 있었어요. 이번 주는 확률이 이상해요.", tag: "[dry] [amused] 붕어빵, 그 뒤로 세 개 더 먹어 봤어요. 셋 다, 꼬리까지 들어 있었어요. 이번 주는, 확률이 이상해요." },
  { id: "y6-c9671878c4", who: "yeonseo", text: "…다행이에요. 저는 못 잤어요. 내일 쓸 무표정 연습하느라.", tag: "[quiet] [dry] ...다행이에요. 저는 못 잤어요. [falling tone] 내일 쓸 무표정 연습하느라." },
  { id: "y6-262838aa65", who: "yeonseo", text: "지면 어떡하죠? 동그라미가 X가 되면.", tag: "[uneasy] [quiet] 지면 어떡하죠? [falling tone] 동그라미가 엑스가 되면." },
  { id: "y6-b59a9c97b4", who: "yeonseo", text: "…그런 위로가 어디 있어요?", tag: "[small laugh] [soft] ...그런 위로가, 어디 있어요?" },
  { id: "y6-bb46f72144", who: "yeonseo", text: "딜러님은 안 무서워요? 아래층 테이블에, 3년 만에 앉는 거.", tag: "[quiet] [curious] 딜러님은 안 무서워요? 아래층 테이블에, 삼 년 만에 앉는 거." },
  { id: "y6-bd65b938a6", who: "yeonseo", text: "패만 보다가 진 사람이 몇 명인지 알아요? 제 수첩에 다 있어요.", tag: "[dry] 패만 보다가 진 사람이, 몇 명인지 알아요? 제 수첩에 다 있어요." },
  { id: "y6-b4b92cde48", who: "yeonseo", text: "가끔이면 승률이 떨어져요. 자주 봐요.", tag: "[shy] [teasing] 가끔이면, 승률이 떨어져요. [falling tone] 자주 봐요." },
  { id: "y6-33d0dfa019", who: "yeonseo", text: "내일은 장갑 안 낄 거예요. 숨길 게 없으니까요.", tag: "[calm] [resolute] 내일은 장갑, 안 낄 거예요. 숨길 게 없으니까요." },
  { id: "y6-72d686a3e5", who: "yeonseo", text: "…지금 뭐 하려는지 알아요. 얼굴에 써 있어요.", tag: "[shy] [flustered] ...지금 뭐 하려는지 알아요. 얼굴에 써 있어요." },
  { id: "y6-9946aa983a", who: "yeonseo", text: "내일 끝나고요. 지금 하면 표정이 생겨서, 사장님한테 읽혀요.", tag: "[shy] [soft] 내일 끝나고요. 지금 하면 표정이 생겨서, 사장님한테 읽혀요." },
  { id: "y6-fc53e97aa0", who: "yeonseo", text: "셋 다 걸어요. 전부.", tag: "[resolute] 셋 다 걸어요. [falling tone] 전부." },
  { id: "y6-c73d0ea971", who: "yeonseo", text: "…그저께 같이 쓴 우산, 아직 현관에 펴 뒀어요. 끝나면 같이 접어요.", tag: "[soft] ...그저께 같이 쓴 우산, 아직 현관에 펴 뒀어요. 끝나면, 같이 접어요." },
  { id: "y6-7c14d8dde0", who: "yeonseo", text: "태양 씨가 소리 지른 1초요. 사장님 눈이 물잔에서 떨어진 건 그때 한 번뿐이었어요.", tag: "[cold] [composed] 태양 씨가 소리 지른, 일 초요. 사장님 눈이 물잔에서 떨어진 건, 그때 한 번뿐이었어요." },
  { id: "y6-93e4f5dea0", who: "yeonseo", text: "…불은, 이걸 붙이려고 아껴 뒀나 봐요.", tag: "[faint smile] ...불은, 이걸 붙이려고 아껴 뒀나 봐요." },
  { id: "y6-5664eb7186", who: "yeonseo", text: "7년 쓰고 반 남았던 거요. …나머지 반은, 이걸 붙이려고 아껴 뒀나 봐요.", tag: "[faint smile] 칠 년 쓰고, 반 남았던 거요. ...나머지 반은, 이걸 붙이려고 아껴 뒀나 봐요." },
  { id: "y6-bdac06fc61", who: "yeonseo", text: "경찰서에 가져갈 거예요. 제 이름이랑 같이.", tag: "[calm] [resolute] 경찰서에 가져갈 거예요. [falling tone] 제 이름이랑 같이." },
  { id: "y6-6a112c2246", who: "yeonseo", text: "알아요. 그래서 가요.", tag: "[calm] [resolute] 알아요. 그래서 가요." },
  { id: "y6-9e9d39674f", who: "yeonseo", text: "다음 카드, 말해 볼까요?", tag: "[cold] 다음 카드, 말해 볼까요?" },
  { id: "y6-ee0661d435", who: "yeonseo", text: "하트 에이스. 클럽 7. 스페이드 2. 다이아 퀸.", tag: "[cold] [precise] 하트 에이스. 클럽 칠. 스페이드 이. 다이아 퀸." },
  { id: "y6-82466e1504", who: "yeonseo", text: "시나리오 쿨러. 스물네 번째예요. 순서까지 다 외워요.", tag: "[cold] 시나리오 쿨러. 스물네 번째예요. 순서까지, 다 외워요." },
  { id: "y6-e8aa8c8371", who: "yeonseo", text: "장부는 종이예요. 저는 종이가 아니에요.", tag: "[calm] [firm] 장부는 종이예요. 저는, 종이가 아니에요." },
  { id: "y6-10ab289292", who: "yeonseo", text: "날짜, 상대, 사장님이 정한 숫자. 하나도 안 틀리고 말할 수 있어요. 오늘 아침, 경찰서에서요.", tag: "[calm] [firm] 날짜, 상대, 사장님이 정한 숫자. 하나도 안 틀리고 말할 수 있어요. [falling tone] 오늘 아침, 경찰서에서요." },
  { id: "y6-4489d74da1", who: "yeonseo", text: "이건 안 타요. 제가 쥐고 있을 거니까요.", tag: "[cold] 이건 안 타요. 제가 쥐고 있을 거니까요." },
  { id: "y6-8a20065a27", who: "yeonseo", text: "누구 하나 다치면, 엎기로 했죠.", tag: "[calm] [resolute] 누구 하나 다치면, 엎기로 했죠." },
  { id: "y6-0ed372a800b", who: "yeonseo", text: "판 엎는 거, 처음 해 봤어요. 생각보다 무거워요.", tag: "[quiet] [amazed] 판 엎는 거, 처음 해 봤어요. 생각보다, 무거워요." },
  { id: "y6-9c5c122e5b", who: "yeonseo", text: "이것도 안 탔어요. 제가 쥐고 있었으니까요.", tag: "[calm] 이것도 안 탔어요. 제가 쥐고 있었으니까요." },
  { id: "y6-72c0469e10", who: "yeonseo", text: "장부는 종이죠. 맞아요. 그런데 저는 종이가 아니에요.", tag: "[calm] [firm] 장부는 종이죠. 맞아요. 그런데 저는, 종이가 아니에요." },
  { id: "y6-cc99b7b25f", who: "yeonseo", text: "7년 동안 제가 앉은 판, 전부 외워요. 날짜, 상대, 사장님이 정한 숫자.", tag: "[calm] [firm] 칠 년 동안 제가 앉은 판, 전부 외워요. [falling tone] 날짜, 상대, 사장님이 정한 숫자." },
  { id: "y6-e6a4a31917", who: "yeonseo", text: "알아요. 그래서 가요. 오늘 아침에.", tag: "[calm] [resolute] 알아요. 그래서 가요. [falling tone] 오늘 아침에." },
  { id: "y6-cf178b7304", who: "yeonseo", text: "…비 그친 다음 날 아침이에요.", tag: "[soft] [surprised] ...비 그친 다음 날 아침이에요." },
  { id: "y6-1ef01ba8bd", who: "yeonseo", text: "골목은 다 젖었는데 하늘은 맑은 거. 제가 제일 좋아하는 아침이에요.", tag: "[warm] [smiling] 골목은 다 젖었는데, 하늘은 맑은 거. 제가 제일 좋아하는 아침이에요." },
  { id: "y6-d13f0a5a75", who: "yeonseo", text: "에이미 씨는 의외로 조용하네요. 오늘은.", tag: "[dry] [teasing] 에이미 씨는, 의외로 조용하네요. [falling tone] 오늘은." },
  { id: "y6-98e1b1d8cd", who: "yeonseo", text: "둘 다요. 오늘은 계산이 맞았어요.", tag: "[soft] [smiling] 둘 다요. 오늘은, 계산이 맞았어요." },
  { id: "y6-7adef6fca0", who: "yeonseo", text: "이긴 거예요. 판이 아니라, 테이블을.", tag: "[soft] [smiling] 이긴 거예요. 판이 아니라, [falling tone] 테이블을." },
  { id: "y6-15ad67d7c1", who: "yeonseo", text: "…기록하지 마요. 정민 씨처럼.", tag: "[embarrassed] ...기록하지 마요. [falling tone] 정민 씨처럼." },
  { id: "y6-f28e9110b3", who: "yeonseo", text: "…축하해요. 이건 계산 안 해도 알았어요.", tag: "[soft] [smiling] ...축하해요. 이건, 계산 안 해도 알았어요." },
  { id: "y6-6f5777ea3b", who: "yeonseo", text: "처벌은 아주 가벼웠어요. 정민 씨 노트 덕분에요. 사장님 덱이 제일 큰 증거였대요.", tag: "[calm] [light] 처벌은, 아주 가벼웠어요. 정민 씨 노트 덕분에요. 사장님 덱이, 제일 큰 증거였대요." },
  { id: "y6-4c336f64f3", who: "yeonseo", text: "증거가 사람 기억뿐이라, 재판이 길었어요. 집행유예. 정민 씨 노트가 아니었으면 더 길었대요.", tag: "[calm] 증거가 사람 기억뿐이라, 재판이 길었어요. 집행유예. 정민 씨 노트가 아니었으면, 더 길었대요." },
  { id: "y6-94f0704e63", who: "yeonseo", text: "요즘은 동그라미만 쳐요. 빚이랑 상관없이, 괜찮았던 날.", tag: "[warm] [smiling] 요즘은 동그라미만 쳐요. [falling tone] 빚이랑 상관없이, 괜찮았던 날." },
  { id: "y6-3df665873f", who: "yeonseo", text: "딜러님. 에이미 씨 울리면, 제가 읽어요. 표정으로 다 보여요.", tag: "[dry] [teasing] 딜러님. 에이미 씨 울리면, 제가 읽어요. 표정으로, 다 보여요." },
  { id: "y6-4f63c496eb", who: "yeonseo", text: "지금은 표정 생겨도 되죠? 사장님, 없으니까.", tag: "[shy] [soft] 지금은, 표정 생겨도 되죠? [falling tone] 사장님, 없으니까." },
  { id: "y6-1dfac80432", who: "yeonseo", text: "처벌은 아주 가벼웠어요. 정민 씨 노트 덕분이라네요. 장갑도, 이제 안 껴요.", tag: "[calm] [light] 처벌은, 아주 가벼웠어요. 정민 씨 노트 덕분이라네요. 장갑도, 이제 안 껴요." },
  { id: "y6-5547c5606c", who: "yeonseo", text: "재판이 길었어요. 집행유예래요. 증거가 사람 기억뿐이라서요. 장갑은, 그래도 안 껴요.", tag: "[calm] 재판이 길었어요. 집행유예래요. 증거가 사람 기억뿐이라서요. 장갑은, 그래도 안 껴요." },
  { id: "y6-c5930f0851", who: "yeonseo", text: "그리고… 달력, 바꿨어요.", tag: "[shy] 그리고... [falling tone] 달력, 바꿨어요." },
  { id: "y6-b5cb23b1df", who: "yeonseo", text: "딜러님이 준 빨간 볼펜, 아직 잘 나와요. 오늘은 꼭 이걸로 그리려고요.", tag: "[warm] [smiling] 딜러님이 준 빨간 볼펜, 아직 잘 나와요. 오늘은, 꼭 이걸로 그리려고요." },
  { id: "y6-634d8cc454", who: "yeonseo", text: "빨간 볼펜도 샀어요. 오늘 쓰려고요.", tag: "[warm] [smiling] 빨간 볼펜도 샀어요. [falling tone] 오늘 쓰려고요." },
  { id: "y6-7cbced0a09", who: "yeonseo", text: "…지금부터 알게 돼요.", tag: "[soft] [mysterious] ...지금부터, 알게 돼요." },
  { id: "y6-3865553cc6", who: "yeonseo", text: "처음 만난 날, 엄지가 먼저 나간다고 했죠.", tag: "[soft] 처음 만난 날, 엄지가 먼저 나간다고 했죠." },
  { id: "y6-c27d3a861f", who: "yeonseo", text: "그때부터 봤어요. 7년 동안 카드만 보던 눈으로, 사람 손을요.", tag: "[shy] [tender] 그때부터 봤어요. 칠 년 동안 카드만 보던 눈으로, [falling tone] 사람 손을요." },
  { id: "y6-8a8b326a3c", who: "yeonseo", text: "…좋아해요. 이건 블러프 아니에요. 안 두드렸잖아요.", tag: "[shy] [sincere] ...좋아해요. 이건 블러프 아니에요. 안 두드렸잖아요." },
  { id: "y6-2fdbbd9846", who: "yeonseo", text: "…끝까지 이상한 순서로 일하네요.", tag: "[faint smile] ...끝까지, 이상한 순서로 일하네요." },
  { id: "y6-7d244ca974", who: "yeonseo", text: "에이미 씨, 좋은 패 쥐면 머리끝 감는 버릇 아직 못 고쳤어요.", tag: "[dry] [teasing] 에이미 씨, 좋은 패 쥐면 머리끝 감는 버릇. 아직 못 고쳤어요." },
  { id: "y6-804ee25484", who: "yeonseo", text: "그럼 콜.", tag: "[calm] [faint smile] 그럼, 콜." },
  { id: "y6-8d99b76489", who: "yeonseo", text: "…졌어요. 그런데 기분이 좋네요. 이상하게.", tag: "[surprised] [warm] ...졌어요. 그런데, 기분이 좋네요. [small laugh] 이상하게." },
  { id: "y6-8ae0f78d6d", who: "yeonseo", text: "…그러니까, 이기라고 옆에 있지 말고요.", tag: "[soft] [teasing] ...그러니까, 이기라고 옆에 있지 말고요." },
  { id: "y6-79fbecb4d4", who: "yeonseo", text: "그냥 있어요. 이 테이블에.", tag: "[soft] [warm] 그냥 있어요. [falling tone] 이 테이블에." },
  { id: "y6-c482985e68", who: "yeonseo", text: "…!", tag: "[sharp gasp] ...!" },
  { id: "y6-beb683ef1e", who: "yeonseo", text: "……네?", tag: "[startled] ......네?" },
  { id: "y7-3a5fd00a54", who: "yeonseo", text: "…이걸로 바꾸라고요?", tag: "[surprised] ...이걸로 바꾸라고요?" },
  { id: "y6-0f88d45cdb", who: "yeonseo", text: "…아.", tag: "[surprised] [soft] ...아." },
  { id: "y6-90a4561eb9", who: "yeonseo", text: "…동그라미.", tag: "[surprised] [soft] ...동그라미." },
  { id: "y6-ae9dc3b013", who: "yeonseo", text: "…차가워요.", tag: "[soft] [surprised] ...차가워요." },
  { id: "y6-e25872d168", who: "yeonseo", text: "…휴식 끝났어요.", tag: "[cool] [curt] ...휴식 끝났어요." },
  { id: "y6-583d280be6", who: "yeonseo", text: "사장님이 웃었어요. '휴가? 연서 씨가? 다녀와요.' 의심하는 웃음이었어요.", tag: "[dry] 사장님이 웃었어요. 휴가? 연서 씨가? 다녀와요. [falling tone] 의심하는 웃음이었어요." },
  { id: "y6-a2f3974f29b", who: "yeonseo", text: "…후, 후후.", tag: "[quiet] ...후, 후후." },
  { id: "y6-9b5728664a", who: "yeonseo", text: "사장님이 이모 아들 결혼식에 안 온 걸 이모가 꺼내면, 백 퍼센트가 돼요.", tag: "[under her breath] [amused] 사장님이 이모 아들 결혼식에 안 온 걸 이모가 꺼내면, 백 퍼센트가 돼요." },
  { id: "y6-d1eab55741", who: "yeonseo", text: "거짓말 확률이 높네요. 안 할래요. 아껴 두려고요.", tag: "[amused] [teasing] 거짓말 확률이 높네요. 안 할래요. [falling tone] 아껴 두려고요." },
  { id: "y6-23fce0d498b", who: "yeonseo", text: "아하하…! 아하하하!", tag: "[relieved] [warm] 아하하... 아하하하." },
  { id: "y6-3ca3805663", who: "yeonseo", text: "아하하. …들었어요? 저 이제 이렇게 웃어요.", tag: "[happy] [bright] 아하하. ...들었어요? 저 이제, 이렇게 웃어요." },
  { id: "y6-5876e9c8b9", who: "yeonseo", text: "…저였어요. 스물넷이었어요.", tag: "[quiet] [steady] ...저였어요. [falling tone] 스물넷이었어요." },
  { id: "y6-b3db1642c4", who: "yeonseo", text: "…저는 그 판에 없었어요. 그건 진짜예요.", tag: "[hesitant] [firm] ...저는, 그 판에 없었어요. 그건 진짜예요." },
  { id: "y6-199aa60a5f", who: "yeonseo", text: "사장님 덱은 여기 있어요.", tag: "[cold] [calm] 사장님 덱은, 여기 있어요." },
  { id: "y6-6969143204", who: "yeonseo", text: "사장님. 오늘은 물잔 안 봐요. 카드만 볼게요.", tag: "[cold] [steady] 사장님. 오늘은 물잔 안 봐요. 카드만 볼게요." },
  { id: "y6-2f007fc29e", who: "yeonseo", text: "하나도 안 틀리고요. 사장님이 그렇게 가르쳤잖아요.", tag: "[cold] [cutting] 하나도 안 틀리고요. 사장님이, 그렇게 가르쳤잖아요." },
  { id: "y6-d4dba85b99c", who: "yeonseo", text: "다 말하면, 다들 가요. 병원 사람들도, 친척들도. 그래서 7년 동안 아무 말도 안 했어요.", tag: "[crying] 다 말하면, 다들 가요... 병원 사람들도, 친척들도. [crying] 그래서 칠 년 동안... 아무 말도 안 했어요." },
  { id: "y6-756c776673cp", who: "yeonseo", text: "…'그 애 잘못 아니다.'", tag: "[sobbing] ...그애 잘못 아니다..." },
  { id: "y6-4e32e5e9e4c", who: "yeonseo", text: "미워해요. 그래도 돼요.", tag: "[holding back tears] 미워해요. [holding back tears] ...그래도 돼요." },
  { id: "y6-ebd32f56dd", who: "yeonseo", text: "…오늘은 출근하기 싫네요.", tag: "[sleepy] [soft] ...오늘은, 출근하기 싫네요." },
  { id: "y6-187d97fac0", who: "yeonseo", text: "정가 삼천오백 원. 이모 단골 할인 오백 원. 지금 우기시는 게 추가 칠백 원. 성공 확률 팔십 퍼센트.", tag: "[under her breath] [matter-of-fact] 정가 삼천오백 원. 이모 단골 할인 오백 원. 지금 우기시는 게 추가 칠백 원. 성공 확률, 팔십 퍼센트." },
  { id: "y7-a46ceffc95", who: "yeonseo", text: "확률은 똑같은데, 실망은 에이스 쪽이 더 커요.", tag: "[dry] 확률은 똑같은데, 실망은 에이스 쪽이 더 커요." },
  { id: "y6-609676aee7", who: "yeonseo", text: "딜러님 셔플은… 제 승률을 떨어뜨려요. 이유는… 계산 중…", tag: "[drowsy] [falling asleep] 딜러님 셔플은... 제 승률을 떨어뜨려요. 이유는... [falling tone] 계산 중..." },
  { id: "y6-eee7185d07", who: "yeonseo", text: "…하아. 불은… 켜지 마요.", tag: "[shy] [quiet] ...하아. 불은... 켜지 마요." },
  { id: "y6-058d08ee3dc", who: "yeonseo", text: "이상해요. 하나도 안 무서워요. 지금은요. 내일은 무섭겠지만. …아하하.", tag: "[calm] [tearful] 이상해요. [tearful] 하나도 안 무서워요. [tearful] 지금은요. [tearful] 내일은... 무섭겠지만. [tearful] ...아하하." },
  { id: "a4-957884f4f6eb", who: "amy", text: "아하하, 그럼 매일 볼 수 있겠네.", tag: "[bright, cheerful] 아하하, 그럼 매일 볼 수 있겠네." },
  { id: "a4-00dee848bceb", who: "amy", text: "…딜러. 나 이제 너랑 같은 회사에 빚졌다. 아하하.", tag: "[hollow] ...딜러. 나 이제, 너랑 같은 회사에 빚졌다. 아하하." },
  { id: "a4-40a7e2c24beb", who: "amy", text: "…딜러. 왔어? 아하하. 늦었다. 3분도 아니고, 4분.", tag: "[hollow, forced smile] ...딜러. 왔어? 아하하. 늦었다. 삼 분도 아니고, 사 분." },
  { id: "a4-192adaf9bdeb", who: "amy", text: "에헤헤. 이거 너한테 꼭 한 번 해 보고 싶었어.", tag: "[mischievous, playful] 에헤헤. 이거 너한테, 꼭 한 번 해 보고 싶었어." },
  { id: "a4-79edc08f00e", who: "amy", text: "에헤헤. 거봐. 그동안은 몸풀기였어.", tag: "[tipsy, giggling] 에헤헤. 거봐. 그동안은, 몸풀기였어." },
  { id: "a4-c94c2683a6e", who: "amy", text: "바보.", tag: "[soft, fond] 바보." },
  { id: "a4-7e25ef4480e", who: "amy", text: "…여기 네 집이잖아. 바보.", tag: "[whispering, shy] ...여기 네 집이잖아. 바보." },
  { id: "a4-0b6294ea4ae", who: "amy", text: "……바보. 자. 세 시 반.", tag: "[shy, mumbling] ......바보. 자. 세 시 반." },
  { id: "a4-9c341b94d5e", who: "amy", text: "……바보. 운 같은 소리 하네.", tag: "[sniffling, soft] ......바보. 운 같은 소리 하네." },
  { id: "a4-fb9ac61befe", who: "amy", text: "……바보. 이기면 온다며. 졌잖아. 그래서 안 온 거잖아.", tag: "[sobbing, voice breaking] ......바보. 이기면 온다며. 졌잖아. 그래서, 안 온 거잖아." },
  { id: "a4-c48b7b937ce", who: "amy", text: "이거 받으면 내가 진 게 진짜 진 게 되잖아요!", tag: "[crying, shouting] 이거 받으면, 내가 진 게 진짜 진 게 되잖아요!" },
  { id: "a4-83e06ab7bde", who: "amy", text: "근데 퇴근하니까 갑자기 눈물이 나. 진 것도 아닌데. 바보같이.", tag: "[tearful, small voice] 근데 퇴근하니까, 갑자기 눈물이 나. 진 것도 아닌데. [sniffles] 바보같이." },
  { id: "a4-2615fd27a5e", who: "amy", text: "…뽑혔다. 내가 뽑았어!", tag: "[gasp, then excited] ...뽑혔다. 내가 뽑았어!" },
  { id: "a4-2d015d6cf1e", who: "amy", text: "이겼다! 사탕 다 내 거야!", tag: "[cheering, excited] 이겼다! 사탕 다 내 거야!" },
  { id: "a4-9612f3ad8fe", who: "amy", text: "이겼다! 선생님을 이겼어!", tag: "[cheering, shouting] 이겼다! 선생님을 이겼어!" },
  { id: "a4-5142cd3b10e", who: "amy", text: "이겼다! 오늘은 딜러가 손님이야.", tag: "[cheering, smug] 이겼다! 오늘은, 딜러가 손님이야." },
  { id: "a4-901f3c466fe", who: "amy", text: "언니 지금 웃었어? 소리 냈어! 들었지, 딜러?", tag: "[hoarse, excited, shouting] 언니 지금 웃었어? 소리 냈어! 들었지, 딜러?" },
  { id: "a4-5a70b32865e", who: "amy", text: "…일어났어? 바닥에서 자면 등 안 아파?", tag: "[sleepy, yawning] ...일어났어? 바닥에서 자면, 등 안 아파?" },
  { id: "a4-96da8c0dfee", who: "amy", text: "흥. 그건 영상이 나빴던 거야.", tag: "[huffy, pouty] 흥. 그건, 영상이 나빴던 거야." },
  { id: "a4-bebcbced1ae", who: "amy", text: "흥. 딜러, 테이블 밖에선 엄청 치사하구나.", tag: "[huffy, pouty] 흥. 딜러, 테이블 밖에선 엄청 치사하구나." },
  { id: "a4-62264f3e52e", who: "amy", text: "흥. 시끄러워. 내 98점은 진짜 98점이야.", tag: "[huffy, defensive] 흥. 시끄러워. 내 구십팔 점은, 진짜 구십팔 점이야." },
  { id: "a4-c634f38737eb", who: "amy", text: "…응원 정도는 해 주지. 쳇.", tag: "[sulky, mumbling] ...응원 정도는 해 주지. 쳇." },
  { id: "a4-6287425546e", who: "amy", text: "쳇. 모처럼 이겼는데.", tag: "[tsk, sulky] 쳇. 모처럼 이겼는데." },
  { id: "a4-f653de4842e", who: "amy", text: "어? 어제 그 딜러!", tag: "[surprised, loud] 어? 어제 그 딜러!" },
  { id: "a4-cff53f380de", who: "amy", text: "…어?", tag: "[startled] ...어?" },
  { id: "a4-3cfb54f19ae", who: "amy", text: "…같이?", tag: "[surprised, soft] ...같이?" },
  { id: "a4-27a7fe100ee", who: "amy", text: "…뭐? 그게 왜 떠?! 왜 하필 지금 뜨냐고!", tag: "[shocked, shouting] ...뭐? 그게 왜 떠?! 왜 하필 지금 뜨냐고!" },
  { id: "a4-ac0810a791e", who: "amy", text: "어, 어. 손. 손 올라왔어.", tag: "[flustered, gasping] 어, 어. 손. 손 올라왔어." },
  { id: "a4-da1f6c91bce", who: "amy", text: "…방금 뭐야? 카드가 날아갔어. 마술이야?", tag: "[gasp, amazed] ...방금 뭐야? 카드가 날아갔어. 마술이야?" },
  { id: "a4-9554a6d8bbe", who: "amy", text: "뭐?! 안 벌렁거렸어!", tag: "[startled, shouting] 뭐?! 안 벌렁거렸어!" },
  { id: "a4-cb7fc73042e", who: "amy", text: "…네?", tag: "[startled, frozen] ...네?" },
  { id: "a4-0503c9592ceb", who: "amy", text: "으으으…!", tag: "[frustrated] 으으으...!" },
  { id: "a4-8b59220aeae", who: "amy", text: "으아아. 이 집게 사장님이랑 친척이야?", tag: "[groaning, frustrated] 으아아. 이 집게, 사장님이랑 친척이야?" },
  { id: "a4-28e587ff0de", who: "amy", text: "흠흠. 딸기우유. 큰 거로.", tag: "[clears throat, smug] 흠흠. 딸기우유. 큰 거로." },
  { id: "a4-06f6e12a17e", who: "amy", text: "하아… 점수 봐. 98점. 이게 실력이지.", tag: "[sighs contentedly, smug] 하아... 점수 봐. 구십팔 점. 이게 실력이지." },
  { id: "a4-c0813cefa7eb", who: "amy", text: "…후우. 숨 참았잖아.", tag: "[relieved] ...후우. 숨 참았잖아." },
  { id: "a4-ad2cfbea7ce", who: "amy", text: "…처음 아닌 척하려고 했는데.", tag: "[whispering, shy, breathless] ...처음 아닌 척하려고 했는데." },
  { id: "a4-f0c1338b2ee", who: "amy", text: "…미워할 거예요. 언니.", tag: "[sniffling, tearful] ...미워할 거예요. 언니." },
  { id: "a4-3525364bc4e", who: "amy", text: "…바보야. 받지 말라고 했잖아.", tag: "[sniffling, voice shaking] ...바보야. 받지 말라고 했잖아." },
  { id: "a4-9df60b0098e", who: "amy", text: "어제 이겼잖아. 그래서 오늘도 이길 줄 알았어. …바보 같지.", tag: "[sad, sniffling] 어제 이겼잖아. 그래서 오늘도 이길 줄 알았어. [falling tone] ...바보 같지." },
  { id: "a4-9ab609041feb", who: "amy", text: "…아하하. 졌어. 완전 졌어.", tag: "[hollow, deflated] ...아하하. 졌어. 완전 졌어." },
  { id: "a4-79ef3f4b5aec", who: "amy", text: "월세 어떡하지. 아하하. 진짜 어떡하지.", tag: "[voice breaking] 월세 어떡하지. 아하하. ...진짜, 어떡하지." },
  { id: "a4-f54ccb90d9eb", who: "amy", text: "…푸흡. 뭐야 그게? 아빠보다 못해.", tag: "[teasing] ...푸흡. 뭐야 그게? 아빠보다 못해." },
  { id: "a4-9cf15cb1ffebc", who: "amy", text: "…아하하. 우리 아빠 진짜 바보다. 나 김치찌개 맵다고 못 먹는데.", tag: "[crying] ...아하하. 우리 아빠, 진짜 바보다... 나 김치찌개, 맵다고 못 먹는데..." },
  { id: "a4-0706d20396e", who: "amy", text: "괜찮아. 괜찮아. 반지하 1년 차면 이 정도는… 아하하. 웃기지? …안 웃겨?", tag: "[forced cheer, nervous laugh] 괜찮아. 괜찮아. 반지하 일 년 차면 이 정도는... 아하하. 웃기지? [small voice] ...안 웃겨?" },
  { id: "a4-7b2cc4c845eb", who: "amy", text: "…아하하. 다 잃었다. 어제 거.", tag: "[hollow, deflated] ...아하하. 다 잃었다. 어제 거." },
  { id: "a4-114392128be", who: "amy", text: "평생인 줄 알았는데. 반년이래. 아하하. 숫자 웃기다.", tag: "[stunned, laughing through tears] 평생인 줄 알았는데. 반년이래. 아하하. 숫자 웃기다." },
  { id: "a4-d6e6a4d12eeb", who: "amy", text: "…아하하. 졌다. 아빠랑 똑같이.", tag: "[hollow] ...아하하. 졌다. [falling tone] 아빠랑 똑같이." },
];
export const V2_LINES: VoiceLine[] = [...V2_P0, ...V2_P1, ...V2_P2, ...V2_P3, ...V2_P4, ...V2_P5];
